INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(1,'Acalmar Emoções','acalmar emocoes',2,1,1,'V, S','Ação','18 metros','Concentração, até 1 minuto','Cada Humanoide em uma Esfera de 6 metros de raio
centrada em um ponto à sua escolha no alcance da
magia deve ser bem-sucedido em uma salvaguarda
de Carisma ou é afetado por um dos seguintes efeitos
(escolha um para cada criatura):
A criatura tem Imunidade às condições Amedronta-
do e Enfeitiçado até que a magia termine. Se a criatura
já estiver Amedrontada ou Enfeitiçada, essas condições
são suprimidas pela duração da magia.
A criatura se torna Indiferente às criaturas à sua
escolha em relação às quais é Hostil. Essa indiferen-
ça encerra se o alvo sofrer dano ou testemunhar os
aliados dela sofrendo dano. Quando a magia termina, a
atitude da criatura volta ao normal.',1,'Encantamento (Bardo, Clérigo)','{"level":"2","name":"Acalmar Emoções","school":[{"text":"Encantamento (Bardo, Clérigo)","top":100.9052999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":116.57119999999998,"prose":false,"stat":false,"head":false,"page":1,"col":0}],"Alcance":[{"text":"18 metros","top":128.47129999999993,"prose":false,"stat":false,"head":false,"page":1,"col":0}],"Componentes":[{"text":"V, S","top":140.3712999999999,"prose":false,"stat":false,"head":false,"page":1,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":152.2713,"prose":false,"stat":false,"head":false,"page":1,"col":0}]},"desc":[{"text":"Cada Humanoide em uma Esfera de 6 metros de raio","top":170.3264999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"centrada em um ponto à sua escolha no alcance da","top":182.22659999999996,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"magia deve ser bem-sucedido em uma salvaguarda","top":194.12659999999994,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"de Carisma ou é afetado por um dos seguintes efeitos","top":206.02659999999992,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"(escolha um para cada criatura):","top":217.9265999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"A criatura tem Imunidade às condições Amedronta-","top":229.8264999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"do e Enfeitiçado até que a magia termine. Se a criatura","top":241.72659999999996,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"já estiver Amedrontada ou Enfeitiçada, essas condições","top":253.62659999999994,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"são suprimidas pela duração da magia.","top":265.5265999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"A criatura se torna Indiferente às criaturas à sua","top":277.4266,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"escolha em relação às quais é Hostil. Essa indiferen-","top":289.3266,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"ça encerra se o alvo sofrer dano ou testemunhar os","top":301.2266,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"aliados dela sofrendo dano. Quando a magia termina, a","top":313.1266,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"atitude da criatura volta ao normal.","top":325.02660000000003,"prose":true,"stat":false,"head":false,"page":1,"col":0}],"page":1}');
