INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(3,'Alarme','alarme',1,3,1,'V, S, M (um sino e um fio de prata)','1 minuto ou Ritual','9 metros','8 horas','Você define um alarme contra intrusão. Escolha uma
porta, uma janela ou uma área no alcance da magia que
não seja maior do que um Cubo de 6 metros de lados.
Até que a magia termine, um alarme o avisa sempre
que uma criatura tocar ou entrar na área protegida. Ao
conjurar a magia, você pode designar criaturas que não
disparam o alarme. Você também escolhe se o alarme é
audível ou mental:
Alarme Mental. Você é alertado por um bipe mental
se estiver a menos de 1,5 quilômetro da área protegida.
Este bipe o acorda se você estiver dormindo.
Alarme Sonoro. O alarme produz o som de uma si-
neta por 10 segundos a até 18 metros da área protegida.',1,'Abjuração (Guardião, Mago)','{"level":"1","name":"Alarme","school":[{"text":"Abjuração (Guardião, Mago)","top":542.3557,"prose":true,"stat":false,"head":false,"page":1,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":558.0217,"prose":false,"stat":false,"head":false,"page":1,"col":0}],"Alcance":[{"text":"9 metros","top":569.9216,"prose":false,"stat":false,"head":false,"page":1,"col":0}],"Componentes":[{"text":"V, S, M (um sino e um fio de prata)","top":581.8217,"prose":false,"stat":false,"head":false,"page":1,"col":0}],"Duração":[{"text":"8 horas","top":593.7217,"prose":false,"stat":false,"head":false,"page":1,"col":0}]},"desc":[{"text":"Você define um alarme contra intrusão. Escolha uma","top":611.777,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"porta, uma janela ou uma área no alcance da magia que","top":623.6768999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"não seja maior do que um Cubo de 6 metros de lados.","top":635.577,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"Até que a magia termine, um alarme o avisa sempre","top":647.477,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"que uma criatura tocar ou entrar na área protegida. Ao","top":659.3769,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"conjurar a magia, você pode designar criaturas que não","top":671.277,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"disparam o alarme. Você também escolhe se o alarme é","top":683.1768999999999,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"audível ou mental:","top":695.077,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"Alarme Mental. Você é alertado por um bipe mental","top":706.977,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"se estiver a menos de 1,5 quilômetro da área protegida.","top":718.8769,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"Este bipe o acorda se você estiver dormindo.","top":730.777,"prose":true,"stat":false,"head":false,"page":1,"col":0},{"text":"Alarme Sonoro. O alarme produz o som de uma si-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":1,"col":1},{"text":"neta por 10 segundos a até 18 metros da área protegida.","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":1,"col":1}],"page":1}');
