INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(5,'Aljava Veloz','aljava veloz',5,5,1,'V, S, M (uma Aljava no valor de 1 ou mais PO)','Ação Bônus','Pessoal','Concentração, até 1 minuto','Ao conjurar a magia e como uma Ação Bônus até que
ela termine, você pode realizar dois ataques com uma
arma que dispara Flechas ou Virotes, como um Arco
Longo ou uma Besta Leve. A magia gera magicamente
a munição necessária para cada ataque. Cada Flecha
ou Virote criado pela magia causa dano equivalente
ao de munição não mágica do seu tipo e se desintegra
imediatamente após atingir ou errar o alvo.',2,'Transmutação (Guardião)','{"level":"5","name":"Aljava Veloz","school":[{"text":"Transmutação (Guardião)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":2,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":2,"col":0}],"Alcance":[{"text":"Pessoal","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":2,"col":0}],"Componentes":[{"text":"V, S, M (uma Aljava no valor de 1 ou mais PO)","top":102.4579,"prose":false,"stat":false,"head":false,"page":2,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":2,"col":0}]},"desc":[{"text":"Ao conjurar a magia e como uma Ação Bônus até que","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"ela termine, você pode realizar dois ataques com uma","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"arma que dispara Flechas ou Virotes, como um Arco","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"Longo ou uma Besta Leve. A magia gera magicamente","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"a munição necessária para cada ataque. Cada Flecha","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"ou Virote criado pela magia causa dano equivalente","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"ao de munição não mágica do seu tipo e se desintegra","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"imediatamente após atingir ou errar o alvo.","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":2,"col":0}],"page":2}');
