INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(6,'Alterar-se','alterar-se',2,5,1,'V, S','Ação','Pessoal','Concentração, até 1 hora','Você altera sua forma física. Escolha uma das seguin-
tes opções. Seus efeitos permanecem pela duração da
magia, durante a qual você pode executar uma ação
Usar Magia para substituir a opção escolhida por uma
diferente.
Adaptação Aquática. Você cria guelras e membranas
entre os dedos. Você pode respirar debaixo d’água
e recebe um Deslocamento de Natação igual ao seu
Deslocamento.
Armas Naturais. Você cria garras (Cortante), presas
(Perfurante), chifres (Perfurante) ou cascos (Contun-
dente). Ao usar seu Ataque Desarmado para causar
dano com essa nova forma, ele causa 1d6 pontos de
dano do tipo entre parênteses em vez de causar o dano
normal para seu Ataque Desarmado, e você usa seu
modificador de atributo de conjuração para as jogadas
de ataque e dano em vez de usar Força.
Mudar Aparência. Você altera sua aparência. Você
decide sua aparência, incluindo altura, peso, traços
faciais, som da voz, comprimento e cor do cabelo, entre
outras características distintivas. Você pode parecer
um membro de outra espécie, embora nenhuma de
suas estatísticas mude. Você não pode parecer como
uma criatura de um tamanho diferente, e sua forma
básica permanece a mesma; se você é bípede, não
pode usar essa magia para se tornar quadrúpede, por
exemplo. Pela duração da magia, você pode executar
uma ação Usar Magia para mudar sua aparência dessa
maneira novamente.',2,'Transmutação (Feiticeiro, Mago)','{"level":"2","name":"Alterar-se","school":[{"text":"Transmutação (Feiticeiro, Mago)","top":259.9171,"prose":true,"stat":false,"head":false,"page":2,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":275.58309999999994,"prose":false,"stat":false,"head":false,"page":2,"col":0}],"Alcance":[{"text":"Pessoal","top":287.4831,"prose":false,"stat":false,"head":false,"page":2,"col":0}],"Componentes":[{"text":"V, S","top":299.38309999999996,"prose":false,"stat":false,"head":false,"page":2,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":311.28309999999993,"prose":false,"stat":false,"head":false,"page":2,"col":0}]},"desc":[{"text":"Você altera sua forma física. Escolha uma das seguin-","top":329.3384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"tes opções. Seus efeitos permanecem pela duração da","top":341.2384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"magia, durante a qual você pode executar uma ação","top":353.1384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"Usar Magia para substituir a opção escolhida por uma","top":365.0384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"diferente.","top":376.9384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"Adaptação Aquática. Você cria guelras e membranas","top":388.8384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"entre os dedos. Você pode respirar debaixo d’água","top":400.7384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"e recebe um Deslocamento de Natação igual ao seu","top":412.6384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"Deslocamento.","top":424.5384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"Armas Naturais. Você cria garras (Cortante), presas","top":436.4384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"(Perfurante), chifres (Perfurante) ou cascos (Contun-","top":448.3384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"dente). Ao usar seu Ataque Desarmado para causar","top":460.2384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"dano com essa nova forma, ele causa 1d6 pontos de","top":472.1384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"dano do tipo entre parênteses em vez de causar o dano","top":484.0384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"normal para seu Ataque Desarmado, e você usa seu","top":495.9384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"modificador de atributo de conjuração para as jogadas","top":507.8384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"de ataque e dano em vez de usar Força.","top":519.7384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"Mudar Aparência. Você altera sua aparência. Você","top":531.6384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"decide sua aparência, incluindo altura, peso, traços","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"faciais, som da voz, comprimento e cor do cabelo, entre","top":555.4384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"outras características distintivas. Você pode parecer","top":567.3384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"um membro de outra espécie, embora nenhuma de","top":579.2384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"suas estatísticas mude. Você não pode parecer como","top":591.1384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"uma criatura de um tamanho diferente, e sua forma","top":603.0383999999999,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"básica permanece a mesma; se você é bípede, não","top":614.9384,"prose":true,"stat":false,"head":false,"page":2,"col":0},{"text":"pode usar essa magia para se to