INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(7,'Amigos','amigos',0,1,1,'S, M (um pouco de maquiagem)','Ação','3 metros','Concentração, até 1 minuto','Você emana magicamente um sentimento de amizade
em relação a uma criatura à sua vista e no alcance da
magia. O alvo deve ser bem-sucedido em uma salva-
guarda de Sabedoria ou tem a condição Enfeitiçado
pela duração da magia. O alvo é bem-sucedido automa-
ticamente se não for um Humanoide, se você estiver
lutando contra ele ou se tiver conjurado esta magia
nele nas últimas 24 horas.
A magia encerra se o alvo sofrer dano ou se você
realizar uma jogada de ataque, causar dano ou forçar
alguém a realizar uma salvaguarda. Quando a magia
termina, o alvo sabe que foi Enfeitiçado por você.',2,'Encantamento (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"0","name":"Amigos","school":[{"text":"Encantamento (Bardo, Bruxo, Feiticeiro, Mago)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":2,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":2,"col":1}],"Alcance":[{"text":"3 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":2,"col":1}],"Componentes":[{"text":"S, M (um pouco de maquiagem)","top":102.4579,"prose":false,"stat":false,"head":false,"page":2,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":2,"col":1}]},"desc":[{"text":"Você emana magicamente um sentimento de amizade","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"em relação a uma criatura à sua vista e no alcance da","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"magia. O alvo deve ser bem-sucedido em uma salva-","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"guarda de Sabedoria ou tem a condição Enfeitiçado","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"pela duração da magia. O alvo é bem-sucedido automa-","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"ticamente se não for um Humanoide, se você estiver","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"lutando contra ele ou se tiver conjurado esta magia","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"nele nas últimas 24 horas.","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"A magia encerra se o alvo sofrer dano ou se você","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"realizar uma jogada de ataque, causar dano ou forçar","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"alguém a realizar uma salvaguarda. Quando a magia","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":2,"col":1},{"text":"termina, o alvo sabe que foi Enfeitiçado por você.","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":2,"col":1}],"page":2}');
