INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(15,'Arca Secreta de Leomund','arca secreta de leomund',4,4,1,'V, S, M (um baú de 1 m por 60 cm por 60 cm,
construído com materiais raros no valor de 5.000 ou mais
PO, e uma réplica minúscula do baú fabricada com os
mesmos materiais no valor de 50 ou mais PO)','Ação','Toque','Até ser dissipada','Você esconde um baú e todo o seu conteúdo no Plano
Etéreo. Você deve tocar no baú e na réplica em minia-
tura que servem como componentes Materiais para a
magia. O baú pode armazenar até 340 litros de mate-
rial não vivo (1 m por 60 cm por 60 cm).
Enquanto o baú permanecer no Plano Etéreo, você
pode executar uma ação Usar Magia e tocar na répli-
ca para recuperar o baú. Ele aparece em um espaço
desocupado no chão a até 1,5 metro de você. Você pode
enviar o baú de volta ao Plano Etéreo como uma ação
Usar Magia para tocar o baú e a réplica.
Após 60 dias, há uma chance cumulativa de 5% no
final de cada dia de que a magia encerre. A magia tam-
bém se encerra se você conjurá-la novamente ou se a
réplica Minúscula for destruída. Se a magia encerrar e
o baú maior estiver no Plano Etéreo, o baú permanece
lá para você ou outra pessoa encontrar.',5,'Invocação (Mago)','{"level":"4","name":"Arca Secreta de Leomund","school":[{"text":"Invocação (Mago)","top":187.66129999999998,"prose":true,"stat":false,"head":false,"page":5,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":203.32719999999995,"prose":false,"stat":false,"head":false,"page":5,"col":0}],"Alcance":[{"text":"Toque","top":215.22719999999993,"prose":false,"stat":false,"head":false,"page":5,"col":0}],"Componentes":[{"text":"V, S, M (um baú de 1 m por 60 cm por 60 cm,","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":5,"col":0},{"text":"construído com materiais raros no valor de 5.000 ou mais","top":239.0272,"prose":false,"stat":false,"head":false,"page":5,"col":0},{"text":"PO, e uma réplica minúscula do baú fabricada com os","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":5,"col":0},{"text":"mesmos materiais no valor de 50 ou mais PO)","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":5,"col":0}],"Duração":[{"text":"Até ser dissipada","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":5,"col":0}]},"desc":[{"text":"Você esconde um baú e todo o seu conteúdo no Plano","top":292.7825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"Etéreo. Você deve tocar no baú e na réplica em minia-","top":304.6825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"tura que servem como componentes Materiais para a","top":316.5825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"magia. O baú pode armazenar até 340 litros de mate-","top":328.4825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"rial não vivo (1 m por 60 cm por 60 cm).","top":340.3825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"Enquanto o baú permanecer no Plano Etéreo, você","top":352.2825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"pode executar uma ação Usar Magia e tocar na répli-","top":364.1825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"ca para recuperar o baú. Ele aparece em um espaço","top":376.0825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"desocupado no chão a até 1,5 metro de você. Você pode","top":387.9825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"enviar o baú de volta ao Plano Etéreo como uma ação","top":399.8825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"Usar Magia para tocar o baú e a réplica.","top":411.7825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"Após 60 dias, há uma chance cumulativa de 5% no","top":423.6825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"final de cada dia de que a magia encerre. A magia tam-","top":435.5825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"bém se encerra se você conjurá-la novamente ou se a","top":447.4825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"réplica Minúscula for destruída. Se a magia encerrar e","top":459.3825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"o baú maior estiver no Plano Etéreo, o baú permanece","top":471.2825,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"lá para você ou outra pessoa encontrar.","top":483.1825,"prose":true,"stat":false,"head":false,"page":5,"col":0}],"page":5}');
