INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(16,'Arma Elemental','arma elemental',3,5,1,'V, S','Ação','Toque','Concentração, até 1 hora','Uma arma não-mágica que você toca se torna uma
arma mágica. Escolha um dos seguintes tipos de dano:
Ácido, Elétrico, Gélido, Ígneo ou Trovejante. Pela dura-
ção da magia, a arma tem um bônus de +1 para jogadas
de ataque e causa 1d4 pontos de dano adicional do tipo
escolhido quando atinge.
Usando um Espaço de Magia de Círculo Superior. Se
você usar um espaço de magia de 5º ou 6º círculo, o
bônus nas jogadas de ataque aumenta para +2, e o dano
adicional aumenta para 2d4. Se você usar um espaço
de magia de 7º círculo ou superior, o bônus aumenta
para +3 e o dano adicional aumenta para 3d4.',5,'Transmutação (Druida, Guardião, Paladino)','{"level":"3","name":"Arma Elemental","school":[{"text":"Transmutação (Druida, Guardião, Paladino)","top":527.3864,"prose":true,"stat":false,"head":false,"page":5,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":543.0524,"prose":false,"stat":false,"head":false,"page":5,"col":0}],"Alcance":[{"text":"Toque","top":554.9524,"prose":false,"stat":false,"head":false,"page":5,"col":0}],"Componentes":[{"text":"V, S","top":566.8524,"prose":false,"stat":false,"head":false,"page":5,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":578.7524,"prose":false,"stat":false,"head":false,"page":5,"col":0}]},"desc":[{"text":"Uma arma não-mágica que você toca se torna uma","top":596.8077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"arma mágica. Escolha um dos seguintes tipos de dano:","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"Ácido, Elétrico, Gélido, Ígneo ou Trovejante. Pela dura-","top":620.6077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"ção da magia, a arma tem um bônus de +1 para jogadas","top":632.5077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"de ataque e causa 1d4 pontos de dano adicional do tipo","top":644.4077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"escolhido quando atinge.","top":656.3077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. Se","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"você usar um espaço de magia de 5º ou 6º círculo, o","top":680.1077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"bônus nas jogadas de ataque aumenta para +2, e o dano","top":692.0077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"adicional aumenta para 2d4. Se você usar um espaço","top":703.9077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"de magia de 7º círculo ou superior, o bônus aumenta","top":715.8077,"prose":true,"stat":false,"head":false,"page":5,"col":0},{"text":"para +3 e o dano adicional aumenta para 3d4.","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":5,"col":0}],"page":5}');
