INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(17,'Arma Espiritual','arma espiritual',2,6,1,'V, S','Ação Bônus','18 metros','Concentração, até 1 minuto','Você cria uma energia espectral flutuante que se
assemelha a uma arma à sua escolha e permanece pela
duração da magia.
A energia aparece no alcance da magia em um espa-
