INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(21,'Arrombar','arrombar',2,5,1,'V','Ação','18 metros','Instantânea','Escolha um objeto à sua vista e no alcance da magia. O
objeto pode ser uma porta, uma caixa, um baú, um con-
junto de grilhões, um cadeado ou outro objeto que conte-
nha um meio mundano ou mágico que impeça o acesso.
Um alvo mantido fechado por uma fechadura mun-
dana ou que está preso ou barrado fica destrancado,
desemperrado ou desobstruído. Se o objeto tiver várias
fechaduras, apenas uma delas é destrancada.
Se o alvo for mantido fechado por Tranca Arcana,
essa magia é suprimida por 10 minutos, durante os
quais o alvo pode ser aberto e fechado.
Ao conjurar a magia, um estrondo, audível a até 90
metros de distância, emana do alvo.',6,'Transmutação (Bardo, Feiticeiro, Mago)','{"level":"2","name":"Arrombar","school":[{"text":"Transmutação (Bardo, Feiticeiro, Mago)","top":644.5223,"prose":true,"stat":false,"head":false,"page":6,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":660.1883,"prose":false,"stat":false,"head":false,"page":6,"col":0}],"Alcance":[{"text":"18 metros","top":672.0883,"prose":false,"stat":false,"head":false,"page":6,"col":0}],"Componentes":[{"text":"V","top":683.9883,"prose":false,"stat":false,"head":false,"page":6,"col":0}],"Duração":[{"text":"Instantânea","top":695.8883,"prose":false,"stat":false,"head":false,"page":6,"col":0}]},"desc":[{"text":"Escolha um objeto à sua vista e no alcance da magia. O","top":713.9436,"prose":true,"stat":false,"head":false,"page":6,"col":0},{"text":"objeto pode ser uma porta, uma caixa, um baú, um con-","top":725.8436,"prose":true,"stat":false,"head":false,"page":6,"col":0},{"text":"junto de grilhões, um cadeado ou outro objeto que conte-","top":397.1625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"nha um meio mundano ou mágico que impeça o acesso.","top":409.0625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"Um alvo mantido fechado por uma fechadura mun-","top":420.96250000000003,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"dana ou que está preso ou barrado fica destrancado,","top":432.8625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"desemperrado ou desobstruído. Se o objeto tiver várias","top":444.7625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"fechaduras, apenas uma delas é destrancada.","top":456.6625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"Se o alvo for mantido fechado por Tranca Arcana,","top":468.5625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"essa magia é suprimida por 10 minutos, durante os","top":480.46250000000003,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"quais o alvo pode ser aberto e fechado.","top":492.3625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"Ao conjurar a magia, um estrondo, audível a até 90","top":504.2625,"prose":true,"stat":false,"head":false,"page":6,"col":1},{"text":"metros de distância, emana do alvo.","top":516.1625,"prose":true,"stat":false,"head":false,"page":6,"col":1}],"page":6}');
