INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(25,'Aumentar/Reduzir','aumentar/reduzir',2,5,1,'V, S, M (uma pitada de ferro em pó)','Ação','9 metros','Concentração, até 1 minuto','Pela duração da magia, você amplia ou reduz uma
criatura, ou objeto, à sua vista e no alcance da magia
(veja o efeito escolhido abaixo). Um objeto à vista não
deve ser usado nem transportado. Se o alvo for uma
criatura involuntária, ele pode realizar uma salvaguar-
da de Constituição. Em caso de sucesso, a magia não
surte efeito.
Tudo o que uma criatura estiver usando e carregan-
do muda de tamanho com ela. Qualquer item que cair
retorna ao tamanho normal de uma só vez. Uma arma
ou munição arremessada retorna ao tamanho normal
imediatamente após atingir ou errar um alvo.
Aumentar. O tamanho do alvo aumenta em uma
categoria — de Médio para Grande, por exemplo. O
alvo também tem Vantagem em testes de Força e salva-
guardas de Força. Os ataques do alvo com suas armas
ampliadas ou Ataques Desarmados causam 1d4 pontos
de dano adicionais em caso de acerto.
Reduzir. O tamanho do alvo diminui em uma
categoria — de Médio para Pequeno, por exemplo. O
alvo também tem Desvantagem em testes de Força e
salvaguardas de Força. Os ataques do alvo com suas
armas reduzidas ou Ataques Desarmados causam 1d4
pontos de dano a menos em caso de acerto (isso não
pode reduzir o dano abaixo de 1).',7,'Transmutação (Bardo, Druida, Feiticeiro, Mago)','{"level":"2","name":"Aumentar/Reduzir","school":[{"text":"Transmutação (Bardo, Druida, Feiticeiro, Mago)","top":296.5006,"prose":true,"stat":false,"head":false,"page":7,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":312.16659999999996,"prose":false,"stat":false,"head":false,"page":7,"col":1}],"Alcance":[{"text":"9 metros","top":324.06659999999994,"prose":false,"stat":false,"head":false,"page":7,"col":1}],"Componentes":[{"text":"V, S, M (uma pitada de ferro em pó)","top":335.96659999999997,"prose":false,"stat":false,"head":false,"page":7,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":347.86659999999995,"prose":false,"stat":false,"head":false,"page":7,"col":1}]},"desc":[{"text":"Pela duração da magia, você amplia ou reduz uma","top":365.9219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"criatura, ou objeto, à sua vista e no alcance da magia","top":377.8219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"(veja o efeito escolhido abaixo). Um objeto à vista não","top":389.7219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"deve ser usado nem transportado. Se o alvo for uma","top":401.6219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"criatura involuntária, ele pode realizar uma salvaguar-","top":413.5219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"da de Constituição. Em caso de sucesso, a magia não","top":425.4219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"surte efeito.","top":437.3219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"Tudo o que uma criatura estiver usando e carregan-","top":449.2219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"do muda de tamanho com ela. Qualquer item que cair","top":461.1219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"retorna ao tamanho normal de uma só vez. Uma arma","top":473.0219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"ou munição arremessada retorna ao tamanho normal","top":484.9219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"imediatamente após atingir ou errar um alvo.","top":496.8219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"Aumentar. O tamanho do alvo aumenta em uma","top":508.7219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"categoria — de Médio para Grande, por exemplo. O","top":520.6219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"alvo também tem Vantagem em testes de Força e salva-","top":532.5219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"guardas de Força. Os ataques do alvo com suas armas","top":544.4218999999999,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"ampliadas ou Ataques Desarmados causam 1d4 pontos","top":556.3217999999999,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"de dano adicionais em caso de acerto.","top":568.2219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"Reduzir. O tamanho do alvo diminui em uma","top":580.1219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"categoria — de Médio para Pequeno, por exemplo. O","top":592.0218,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"alvo também tem Desvantagem em testes de Força e","top":603.9218999999999,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"salvaguardas de Força. Os ataques do alvo com suas","top":615.8217999999999,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"armas reduzidas ou Ataques Desarmados causam 1d4","top":627.7219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"pontos de dano a menos em caso de acerto (isso não","top":639.6219,"prose":true,"stat":false,"head":false,"page":7,"col":1},{"text":"pode reduzir o dano abaixo de 1).","