persiste, você pode restaurar 2d6 Pontos de Vida em
uma criatura dentro dela.',8,'Abjuração (Clérigo, Druida, Paladino)','{"level":"3","name":"Aura de Vitalidade","school":[{"text":"Abjuração (Clérigo, Druida, Paladino)","top":409.2423,"prose":true,"stat":false,"head":false,"page":8,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":424.90829999999994,"prose":false,"stat":false,"head":false,"page":8,"col":0}],"Alcance":[{"text":"Pessoal","top":436.8083,"prose":false,"stat":false,"head":false,"page":8,"col":0}],"Componentes":[{"text":"V","top":448.70829999999995,"prose":false,"stat":false,"head":false,"page":8,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":460.6083,"prose":false,"stat":false,"head":false,"page":8,"col":0}]},"desc":[{"text":"Uma aura irradia de você em uma Emanação de 9 me-","top":478.66360000000003,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"tros pela duração da magia. Quando você cria a aura","top":490.5636,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"e no início de cada um dos seus turnos enquanto ela","top":502.4636,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"persiste, você pode restaurar 2d6 Pontos de Vida em","top":514.3636,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"uma criatura dentro dela.","top":526.2636,"prose":true,"stat":false,"head":false,"page":8,"col":0}],"page":8}');
