mágicos tratam o alvo como se fosse uma criatura do
tipo escolhido.',8,'Ilusão (Mago)','{"level":"2","name":"Aura Mágica de Nystul","school":[{"text":"Ilusão (Mago)","top":570.4675,"prose":true,"stat":false,"head":false,"page":8,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":586.1335,"prose":false,"stat":false,"head":false,"page":8,"col":0}],"Alcance":[{"text":"Toque","top":598.0335,"prose":false,"stat":false,"head":false,"page":8,"col":0}],"Componentes":[{"text":"V, S, M (um pequeno quadrado de seda)","top":609.9335,"prose":false,"stat":false,"head":false,"page":8,"col":0}],"Duração":[{"text":"24 horas","top":621.8335,"prose":false,"stat":false,"head":false,"page":8,"col":0}]},"desc":[{"text":"Com um toque, você coloca uma ilusão em uma cria-","top":639.8888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"tura voluntária ou em um objeto que não esteja sendo","top":651.7888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"usado ou carregado. Uma criatura adquire o efeito","top":663.6888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"Máscara descrito abaixo, e um objeto adquire o efeito","top":675.5888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"Falsa Aura descrito abaixo. O efeito permanece pela","top":687.4888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"duração da magia. Se você conjurar a magia na mesma","top":699.3888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"criatura ou objeto todos os dias por 30 dias, a ilusão","top":711.2888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"dura até ser dissipada.","top":723.1888,"prose":true,"stat":false,"head":false,"page":8,"col":0},{"text":"Falsa Aura (Objeto). Você muda a forma como o alvo","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"aparece para magias e efeitos mágicos que detectam","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"auras mágicas, como Detectar Magia. Você pode realizar","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"um objeto não mágico parecer mágico, realizar um","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"item mágico parecer não mágico ou alterar a aura do","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"objeto para parecer pertencer a uma escola de magia","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"que você escolher.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"Máscara (Criatura). Escolha um tipo de criatura","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"diferente do tipo real do alvo. Magias e outros efeitos","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"mágicos tratam o alvo como se fosse uma criatura do","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":8,"col":1},{"text":"tipo escolhido.","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":8,"col":1}],"page":8}');
