INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(37,'Boca Encantada','boca encantada',2,7,1,'V, S, M (poeira de jade no valor de 10 ou mais
PO, que a magia consome)','1 minuto ou Ritual','9 metros','Até ser dissipada','Você implanta uma mensagem em um objeto que
esteja no alcance da magia. Essa mensagem é revelada
quando uma circunstância de disparo ocorrer. Escolha
um objeto à sua vista e que não esteja sendo usado ou
carregado por outra criatura. Fale, então, a mensagem,
que deve possuir 25 palavras ou menos, embora ela
possa ser emitida ao longo de um período de até 10
minutos. Por fim, determine a circunstância de disparo
para magia revelar a mensagem.
Quando tal circunstância ocorrer, uma boca encan-
tada aparece no objeto e recita a mensagem com a sua
voz e no mesmo volume que você falou. Se o objeto
escolhido tiver uma boca ou algo que se assemelhe (por
exemplo, a boca de uma estátua), a boca encantada se
sobrepõe para parecer que as palavras saem da boca do
próprio objeto. Ao conjurar a magia, você determina se
ela se encerra após entregar a mensagem ou se perma-
nece para repetir o conteúdo sempre que a circunstân-
cia de disparo ocorrer.
A circunstância de disparo pode ser tão abrangente
ou específica quanto você quiser, mas deve ser baseada
em condições visuais ou auditivas que ocorram a até
9 metros do objeto. Por exemplo, você pode instruir a
boca a falar sempre que uma criatura se aproxime a até
9 metros do objeto, ou quando um sino de prata soar a
até 9 metros de distância do objeto.',10,'Ilusão (Bardo, Mago)','{"level":"2","name":"Boca Encantada","school":[{"text":"Ilusão (Bardo, Mago)","top":552.0424,"prose":true,"stat":false,"head":false,"page":10,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":567.7083,"prose":false,"stat":false,"head":false,"page":10,"col":0}],"Alcance":[{"text":"9 metros","top":579.6083,"prose":false,"stat":false,"head":false,"page":10,"col":0}],"Componentes":[{"text":"V, S, M (poeira de jade no valor de 10 ou mais","top":591.5083,"prose":false,"stat":false,"head":false,"page":10,"col":0},{"text":"PO, que a magia consome)","top":603.4083,"prose":false,"stat":false,"head":false,"page":10,"col":0}],"Duração":[{"text":"Até ser dissipada","top":615.3082999999999,"prose":false,"stat":false,"head":false,"page":10,"col":0}]},"desc":[{"text":"Você implanta uma mensagem em um objeto que","top":633.3636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"esteja no alcance da magia. Essa mensagem é revelada","top":645.2636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"quando uma circunstância de disparo ocorrer. Escolha","top":657.1636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"um objeto à sua vista e que não esteja sendo usado ou","top":669.0636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"carregado por outra criatura. Fale, então, a mensagem,","top":680.9636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"que deve possuir 25 palavras ou menos, embora ela","top":692.8636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"possa ser emitida ao longo de um período de até 10","top":704.7636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"minutos. Por fim, determine a circunstância de disparo","top":716.6636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"para magia revelar a mensagem.","top":728.5636,"prose":true,"stat":false,"head":false,"page":10,"col":0},{"text":"Quando tal circunstância ocorrer, uma boca encan-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"tada aparece no objeto e recita a mensagem com a sua","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"voz e no mesmo volume que você falou. Se o objeto","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"escolhido tiver uma boca ou algo que se assemelhe (por","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"exemplo, a boca de uma estátua), a boca encantada se","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"sobrepõe para parecer que as palavras saem da boca do","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"próprio objeto. Ao conjurar a magia, você determina se","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"ela se encerra após entregar a mensagem ou se perma-","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"nece para repetir o conteúdo sempre que a circunstân-","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"cia de disparo ocorrer.","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"A circunstância de disparo pode ser tão abrangente","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"ou específica quanto você quiser, mas deve ser baseada","top":167.2573,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"em condições visuais ou auditivas que ocorram a até","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":10,"col":1},{"text":"9 metros do objeto. Por exemplo, você pode instruir a","top":191.05729999999994,"prose":true,"stat"