INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(41,'Bom Fruto','bom fruto',1,4,1,'V, S, M (um ramo de visco)','Ação','Pessoal','24 horas','Dez frutos aparecem em sua mão e são infundidos ma-
gicamente pela duração da magia. Uma criatura pode
executar uma Ação Bônus para comer um fruto. Comer
um fruto restaura 1 Ponto de Vida e fornece alimento
suficiente para sustentar uma criatura por um dia. Fru-
tos não comidos desaparecem quando a magia termina.',11,'Invocação (Druida, Guardião)','{"level":"1","name":"Bom Fruto","school":[{"text":"Invocação (Druida, Guardião)","top":409.3858,"prose":true,"stat":false,"head":false,"page":11,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":424.95179999999993,"prose":false,"stat":false,"head":false,"page":11,"col":1}],"Alcance":[{"text":"Pessoal","top":436.75179999999995,"prose":false,"stat":false,"head":false,"page":11,"col":1}],"Componentes":[{"text":"V, S, M (um ramo de visco)","top":448.55179999999996,"prose":false,"stat":false,"head":false,"page":11,"col":1}],"Duração":[{"text":"24 horas","top":460.35179999999997,"prose":false,"stat":false,"head":false,"page":11,"col":1}]},"desc":[{"text":"Dez frutos aparecem em sua mão e são infundidos ma-","top":478.3071,"prose":true,"stat":false,"head":false,"page":11,"col":1},{"text":"gicamente pela duração da magia. Uma criatura pode","top":490.107,"prose":true,"stat":false,"head":false,"page":11,"col":1},{"text":"executar uma Ação Bônus para comer um fruto. Comer","top":501.9071,"prose":true,"stat":false,"head":false,"page":11,"col":1},{"text":"um fruto restaura 1 Ponto de Vida e fornece alimento","top":513.7071000000001,"prose":true,"stat":false,"head":false,"page":11,"col":1},{"text":"suficiente para sustentar uma criatura por um dia. Fru-","top":525.5070000000001,"prose":true,"stat":false,"head":false,"page":11,"col":1},{"text":"tos não comidos desaparecem quando a magia termina.","top":537.3071,"prose":true,"stat":false,"head":false,"page":11,"col":1}],"page":11}');
