INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(44,'Caldeirão Borbulhante de Tasha','caldeirao borbulhante de tasha',6,4,1,'V, S, M (uma colher de mexer caldeirão dourada
no valor de 500 ou mais PO)','Ação','1,5 metro','10 minutos','Você conjura um caldeirão com pés de garra cheio
de líquido borbulhante. O caldeirão aparece em um
espaço desocupado no chão a até 1,5 metro de você
e permanece pela duração da magia. O caldeirão não
pode ser movido e desaparece quando a magia termina,
junto com o líquido borbulhante dentro dele.
O líquido no caldeirão copia as propriedades de uma
poção Comum ou Incomum à sua escolha (como uma
Poção de Cura). Como uma Ação Bônus, você ou um
aliado pode alcançar o caldeirão e retirar dele uma po-
ção desse tipo. A poção está contida em um frasco que
desaparece quando a poção é consumida. O caldeirão
pode produzir um número dessas poções igual ao seu
modificador de atributo de conjuração (mínimo 1).
Quando a última dessas poções é retirada do caldeirão,
o caldeirão desaparece e a magia termina.
Poções obtidas do caldeirão que não são consu-
midas desaparecem quando você conjura esta magia
novamente.',12,'Invocação (Bruxo, Mago)','{"level":"6","name":"Caldeirão Borbulhante de Tasha","school":[{"text":"Invocação (Bruxo, Mago)","top":434.3306,"prose":true,"stat":false,"head":false,"page":12,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":449.99649999999997,"prose":false,"stat":false,"head":false,"page":12,"col":1}],"Alcance":[{"text":"1,5 metro","top":461.8966,"prose":false,"stat":false,"head":false,"page":12,"col":1}],"Componentes":[{"text":"V, S, M (uma colher de mexer caldeirão dourada","top":473.79659999999996,"prose":false,"stat":false,"head":false,"page":12,"col":1},{"text":"no valor de 500 ou mais PO)","top":485.69659999999993,"prose":false,"stat":false,"head":false,"page":12,"col":1}],"Duração":[{"text":"10 minutos","top":497.59649999999993,"prose":false,"stat":false,"head":false,"page":12,"col":1}]},"desc":[{"text":"Você conjura um caldeirão com pés de garra cheio","top":515.6518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"de líquido borbulhante. O caldeirão aparece em um","top":527.5518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"espaço desocupado no chão a até 1,5 metro de você","top":539.4518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"e permanece pela duração da magia. O caldeirão não","top":551.3519,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"pode ser movido e desaparece quando a magia termina,","top":563.2518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"junto com o líquido borbulhante dentro dele.","top":575.1518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"O líquido no caldeirão copia as propriedades de uma","top":587.0518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"poção Comum ou Incomum à sua escolha (como uma","top":598.9518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"Poção de Cura). Como uma Ação Bônus, você ou um","top":610.8519,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"aliado pode alcançar o caldeirão e retirar dele uma po-","top":622.7518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"ção desse tipo. A poção está contida em um frasco que","top":634.6518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"desaparece quando a poção é consumida. O caldeirão","top":646.5518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"pode produzir um número dessas poções igual ao seu","top":658.4518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"modificador de atributo de conjuração (mínimo 1).","top":670.3519,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"Quando a última dessas poções é retirada do caldeirão,","top":682.2518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"o caldeirão desaparece e a magia termina.","top":694.1518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"Poções obtidas do caldeirão que não são consu-","top":706.0518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"midas desaparecem quando você conjura esta magia","top":717.9518,"prose":true,"stat":false,"head":false,"page":12,"col":1},{"text":"novamente.","top":729.8519,"prose":true,"stat":false,"head":false,"page":12,"col":1}],"page":12}');
