INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(45,'Caminhar no Vento','caminhar no vento',6,5,1,'V, S, M (uma vela)','1 minuto','9 metros','8 horas','Você e até dez criaturas voluntárias à sua escolha
no alcance da magia assumem formas gasosas pela
duração da magia, aparecendo como fiapos de nuvem.
Enquanto estiver nesta forma de nuvem, um alvo tem
um Deslocamento de Voo de 90 metros e pode pairar;
tem Imunidade à condição Caído; e tem Resistência a
dano Contundente, Cortante e Perfurante. As únicas
ações que um alvo pode executar nesta forma são a
ação Correr ou Usar Magia para começar a reverter à
sua forma normal. Reverter leva 1 minuto, durante o
qual o alvo tem a condição Atordoado. Até que a magia
termine, o alvo pode voltar à forma de nuvem, o que
também requer uma ação Usar Magia seguida de uma
transformação de 1 minuto.
Se um alvo estiver em forma de nuvem e voando
quando o efeito terminar, ele desce 18 metros por roda-
da por 1 minuto até pousar, o que faz com segurança.
Se não conseguir pousar após 1 minuto, ele cai pela
distância restante.',13,'Transmutação (Druida)','{"level":"6","name":"Caminhar no Vento","school":[{"text":"Transmutação (Druida)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":13,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":13,"col":0}],"Alcance":[{"text":"9 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":13,"col":0}],"Componentes":[{"text":"V, S, M (uma vela)","top":102.4579,"prose":false,"stat":false,"head":false,"page":13,"col":0}],"Duração":[{"text":"8 horas","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":13,"col":0}]},"desc":[{"text":"Você e até dez criaturas voluntárias à sua escolha","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"no alcance da magia assumem formas gasosas pela","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"duração da magia, aparecendo como fiapos de nuvem.","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"Enquanto estiver nesta forma de nuvem, um alvo tem","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"um Deslocamento de Voo de 90 metros e pode pairar;","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"tem Imunidade à condição Caído; e tem Resistência a","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"dano Contundente, Cortante e Perfurante. As únicas","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"ações que um alvo pode executar nesta forma são a","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"ação Correr ou Usar Magia para começar a reverter à","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"sua forma normal. Reverter leva 1 minuto, durante o","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"qual o alvo tem a condição Atordoado. Até que a magia","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"termine, o alvo pode voltar à forma de nuvem, o que","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"também requer uma ação Usar Magia seguida de uma","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"transformação de 1 minuto.","top":287.1132,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"Se um alvo estiver em forma de nuvem e voando","top":299.0132,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"quando o efeito terminar, ele desce 18 metros por roda-","top":310.9132,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"da por 1 minuto até pousar, o que faz com segurança.","top":322.8132,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"Se não conseguir pousar após 1 minuto, ele cai pela","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":13,"col":0},{"text":"distância restante.","top":346.6132,"prose":true,"stat":false,"head":false,"page":13,"col":0}],"page":13}');
