INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(47,'Campo Antimagia','campo antimagia',8,3,1,'V, S, M (raspas de ferro)','Ação','Pessoal','Concentração, até 1 hora','Uma aura de antimagia envolve você em uma Ema-
nação de 3 metros. Ninguém pode conjurar magias,
executar a ação Usar Magia ou criar outros efeitos
mágicos dentro da aura, e esses efeitos não podem ter
como alvo ou afetar qualquer coisa dentro dela. As
propriedades mágicas dos itens mágicos não funcio-
nam dentro da aura ou em qualquer coisa dentro dela.
Áreas de efeito criadas por magias ou outros efeitos
mágicos não podem se estender para dentro da aura, e
ninguém pode se teleportar para dentro ou para fora
dela ou usar viagens planares para lá. Os portais se
fecham temporariamente enquanto estão na aura.
Magias em andamento, exceto aquelas conjuradas
por um Artefato ou por uma divindade, são suprimi-
das na área. Enquanto um efeito é suprimido, ele não
funciona, mas o tempo que ele gasta suprimido conta
para sua duração
Dissipar Magia não tem efeito sobre a aura, e as auras
criadas por diferentes magias de Campo Antimagia não
se anulam.',13,'Abjuração (Clérigo, Mago)','{"level":"8","name":"Campo Antimagia","school":[{"text":"Abjuração (Clérigo, Mago)","top":307.5171,"prose":true,"stat":false,"head":false,"page":13,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":323.18309999999997,"prose":false,"stat":false,"head":false,"page":13,"col":1}],"Alcance":[{"text":"Pessoal","top":335.08309999999994,"prose":false,"stat":false,"head":false,"page":13,"col":1}],"Componentes":[{"text":"V, S, M (raspas de ferro)","top":346.9831,"prose":false,"stat":false,"head":false,"page":13,"col":1}],"Duração":[{"text":"Concentração, até 1 hora","top":358.88309999999996,"prose":false,"stat":false,"head":false,"page":13,"col":1}]},"desc":[{"text":"Uma aura de antimagia envolve você em uma Ema-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"nação de 3 metros. Ninguém pode conjurar magias,","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"executar a ação Usar Magia ou criar outros efeitos","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"mágicos dentro da aura, e esses efeitos não podem ter","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"como alvo ou afetar qualquer coisa dentro dela. As","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"propriedades mágicas dos itens mágicos não funcio-","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"nam dentro da aura ou em qualquer coisa dentro dela.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Áreas de efeito criadas por magias ou outros efeitos","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"mágicos não podem se estender para dentro da aura, e","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"ninguém pode se teleportar para dentro ou para fora","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"dela ou usar viagens planares para lá. Os portais se","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"fecham temporariamente enquanto estão na aura.","top":167.2573,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Magias em andamento, exceto aquelas conjuradas","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"por um Artefato ou por uma divindade, são suprimi-","top":191.05729999999994,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"das na área. Enquanto um efeito é suprimido, ele não","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"funciona, mas o tempo que ele gasta suprimido conta","top":214.8572999999999,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"para sua duração","top":226.7573,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Dissipar Magia não tem efeito sobre a aura, e as auras","top":238.65729999999996,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"criadas por diferentes magias de Campo Antimagia não","top":250.55729999999994,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"se anulam.","top":262.4572999999999,"prose":true,"stat":false,"head":false,"page":14,"col":0}],"page":13}');
