INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(48,'Cão Fiel de Mordenkainen','cao fiel de mordenkainen',4,4,1,'V, S, M (um apito de prata)','Ação','9 metros','8 horas','Você conjura um cão de guarda fantasmagórico em um
espaço desocupado à sua vista e no alcance da magia.
O cão permanece pela duração magia ou até que vocês
dois estejam separados por mais de 90 metros.
Ninguém além de você pode ver o cão, e ele é intan-
gível e invulnerável. Quando uma criatura de tamanho
Pequeno ou maior se aproxima a 9 metros dele sem an-
tes falar a senha que você especificou ao conjurar essa
magia, o cão começa a latir alto. O cão possui Visão
Verdadeira com alcance de 9 metros.
No início de cada um dos seus turnos, o cão tenta
morder um inimigo a até 1,5 metro dele. Esse inimigo
deve ser bem-sucedido em uma salvaguarda de Destre-
za ou sofre 4d8 pontos de dano Energético.
Nos seus turnos subsequentes, você pode executar
uma ação Usar Magia para mover o cão até 9 metros.',14,'Invocação (Mago)','{"level":"4","name":"Cão Fiel de Mordenkainen","school":[{"text":"Invocação (Mago)","top":306.6612,"prose":true,"stat":false,"head":false,"page":14,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":322.32719999999995,"prose":false,"stat":false,"head":false,"page":14,"col":0}],"Alcance":[{"text":"9 metros","top":334.2272,"prose":false,"stat":false,"head":false,"page":14,"col":0}],"Componentes":[{"text":"V, S, M (um apito de prata)","top":346.12719999999996,"prose":false,"stat":false,"head":false,"page":14,"col":0}],"Duração":[{"text":"8 horas","top":358.02719999999994,"prose":false,"stat":false,"head":false,"page":14,"col":0}]},"desc":[{"text":"Você conjura um cão de guarda fantasmagórico em um","top":376.0825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"espaço desocupado à sua vista e no alcance da magia.","top":387.9825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"O cão permanece pela duração magia ou até que vocês","top":399.8825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"dois estejam separados por mais de 90 metros.","top":411.7825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Ninguém além de você pode ver o cão, e ele é intan-","top":423.6825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"gível e invulnerável. Quando uma criatura de tamanho","top":435.5825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Pequeno ou maior se aproxima a 9 metros dele sem an-","top":447.4825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"tes falar a senha que você especificou ao conjurar essa","top":459.3825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"magia, o cão começa a latir alto. O cão possui Visão","top":471.2825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Verdadeira com alcance de 9 metros.","top":483.1825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"No início de cada um dos seus turnos, o cão tenta","top":495.0825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"morder um inimigo a até 1,5 metro dele. Esse inimigo","top":506.9825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"deve ser bem-sucedido em uma salvaguarda de Destre-","top":518.8824999999999,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"za ou sofre 4d8 pontos de dano Energético.","top":530.7825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"Nos seus turnos subsequentes, você pode executar","top":542.6825,"prose":true,"stat":false,"head":false,"page":14,"col":0},{"text":"uma ação Usar Magia para mover o cão até 9 metros.","top":554.5825,"prose":true,"stat":false,"head":false,"page":14,"col":0}],"page":14}');
