INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(55,'Chicote de Espinhos','chicote de espinhos',0,5,1,'V, S, M (o caule de uma planta espinhosa)','Ação','9 metros','Instantânea','Você cria um chicote semelhante a uma videira cober-
to de espinhos que ataca ao seu comando em direção a
uma criatura no alcance da magia. Realize um ataque
mágico corpo a corpo contra o alvo. Em caso de acer-
to, o alvo sofre 1d6 pontos de dano Perfurante e, se for
Grande ou menor, você pode puxá-lo até 3 metros mais
perto de você.
Aprimoramento de Truque. O dano aumenta em 1d6
quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).',15,'Transmutação (Druida)','{"level":"0","name":"Chicote de Espinhos","school":[{"text":"Transmutação (Druida)","top":677.5676,"prose":true,"stat":false,"head":false,"page":15,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":693.2335,"prose":false,"stat":false,"head":false,"page":15,"col":0}],"Alcance":[{"text":"9 metros","top":705.1335,"prose":false,"stat":false,"head":false,"page":15,"col":0}],"Componentes":[{"text":"V, S, M (o caule de uma planta espinhosa)","top":717.0335,"prose":false,"stat":false,"head":false,"page":15,"col":0}],"Duração":[{"text":"Instantânea","top":728.9335,"prose":false,"stat":false,"head":false,"page":15,"col":0}]},"desc":[{"text":"Você cria um chicote semelhante a uma videira cober-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"to de espinhos que ataca ao seu comando em direção a","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"uma criatura no alcance da magia. Realize um ataque","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"mágico corpo a corpo contra o alvo. Em caso de acer-","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"to, o alvo sofre 1d6 pontos de dano Perfurante e, se for","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"Grande ou menor, você pode puxá-lo até 3 metros mais","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"perto de você.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"Aprimoramento de Truque. O dano aumenta em 1d6","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":15,"col":1}],"page":15}');
