INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(57,'Círculo da Morte','circulo da morte',6,2,1,'V, S, M (o pó de uma pérola negra esmagada
no valor de 500 ou mais PO)','Ação','45 metros','Instantânea','Uma Esfera de 18 metros de raio de energia negativa
parte de um ponto à sua escolha no alcance da magia.
Cada criatura nessa área realiza uma salvaguarda de
Constituição, sofrendo 8d8 pontos de dano Necrótico
se falhar ou metade desse dano em caso de sucesso.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 2d8 para cada círculo de espaço de
magia acima de 6.',15,'Necromancia (Bruxo, Feiticeiro, Mago)','{"level":"6","name":"Círculo da Morte","school":[{"text":"Necromancia (Bruxo, Feiticeiro, Mago)","top":408.3866,"prose":true,"stat":false,"head":false,"page":15,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":424.05249999999995,"prose":false,"stat":false,"head":false,"page":15,"col":1}],"Alcance":[{"text":"45 metros","top":435.9525,"prose":false,"stat":false,"head":false,"page":15,"col":1}],"Componentes":[{"text":"V, S, M (o pó de uma pérola negra esmagada","top":447.85249999999996,"prose":false,"stat":false,"head":false,"page":15,"col":1},{"text":"no valor de 500 ou mais PO)","top":459.75249999999994,"prose":false,"stat":false,"head":false,"page":15,"col":1}],"Duração":[{"text":"Instantânea","top":471.6525,"prose":false,"stat":false,"head":false,"page":15,"col":1}]},"desc":[{"text":"Uma Esfera de 18 metros de raio de energia negativa","top":489.7078,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"parte de um ponto à sua escolha no alcance da magia.","top":501.6078,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"Cada criatura nessa área realiza uma salvaguarda de","top":513.5078000000001,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"Constituição, sofrendo 8d8 pontos de dano Necrótico","top":525.4078,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"se falhar ou metade desse dano em caso de sucesso.","top":537.3078,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":549.2077999999999,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"dano aumenta em 2d8 para cada círculo de espaço de","top":561.1078,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"magia acima de 6.","top":573.0078,"prose":true,"stat":false,"head":false,"page":15,"col":1}],"page":15}');
