INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(58,'Círculo de Poder','circulo de poder',5,3,1,'V','Ação','Pessoal','Concentração, até 10 minutos','Uma aura irradia de você em uma Emanação de 9 me-
tros pela duração da magia. Enquanto estiver na aura,
você e seus aliados têm Vantagem em salvaguardas
contra magias e outros efeitos mágicos. Quando uma
criatura afetada realiza uma salvaguarda contra uma
magia ou efeito mágico que permite que sofra apenas
metade do dano, ela não sofre dano em caso de sucesso.',15,'Abjuração (Clérigo, Mago, Paladino)','{"level":"5","name":"Círculo de Poder","school":[{"text":"Abjuração (Clérigo, Mago, Paladino)","top":617.2117,"prose":true,"stat":false,"head":false,"page":15,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":632.8777,"prose":false,"stat":false,"head":false,"page":15,"col":1}],"Alcance":[{"text":"Pessoal","top":644.7777,"prose":false,"stat":false,"head":false,"page":15,"col":1}],"Componentes":[{"text":"V","top":656.6777,"prose":false,"stat":false,"head":false,"page":15,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":668.5777,"prose":false,"stat":false,"head":false,"page":15,"col":1}]},"desc":[{"text":"Uma aura irradia de você em uma Emanação de 9 me-","top":686.633,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"tros pela duração da magia. Enquanto estiver na aura,","top":698.533,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"você e seus aliados têm Vantagem em salvaguardas","top":710.433,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"contra magias e outros efeitos mágicos. Quando uma","top":722.333,"prose":true,"stat":false,"head":false,"page":15,"col":1},{"text":"criatura afetada realiza uma salvaguarda contra uma","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"magia ou efeito mágico que permite que sofra apenas","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"metade do dano, ela não sofre dano em caso de sucesso.","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":16,"col":0}],"page":15}');
