INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(59,'Círculo de Teleporte','circulo de teleporte',5,4,1,'V, M (tintas raras no valor de 50 ou mais PO,
que a magia consome)','1 minuto','3 metros','1 rodada','Ao conjurar a magia, você desenha um círculo de 1,5
metro de raio no chão inscrito com símbolos que ligam
sua localização a um círculo de teleporte permanente à
sua escolha, cuja sequência de símbolos você conhece
e que está no mesmo plano de existência que você. Um
portal cintilante se abre dentro do círculo que você de-
senhou e permanece aberto até o final do seu próximo
turno. Qualquer criatura que entre no portal aparece
instantaneamente a 1,5 metro do círculo de destino ou
no espaço desocupado mais próximo, se esse espaço
estiver ocupado.
Muitos dos principais templos, guildas e outros lugares
importantes têm círculos de teleporte permanentes. Cada
círculo inclui uma sequência de símbolos única — uma
sequência de runas dispostas em um determinado padrão.
Ao adquirir a capacidade de conjurar essa magia pela
primeira vez, você aprende as sequências de símbolos
para dois destinos no Plano Material, escolhidos pelo
Mestre. Durante suas aventuras, é possível aprender
sequências adicionais. Você pode memorizar um novo
símbolo após estudá-lo por 1 minuto.
Você pode criar um círculo de teleporte permanente
conjurando essa magia no mesmo local todos os dias
por 365 dias.',16,'Invocação (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"5","name":"Círculo de Teleporte","school":[{"text":"Invocação (Bardo, Bruxo, Feiticeiro, Mago)","top":104.36129999999991,"prose":true,"stat":false,"head":false,"page":16,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":120.02729999999997,"prose":false,"stat":false,"head":false,"page":16,"col":0}],"Alcance":[{"text":"3 metros","top":131.92729999999995,"prose":false,"stat":false,"head":false,"page":16,"col":0}],"Componentes":[{"text":"V, M (tintas raras no valor de 50 ou mais PO,","top":143.82729999999992,"prose":false,"stat":false,"head":false,"page":16,"col":0},{"text":"que a magia consome)","top":155.7273,"prose":false,"stat":false,"head":false,"page":16,"col":0}],"Duração":[{"text":"1 rodada","top":167.6273,"prose":false,"stat":false,"head":false,"page":16,"col":0}]},"desc":[{"text":"Ao conjurar a magia, você desenha um círculo de 1,5","top":185.68259999999998,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"metro de raio no chão inscrito com símbolos que ligam","top":197.58259999999996,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"sua localização a um círculo de teleporte permanente à","top":209.48259999999993,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"sua escolha, cuja sequência de símbolos você conhece","top":221.3825999999999,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"e que está no mesmo plano de existência que você. Um","top":233.2826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"portal cintilante se abre dentro do círculo que você de-","top":245.18259999999998,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"senhou e permanece aberto até o final do seu próximo","top":257.08259999999996,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"turno. Qualquer criatura que entre no portal aparece","top":268.98259999999993,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"instantaneamente a 1,5 metro do círculo de destino ou","top":280.8826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"no espaço desocupado mais próximo, se esse espaço","top":292.7826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"estiver ocupado.","top":304.6826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"Muitos dos principais templos, guildas e outros lugares","top":316.5826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"importantes têm círculos de teleporte permanentes. Cada","top":328.4826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"círculo inclui uma sequência de símbolos única — uma","top":340.3826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"sequência de runas dispostas em um determinado padrão.","top":352.2826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"Ao adquirir a capacidade de conjurar essa magia pela","top":364.1826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"primeira vez, você aprende as sequências de símbolos","top":376.0826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"para dois destinos no Plano Material, escolhidos pelo","top":387.9826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"Mestre. Durante suas aventuras, é possível aprender","top":399.8826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"sequências adicionais. Você pode memorizar um novo","top":411.7826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"símbolo após estudá-lo por 1 minuto.","top":423.6826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"Você pode criar um círculo de teleporte permanente","top":435.5826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"conjurando essa magia no mesmo local todos os dias","top":447.4826,"prose":true,"stat":false,"head":false,"page":16,"col":0},{"text":"por 365 dias.","top":459.3826,"prose":true,"stat":false,"head":false,"page":16,"col":0}],"page":16}');
