INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(61,'Clarividência','clarividencia',3,8,1,'V, S, M (um foco no valor de 100 ou mais PO,
seja um chifre adornado com joias e usado para escutar, ou
um olho de vidro usado para enxergar)','10 minutos','1,5 km','Concentração, até 10 minutos','Você cria um sensor Invisível no alcance da magia em
um local que lhe seja familiar (um lugar que você já viu
ou visitou antes) ou em um local óbvio que não lhe seja
familiar (como atrás de uma porta, em uma esquina
ou em um bosque). O sensor não pode ser atacado e
permanece no lugar pela duração da magia.
Ao conjurar a magia, escolha ver ou ouvir. Você pode
usar o sentido escolhido através do sensor como se
estivesse em seu espaço. Como uma Ação Bônus, você
pode alternar entre ver e ouvir.
Uma criatura que veja o sensor (como uma criatura
que se beneficia de Ver o Invisível ou Visão Verdadeira)
enxerga uma esfera luminosa do tamanho do seu punho.',16,'Adivinhação (Bardo, Clérigo, Feiticeiro, Mago)','{"level":"3","name":"Clarividência","school":[{"text":"Adivinhação (Bardo, Clérigo, Feiticeiro, Mago)","top":199.56129999999996,"prose":true,"stat":false,"head":false,"page":16,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos","top":215.2273,"prose":false,"stat":false,"head":false,"page":16,"col":1}],"Alcance":[{"text":"1,5 km","top":227.1273,"prose":false,"stat":false,"head":false,"page":16,"col":1}],"Componentes":[{"text":"V, S, M (um foco no valor de 100 ou mais PO,","top":239.0272,"prose":false,"stat":false,"head":false,"page":16,"col":1},{"text":"seja um chifre adornado com joias e usado para escutar, ou","top":250.92729999999995,"prose":false,"stat":false,"head":false,"page":16,"col":1},{"text":"um olho de vidro usado para enxergar)","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":16,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":16,"col":1}]},"desc":[{"text":"Você cria um sensor Invisível no alcance da magia em","top":292.7825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"um local que lhe seja familiar (um lugar que você já viu","top":304.6825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"ou visitou antes) ou em um local óbvio que não lhe seja","top":316.5825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"familiar (como atrás de uma porta, em uma esquina","top":328.4825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"ou em um bosque). O sensor não pode ser atacado e","top":340.3825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"permanece no lugar pela duração da magia.","top":352.2825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"Ao conjurar a magia, escolha ver ou ouvir. Você pode","top":364.1825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"usar o sentido escolhido através do sensor como se","top":376.0825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"estivesse em seu espaço. Como uma Ação Bônus, você","top":387.9825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"pode alternar entre ver e ouvir.","top":399.8825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"Uma criatura que veja o sensor (como uma criatura","top":411.7825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"que se beneficia de Ver o Invisível ou Visão Verdadeira)","top":423.6825,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"enxerga uma esfera luminosa do tamanho do seu punho.","top":435.5825,"prose":true,"stat":false,"head":false,"page":16,"col":1}],"page":16}');
