INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(62,'Clone','clone',8,2,1,'V, S, M (um diamante no valor de 1.000 ou
mais PO, que a magia consome, e um recipiente vedável no
valor de 2.000 ou mais PO que seja grande o suficiente para
conter a criatura sendo clonada)','1 hora','Toque','Instantânea','Você toca uma criatura ou pelo menos 2,5 centíme-
tros cúbicos da carne dela. Uma duplicata inerte dessa
criatura se forma dentro do recipiente usado na con-
juração da magia e termina de crescer após 120 dias;
você escolhe se o clone finalizado tem a mesma idade
da criatura ou é mais nova. O clone permanece inerte e
dura indefinidamente enquanto o recipiente o contém
permanecer intacto.
Se a criatura original morrer após o clone terminar
de se formar, a alma da criatura é transferida para o
clone se a alma estiver livre e disposta a retornar. O
clone é fisicamente idêntico ao original e tem a mesma
personalidade, memórias e habilidades, mas nenhum
dos equipamentos do original. Os restos originais da
criatura, se houver, tornam-se inertes e não podem
ser revividos, uma vez que a alma da criatura está em
outro lugar.',16,'Necromancia (Mago)','{"level":"8","name":"Clone","school":[{"text":"Necromancia (Mago)","top":479.7864,"prose":true,"stat":false,"head":false,"page":16,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 hora","top":495.45239999999995,"prose":false,"stat":false,"head":false,"page":16,"col":1}],"Alcance":[{"text":"Toque","top":507.35239999999993,"prose":false,"stat":false,"head":false,"page":16,"col":1}],"Componentes":[{"text":"V, S, M (um diamante no valor de 1.000 ou","top":519.2524,"prose":false,"stat":false,"head":false,"page":16,"col":1},{"text":"mais PO, que a magia consome, e um recipiente vedável no","top":531.1524,"prose":false,"stat":false,"head":false,"page":16,"col":1},{"text":"valor de 2.000 ou mais PO que seja grande o suficiente para","top":543.0524,"prose":false,"stat":false,"head":false,"page":16,"col":1},{"text":"conter a criatura sendo clonada)","top":554.9524,"prose":false,"stat":false,"head":false,"page":16,"col":1}],"Duração":[{"text":"Instantânea","top":566.8524,"prose":false,"stat":false,"head":false,"page":16,"col":1}]},"desc":[{"text":"Você toca uma criatura ou pelo menos 2,5 centíme-","top":584.9077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"tros cúbicos da carne dela. Uma duplicata inerte dessa","top":596.8077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"criatura se forma dentro do recipiente usado na con-","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"juração da magia e termina de crescer após 120 dias;","top":620.6077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"você escolhe se o clone finalizado tem a mesma idade","top":632.5077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"da criatura ou é mais nova. O clone permanece inerte e","top":644.4077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"dura indefinidamente enquanto o recipiente o contém","top":656.3077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"permanecer intacto.","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"Se a criatura original morrer após o clone terminar","top":680.1077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"de se formar, a alma da criatura é transferida para o","top":692.0077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"clone se a alma estiver livre e disposta a retornar. O","top":703.9077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"clone é fisicamente idêntico ao original e tem a mesma","top":715.8077,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"personalidade, memórias e habilidades, mas nenhum","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":16,"col":1},{"text":"dos equipamentos do original. Os restos originais da","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"criatura, se houver, tornam-se inertes e não podem","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"ser revividos, uma vez que a alma da criatura está em","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"outro lugar.","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":17,"col":0}],"page":16}');
