INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(64,'Comando','comando',1,1,1,'V','Ação','18 metros','Instantânea','Você profere uma palavra única de comando para uma
criatura à sua vista e no alcance da magia. O alvo deve
ser bem-sucedido em uma salvaguarda de Sabedoria
ou segue o comando no próximo turno dele. Escolha o
comando a partir destas opções:
Abaixar. O alvo tem a condição Caído e, em seguida,
termina o turno.
Aproximar. O alvo se move em sua direção pela rota
mais curta e direta, terminando o turno dele se ele se
mover a até 1,5 metro de você.
Fugir. O alvo usa o próprio turno se afastando de
você pelos meios mais rápidos disponíveis.
Largar. O alvo solta o que estiver segurando e, em
seguida, termina o turno.
Parar. No turno do alvo, ele não se move e não exe-
cuta nenhuma ação ou Ação Bônus.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher uma criatura adicional para cada
círculo de espaço de magia acima de 1.',17,'Encantamento (Bardo, Clérigo, Paladino)','{"level":"1","name":"Comando","school":[{"text":"Encantamento (Bardo, Clérigo, Paladino)","top":336.9865,"prose":true,"stat":false,"head":false,"page":17,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":352.6525,"prose":false,"stat":false,"head":false,"page":17,"col":0}],"Alcance":[{"text":"18 metros","top":364.55249999999995,"prose":false,"stat":false,"head":false,"page":17,"col":0}],"Componentes":[{"text":"V","top":376.4525,"prose":false,"stat":false,"head":false,"page":17,"col":0}],"Duração":[{"text":"Instantânea","top":388.35249999999996,"prose":false,"stat":false,"head":false,"page":17,"col":0}]},"desc":[{"text":"Você profere uma palavra única de comando para uma","top":406.4078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"criatura à sua vista e no alcance da magia. O alvo deve","top":418.3078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"ser bem-sucedido em uma salvaguarda de Sabedoria","top":430.2078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"ou segue o comando no próximo turno dele. Escolha o","top":442.1078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"comando a partir destas opções:","top":454.00780000000003,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Abaixar. O alvo tem a condição Caído e, em seguida,","top":465.9078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"termina o turno.","top":477.8078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Aproximar. O alvo se move em sua direção pela rota","top":489.7078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"mais curta e direta, terminando o turno dele se ele se","top":501.6078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"mover a até 1,5 metro de você.","top":513.5078000000001,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Fugir. O alvo usa o próprio turno se afastando de","top":525.4078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"você pelos meios mais rápidos disponíveis.","top":537.3078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Largar. O alvo solta o que estiver segurando e, em","top":549.2077999999999,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"seguida, termina o turno.","top":561.1078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Parar. No turno do alvo, ele não se move e não exe-","top":573.0078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"cuta nenhuma ação ou Ação Bônus.","top":584.9078,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":596.9878,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"Você pode escolher uma criatura adicional para cada","top":608.7077999999999,"prose":true,"stat":false,"head":false,"page":17,"col":0},{"text":"círculo de espaço de magia acima de 1.","top":620.6078,"prose":true,"stat":false,"head":false,"page":17,"col":0}],"page":17}');
