INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(65,'Compreender Idiomas','compreender idiomas',1,8,1,'V, S, M (uma pitada de fuligem e sal)','Ação ou Ritual','Pessoal','1 hora','Pela duração da magia, você entende o significado lite-
ral de qualquer idioma que ouça ou veja escrito. Você
também entende qualquer escrita que veja, mas deve
estar tocando a superfície na qual as palavras estão
escritas. Leva cerca de 1 minuto para ler uma página de
texto. Esta magia não decodifica símbolos ou mensa-
gens secretas.',17,'Adivinhação (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"1","name":"Compreender Idiomas","school":[{"text":"Adivinhação (Bardo, Bruxo, Feiticeiro, Mago)","top":664.8118,"prose":true,"stat":false,"head":false,"page":17,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":680.4777,"prose":false,"stat":false,"head":false,"page":17,"col":0}],"Alcance":[{"text":"Pessoal","top":692.3777,"prose":false,"stat":false,"head":false,"page":17,"col":0}],"Componentes":[{"text":"V, S, M (uma pitada de fuligem e sal)","top":704.2777,"prose":false,"stat":false,"head":false,"page":17,"col":0}],"Duração":[{"text":"1 hora","top":716.1777,"prose":false,"stat":false,"head":false,"page":17,"col":0}]},"desc":[{"text":"Pela duração da magia, você entende o significado lite-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"ral de qualquer idioma que ouça ou veja escrito. Você","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"também entende qualquer escrita que veja, mas deve","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"estar tocando a superfície na qual as palavras estão","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"escritas. Leva cerca de 1 minuto para ler uma página de","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"texto. Esta magia não decodifica símbolos ou mensa-","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"gens secretas.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":17,"col":1}],"page":17}');
