INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(67,'Comunhão','comunhao',5,8,1,'V, S, M (incenso)','1 minuto ou Ritual','Pessoal','1 minuto','Você entra em contato com uma divindade ou um
representante divino e realiza até três perguntas que
podem ser respondidas com sim ou não. Você deve re-
alizar suas perguntas antes que a magia termine. Você
recebe uma resposta correta para cada pergunta.
Os seres divinos não são necessariamente oniscien-
tes, então você pode receber “indeterminado” como
resposta se uma pergunta pertencer a informações que
estão além do conhecimento da divindade. Em um caso
em que uma resposta de uma palavra possa ser engano-
sa ou contrária aos interesses da divindade, o Mestre
pode oferecer uma frase curta como resposta.
Se você conjurar a magia mais de uma vez antes de
terminar um Descanso Longo, há uma chance cumu-
lativa de 25% para cada conjuração após a primeira de
que você não receba resposta.',17,'Adivinhação (Clérigo)','{"level":"5","name":"Comunhão","school":[{"text":"Adivinhação (Clérigo)","top":378.9171,"prose":true,"stat":false,"head":false,"page":17,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":394.58309999999994,"prose":false,"stat":false,"head":false,"page":17,"col":1}],"Alcance":[{"text":"Pessoal","top":406.4831,"prose":false,"stat":false,"head":false,"page":17,"col":1}],"Componentes":[{"text":"V, S, M (incenso)","top":418.38309999999996,"prose":false,"stat":false,"head":false,"page":17,"col":1}],"Duração":[{"text":"1 minuto","top":430.28309999999993,"prose":false,"stat":false,"head":false,"page":17,"col":1}]},"desc":[{"text":"Você entra em contato com uma divindade ou um","top":448.3384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"representante divino e realiza até três perguntas que","top":460.2384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"podem ser respondidas com sim ou não. Você deve re-","top":472.1384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"alizar suas perguntas antes que a magia termine. Você","top":484.0384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"recebe uma resposta correta para cada pergunta.","top":495.9384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"Os seres divinos não são necessariamente oniscien-","top":507.8384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"tes, então você pode receber “indeterminado” como","top":519.7384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"resposta se uma pergunta pertencer a informações que","top":531.6384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"estão além do conhecimento da divindade. Em um caso","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"em que uma resposta de uma palavra possa ser engano-","top":555.4384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"sa ou contrária aos interesses da divindade, o Mestre","top":567.3384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"pode oferecer uma frase curta como resposta.","top":579.2384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"Se você conjurar a magia mais de uma vez antes de","top":591.1384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"terminar um Descanso Longo, há uma chance cumu-","top":603.0383999999999,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"lativa de 25% para cada conjuração após a primeira de","top":614.9384,"prose":true,"stat":false,"head":false,"page":17,"col":1},{"text":"que você não receba resposta.","top":626.8384,"prose":true,"stat":false,"head":false,"page":17,"col":1}],"page":17}');
