INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(68,'Comunhão com a Natureza','comunhao com a natureza',5,8,1,'V, S','1 minuto ou Ritual','Pessoal','Instantânea','Você comunga com os espíritos da natureza adqui-
rindo conhecimento da área circundante. Ao ar livre, a
magia lhe dá conhecimento da área a até 5 quilômetros
de você. Em cavernas e outros ambientes subterrâneos
naturais, o raio é limitado a 90 metros. A magia não
funciona onde a natureza foi substituída por constru-
ções, como em castelos e povoados.
Escolha três dos seguintes fatos; você aprende esses
fatos no que se refere à área da magia:
• Localização de povoados
• Localização de portais para outros planos de
existência
• Localização de uma criatura de Nível de Desafio 10
ou maior (à escolha do Mestre) que seja Celestial,
Elemental, Feérico, Ínfero ou Morto-vivo
• O tipo mais predominante de planta, mineral ou Fera
(você escolhe sobre qual aprender)
• Localização de corpos d’água
Por exemplo, você pode determinar a localização de
um monstro poderoso na área, os locais dos corpos
d’água e os locais de quaisquer povoados.',17,'Adivinhação (Druida, Guardião)','{"level":"5","name":"Comunhão com a Natureza","school":[{"text":"Adivinhação (Druida, Guardião)","top":671.0424,"prose":true,"stat":false,"head":false,"page":17,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":686.7083,"prose":false,"stat":false,"head":false,"page":17,"col":1}],"Alcance":[{"text":"Pessoal","top":698.6083,"prose":false,"stat":false,"head":false,"page":17,"col":1}],"Componentes":[{"text":"V, S","top":710.5083,"prose":false,"stat":false,"head":false,"page":17,"col":1}],"Duração":[{"text":"Instantânea","top":722.4082999999999,"prose":false,"stat":false,"head":false,"page":17,"col":1}]},"desc":[{"text":"Você comunga com os espíritos da natureza adqui-","top":416.4988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"rindo conhecimento da área circundante. Ao ar livre, a","top":428.3988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"magia lhe dá conhecimento da área a até 5 quilômetros","top":440.2989,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"de você. Em cavernas e outros ambientes subterrâneos","top":452.1988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"naturais, o raio é limitado a 90 metros. A magia não","top":464.0988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"funciona onde a natureza foi substituída por constru-","top":475.9988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"ções, como em castelos e povoados.","top":487.8988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"Escolha três dos seguintes fatos; você aprende esses","top":499.7989,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"fatos no que se refere à área da magia:","top":511.6988,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"• Localização de povoados","top":529.2681,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"• Localização de portais para outros planos de","top":541.1681,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"existência","top":553.0681,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"• Localização de uma criatura de Nível de Desafio 10","top":564.9680999999999,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"ou maior (à escolha do Mestre) que seja Celestial,","top":576.8682,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"Elemental, Feérico, Ínfero ou Morto-vivo","top":588.7681,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"• O tipo mais predominante de planta, mineral ou Fera","top":600.6681,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"(você escolhe sobre qual aprender)","top":612.5681,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"• Localização de corpos d’água","top":624.4680999999999,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"Por exemplo, você pode determinar a localização de","top":642.0373999999999,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"um monstro poderoso na área, os locais dos corpos","top":653.9374,"prose":true,"stat":false,"head":false,"page":18,"col":0},{"text":"d’água e os locais de quaisquer povoados.","top":665.8374,"prose":true,"stat":false,"head":false,"page":18,"col":0}],"page":17}');
