INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(69,'Cone de Frio','cone de frio',5,6,1,'V, S, M (um pequeno cone de cristal ou vidro)','Ação','Pessoal','Instantânea','Você libera uma rajada de ar frio. Cada criatura em
um Cone de 18 metros originado em você realiza uma
salvaguarda de Constituição, sofrendo 8d8 pontos de
dano Gélido se falhar, ou metade desse dano em caso
de sucesso. Uma criatura morta por esta magia se tor-
na uma estátua congelada até descongelar.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 5.',18,'Evocação (Druida, Feiticeiro, Mago)','{"level":"5","name":"Cone de Frio","school":[{"text":"Evocação (Druida, Feiticeiro, Mago)","top":443.1335,"prose":true,"stat":false,"head":false,"page":18,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":458.79949999999997,"prose":false,"stat":false,"head":false,"page":18,"col":1}],"Alcance":[{"text":"Pessoal","top":470.69939999999997,"prose":false,"stat":false,"head":false,"page":18,"col":1}],"Componentes":[{"text":"V, S, M (um pequeno cone de cristal ou vidro)","top":482.59939999999995,"prose":false,"stat":false,"head":false,"page":18,"col":1}],"Duração":[{"text":"Instantânea","top":494.49949999999995,"prose":false,"stat":false,"head":false,"page":18,"col":1}]},"desc":[{"text":"Você libera uma rajada de ar frio. Cada criatura em","top":512.5547,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"um Cone de 18 metros originado em você realiza uma","top":524.4547,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"salvaguarda de Constituição, sofrendo 8d8 pontos de","top":536.3548,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"dano Gélido se falhar, ou metade desse dano em caso","top":548.2547999999999,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"de sucesso. Uma criatura morta por esta magia se tor-","top":560.1547,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"na uma estátua congelada até descongelar.","top":572.0546999999999,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":583.9548,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"dano aumenta em 1d8 para cada círculo de espaço de","top":595.8547,"prose":true,"stat":false,"head":false,"page":18,"col":1},{"text":"magia acima de 5.","top":607.7547999999999,"prose":true,"stat":false,"head":false,"page":18,"col":1}],"page":18}');
