INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(70,'Confusão','confusao',4,1,1,'V, S, M (três cascas de nozes)','Ação','27 metros','Concentração, até 1 minuto','Cada criatura em uma Esfera de 3 metros de raio cen-
trada em um ponto à sua escolha no alcance da magia
deve ser bem-sucedida em uma salvaguarda de Sabe-
doria, ou esse alvo não pode executar Ações Bônus ou
Reações, e deve jogar 1d10 no início de cada um dos
turnos dele para determinar o comportamento nesse
turno, consultando a tabela abaixo.
1d10 Comportamento para o Turno
1 O alvo não executa uma ação e usa todo o
deslocamento para se mover. Jogue 1d4 para a direção:
1, norte; 2, leste; 3, sul; ou 4, oeste.
2-6 O alvo não se move ou executa ações.
7-8 O alvo não se move e executa a ação Atacar para
realizar um ataque corpo a corpo contra uma criatura
aleatória ao alcance. Se nenhuma estiver ao alcance, o
alvo não executa nenhuma ação.
9-10 O alvo escolhe o comportamento dele.
Ao final de cada um dos turnos dele, um alvo afetado
repete a salvaguarda, encerrando a magia em caso de
sucesso.
Usando um Espaço de Magia de Círculo Superior. O
raio da Esfera aumenta em 1,5 metro para cada círculo
de espaço de magia acima de 4.',18,'Encantamento (Bardo, Druida, Feiticeiro, Mago)','{"level":"4","name":"Confusão","school":[{"text":"Encantamento (Bardo, Druida, Feiticeiro, Mago)","top":651.9586999999999,"prose":true,"stat":false,"head":false,"page":18,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":667.6247,"prose":false,"stat":false,"head":false,"page":18,"col":1}],"Alcance":[{"text":"27 metros","top":679.5246999999999,"prose":false,"stat":false,"head":false,"page":18,"col":1}],"Componentes":[{"text":"V, S, M (três cascas de nozes)","top":691.4245999999999,"prose":false,"stat":false,"head":false,"page":18,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":703.3247,"prose":false,"stat":false,"head":false,"page":18,"col":1}]},"desc":[{"text":"Cada criatura em uma Esfera de 3 metros de raio cen-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"trada em um ponto à sua escolha no alcance da magia","top":47.95729999999992,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"deve ser bem-sucedida em uma salvaguarda de Sabe-","top":59.557399999999916,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"doria, ou esse alvo não pode executar Ações Bônus ou","top":71.15729999999996,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Reações, e deve jogar 1d10 no início de cada um dos","top":82.75739999999996,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"turnos dele para determinar o comportamento nesse","top":94.35739999999998,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"turno, consultando a tabela abaixo.","top":105.95729999999992,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"1d10 Comportamento para o Turno","top":127.40750000000003,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"1 O alvo não executa uma ação e usa todo o","top":141.49069999999995,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"deslocamento para se mover. Jogue 1d4 para a direção:","top":155.99069999999995,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"1, norte; 2, leste; 3, sul; ou 4, oeste.","top":170.49069999999995,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"2-6 O alvo não se move ou executa ações.","top":184.01029999999992,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"7-8 O alvo não se move e executa a ação Atacar para","top":198.18349999999998,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"realizar um ataque corpo a corpo contra uma criatura","top":212.68349999999998,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"aleatória ao alcance. Se nenhuma estiver ao alcance, o","top":227.18349999999998,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"alvo não executa nenhuma ação.","top":241.68349999999998,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"9-10 O alvo escolhe o comportamento dele.","top":254.87649999999996,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"Ao final de cada um dos turnos dele, um alvo afetado","top":282.4898,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"repete a salvaguarda, encerrando a magia em caso de","top":294.0898,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"sucesso.","top":305.6898,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":317.2898,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"raio da Esfera aumenta em 1,5 metro para cada círculo","top":328.8898,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"de espaço de magia acima de 4.","top":340.4898,"prose":true,"stat":false,"head":false,"page":19,"col":0}],"page":18}');
