INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(71,'Consagrar','consagrar',5,3,1,'V, S, M (incenso no valor de 1.000 ou mais PO,
que a magia consome)','24 horas','Toque','Até ser dissipada','Você toca um ponto e infunde uma área ao seu redor
com poder sagrado ou profano. A área pode ter um
raio de até 18 metros, e a magia falha se o raio incluir
uma área já sob o efeito de Consagrar. A área afetada
tem os seguintes efeitos.
Vigília Consagrada. Escolha um tipo de criatura:
Aberração, Celestial, Elemental, Feérico, Ínfero ou
Morto-Vivo. Criaturas do tipo escolhido não podem
entrar voluntariamente na área, e qualquer criatura
que esteja possuída por elas, ou tem a condição Ame-
drontado ou Enfeitiçado por essas criaturas, não será
considerada possuída, nem terá as condições Ame-
drontado ou Enfeitiçado enquanto enquanto estiver na
área.
Efeito Adicional. Você vincula um efeito adicional à
área da lista abaixo:
Coragem. Criaturas de qualquer tipo que você esco-
lher não recebem a condição Amedrontado enquanto
estiverem na área.
Descanso Pacífico. Cadáveres enterrados na área
não podem ser transformados em Mortos-vivos.
Escuridão. Escuridão preenche a área. A luz normal,
bem como a luz mágica criada por magias de um círcu-
lo inferior a esta magia, não pode iluminar a área.
Idiomas. Criaturas de qualquer tipo que você escolher
podem se comunicar com qualquer outra criatura na área,
mesmo que não compartilhem um idioma em comum.
Interferência Extradimensional. Criaturas de qual-
quer tipo que você escolher não podem entrar ou sair
da área usando teleporte ou viagem interplanar.
Luz do Dia. Luz Plena preenche a área. Escuridão
mágica criada por magias de um círculo inferior a esta
magia não pode extinguir a luz.
Medo. Criaturas de qualquer tipo que você escolher
tem a condição Amedrontado enquanto estiverem na
área.
Resistência. Criaturas de qualquer tipo que você es-
colher têm Resistência a um tipo de dano à sua escolha
enquanto estiverem na área.
Silêncio. Nenhum som pode emanar de dentro da
área e nenhum som pode adentrá-la.
Vulnerabilidade. Criaturas de qualquer tipo que
você escolher têm Vulnerabilidade a um tipo de dano à
sua escolha enquanto estiverem na área.',19,'Abjuração (Clérigo)','{"level":"5","name":"Consagrar","school":[{"text":"Abjuração (Clérigo)","top":383.79380000000003,"prose":true,"stat":false,"head":false,"page":19,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"24 horas","top":399.1597,"prose":false,"stat":false,"head":false,"page":19,"col":0}],"Alcance":[{"text":"Toque","top":410.75969999999995,"prose":false,"stat":false,"head":false,"page":19,"col":0}],"Componentes":[{"text":"V, S, M (incenso no valor de 1.000 ou mais PO,","top":422.3597,"prose":false,"stat":false,"head":false,"page":19,"col":0},{"text":"que a magia consome)","top":433.95969999999994,"prose":false,"stat":false,"head":false,"page":19,"col":0}],"Duração":[{"text":"Até ser dissipada","top":445.55969999999996,"prose":false,"stat":false,"head":false,"page":19,"col":0}]},"desc":[{"text":"Você toca um ponto e infunde uma área ao seu redor","top":463.315,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"com poder sagrado ou profano. A área pode ter um","top":474.915,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"raio de até 18 metros, e a magia falha se o raio incluir","top":486.515,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"uma área já sob o efeito de Consagrar. A área afetada","top":498.115,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"tem os seguintes efeitos.","top":509.71500000000003,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Vigília Consagrada. Escolha um tipo de criatura:","top":521.315,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Aberração, Celestial, Elemental, Feérico, Ínfero ou","top":532.915,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Morto-Vivo. Criaturas do tipo escolhido não podem","top":544.515,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"entrar voluntariamente na área, e qualquer criatura","top":556.115,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"que esteja possuída por elas, ou tem a condição Ame-","top":567.7149999999999,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"drontado ou Enfeitiçado por essas criaturas, não será","top":579.3149999999999,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"considerada possuída, nem terá as condições Ame-","top":590.915,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"drontado ou Enfeitiçado enquanto enquanto estiver na","top":602.515,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"área.","top":614.115,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Efeito Adicional. Você vincula um efeito adicional à","top":625.7149999999999,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"área da lista abaixo:","top":637.3149999999999,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Coragem. Criaturas de qualquer tipo que você esco-","top":648.915,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"lher não recebem a condição Amedrontado enquanto","top":660.515,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"estiverem na área.","top":672.115,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Descanso Pacífico. Cadáveres enterrados na área","top":683.715,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"não podem ser transformados em Mortos-vivos.","top":695.315,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Escuridão. Escuridão preenche a área. A luz normal,","top":706.915,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"bem como a luz mágica criada por magias de um círcu-","top":718.515,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"lo inferior a esta magia, não pode iluminar a área.","top":730.115,"prose":true,"stat":false,"head":false,"page":19,"col":0},{"text":"Idiomas. Criaturas de qualquer tipo que você escolher","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"podem se comunicar com qualquer outra criatura na área,","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"mesmo que não compartilhem um idioma em comum.","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Interferência Extradimensional. Criaturas de qual-","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"quer tipo que você escolher não podem entrar ou sair","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"da área usando teleporte ou viagem interplanar.","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Luz do Dia. Luz Plena preenche a área. Escuridão","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"mágica criada por magias de um círculo inferior a esta","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"magia não pode extinguir a luz.","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Medo. Criaturas de qualquer tipo que você escolher","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"tem a condição Amedrontado enquanto estiverem na","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"área.","top":167.2573,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Resistência. Criaturas de qualquer tipo que você es-","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"colher têm Resistência a um tipo de dano à sua escolha","top":191.05729999999994,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"enquanto estiverem na área.","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Silêncio. Nenhum som pode emanar de dentro da","top":214.8572999999999,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"área e nenhum som pode adentrá-la.","top":226.7573,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Vulnerabilidade. Criaturas de qualquer tipo que","top":238.65729999999996,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"você escolher têm Vulnerabilidade a um tipo de dano à","top":250.55729999999994,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"sua escolha enquanto estiverem na área.","top":262.4572999999999,"prose":true,"stat":false,"head":false,"page":19,"col":1}],"page":19}');
