INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(72,'Contágio','contagio',5,2,1,'V, S','Ação','Toque','7 dias','Seu toque inflige um contágio mágico. O alvo deve ser
bem-sucedido em uma salvaguarda de Constituição ou
sofre 11d8 pontos de dano necrótico e tem a condi-
ção Envenenado. Além disso, escolha um atributo ao
conjurar a magia. Enquanto estiver envenenado, o alvo
tem Desvantagem em salvaguardas realizadas com o
atributo escolhido.
O alvo deve repetir a salvaguarda no final de cada
um dos turnos até obter três sucessos ou fracassos. Se
o alvo obtiver três sucessos, a magia encerra para o
alvo. Se obter três fracassos, a magia permanece 7 dias
sobre ele.
Sempre que o alvo Envenenado receber um efeito
que encerre a condição Envenenado, ele deve ser bem-
-sucedido em uma salvaguarda de Constituição, ou a
condição Envenenado não encerra nele.',19,'Necromancia (Clérigo, Druida)','{"level":"5","name":"Contágio","school":[{"text":"Necromancia (Clérigo, Druida)","top":306.6612,"prose":true,"stat":false,"head":false,"page":19,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":318.07519999999994,"prose":false,"stat":false,"head":false,"page":19,"col":1}],"Alcance":[{"text":"Toque","top":329.9752,"prose":false,"stat":false,"head":false,"page":19,"col":1}],"Componentes":[{"text":"V, S","top":341.87519999999995,"prose":false,"stat":false,"head":false,"page":19,"col":1}],"Duração":[{"text":"7 dias","top":353.7752,"prose":false,"stat":false,"head":false,"page":19,"col":1}]},"desc":[{"text":"Seu toque inflige um contágio mágico. O alvo deve ser","top":371.83050000000003,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"bem-sucedido em uma salvaguarda de Constituição ou","top":383.7305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"sofre 11d8 pontos de dano necrótico e tem a condi-","top":395.6305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"ção Envenenado. Além disso, escolha um atributo ao","top":407.5305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"conjurar a magia. Enquanto estiver envenenado, o alvo","top":419.4305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"tem Desvantagem em salvaguardas realizadas com o","top":431.33050000000003,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"atributo escolhido.","top":443.2305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"O alvo deve repetir a salvaguarda no final de cada","top":455.1305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"um dos turnos até obter três sucessos ou fracassos. Se","top":467.0305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"o alvo obtiver três sucessos, a magia encerra para o","top":478.9305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"alvo. Se obter três fracassos, a magia permanece 7 dias","top":490.83050000000003,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"sobre ele.","top":502.7305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Sempre que o alvo Envenenado receber um efeito","top":514.6305,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"que encerre a condição Envenenado, ele deve ser bem-","top":526.5305000000001,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"-sucedido em uma salvaguarda de Constituição, ou a","top":538.4304999999999,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"condição Envenenado não encerra nele.","top":550.3305,"prose":true,"stat":false,"head":false,"page":19,"col":1}],"page":19}');
