INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(73,'Contato Extraplanar','contato extraplanar',5,8,1,'V','1 minuto ou Ritual','Pessoal','1 minuto','Você entra em contato mentalmente com um semideus,
com o espírito de um sábio morto há muito tempo ou
com alguma outra entidade conhecedora de outro pla-
no. Entrar em contato com essa inteligência sobrenatu-
ral pode fragmentar sua mente. Ao conjurar essa magia,
realize uma salvaguarda de Inteligência CD 15.
Em caso de sucesso, você pode realizar até cinco
perguntas à entidade. Você deve realizar suas pergun-
tas antes que a magia termine. O Mestre responde a
cada pergunta com uma palavra, como “sim”, “não”,
“talvez”, “nunca”, “irrelevante” ou “indeterminado” (se
a entidade não souber a resposta à pergunta). Se a res-
posta com uma palavra for enganosa, o Mestre pode,
em vez disso, oferecer uma frase curta como resposta.
Se falhar, você sofre 6d6 pontos de dano Psíquico e
tem a condição Incapacitado até completar um Des-
canso Longo. Uma magia Restauração Maior conjurada
em você encerra esse efeito.',19,'Adivinhação (Bruxo, Mago)','{"level":"5","name":"Contato Extraplanar","school":[{"text":"Adivinhação (Bruxo, Mago)","top":594.5345,"prose":true,"stat":false,"head":false,"page":19,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":610.2004999999999,"prose":false,"stat":false,"head":false,"page":19,"col":1}],"Alcance":[{"text":"Pessoal","top":622.1004,"prose":false,"stat":false,"head":false,"page":19,"col":1}],"Componentes":[{"text":"V","top":634.0004,"prose":false,"stat":false,"head":false,"page":19,"col":1}],"Duração":[{"text":"1 minuto","top":645.9004,"prose":false,"stat":false,"head":false,"page":19,"col":1}]},"desc":[{"text":"Você entra em contato mentalmente com um semideus,","top":663.9557,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"com o espírito de um sábio morto há muito tempo ou","top":675.8557,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"com alguma outra entidade conhecedora de outro pla-","top":687.7556999999999,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"no. Entrar em contato com essa inteligência sobrenatu-","top":699.6557,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"ral pode fragmentar sua mente. Ao conjurar essa magia,","top":711.5557,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"realize uma salvaguarda de Inteligência CD 15.","top":723.4557,"prose":true,"stat":false,"head":false,"page":19,"col":1},{"text":"Em caso de sucesso, você pode realizar até cinco","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"perguntas à entidade. Você deve realizar suas pergun-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"tas antes que a magia termine. O Mestre responde a","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"cada pergunta com uma palavra, como “sim”, “não”,","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"“talvez”, “nunca”, “irrelevante” ou “indeterminado” (se","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"a entidade não souber a resposta à pergunta). Se a res-","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"posta com uma palavra for enganosa, o Mestre pode,","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"em vez disso, oferecer uma frase curta como resposta.","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"Se falhar, você sofre 6d6 pontos de dano Psíquico e","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"tem a condição Incapacitado até completar um Des-","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"canso Longo. Uma magia Restauração Maior conjurada","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"em você encerra esse efeito.","top":167.2573,"prose":true,"stat":false,"head":false,"page":20,"col":0}],"page":19}');
