INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(74,'Contingência','contingencia',6,3,1,'V, S, M (uma estatueta de si mesmo incrustada
de pedras preciosas no valor de 1.500 ou mais PO)','10 minutos','Pessoal','10 dias','Escolha uma magia de 5º círculo ou inferior que você
possa conjurar, que tenha um tempo de conjuração
de uma ação e que possa ter você como alvo. Você
conjura essa magia — chamada de magia contingente
— como parte da conjuração de Contingência, gastando
espaços de magia para ambas, mas a magia contingente
não entra em efeito. Em vez disso, ela é ativada quando
ocorre um determinado gatilho. Você descreve esse
gatilho quando conjura as duas magias. Por exemplo,
uma Contingência conjurada com Respirar na Água pode
estipular que Respirar na Água é ativada quando você é
envolvido por água ou um líquido semelhante.
A magia contingente ativa-se imediatamente após o
gatilho ocorrer pela primeira vez, quer você queira ou
não, e então a Contingência termina.
A magia contingente tem efeito apenas em você,
mesmo que normalmente possa ter como alvo outros.
Você pode usar apenas uma magia Contingência por
vez. Se você conjurar esta magia novamente, o efeito
de outra magia Contingência em você encerra. Além
disso, a Contingência encerra em você se o componente
material da magia não estiver em sua pessoa.',20,'Abjuração (Mago)','{"level":"6","name":"Contingência","school":[{"text":"Abjuração (Mago)","top":211.46119999999996,"prose":true,"stat":false,"head":false,"page":20,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":20,"col":0}],"Alcance":[{"text":"Pessoal","top":239.0272,"prose":false,"stat":false,"head":false,"page":20,"col":0}],"Componentes":[{"text":"V, S, M (uma estatueta de si mesmo incrustada","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":20,"col":0},{"text":"de pedras preciosas no valor de 1.500 ou mais PO)","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":20,"col":0}],"Duração":[{"text":"10 dias","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":20,"col":0}]},"desc":[{"text":"Escolha uma magia de 5º círculo ou inferior que você","top":292.7825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"possa conjurar, que tenha um tempo de conjuração","top":304.6825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"de uma ação e que possa ter você como alvo. Você","top":316.5825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"conjura essa magia — chamada de magia contingente","top":328.4825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"— como parte da conjuração de Contingência, gastando","top":340.3825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"espaços de magia para ambas, mas a magia contingente","top":352.2825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"não entra em efeito. Em vez disso, ela é ativada quando","top":364.1825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"ocorre um determinado gatilho. Você descreve esse","top":376.0825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"gatilho quando conjura as duas magias. Por exemplo,","top":387.9825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"uma Contingência conjurada com Respirar na Água pode","top":399.8825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"estipular que Respirar na Água é ativada quando você é","top":411.7825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"envolvido por água ou um líquido semelhante.","top":423.6825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"A magia contingente ativa-se imediatamente após o","top":435.5825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"gatilho ocorrer pela primeira vez, quer você queira ou","top":447.4825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"não, e então a Contingência termina.","top":459.3825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"A magia contingente tem efeito apenas em você,","top":471.2825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"mesmo que normalmente possa ter como alvo outros.","top":483.1825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"Você pode usar apenas uma magia Contingência por","top":495.0825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"vez. Se você conjurar esta magia novamente, o efeito","top":506.9825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"de outra magia Contingência em você encerra. Além","top":518.8824999999999,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"disso, a Contingência encerra em você se o componente","top":530.7825,"prose":true,"stat":false,"head":false,"page":20,"col":0},{"text":"material da magia não estiver em sua pessoa.","top":542.6825,"prose":true,"stat":false,"head":false,"page":20,"col":0}],"page":20}');
