INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(75,'Contramagia','contramagia',3,3,1,'S','Reação, que você executa quando vê
uma criatura a até 18 metros de você conjurando uma
magia com componentes Verbais, Somáticos ou Materiais','18 metros','Instantânea','Você tenta interromper uma criatura no processo de
conjurar uma magia. A criatura realiza uma salvaguar-
da de Constituição. Se falhar, a magia se dissipa sem
efeito, e a ação, Ação Bônus ou Reação usada para
conjurá-la é desperdiçada. Se a magia do alvo foi con-
jurada com um espaço de magia, o espaço de magia da
criatura não é gasto.',20,'Abjuração (Bruxo, Feiticeiro, Mago)','{"level":"3","name":"Contramagia","school":[{"text":"Abjuração (Bruxo, Feiticeiro, Mago)","top":586.8864,"prose":true,"stat":false,"head":false,"page":20,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Reação, que você executa quando vê","top":602.5524,"prose":false,"stat":false,"head":false,"page":20,"col":0},{"text":"uma criatura a até 18 metros de você conjurando uma","top":614.4524,"prose":false,"stat":false,"head":false,"page":20,"col":0},{"text":"magia com componentes Verbais, Somáticos ou Materiais","top":626.3524,"prose":false,"stat":false,"head":false,"page":20,"col":0}],"Alcance":[{"text":"18 metros","top":638.2524,"prose":false,"stat":false,"head":false,"page":20,"col":0}],"Componentes":[{"text":"S","top":650.1524,"prose":false,"stat":false,"head":false,"page":20,"col":0}],"Duração":[{"text":"Instantânea","top":662.0524,"prose":false,"stat":false,"head":false,"page":20,"col":0}]},"desc":[{"text":"Você tenta interromper uma criatura no processo de","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":20,"col":1},{"text":"conjurar uma magia. A criatura realiza uma salvaguar-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":20,"col":1},{"text":"da de Constituição. Se falhar, a magia se dissipa sem","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":20,"col":1},{"text":"efeito, e a ação, Ação Bônus ou Reação usada para","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":20,"col":1},{"text":"conjurá-la é desperdiçada. Se a magia do alvo foi con-","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":20,"col":1},{"text":"jurada com um espaço de magia, o espaço de magia da","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":20,"col":1},{"text":"criatura não é gasto.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":20,"col":1}],"page":20}');
