INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(77,'Controlar o Clima','controlar o clima',8,5,1,'V, S, M (um incenso aceso)','10 minutos','Pessoal','Concentração, até 8 horas','Você assume o controle do clima a até 8 quilômetros
de você pela duração da magia. Você deve estar ao ar
livre para conjurar esta magia, e ela encerra se você for
para áreas internas.
Ao conjurar a magia, você altera a condição climática
atual, determinada pelo Mestre. Você pode alterar a
precipitação, a temperatura e o vento. Leva 1d4 x 10
minutos para as novas condições do clima entrarem em
vigor. Depois que elas se estabelecerem, você pode alte-
rar as condições novamente. Quando a magia termina,
o clima volta gradualmente ao normal.
Ao alterar as condições meteorológicas, encontre
uma condição atual nas tabelas a seguir e altere o está-
gio em um, para cima ou para baixo. Ao mudar o vento,
você pode alterar a direção dele.
Precipitação
Estágio Condição
1 Limpo
2 Nuvens leves
3 Nublado ou com neblina
4 Chuva, granizo ou neve
5 Chuva torrencial, tempestade de granizo ou nevasca
Temperatura Vento
Estágio Condição Estágio Condição
1 Calor insuportável 1 Calmo
2 Quente 2 Vento moderado
3 Ameno 3 Vento forte
4 Fresco 4 Vendaval
5 Frio 5 Tempestade
6 Frio extremo',21,'Transmutação (Clérigo, Druida, Mago)','{"level":"8","name":"Controlar o Clima","school":[{"text":"Transmutação (Clérigo, Druida, Mago)","top":498.18850000000003,"prose":true,"stat":false,"head":false,"page":21,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos","top":513.8543999999999,"prose":false,"stat":false,"head":false,"page":21,"col":0}],"Alcance":[{"text":"Pessoal","top":525.7544,"prose":false,"stat":false,"head":false,"page":21,"col":0}],"Componentes":[{"text":"V, S, M (um incenso aceso)","top":537.6544,"prose":false,"stat":false,"head":false,"page":21,"col":0}],"Duração":[{"text":"Concentração, até 8 horas","top":549.5544,"prose":false,"stat":false,"head":false,"page":21,"col":0}]},"desc":[{"text":"Você assume o controle do clima a até 8 quilômetros","top":567.6097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"de você pela duração da magia. Você deve estar ao ar","top":579.5097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"livre para conjurar esta magia, e ela encerra se você for","top":591.4096999999999,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"para áreas internas.","top":603.3097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"Ao conjurar a magia, você altera a condição climática","top":615.2097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"atual, determinada pelo Mestre. Você pode alterar a","top":627.1097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"precipitação, a temperatura e o vento. Leva 1d4 x 10","top":639.0097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"minutos para as novas condições do clima entrarem em","top":650.9096999999999,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"vigor. Depois que elas se estabelecerem, você pode alte-","top":662.8097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"rar as condições novamente. Quando a magia termina,","top":674.7097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"o clima volta gradualmente ao normal.","top":686.6097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"Ao alterar as condições meteorológicas, encontre","top":698.5097,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"uma condição atual nas tabelas a seguir e altere o está-","top":710.4096999999999,"prose":true,"stat":false,"head":false,"page":21,"col":0},{"text":"gio em um, para cima ou para baixo. Ao mudar o vento,","top":382.5845,"prose":true,"stat":false,"head":false,"page":21,"col":1},{"text":"você pode alterar a direção dele.","top":394.4845,"prose":true,"stat":false,"head":false,"page":21,"col":1},{"text":"Precipitação","top":414.2335,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"Estágio Condição","top":430.4077,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"1 Limpo","top":444.49089999999995,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"2 Nuvens leves","top":458.66409999999996,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"3 Nublado ou com neblina","top":472.83739999999995,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"4 Chuva, granizo ou neve","top":487.01059999999995,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"5 Chuva torrencial, tempestade de granizo ou nevasca","top":501.18379999999996,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"Temperatura Vento","top":525.346,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"Estágio Condição Estágio Condição","top":541.5201999999999,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"1 Calor insuportável 1 Calmo","top":555.6034999999999,"prose":false,"stat":false,"head":false,"page":21,"col":1},{"text":"2 Quente 2 Vento moderado","top":569.7767,"prose":false,"stat":false,"head":false,"page":21,"col":1}