INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(80,'Convocar Familiar','convocar familiar',1,4,1,'V, S, M (incenso queimando no valor de 10 ou
mais PO, que a magia consome)','1 hora ou Ritual','3 metros','Instantânea','Você adquire o serviço de um familiar, um espírito que
assume uma forma animal que você escolhe: Aranha,
Coruja, Corvo, Doninha, Falcão, Gato, Lagarto, Mor-
cego, Polvo, Rato, Sapo ou outra Fera que tenha um
Nível de Desafio 0. Aparecendo em um espaço desocu-
pado no alcance da magia, o familiar tem as estatísticas
da forma escolhida (veja o apêndice B), embora seja
um Celestial, Feérico ou Ínfero (à sua escolha) em vez
de uma Fera. Seu familiar age independentemente de
você, mas obedece aos seus comandos.
Conexão Telepática. Enquanto seu familiar estiver
a até 30 metros de você, você pode se comunicar
telepaticamente com ele. Além disso, como uma Ação
Bônus, você pode ver através dos olhos do familiar e
ouvir o que ele ouve até o início do seu próximo turno,
obtendo os benefícios de quaisquer sentidos especiais
que ele tenha.
Por fim, ao conjurar uma magia com um alcance de
toque, seu familiar pode entregar o toque. Seu familiar
deve estar a até 30 metros de você, e ele deve executar
uma Reação para entregar o toque quando você conju-
rar a magia.
Combate. O familiar é um aliado seu e de seus
aliados. Ele joga a Iniciativa dele e age no turno dele.
Um familiar não pode atacar, mas pode realizar outras
ações normalmente.
Desaparecimento do Familiar. Quando o familiar é
reduzido a 0 Pontos de Vida, ele desaparece. Ele rea-
parece depois que você conjura esta magia novamente.
Como uma ação Usar Magia, você pode descartar
temporariamente o familiar para uma mini dimensão.
Como alternativa, você pode descartá-lo para sempre.
Como uma ação Usar Magia enquanto está tempo-
rariamente descartado, você pode fazer com que ele
reapareça em um espaço desocupado a até 9 metros de
você. Sempre que o familiar é reduzido a 0 Pontos de
Vida ou desaparece na mini dimensão, ele deixa para
trás no espaço que ocupava qualquer coisa que estives-
se vestindo ou carregando.
Apenas um Familiar. Você não pode ter mais de um
familiar ao mesmo tempo. Ao conjurar esta magia
enquanto você tem um familiar, você faz com que ele
adote uma nova forma elegível.',23,'Invocação (Mago)','{"level":"1","name":"Convocar Familiar","school":[{"text":"Invocação (Mago)","top":303.9369,"prose":true,"stat":false,"head":false,"page":23,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 hora ou Ritual","top":319.6029,"prose":false,"stat":false,"head":false,"page":23,"col":1}],"Alcance":[{"text":"3 metros","top":331.50289999999995,"prose":false,"stat":false,"head":false,"page":23,"col":1}],"Componentes":[{"text":"V, S, M (incenso queimando no valor de 10 ou","top":343.40279999999996,"prose":false,"stat":false,"head":false,"page":23,"col":1},{"text":"mais PO, que a magia consome)","top":355.30279999999993,"prose":false,"stat":false,"head":false,"page":23,"col":1}],"Duração":[{"text":"Instantânea","top":367.20279999999997,"prose":false,"stat":false,"head":false,"page":23,"col":1}]},"desc":[{"text":"Você adquire o serviço de um familiar, um espírito que","top":385.2581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"assume uma forma animal que você escolhe: Aranha,","top":397.1581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Coruja, Corvo, Doninha, Falcão, Gato, Lagarto, Mor-","top":409.23810000000003,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"cego, Polvo, Rato, Sapo ou outra Fera que tenha um","top":420.95820000000003,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Nível de Desafio 0. Aparecendo em um espaço desocu-","top":432.8581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"pado no alcance da magia, o familiar tem as estatísticas","top":444.7581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"da forma escolhida (veja o apêndice B), embora seja","top":456.6581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"um Celestial, Feérico ou Ínfero (à sua escolha) em vez","top":468.5581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"de uma Fera. Seu familiar age independentemente de","top":480.45820000000003,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"você, mas obedece aos seus comandos.","top":492.3581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Conexão Telepática. Enquanto seu familiar estiver","top":504.2581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"a até 30 metros de você, você pode se comunicar","top":516.1581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"telepaticamente com ele. Além disso, como uma Ação","top":528.0581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Bônus, você pode ver através dos olhos do familiar e","top":539.9581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"ouvir o que ele ouve até o início do seu próximo turno,","top":551.8580999999999,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"obtendo os benefícios de quaisquer sentidos especiais","top":563.7582,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"que ele tenha.","top":575.6581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Por fim, ao conjurar uma magia com um alcance de","top":587.5581999999999,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"toque, seu familiar pode entregar o toque. Seu familiar","top":599.4581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"deve estar a até 30 metros de você, e ele deve executar","top":611.3580999999999,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"uma Reação para entregar o toque quando você conju-","top":623.2582,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"rar a magia.","top":635.1581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Combate. O familiar é um aliado seu e de seus","top":647.0581999999999,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"aliados. Ele joga a Iniciativa dele e age no turno dele.","top":658.9581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Um familiar não pode atacar, mas pode realizar outras","top":670.8581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"ações normalmente.","top":682.7582,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Desaparecimento do Familiar. Quando o familiar é","top":694.6581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"reduzido a 0 Pontos de Vida, ele desaparece. Ele rea-","top":706.5581999999999,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"parece depois que você conjura esta magia novamente.","top":718.4581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"Como uma ação Usar Magia, você pode descartar","top":730.3581,"prose":true,"stat":false,"head":false,"page":23,"col":1},{"text":"temporariamente o familiar para uma mini dimensão.","top":316.3444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"Como alternativa, você pode descartá-lo para sempre.","top":328.2444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"Como uma ação Usar Magia enquanto está tempo-","top":340.1444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"rariamente descartado, você pode fazer com que ele","top":352.0444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"reapareça em um espaço desocupado a até 9 metros de","top":363.94440000000003,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"você. Sempre que o familiar é reduzido a 0 Pontos de","top":375.8444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"Vida ou desaparece na mini dimensão, ele deixa para","top":387.7444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"trás no espaço que ocupava qualquer coisa que estives-","top":399.6444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"se vestindo ou carregando.","top":411.5444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"Apenas um Familiar. Você não pode ter mais de um","top":423.44440000000003,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"familiar ao mesmo tempo. Ao conjurar esta magia","top":435.3444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"enquanto você tem um familiar, você faz com que ele","top":447.2444,"prose":true,"stat":false,"head":false,"page":24,"col":0},{"text":"adote uma nova forma elegível.","top":459.1444,"prose":true,"stat":false,"head":false,"page":24,"col":0}],"page":23}');
