INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(83,'Convocar Relâmpagos','convocar relampagos',3,4,1,'V, S','Ação','36 metros','Concentração, até 10 minutos','Uma nuvem de tempestade aparece em um ponto no
alcance da magia à sua vista acima de você. A nuvem
tem a forma de um Cilindro com 3 metros de altura e
um raio de 18 metros.
Ao conjurar a magia, escolha um ponto à sua vista
sob a nuvem. Um relâmpago é disparado da nuvem até
aquele ponto. Cada criatura a até 1,5 metro desse pon-
to realiza uma salvaguarda de Destreza, sofrendo 3d10
pontos de dano Elétrico se falhar ou metade desse
dano em caso de sucesso.
Até que a magia termine, você pode executar uma
ação Usar Magia para invocar relâmpagos desse modo
novamente, escolhendo o mesmo ponto ou um diferente.
Se o conjurador estiver ao ar livre durante uma tem-
pestade ao conjurar esta magia, ele passa a controlar a
tempestade existente em vez de criar uma nova. Nessas
condições, o dano da magia é aumentado em 1d10.
Usando um Espaço de Magia de Círculo Superior. O
dano é aumentado em 1d10 pontos para cada círculo
de espaço de magia acima de 3.',25,'Invocação (Druida)','{"level":"3","name":"Convocar Relâmpagos","school":[{"text":"Invocação (Druida)","top":339.8614,"prose":true,"stat":false,"head":false,"page":25,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":355.42729999999995,"prose":false,"stat":false,"head":false,"page":25,"col":1}],"Alcance":[{"text":"36 metros","top":367.22729999999996,"prose":false,"stat":false,"head":false,"page":25,"col":1}],"Componentes":[{"text":"V, S","top":379.02729999999997,"prose":false,"stat":false,"head":false,"page":25,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":390.8273,"prose":false,"stat":false,"head":false,"page":25,"col":1}]},"desc":[{"text":"Uma nuvem de tempestade aparece em um ponto no","top":408.7826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"alcance da magia à sua vista acima de você. A nuvem","top":420.5826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"tem a forma de um Cilindro com 3 metros de altura e","top":432.3826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"um raio de 18 metros.","top":444.1826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"Ao conjurar a magia, escolha um ponto à sua vista","top":455.9826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"sob a nuvem. Um relâmpago é disparado da nuvem até","top":467.7826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"aquele ponto. Cada criatura a até 1,5 metro desse pon-","top":479.5826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"to realiza uma salvaguarda de Destreza, sofrendo 3d10","top":491.3826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"pontos de dano Elétrico se falhar ou metade desse","top":503.1826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"dano em caso de sucesso.","top":514.9826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"Até que a magia termine, você pode executar uma","top":526.7826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"ação Usar Magia para invocar relâmpagos desse modo","top":538.5826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"novamente, escolhendo o mesmo ponto ou um diferente.","top":550.3825999999999,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"Se o conjurador estiver ao ar livre durante uma tem-","top":562.1826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"pestade ao conjurar esta magia, ele passa a controlar a","top":573.9826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"tempestade existente em vez de criar uma nova. Nessas","top":585.7826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"condições, o dano da magia é aumentado em 1d10.","top":597.5826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":609.3825999999999,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"dano é aumentado em 1d10 pontos para cada círculo","top":621.1826,"prose":true,"stat":false,"head":false,"page":25,"col":1},{"text":"de espaço de magia acima de 3.","top":632.9826,"prose":true,"stat":false,"head":false,"page":25,"col":1}],"page":25}');
