INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(84,'Corda Extradimensional','corda extradimensional',2,5,1,'V, S, M (um pedaço de corda)','Ação','Toque','1 hora','Você toca uma corda. Uma extremidade dela paira
para cima até que a corda fique perpendicular ao chão
ou alcance um teto. Na extremidade superior da corda,
um portal Invisível de 1 metro por 1,5 metro se abre
para um espaço extradimensional que permanece até
que a magia termine. Esse espaço pode ser alcançado
escalando a corda, que pode ser puxada para dentro ou
para fora dele.
O espaço pode conter até oito criaturas Médias ou
menores. Ataques, magias e outros efeitos não podem
passar para dentro ou para fora do espaço, mas as cria-
turas dentro dele podem ver através do portal. Qualquer
coisa dentro do espaço cai quando a magia termina.',25,'Transmutação (Mago)','{"level":"2","name":"Corda Extradimensional","school":[{"text":"Transmutação (Mago)","top":676.8865,"prose":true,"stat":false,"head":false,"page":25,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":692.4525,"prose":false,"stat":false,"head":false,"page":25,"col":1}],"Alcance":[{"text":"Toque","top":704.2524999999999,"prose":false,"stat":false,"head":false,"page":25,"col":1}],"Componentes":[{"text":"V, S, M (um pedaço de corda)","top":716.0525,"prose":false,"stat":false,"head":false,"page":25,"col":1}],"Duração":[{"text":"1 hora","top":727.8525,"prose":false,"stat":false,"head":false,"page":25,"col":1}]},"desc":[{"text":"Você toca uma corda. Uma extremidade dela paira","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"para cima até que a corda fique perpendicular ao chão","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"ou alcance um teto. Na extremidade superior da corda,","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"um portal Invisível de 1 metro por 1,5 metro se abre","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"para um espaço extradimensional que permanece até","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"que a magia termine. Esse espaço pode ser alcançado","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"escalando a corda, que pode ser puxada para dentro ou","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"para fora dele.","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"O espaço pode conter até oito criaturas Médias ou","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"menores. Ataques, magias e outros efeitos não podem","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"passar para dentro ou para fora do espaço, mas as cria-","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"turas dentro dele podem ver através do portal. Qualquer","top":167.2573,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"coisa dentro do espaço cai quando a magia termina.","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":26,"col":0}],"page":25}');
