INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(85,'Cordão de Flechas','cordao de flechas',2,5,1,'V, S, M (uma trança ornamental)','Ação','Toque','8 horas','Toque até quatro flechas ou virotes não mágicas e
finque-os no chão em seu espaço. Até que a magia
termine, a munição não pode ser retirada fisicamente.
Sempre que uma criatura que não seja você entrar em
um espaço a até 9 metros da munição pela primeira vez
ou terminar o turno dela lá, uma das peças de munição
voa para atingi-la. A criatura deve ser bem-sucedida
em uma salvaguarda de Destreza ou sofre 2d4 pontos
de dano Perfurante. A munição é então destruída. A
magia termina quando nenhuma munição permanecer
fincada no chão.
Ao conjurar esta magia, você pode designar quais-
quer criaturas que escolher, e a magia as ignora.
Usando um Espaço de Magia de Círculo Superior. A
quantidade de munição que pode ser afetada aumenta
em dois para cada círculo de espaço de magia acima de 2.',26,'Transmutação (Guardião)','{"level":"2","name":"Cordão de Flechas","school":[{"text":"Transmutação (Guardião)","top":223.36119999999994,"prose":true,"stat":false,"head":false,"page":26,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":239.0272,"prose":false,"stat":false,"head":false,"page":26,"col":0}],"Alcance":[{"text":"Toque","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":26,"col":0}],"Componentes":[{"text":"V, S, M (uma trança ornamental)","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":26,"col":0}],"Duração":[{"text":"8 horas","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":26,"col":0}]},"desc":[{"text":"Toque até quatro flechas ou virotes não mágicas e","top":292.7825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"finque-os no chão em seu espaço. Até que a magia","top":304.6825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"termine, a munição não pode ser retirada fisicamente.","top":316.5825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"Sempre que uma criatura que não seja você entrar em","top":328.4825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"um espaço a até 9 metros da munição pela primeira vez","top":340.3825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"ou terminar o turno dela lá, uma das peças de munição","top":352.2825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"voa para atingi-la. A criatura deve ser bem-sucedida","top":364.1825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"em uma salvaguarda de Destreza ou sofre 2d4 pontos","top":376.0825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"de dano Perfurante. A munição é então destruída. A","top":387.9825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"magia termina quando nenhuma munição permanecer","top":399.8825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"fincada no chão.","top":411.7825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"Ao conjurar esta magia, você pode designar quais-","top":423.6825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"quer criaturas que escolher, e a magia as ignora.","top":435.5825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. A","top":447.4825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"quantidade de munição que pode ser afetada aumenta","top":459.3825,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"em dois para cada círculo de espaço de magia acima de 2.","top":471.2825,"prose":true,"stat":false,"head":false,"page":26,"col":0}],"page":26}');
