INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(86,'Coroa da Loucura','coroa da loucura',2,1,1,'V, S','Ação','36 metros','Concentração, até 1 minuto','Uma criatura à sua vista e no alcance da magia deve
ser bem-sucedida em uma salvaguarda de Sabedoria ou
tem a condição Enfeitiçado pela duração da magia. A
criatura é bem-sucedida automaticamente se não for
Humanoide.
Uma coroa espectral aparece na cabeça do alvo
Enfeitiçado, e ele deve executar uma ação antes de se
mover em cada um de seus turnos para realizar um
ataque corpo a corpo contra uma criatura diferente
dela própria que você escolher mentalmente. O alvo
pode agir normalmente no turno dele se você não esco-
lher nenhuma criatura ou se nenhuma criatura estiver
ao alcance dele. O alvo repete a salvaguarda no final de
cada um dos turnos dele, encerrando a magia em caso
de sucesso.
Nos seus turnos subsequentes, você deve executar a
ação Usar Magia para manter o controle sobre o alvo,
ou a magia encerra.',26,'Encantamento (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"2","name":"Coroa da Loucura","school":[{"text":"Encantamento (Bardo, Bruxo, Feiticeiro, Mago)","top":515.4864,"prose":true,"stat":false,"head":false,"page":26,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":531.1524,"prose":false,"stat":false,"head":false,"page":26,"col":0}],"Alcance":[{"text":"36 metros","top":543.0524,"prose":false,"stat":false,"head":false,"page":26,"col":0}],"Componentes":[{"text":"V, S","top":554.9524,"prose":false,"stat":false,"head":false,"page":26,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":566.8524,"prose":false,"stat":false,"head":false,"page":26,"col":0}]},"desc":[{"text":"Uma criatura à sua vista e no alcance da magia deve","top":584.9077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"ser bem-sucedida em uma salvaguarda de Sabedoria ou","top":596.8077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"tem a condição Enfeitiçado pela duração da magia. A","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"criatura é bem-sucedida automaticamente se não for","top":620.6077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"Humanoide.","top":632.5077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"Uma coroa espectral aparece na cabeça do alvo","top":644.4077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"Enfeitiçado, e ele deve executar uma ação antes de se","top":656.3077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"mover em cada um de seus turnos para realizar um","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"ataque corpo a corpo contra uma criatura diferente","top":680.1077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"dela própria que você escolher mentalmente. O alvo","top":692.0077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"pode agir normalmente no turno dele se você não esco-","top":703.9077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"lher nenhuma criatura ou se nenhuma criatura estiver","top":715.8077,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"ao alcance dele. O alvo repete a salvaguarda no final de","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":26,"col":0},{"text":"cada um dos turnos dele, encerrando a magia em caso","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":26,"col":1},{"text":"de sucesso.","top":47.95729999999992,"prose":true,"stat":false,"head":false,"page":26,"col":1},{"text":"Nos seus turnos subsequentes, você deve executar a","top":59.557399999999916,"prose":true,"stat":false,"head":false,"page":26,"col":1},{"text":"ação Usar Magia para manter o controle sobre o alvo,","top":71.15729999999996,"prose":true,"stat":false,"head":false,"page":26,"col":1},{"text":"ou a magia encerra.","top":82.75739999999996,"prose":true,"stat":false,"head":false,"page":26,"col":1}],"page":26}');
