INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(90,'Criação','criacao',5,7,1,'V, S, M (um pincel)','1 minuto','9 metros','Especial','Você puxa mechas de material obscuro do Sombral
para criar um objeto no alcance da magia. É um objeto
de matéria vegetal (tecido, corda, madeira e algo
similar) ou matéria mineral (pedra, cristal, metal e algo
similar). O objeto não deve ser maior que um Cubo de
1,5 metro de lado, e deve ter a forma e ser de um mate-
rial que você já viu.
A duração da magia depende do material do objeto,
conforme mostrado na tabela Materiais. Se o objeto
for composto por vários materiais, use a duração mais
curta. Usar qualquer objeto criado por esta magia
como componente Material de outra magia faz com
que a outra magia falhe.
Materiais
Materiais Duração
Matéria vegetal 24 horas
Rocha ou cristal 12 horas
Metais preciosos 1 hora
Pedras preciosas 10 minutos
Adamantina ou mitral 1 minuto
Usando um Espaço de Magia de Círculo Superior. O
Cubo aumenta em 1,5 metro de lado para cada círculo
de espaço de magia acima de 5.',27,'Ilusão (Feiticeiro, Mago)','{"level":"5","name":"Criação","school":[{"text":"Ilusão (Feiticeiro, Mago)","top":235.26119999999992,"prose":true,"stat":false,"head":false,"page":27,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":27,"col":0}],"Alcance":[{"text":"9 metros","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":27,"col":0}],"Componentes":[{"text":"V, S, M (um pincel)","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":27,"col":0}],"Duração":[{"text":"Especial","top":286.62719999999996,"prose":false,"stat":false,"head":false,"page":27,"col":0}]},"desc":[{"text":"Você puxa mechas de material obscuro do Sombral","top":304.6825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"para criar um objeto no alcance da magia. É um objeto","top":316.5825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"de matéria vegetal (tecido, corda, madeira e algo","top":328.4825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"similar) ou matéria mineral (pedra, cristal, metal e algo","top":340.3825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"similar). O objeto não deve ser maior que um Cubo de","top":352.2825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"1,5 metro de lado, e deve ter a forma e ser de um mate-","top":364.1825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"rial que você já viu.","top":376.0825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"A duração da magia depende do material do objeto,","top":387.9825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"conforme mostrado na tabela Materiais. Se o objeto","top":399.8825,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"for composto por vários materiais, use a duração mais","top":411.7825,"pro