INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(91,'Criar Chamas','criar chamas',0,4,1,'V, S','Ação Bônus','Pessoal','10 minutos','Uma chama bruxuleante surge em sua mão e permane-
ce lá pela duração da magia. Enquanto estiver lá, a cha-
ma não emite calor, não queima nada, e emite Luz Plena
em um raio de 6 metros e Meia-luz por mais 6 metros.
A magia se encerra se você a conjurar novamente.
Até que a magia termine, você pode executar uma
ação Usar Magia para arremessar a chama em uma
criatura ou objeto a até 18 metros de você. Realize um
ataque mágico à distância. Em caso de acerto, o alvo
sofre 1d8 pontos de dano Ígneo.
Aprimoramento de Truque. O dano aumenta em 1d8
quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).',27,'Invocação (Druida)','{"level":"0","name":"Criar Chamas","school":[{"text":"Invocação (Druida)","top":650.399,"prose":true,"stat":false,"head":false,"page":27,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":666.0649999999999,"prose":false,"stat":false,"head":false,"page":27,"col":0}],"Alcance":[{"text":"Pessoal","top":677.965,"prose":false,"stat":false,"head":false,"page":27,"col":0}],"Componentes":[{"text":"V, S","top":689.865,"prose":false,"stat":false,"head":false,"page":27,"col":0}],"Duração":[{"text":"10 minutos","top":701.765,"prose":false,"stat":false,"head":false,"page":27,"col":0}]},"desc":[{"text":"Uma chama bruxuleante surge em sua mão e permane-","top":719.8203,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"ce lá pela duração da magia. Enquanto estiver lá, a cha-","top":731.7203,"prose":true,"stat":false,"head":false,"page":27,"col":0},{"text":"ma não emite calor, não queima nada, e emite Luz Plena","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"em um raio de 6 metros e Meia-luz por mais 6 metros.","top":48.057399999999916,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"A magia se encerra se você a conjurar novamente.","top":59.75739999999996,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"Até que a magia termine, você pode executar uma","top":71.45729999999992,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"ação Usar Magia para arremessar a chama em uma","top":83.15729999999996,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"criatura ou objeto a até 18 metros de você. Realize um","top":94.85739999999998,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"ataque mágico à distância. Em caso de acerto, o alvo","top":106.55739999999992,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"sofre 1d8 pontos de dano Ígneo.","top":118.25739999999996,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"Aprimoramento de Truque. O dano aumenta em 1d8","top":129.95729999999992,"prose":true,"stat":false,"head":false,"page":27,"col":1},{"text":"quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).","top":141.65729999999996,"prose":true,"stat":false,"head":false,"page":27,"col":1}],"page":27}');
