INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(95,'Criar Passagem','criar passagem',5,5,1,'V, S, M (uma pitada de sementes de gergelim)','Ação','9 metros','1 hora','Uma passagem aparece em um ponto à sua vista em
uma superfície de madeira, gesso ou pedra (como uma
parede, teto ou piso) no alcance e pela duração da
magia. Você escolhe as dimensões da abertura: até 1,5
metro de largura, 2,5 metros de altura e 6 metros de
profundidade. A passagem não cria instabilidade em
uma estrutura ao seu redor.
Quando a abertura desaparece, qualquer criatura ou
objeto ainda na passagem criada pela magia é ejetado
com segurança para um espaço desocupado mais pró-
ximo da superfície na qual você conjurou a magia.',28,'Transmutação (Mago)','{"level":"5","name":"Criar Passagem","school":[{"text":"Transmutação (Mago)","top":449.3864,"prose":true,"stat":false,"head":false,"page":28,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":464.85239999999993,"prose":false,"stat":false,"head":false,"page":28,"col":0}],"Alcance":[{"text":"9 metros","top":476.5524,"prose":false,"stat":false,"head":false,"page":28,"col":0}],"Componentes":[{"text":"V, S, M (uma pitada de sementes de gergelim)","top":488.25239999999997,"prose":false,"stat":false,"head":false,"page":28,"col":0}],"Duração":[{"text":"1 hora","top":499.95239999999995,"prose":false,"stat":false,"head":false,"page":28,"col":0}]},"desc":[{"text":"Uma passagem aparece em um ponto à sua vista em","top":517.8077000000001,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"uma superfície de madeira, gesso ou pedra (como uma","top":529.5077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"parede, teto ou piso) no alcance e pela duração da","top":541.2076999999999,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"magia. Você escolhe as dimensões da abertura: até 1,5","top":552.9077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"metro de largura, 2,5 metros de altura e 6 metros de","top":564.6077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"profundidade. A passagem não cria instabilidade em","top":576.3077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"uma estrutura ao seu redor.","top":588.0077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"Quando a abertura desaparece, qualquer criatura ou","top":599.7076999999999,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"objeto ainda na passagem criada pela magia é ejetado","top":611.4077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"com segurança para um espaço desocupado mais pró-","top":623.1077,"prose":true,"stat":false,"head":false,"page":28,"col":0},{"text":"ximo da superfície na qual você conjurou a magia.","top":634.8077,"prose":true,"stat":false,"head":false,"page":28,"col":0}],"page":28}');
