INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(96,'Cúpula Antivida','cupula antivida',5,3,1,'V, S','Ação','Pessoal','Concentração, até 1 hora','Uma aura estende-se de você em uma Emanação de
3 metros pela duração da magia. A aura impede que
criaturas que não sejam Constructos e Mortos-Vivos
passem ou alcancem através dela. Uma criatura afetada
pode conjurar magias ou realizar ataques com armas à
Distância ou com Extensão através da barreira.
Se você se mover de modo que uma criatura afetada
seja forçada a atravessar a barreira, a magia encerra.',28,'Abjuração (Druida)','{"level":"5","name":"Cúpula Antivida","school":[{"text":"Abjuração (Druida)","top":678.4116,"prose":true,"stat":false,"head":false,"page":28,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":693.8776,"prose":false,"stat":false,"head":false,"page":28,"col":0}],"Alcance":[{"text":"Pessoal","top":705.5776,"prose":false,"stat":false,"head":false,"page":28,"col":0}],"Componentes":[{"text":"V, S","top":717.2776,"prose":false,"stat":false,"head":false,"page":28,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":729.1776,"prose":false,"stat":false,"head":false,"page":28,"col":0}]},"desc":[{"text":"Uma aura estende-se de você em uma Emanação de","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"3 metros pela duração da magia. A aura impede que","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"criaturas que não sejam Constructos e Mortos-Vivos","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"passem ou alcancem através dela. Uma criatura afetada","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"pode conjurar magias ou realizar ataques com armas à","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"Distância ou com Extensão através da barreira.","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"Se você se mover de modo que uma criatura afetada","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":28,"col":1},{"text":"seja forçada a atravessar a barreira, a magia encerra.","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":28,"col":1}],"page":28}');
