INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(101,'Danação','danacao',1,1,1,'V, S, M (o olho petrificado de uma salamandra)','Ação Bônus','27 metros','Concentração, até 1 hora','Você coloca uma maldição em uma criatura à sua vista
e no alcance da magia. Até que a magia termine, você
causa 1d6 pontos de dano Necrótico adicional ao alvo
sempre que o acertar com uma jogada de ataque. Além
disso, escolha um atributo ao conjurar a magia. O alvo
tem Desvantagem nos testes de atributo realizados
com o atributo escolhido.
Se o alvo é reduzido a 0 Pontos de Vida antes que
esta magia termine, você pode executar uma ação
Bônus em um turno posterior para amaldiçoar uma
nova criatura.
Usando um Espaço de Magia de Círculo Superior.
Sua Concentração pode durar mais com um espaço
de magia de 2º círculo (em até 4 horas), 3º–4º círculo
(em até 8 horas) ou 5º círculo ou superior (em até 24
horas).',29,'Encantamento (Bruxo)','{"level":"1","name":"Danação","school":[{"text":"Encantamento (Bruxo)","top":259.9171,"prose":true,"stat":false,"head":false,"page":29,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":275.58309999999994,"prose":false,"stat":false,"head":false,"page":29,"col":0}],"Alcance":[{"text":"27 metros","top":287.4831,"prose":false,"stat":false,"head":false,"page":29,"col":0}],"Componentes":[{"text":"V, S, M (o olho petrificado de uma salamandra)","top":299.38309999999996,"prose":false,"stat":false,"head":false,"page":29,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":311.28309999999993,"prose":false,"stat":false,"head":false,"page":29,"col":0}]},"desc":[{"text":"Você coloca uma maldição em uma criatura à sua vista","top":329.3384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"e no alcance da magia. Até que a magia termine, você","top":341.2384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"causa 1d6 pontos de dano Necrótico adicional ao alvo","top":353.1384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"sempre que o acertar com uma jogada de ataque. Além","top":365.0384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"disso, escolha um atributo ao conjurar a magia. O alvo","top":376.9384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"tem Desvantagem nos testes de atributo realizados","top":388.8384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"com o atributo escolhido.","top":400.7384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"Se o alvo é reduzido a 0 Pontos de Vida antes que","top":412.6384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"esta magia termine, você pode executar uma ação","top":424.5384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"Bônus em um turno posterior para amaldiçoar uma","top":436.4384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"nova criatura.","top":448.3384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":460.4184,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"Sua Concentração pode durar mais com um espaço","top":472.1384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"de magia de 2º círculo (em até 4 horas), 3º–4º círculo","top":484.0384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"(em até 8 horas) ou 5º círculo ou superior (em até 24","top":495.9384,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"horas).","top":507.8384,"prose":true,"stat":false,"head":false,"page":29,"col":0}],"page":29}');
