INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(102,'Dança Irresistível de Otto','danca irresistivel de otto',6,1,1,'V','Ação','9 metros','Concentração, até 1 minuto','Uma criatura à sua vista e no alcance da magia deve
realizar uma salvaguarda de Sabedoria. Em caso de
sucesso, o alvo dança comicamente até o final do pró-
ximo turno dele, durante o qual ele deve gastar todo o
movimento para dançar no mesmo lugar.
Se falhar, o alvo tem a condição Enfeitiçado pela
duração da magia. Enquanto Enfeitiçado, o alvo
dança comicamente, deve usar todo o seu movimento
para dançar no mesmo lugar e tem Desvantagem em
salvaguardas de Destreza e jogadas de ataque, e outras
criaturas têm Vantagem em jogadas de ataque contra
ele. Em cada um dos turnos do alvo, ele pode executar
uma ação para se recompor e repetir a salvaguarda,
encerrando a magia em caso de sucesso.',29,'Encantamento (Bardo, Mago)','{"level":"6","name":"Dança Irresistível de Otto","school":[{"text":"Encantamento (Bardo, Mago)","top":552.0424,"prose":true,"stat":false,"head":false,"page":29,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":567.7083,"prose":false,"stat":false,"head":false,"page":29,"col":0}],"Alcance":[{"text":"9 metros","top":579.6083,"prose":false,"stat":false,"head":false,"page":29,"col":0}],"Componentes":[{"text":"V","top":591.5083,"prose":false,"stat":false,"head":false,"page":29,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":603.4083,"prose":false,"stat":false,"head":false,"page":29,"col":0}]},"desc":[{"text":"Uma criatura à sua vista e no alcance da magia deve","top":621.4636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"realizar uma salvaguarda de Sabedoria. Em caso de","top":633.3636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"sucesso, o alvo dança comicamente até o final do pró-","top":645.2636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"ximo turno dele, durante o qual ele deve gastar todo o","top":657.1636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"movimento para dançar no mesmo lugar.","top":669.0636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"Se falhar, o alvo tem a condição Enfeitiçado pela","top":680.9636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"duração da magia. Enquanto Enfeitiçado, o alvo","top":692.8636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"dança comicamente, deve usar todo o seu movimento","top":704.7636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"para dançar no mesmo lugar e tem Desvantagem em","top":716.6636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"salvaguardas de Destreza e jogadas de ataque, e outras","top":728.5636,"prose":true,"stat":false,"head":false,"page":29,"col":0},{"text":"criaturas têm Vantagem em jogadas de ataque contra","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"ele. Em cada um dos turnos do alvo, ele pode executar","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"uma ação para se recompor e repetir a salvaguarda,","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"encerrando a magia em caso de sucesso.","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":29,"col":1}],"page":29}');
