INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(103,'De Carne para Pedra','de carne para pedra',6,5,1,'V, S, M (uma pena de cocatriz)','Ação','18 metros','Concentração, até 1 minuto','Você tenta transformar uma criatura à sua vista e no
alcance da magia em pedra. O alvo realiza uma salva-
guarda de Constituição. Se falhar, ele tem a condição
Contido pela duração da magia. Em uma salvaguarda
bem-sucedida, o Deslocamento dele é 0 até o início do
seu próximo turno. Constructos são bem-sucedidos
automaticamente na salvaguarda.
Um alvo Contido realiza outra salvaguarda de
Constituição no final de cada um dos turnos dele. Em
caso de sucesso por três vezes contra esta magia, ela
se encerra. Se falhar por três vezes, ele é transformado
em pedra e tem a condição Petrificado pela duração
da magia. Os sucessos e fracassos não precisam ser
consecutivos; acompanhe ambos até que o alvo alcance
três de um tipo.
Se você mantiver sua Concentração nesta magia por
toda a duração possível, o alvo tem a condição Petrifi-
cado até que a condição seja encerrada por Restauração
Maior ou efeito mágico semelhante.',29,'Transmutação (Druida, Feiticeiro, Mago)','{"level":"6","name":"De Carne para Pedra","school":[{"text":"Transmutação (Druida, Feiticeiro, Mago)","top":116.2613,"prose":true,"stat":false,"head":false,"page":29,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":131.92729999999995,"prose":false,"stat":false,"head":false,"page":29,"col":1}],"Alcance":[{"text":"18 metros","top":143.82729999999992,"prose":false,"stat":false,"head":false,"page":29,"col":1}],"Componentes":[{"text":"V, S, M (uma pena de cocatriz)","top":155.7273,"prose":false,"stat":false,"head":false,"page":29,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":167.6273,"prose":false,"stat":false,"head":false,"page":29,"col":1}]},"desc":[{"text":"Você tenta transformar uma criatura à sua vista e no","top":185.68259999999998,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"alcance da magia em pedra. O alvo realiza uma salva-","top":197.58259999999996,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"guarda de Constituição. Se falhar, ele tem a condição","top":209.48259999999993,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"Contido pela duração da magia. Em uma salvaguarda","top":221.3825999999999,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"bem-sucedida, o Deslocamento dele é 0 até o início do","top":233.2826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"seu próximo turno. Constructos são bem-sucedidos","top":245.18259999999998,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"automaticamente na salvaguarda.","top":257.08259999999996,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"Um alvo Contido realiza outra salvaguarda de","top":268.98259999999993,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"Constituição no final de cada um dos turnos dele. Em","top":280.8826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"caso de sucesso por três vezes contra esta magia, ela","top":292.7826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"se encerra. Se falhar por três vezes, ele é transformado","top":304.6826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"em pedra e tem a condição Petrificado pela duração","top":316.5826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"da magia. Os sucessos e fracassos não precisam ser","top":328.4826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"consecutivos; acompanhe ambos até que o alvo alcance","top":340.3826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"três de um tipo.","top":352.2826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"Se você mantiver sua Concentração nesta magia por","top":364.1826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"toda a duração possível, o alvo tem a condição Petrifi-","top":376.0826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"cado até que a condição seja encerrada por Restauração","top":387.9826,"prose":true,"stat":false,"head":false,"page":29,"col":1},{"text":"Maior ou efeito mágico semelhante.","top":399.8826,"prose":true,"stat":false,"head":false,"page":29,"col":1}],"page":29}');
