INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(105,'Defensor da Fé','defensor da fe',4,4,1,'V','Ação','9 metros','8 horas','Um defensor espectral Grande aparece e paira pela du-
ração da magia em um espaço desocupado à sua vista
e no alcance da magia. O defensor ocupa esse espaço e
não pode ser atingido, e aparece em uma forma apro-
priada para sua divindade ou panteão.
Qualquer inimigo que se mova para um espaço a até
3 metros do defensor pela primeira vez em um turno
ou inicie o turno lá realiza uma salvaguarda de Destre-
za, sofrendo 20 pontos de dano Radiante se falhar, ou
metade desse dano em caso de sucesso. O defensor de-
saparece quando causa um total de 60 pontos de dano.',29,'Invocação (Clérigo)','{"level":"4","name":"Defensor da Fé","school":[{"text":"Invocação (Clérigo)","top":641.0118,"prose":true,"stat":false,"head":false,"page":29,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":656.6777,"prose":false,"stat":false,"head":false,"page":29,"col":1}],"Alcance":[{"text":"9 metros","top":668.5777,"prose":false,"stat":false,"head":false,"page":29,"col":1}],"Componentes":[{"text":"V","top":680.4777,"prose":false,"stat":false,"head":false,"page":29,"col":1}],"Duração":[{"text":"8 horas","top":692.3777,"prose":false,"stat":false,"head":false,"page":29,"col":1}]},"desc":[{"text":"Um defensor espectral Grande aparece e paira pela du-","top":416.4988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"ração da magia em um espaço desocupado à sua vista","top":428.3988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"e no alcance da magia. O defensor ocupa esse espaço e","top":440.2989,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"não pode ser atingido, e aparece em uma forma apro-","top":452.1988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"priada para sua divindade ou panteão.","top":464.0988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"Qualquer inimigo que se mova para um espaço a até","top":475.9988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"3 metros do defensor pela primeira vez em um turno","top":487.8988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"ou inicie o turno lá realiza uma salvaguarda de Destre-","top":499.7989,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"za, sofrendo 20 pontos de dano Radiante se falhar, ou","top":511.6988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"metade desse dano em caso de sucesso. O defensor de-","top":523.5988,"prose":true,"stat":false,"head":false,"page":30,"col":0},{"text":"saparece quando causa um total de 60 pontos de dano.","top":535.4988,"prose":true,"stat":false,"head":false,"page":30,"col":0}],"page":29}');
