INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(107,'Desintegrar','desintegrar',6,5,1,'V, S, M (uma pedra-ímã e poeira)','Ação','18 metros','Instantânea','Você dispara um raio verde em um alvo à sua vista e
no alcance da magia. O alvo pode ser uma criatura, um
objeto não mágico ou uma criação de energia mágica,
como a muralha criada por Muralha de Energia.
Uma criatura alvo desta magia realiza uma salva-
guarda de Destreza. Se falhar, o alvo sofre 10d6 + 40
pontos de dano Energético. Se esse dano reduz o alvo
a 0 Pontos de Vida, ele e tudo o que não é mágico que
está usando e carregando são desintegrados em pó cin-
za. O alvo só pode ser revivido por uma magia Desejo
ou Ressurreição Verdadeira.
Esta magia desintegra automaticamente um obje-
to não mágico Grande ou menor, ou uma criação de
energia mágica. Se tal alvo for Enorme ou maior, esta
magia desintegra uma porção de um Cubo de 3 metros
de lado dele.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 3d6 para cada círculo de espaço de
magia acima de 6.',31,'Transmutação (Feiticeiro, Mago)','{"level":"6","name":"Desintegrar","school":[{"text":"Transmutação (Feiticeiro, Mago)","top":520.8612,"prose":true,"stat":false,"head":false,"page":31,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":536.5272,"prose":false,"stat":false,"head":false,"page":31,"col":0}],"Alcance":[{"text":"18 metros","top":548.4272,"prose":false,"stat":false,"head":false,"page":31,"col":0}],"Componentes":[{"text":"V, S, M (uma pedra-ímã e poeira)","top":560.3272,"prose":false,"stat":false,"head":false,"page":31,"col":0}],"Duração":[{"text":"Instantânea","top":572.2272,"prose":false,"stat":false,"head":false,"page":31,"col":0}]},"desc":[{"text":"Você dispara um raio verde em um alvo à sua vista e","top":590.2825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"no alcance da magia. O alvo pode ser uma criatura, um","top":602.1825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"objeto não mágico ou uma criação de energia mágica,","top":614.0825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"como a muralha criada por Muralha de Energia.","top":625.9825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"Uma criatura alvo desta magia realiza uma salva-","top":637.8824999999999,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"guarda de Destreza. Se falhar, o alvo sofre 10d6 + 40","top":649.7825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"pontos de dano Energético. Se esse dano reduz o alvo","top":661.6825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"a 0 Pontos de Vida, ele e tudo o que não é mágico que","top":673.5825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"está usando e carregando são desintegrados em pó cin-","top":685.4825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"za. O alvo só pode ser revivido por uma magia Desejo","top":697.3824999999999,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"ou Ressurreição Verdadeira.","top":709.2825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"Esta magia desintegra automaticamente um obje-","top":721.1825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"to não mágico Grande ou menor, ou uma criação de","top":733.0825,"prose":true,"stat":false,"head":false,"page":31,"col":0},{"text":"energia mágica. Se tal alvo for Enorme ou maior, esta","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"magia desintegra uma porção de um Cubo de 3 metros","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"de lado dele.","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"dano aumenta em 3d6 para cada círculo de espaço de","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"magia acima de 6.","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":31,"col":1}],"page":31}');
