INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(109,'Despertar','despertar',5,5,1,'V, S, M (uma ágata no valor de 1.000 ou mais
PO, que a magia consome)','8 horas','Toque','Instantânea','Você passa o tempo de conjuração traçando caminhos
mágicos em uma pedra preciosa e, em seguida, toca
o alvo. O alvo deve ser uma criatura do tipo Fera ou
Planta com uma Inteligência de 3 ou menos, ou uma
planta natural que não seja uma criatura. O alvo obtém
um valor de Inteligência de 10 e a capacidade de falar
um idioma que você conhece. Se o alvo for uma planta
natural, ele se torna uma criatura do tipo Planta e
recebe a capacidade de mover seus membros, raízes, vi-
deiras, trepadeiras e assim por diante, e obtém sentidos
semelhantes aos de um humano. O Mestre escolhe as
estatísticas apropriadas para a Planta desperta, como
as estatísticas do Arbusto Desperto ou da Árvore
Desperta no Livro dos Monstros.
O alvo desperto tem a condição Enfeitiçado por 30
dias ou até que você ou seus aliados lhe causem dano.
Quando essa condição termina, a criatura despertada
decide qual atitude tem em relação a você.',31,'Transmutação (Bardo, Druida)','{"level":"5","name":"Despertar","school":[{"text":"Transmutação (Bardo, Druida)","top":396.4865,"prose":true,"stat":false,"head":false,"page":31,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"8 horas","top":412.1525,"prose":false,"stat":false,"head":false,"page":31,"col":1}],"Alcance":[{"text":"Toque","top":424.05249999999995,"prose":false,"stat":false,"head":false,"page":31,"col":1}],"Componentes":[{"text":"V, S, M (uma ágata no valor de 1.000 ou mais","top":435.9525,"prose":false,"stat":false,"head":false,"page":31,"col":1},{"text":"PO, que a magia consome)","top":447.85249999999996,"prose":false,"stat":false,"head":false,"page":31,"col":1}],"Duração":[{"text":"Instantânea","top":459.75249999999994,"prose":false,"stat":false,"head":false,"page":31,"col":1}]},"desc":[{"text":"Você passa o tempo de conjuração traçando caminhos","top":477.8078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"mágicos em uma pedra preciosa e, em seguida, toca","top":489.7078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"o alvo. O alvo deve ser uma criatura do tipo Fera ou","top":501.6078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"Planta com uma Inteligência de 3 ou menos, ou uma","top":513.5078000000001,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"planta natural que não seja uma criatura. O alvo obtém","top":525.4078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"um valor de Inteligência de 10 e a capacidade de falar","top":537.3078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"um idioma que você conhece. Se o alvo for uma planta","top":549.2077999999999,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"natural, ele se torna uma criatura do tipo Planta e","top":561.1078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"recebe a capacidade de mover seus membros, raízes, vi-","top":573.0078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"deiras, trepadeiras e assim por diante, e obtém sentidos","top":584.9078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"semelhantes aos de um humano. O Mestre escolhe as","top":596.8078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"estatísticas apropriadas para a Planta desperta, como","top":608.7077999999999,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"as estatísticas do Arbusto Desperto ou da Árvore","top":620.6078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"Desperta no Livro dos Monstros.","top":632.5078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"O alvo desperto tem a condição Enfeitiçado por 30","top":644.4078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"dias ou até que você ou seus aliados lhe causem dano.","top":656.3078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"Quando essa condição termina, a criatura despertada","top":668.2078,"prose":true,"stat":false,"head":false,"page":31,"col":1},{"text":"decide qual atitude tem em relação a você.","top":680.1078,"prose":true,"stat":false,"head":false,"page":31,"col":1}],"page":31}');
