INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(121,'Detectar Pensamentos','detectar pensamentos',2,8,1,'V, S, M (1 Peça de Cobre)','Ação','Pessoal','Concentração, até 1 minuto','Você ativa um dos efeitos abaixo. Até que a magia ter-
mine, você pode ativar qualquer um dos efeitos como
uma ação Usar Magia em seus turnos posteriores.
Sentir Pensamentos. Você sente a presença de pensa-
mentos a até 9 metros de você que pertencem a cria-
turas que conhecem idiomas ou são telepáticas. Você
não lê os pensamentos, mas sabe o que uma criatura
presente está pensando.
A magia é bloqueada por 30 centímetros de pedra,
terra ou madeira, 2,5 centímetros de metal ou uma
folha fina de chumbo.
Ler Pensamentos. Escolha uma criatura à sua vista a
até 9 metros de você ou uma criatura a até 9 metros de
você que você tenha detectado com a opção Sentir Pen-
samentos. Você agora descobre o que mais se destaca
no pensamento do alvo. Se o alvo não souber nenhum
idioma e não for telepático, você não descobre nada.
Como uma ação Usar Magia em seu próximo turno,
você pode tentar sondar mais profundamente a mente
do alvo. Se você investigar mais profundamente, o alvo
realiza uma salvaguarda de Sabedoria. Se falhar, você
descobre o raciocínio, as emoções e algo que paira na
mente dele (como preocupação, amor ou ódio). Em
caso de sucesso, a magia encerra. De qualquer forma,
o alvo sabe que você está sondando a mente dele e, até
que você desvie sua atenção da mente do alvo, o alvo
pode executar uma ação no turno dele para realizar um
teste de Inteligência (Arcanismo) contra a CD para evi-
tar sua magia, encerrando a magia em caso de sucesso.',34,'Adivinhação (Bardo, Feiticeiro, Mago)','{"level":"2","name":"Detectar Pensamentos","school":[{"text":"Adivinhação (Bardo, Feiticeiro, Mago)","top":492.5423,"prose":true,"stat":false,"head":false,"page":34,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":508.20829999999995,"prose":false,"stat":false,"head":false,"page":34,"col":0}],"Alcance":[{"text":"Pessoal","top":520.1083,"prose":false,"stat":false,"head":false,"page":34,"col":0}],"Componentes":[{"text":"V, S, M (1 Peça de Cobre)","top":532.0083,"prose":false,"stat":false,"head":false,"page":34,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":543.9083,"prose":false,"stat":false,"head":false,"page":34,"col":0}]},"desc":[{"text":"Você ativa um dos efeitos abaixo. Até que a magia ter-","top":561.9636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"mine, você pode ativar qualquer um dos efeitos como","top":573.8636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"uma ação Usar Magia em seus turnos posteriores.","top":585.7636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"Sentir Pensamentos. Você sente a presença de pensa-","top":597.6636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"mentos a até 9 metros de você que pertencem a cria-","top":609.5636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"turas que conhecem idiomas ou são telepáticas. Você","top":621.4636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"não lê os pensamentos, mas sabe o que uma criatura","top":633.3636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"presente está pensando.","top":645.2636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"A magia é bloqueada por 30 centímetros de pedra,","top":657.1636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"terra ou madeira, 2,5 centímetros de metal ou uma","top":669.0636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"folha fina de chumbo.","top":680.9636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"Ler Pensamentos. Escolha uma criatura à sua vista a","top":692.8636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"até 9 metros de você ou uma criatura a até 9 metros de","top":704.7636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"você que você tenha detectado com a opção Sentir Pen-","top":716.6636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"samentos. Você agora descobre o que mais se destaca","top":728.5636,"prose":true,"stat":false,"head":false,"page":34,"col":0},{"text":"no pensamento do alvo. Se o alvo não souber nenhum","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"idioma e não for telepático, você não descobre nada.","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"Como uma ação Usar Magia em seu próximo turno,","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"você pode tentar sondar mais profundamente a mente","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"do alvo. Se você investigar mais profundamente, o alvo","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"realiza uma salvaguarda de Sabedoria. Se falhar, você","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"descobre o raciocínio, as emoções e algo que paira na","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"mente dele (como preocupação, amor ou ódio). Em","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"caso de sucesso, a magia encerra. De qualquer forma,","top":131.55739999999992,"prose":true,"stat":false,"