INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(123,'Disco Flutuante de Tenser','disco flutuante de tenser',1,4,1,'V, S, M (uma gota de mercúrio)','Ação ou Ritual','9 metros','1 hora','Esta magia cria um disco circular horizontal formado
de energia com 1 metro de diâmetro e 2,5 centímetros
de altura, que flutua a 1 metro do chão em um espaço
desocupado à sua escolha, à sua vista e no alcance da
magia. O disco permanece pela duração da magia e pode
carregar até 225 quilos. Se mais peso for colocado sobre
ele, a magia se encerra e tudo no disco cai no chão.
O disco fica imóvel enquanto você estiver a até 6
metros dele. Se você se mover a mais de 6 metros de
distância dele, o disco segue você, permanecendo a até
6 metros de distância. Ele pode atravessar terrenos
irregulares, subir ou descer escadas, declives e afins,
mas não pode atravessar uma mudança de elevação de
3 metros ou mais. Por exemplo, o disco não pode se
mover através de um fosso de 3 metros de profundi-
dade, nem poderia deixar tal fosso se fosse criado no
fundo dele.
Se você se mover a mais de 30 metros do disco (nor-
malmente porque ele não pode se mover em torno de
um obstáculo para segui-lo), a magia encerra.',34,'Invocação (Mago)','{"level":"1","name":"Disco Flutuante de Tenser","school":[{"text":"Invocação (Mago)","top":432.1864,"prose":true,"stat":false,"head":false,"page":34,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":447.85239999999993,"prose":false,"stat":false,"head":false,"page":34,"col":1}],"Alcance":[{"text":"9 metros","top":459.75239999999997,"prose":false,"stat":false,"head":false,"page":34,"col":1}],"Componentes":[{"text":"V, S, M (uma gota de mercúrio)","top":471.65239999999994,"prose":false,"stat":false,"head":false,"page":34,"col":1}],"Duração":[{"text":"1 hora","top":483.5524,"prose":false,"stat":false,"head":false,"page":34,"col":1}]},"desc":[{"text":"Esta magia cria um disco circular horizontal formado","top":501.6077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"de energia com 1 metro de diâmetro e 2,5 centímetros","top":513.5077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"de altura, que flutua a 1 metro do chão em um espaço","top":525.4077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"desocupado à sua escolha, à sua vista e no alcance da","top":537.3077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"magia. O disco permanece pela duração da magia e pode","top":549.2076999999999,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"carregar até 225 quilos. Se mais peso for colocado sobre","top":561.1077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"ele, a magia se encerra e tudo no disco cai no chão.","top":573.0077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"O disco fica imóvel enquanto você estiver a até 6","top":584.9077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"metros dele. Se você se mover a mais de 6 metros de","top":596.8077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"distância dele, o disco segue você, permanecendo a até","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"6 metros de distância. Ele pode atravessar terrenos","top":620.6077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"irregulares, subir ou descer escadas, declives e afins,","top":632.5077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"mas não pode atravessar uma mudança de elevação de","top":644.4077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"3 metros ou mais. Por exemplo, o disco não pode se","top":656.3077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"mover através de um fosso de 3 metros de profundi-","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"dade, nem poderia deixar tal fosso se fosse criado no","top":680.1077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"fundo dele.","top":692.0077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"Se você se mover a mais de 30 metros do disco (nor-","top":703.9077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"malmente porque ele não pode se mover em torno de","top":715.8077,"prose":true,"stat":false,"head":false,"page":34,"col":1},{"text":"um obstáculo para segui-lo), a magia encerra.","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":34,"col":1}],"page":34}');
