INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(126,'Dissipar o Bem e o Mal','dissipar o bem e o mal',5,3,1,'V, S, M (prata e ferro em pó)','Ação','Pessoal','Concentração, até 1 minuto','Pela duração da magia, Celestiais, Elementais, Feéricos,
Ínferos e Mortos-Vivos têm Desvantagem em jogadas
de ataque contra você. Você pode encerrar a magia
mais cedo usando uma das seguintes funções especiais.
Exorcizar. Como uma ação Usar Magia, você tem
como alvo uma criatura a sua vista a até 1,5 metro de
você e que seja um dos tipos de criatura acima. O alvo
deve ser bem-sucedido em uma salvaguarda de Caris-
ma ou é enviado de volta ao seu plano de origem, se
ainda não estiver lá. Se não estiverem em seu plano de
origem, Feéricos são enviados para Faéria e Mortos-Vi-
vos são enviadas para o Sombral.
Quebrar Encantamento. Como uma ação Usar Magia,
toque uma criatura que esteja possuída ou sob os
efeitos de Amedrontado ou Enfeitiçado por uma ou
mais das criaturas mencionadas. O alvo deixa de estar
possuído, Amedrontado ou Enfeitiçado por elas.',36,'Abjuração (Clérigo, Paladino)','{"level":"5","name":"Dissipar o Bem e o Mal","school":[{"text":"Abjuração (Clérigo, Paladino)","top":443.4463,"prose":true,"stat":false,"head":false,"page":36,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":459.11229999999995,"prose":false,"stat":false,"head":false,"page":36,"col":0}],"Alcance":[{"text":"Pessoal","top":471.0123,"prose":false,"stat":false,"head":false,"page":36,"col":0}],"Componentes":[{"text":"V, S, M (prata e ferro em pó)","top":482.9122,"prose":false,"stat":false,"head":false,"page":36,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":494.81229999999994,"prose":false,"stat":false,"head":false,"page":36,"col":0}]},"desc":[{"text":"Pela duração da magia, Celestiais, Elementais, Feéricos,","top":512.8675000000001,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"Ínferos e Mortos-Vivos têm Desvantagem em jogadas","top":524.7674999999999,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"de ataque contra você. Você pode encerrar a magia","top":536.6676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"mais cedo usando uma das seguintes funções especiais.","top":548.5676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"Exorcizar. Como uma ação Usar Magia, você tem","top":560.4676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"como alvo uma criatura a sua vista a até 1,5 metro de","top":572.3675,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"você e que seja um dos tipos de criatura acima. O alvo","top":584.2676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"deve ser bem-sucedido em uma salvaguarda de Caris-","top":596.1675,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"ma ou é enviado de volta ao seu plano de origem, se","top":608.0676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"ainda não estiver lá. Se não estiverem em seu plano de","top":619.9676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"origem, Feéricos são enviados para Faéria e Mortos-Vi-","top":631.8675,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"vos são enviadas para o Sombral.","top":643.7676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"Quebrar Encantamento. Como uma ação Usar Magia,","top":655.6675,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"toque uma criatura que esteja possuída ou sob os","top":667.5676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"efeitos de Amedrontado ou Enfeitiçado por uma ou","top":679.4676,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"mais das criaturas mencionadas. O alvo deixa de estar","top":691.3675,"prose":true,"stat":false,"head":false,"page":36,"col":0},{"text":"possuído, Amedrontado ou Enfeitiçado por elas.","top":703.2676,"prose":true,"stat":false,"head":false,"page":36,"col":0}],"page":36}');
