INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(127,'Dominar Fera','dominar fera',4,1,1,'V, S','Ação','18 metros','Concentração, até 1 minuto','Uma Fera à sua vista e no alcance da magia deve ser
bem-sucedida em uma salvaguarda de Sabedoria ou
tem a condição Enfeitiçado pela duração da magia.
O alvo tem Vantagem na salvaguarda se você ou seus
aliados estiverem lutando contra ele. Sempre que o
alvo sofre dano, ele repete a salvaguarda, encerrando a
magia em caso de sucesso.
Você tem um vínculo telepático com o alvo Enfeitiça-
do enquanto vocês dois estão no mesmo plano de exis-
tência. No seu turno, você pode usar este vínculo para
emitir comandos para o alvo (nenhuma ação é neces-
sária), como “Ataque essa criatura”, “Mova-se para lá”
ou “Busque aquele objeto”. O alvo faz o possível para
obedecer no turno dele. Se ele concluir um pedido e
não receber mais instruções de você, ele age e se move
como quiser, concentrando-se em se proteger.
Você pode ordenar o alvo a executar uma Reação,
mas deve executar sua própria Reação para tanto.
Usando um Espaço de Magia de Círculo Superior. Sua
Concentração pode durar mais com um espaço de ma-
gia de 5º círculo (em até 10 minutos), 6º círculo (em
até 1 hora) ou 7º círculo ou superior (em até 8 horas).',36,'Encantamento (Druida, Feiticeiro, Guardião)','{"level":"4","name":"Dominar Fera","school":[{"text":"Encantamento (Druida, Feiticeiro, Guardião)","top":443.4463,"prose":true,"stat":false,"head":false,"page":36,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":459.11229999999995,"prose":false,"stat":false,"head":false,"page":36,"col":1}],"Alcance":[{"text":"18 metros","top":471.0123,"prose":false,"stat":false,"head":false,"page":36,"col":1}],"Componentes":[{"text":"V, S","top":482.9122,"prose":false,"stat":false,"head":false,"page":36,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":494.81229999999994,"prose":false,"stat":false,"head":false,"page":36,"col":1}]},"desc":[{"text":"Uma Fera à sua vista e no alcance da magia deve ser","top":512.8675000000001,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"bem-sucedida em uma salvaguarda de Sabedoria ou","top":524.7674999999999,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"tem a condição Enfeitiçado pela duração da magia.","top":536.6676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"O alvo tem Vantagem na salvaguarda se você ou seus","top":548.5676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"aliados estiverem lutando contra ele. Sempre que o","top":560.4676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"alvo sofre dano, ele repete a salvaguarda, encerrando a","top":572.3675,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"magia em caso de sucesso.","top":584.2676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"Você tem um vínculo telepático com o alvo Enfeitiça-","top":596.1675,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"do enquanto vocês dois estão no mesmo plano de exis-","top":608.0676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"tência. No seu turno, você pode usar este vínculo para","top":619.9676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"emitir comandos para o alvo (nenhuma ação é neces-","top":631.8675,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"sária), como “Ataque essa criatura”, “Mova-se para lá”","top":643.7676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"ou “Busque aquele objeto”. O alvo faz o possível para","top":655.6675,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"obedecer no turno dele. Se ele concluir um pedido e","top":667.5676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"não receber mais instruções de você, ele age e se move","top":679.4676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"como quiser, concentrando-se em se proteger.","top":691.3675,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"Você pode ordenar o alvo a executar uma Reação,","top":703.2676,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"mas deve executar sua própria Reação para tanto.","top":715.1675,"prose":true,"stat":false,"head":false,"page":36,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. Sua","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":37,"col":0},{"text":"Concentração pode durar mais com um espaço de ma-","top":48.057399999999916,"prose":true,"stat":false,"head":false,"page":37,"col":0},{"text":"gia de 5º círculo (em até 10 minutos), 6º círculo (em","top":59.75739999999996,"prose":true,"stat":false,"head":false,"page":37,"col":0},{"text":"até 1 hora) ou 7º círculo ou superior (em até 8 horas).","top":71.45729999999992,"prose":true,"stat":false,"head":false,"page":37,"col":0}],"page":36}');
