INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(135,'Encontrar o Caminho','encontrar o caminho',6,8,1,'V, S, M (um conjunto de ferramentas de
adivinhação — como cartas ou runas — no valor de 100 ou
mais PO)','1 minuto','Pessoal','Concentração, até 1 dia','Você sente magicamente a rota física mais direta para
um local que você nomeia. Você deve estar familiari-
zado com o local, e a magia falha se você declarar um
destino em outro plano de existência, um destino em
movimento (como uma fortaleza móvel) ou um destino
inespecífico (como “o covil de um dragão verde”).
Enquanto durar a magia, desde que você esteja no
mesmo plano de existência do destino, você sabe a que
distância ele está e em que direção se encontra. Sempre
que se depara com uma escolha de caminhos ao longo
do trajeto, você sabe qual é o caminho mais direto.',39,'Adivinhação (Bardo, Clérigo, Druida)','{"level":"6","name":"Encontrar o Caminho","school":[{"text":"Adivinhação (Bardo, Clérigo, Druida)","top":104.36129999999991,"prose":true,"stat":false,"head":false,"page":39,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":120.02729999999997,"prose":false,"stat":false,"head":false,"page":39,"col":0}],"Alcance":[{"text":"Pessoal","top":131.92729999999995,"prose":false,"stat":false,"head":false,"page":39,"col":0}],"Componentes":[{"text":"V, S, M (um conjunto de ferramentas de","top":143.82729999999992,"prose":false,"stat":false,"head":false,"page":39,"col":0},{"text":"adivinhação — como cartas ou runas — no valor de 100 ou","top":155.7273,"prose":false,"stat":false,"head":false,"page":39,"col":0},{"text":"mais PO)","top":167.6273,"prose":false,"stat":false,"head":false,"page":39,"col":0}],"Duração":[{"text":"Concentração, até 1 dia","top":179.52729999999997,"prose":false,"stat":false,"head":false,"page":39,"col":0}]},"desc":[{"text":"Você sente magicamente a rota física mais direta para","top":197.58259999999996,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"um local que você nomeia. Você deve estar familiari-","top":209.48259999999993,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"zado com o local, e a magia falha se você declarar um","top":221.3825999999999,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"destino em outro plano de existência, um destino em","top":233.2826,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"movimento (como uma fortaleza móvel) ou um destino","top":245.18259999999998,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"inespecífico (como “o covil de um dragão verde”).","top":257.08259999999996,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"Enquanto durar a magia, desde que você esteja no","top":268.98259999999993,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"mesmo plano de existência do destino, você sabe a que","top":280.8826,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"distância ele está e em que direção se encontra. Sempre","top":292.7826,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"que se depara com uma escolha de caminhos ao longo","top":304.6826,"prose":true,"stat":false,"head":false,"page":39,"col":0},{"text":"do trajeto, você sabe qual é o caminho mais direto.","top":316.5826,"prose":true,"stat":false,"head":false,"page":39,"col":0}],"page":39}');
