círculo de espaço de magia acima de 2.',39,'Transmutação (Bruxo, Feiticeiro, Mago)','{"level":"2","name":"Escalada de Aranha","school":[{"text":"Transmutação (Bruxo, Feiticeiro, Mago)","top":151.96129999999994,"prose":true,"stat":false,"head":false,"page":39,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":167.6273,"prose":false,"stat":false,"head":false,"page":39,"col":1}],"Alcance":[{"text":"Toque","top":179.5272,"prose":false,"stat":false,"head":false,"page":39,"col":1}],"Componentes":[{"text":"V, S, M (uma gota de betume e uma aranha)","top":191.42729999999995,"prose":false,"stat":false,"head":false,"page":39,"col":1}],"Duração":[{"text":"Concentração, até 1 hora","top":203.32719999999995,"prose":false,"stat":false,"head":false,"page":39,"col":1}]},"desc":[{"text":"Até que a magia termine, uma criatura voluntária","top":221.38249999999994,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"que você tocar adquire a capacidade de se mover por","top":233.2824999999999,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"superfícies verticais e ao longo de tetos, deixando as","top":245.1825,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"mãos livres. O alvo também adquire um Deslocamento","top":257.0825,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"de Escalada igual ao Deslocamento dele.","top":268.98249999999996,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":281.0625,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"Você pode escolher uma criatura adicional para cada","top":292.7825,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"círculo de espaço de magia acima de 2.","top":304.6825,"prose":true,"stat":false,"head":false,"page":39,"col":1}],"page":39}');
