mensagem oculta.',39,'Ilusão (Bardo, Bruxo, Mago)','{"level":"1","name":"Escrita Ilusória","school":[{"text":"Ilusão (Bardo, Bruxo, Mago)","top":348.8864,"prose":true,"stat":false,"head":false,"page":39,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":364.5524,"prose":false,"stat":false,"head":false,"page":39,"col":1}],"Alcance":[{"text":"Toque","top":376.45239999999995,"prose":false,"stat":false,"head":false,"page":39,"col":1}],"Componentes":[{"text":"S, M (tinta no valor de 10 ou mais PO, que a","top":388.35239999999993,"prose":false,"stat":false,"head":false,"page":39,"col":1},{"text":"magia consome)","top":400.25239999999997,"prose":false,"stat":false,"head":false,"page":39,"col":1}],"Duração":[{"text":"10 dias","top":412.15239999999994,"prose":false,"stat":false,"head":false,"page":39,"col":1}]},"desc":[{"text":"Você escreve em pergaminho, papel ou outro material","top":430.2077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"apropriado e o imbuí com uma ilusão que permane-","top":442.1077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"ce pela duração. Para você e quaisquer criaturas que","top":454.0077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"escolher ao conjurar a magia, a escrita parece normal,","top":465.90770000000003,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"como se estivesse escrita por sua mão, e transmite o","top":477.8077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"significado de sua intenção no momento em que o tex-","top":489.7077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"to foi redigido. Para os demais, as palavras aparecem","top":501.6077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"como se estivessem em um alfabeto desconhecido ou","top":513.5077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"mágico, tornando-se ininteligíveis. Se preferir, a ilusão","top":525.4077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"pode alterar o significado, a caligrafia e o idioma do","top":537.3077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"texto, embora você deva conhecer o idioma.","top":549.2076999999999,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"Se a magia for dissipada, o texto original e a ilusão","top":561.1077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"desaparecem.","top":573.0077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"Uma criatura que possui Visão Verdadeira pode ler a","top":584.9077,"prose":true,"stat":false,"head":false,"page":39,"col":1},{"text":"mensagem oculta.","top":596.8077,"prose":true,"stat":false,"head":false,"page":39,"col":1}],"page":39}');
