op":292.7826,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"corpo, o escudo irrompe em chamas. O atacante sofre","top":304.6826,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"2d8 pontos de dano Ígneo de um escudo quente ou","top":316.5826,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"2d8 pontos de dano Gélido de um escudo frio.","top":328.4826,"prose":true,"stat":false,"head":false,"page":40,"col":0}],"page":40}');
