INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(143,'Escuridão','escuridao',2,6,1,'V, M (pelo de morcego e um pedaço de carvão)','Ação','18 metros','Concentração, até 10 minutos','Pela duração da magia, uma Escuridão mágica se
espalha a partir de um ponto no alcance da magia e
preenche uma Esfera de 4,5 metros de raio. Visão no
escuro não pode ver através dela, e luz não mágica não
pode iluminá-la.
Como alternativa, você conjura a magia em um objeto
que não esteja sendo usado ou carregado, fazendo com
que a Escuridão preencha uma Emanação de 4,5 me-
tros originada desse objeto. Cobrir esse objeto com algo
opaco, como uma tigela ou elmo, bloqueia a Escuridão.
Se qualquer área desta magia se sobrepuser a uma
área de Luz Plena ou Meia-luz criada por uma magia
de 2º círculo ou inferior, essa outra magia é dissipada.',40,'Evocação (Bruxo, Feiticeiro, Mago)','{"level":"2","name":"Escuridão","school":[{"text":"Evocação (Bruxo, Feiticeiro, Mago)","top":510.1117,"prose":true,"stat":false,"head":false,"page":40,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":525.7777,"prose":false,"stat":false,"head":false,"page":40,"col":0}],"Alcance":[{"text":"18 metros","top":537.6777,"prose":false,"stat":false,"head":false,"page":40,"col":0}],"Componentes":[{"text":"V, M (pelo de morcego e um pedaço de carvão)","top":549.5777,"prose":false,"stat":false,"head":false,"page":40,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":561.4777,"prose":false,"stat":false,"head":false,"page":40,"col":0}]},"desc":[{"text":"Pela duração da magia, uma Escuridão mágica se","top":579.533,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"espalha a partir de um ponto no alcance da magia e","top":591.433,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"preenche uma Esfera de 4,5 metros de raio. Visão no","top":603.333,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"escuro não pode ver através dela, e luz não mágica não","top":615.233,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"pode iluminá-la.","top":627.133,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"Como alternativa, você conjura a magia em um objeto","top":639.033,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"que não esteja sendo usado ou carregado, fazendo com","top":650.933,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"que a Escuridão preencha uma Emanação de 4,5 me-","top":662.833,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"tros originada desse objeto. Cobrir esse objeto com algo","top":674.733,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"opaco, como uma tigela ou elmo, bloqueia a Escuridão.","top":686.633,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"Se qualquer área desta magia se sobrepuser a uma","top":698.533,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"área de Luz Plena ou Meia-luz criada por uma magia","top":710.433,"prose":true,"stat":false,"head":false,"page":40,"col":0},{"text":"de 2º círculo ou inferior, essa outra magia é dissipada.","top":722.333,"prose":true,"stat":false,"head":false,"page":40,"col":0}],"page":40}');
