INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(145,'Esfera Flamejante','esfera flamejante',2,4,1,'V, S, M (uma bola de cera)','Ação','18 metros','Concentração, até 1 minuto','Você cria uma esfera de fogo de 1,5 metro de diâmetro
em um espaço desocupado no chão no alcance e pela
duração da magia. Qualquer criatura que termine o
turno a até 1,5 metro da esfera realiza uma salvaguarda
de Destreza, sofrendo 2d6 pontos de dano Ígneo se
falhar, ou metade desse dano em caso de sucesso.
Como uma Ação Bônus, você pode mover a esfera
até 9 metros, rolando-a pelo chão. Se você mover a
esfera para o espaço de uma criatura, essa criatura
realiza a salvaguarda contra a esfera, e a esfera para de
se mover durante o turno.
Ao mover a esfera, você pode direcioná-la sobre bar-
reiras de até 1,5 metro de altura e saltar sobre poços de
até 3 metros de largura. Objetos inflamáveis que não
estão sendo usados ou carregados entram em combus-
tão se tocados pela esfera, e ela emite Luz Plena em um
raio de 6 metros e Meia-luz por mais 6 metros.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d6 para cada círculo de espaço de
magia acima de 2.',40,'Invocação (Druida, Feiticeiro, Mago)','{"level":"2","name":"Esfera Flamejante","school":[{"text":"Invocação (Druida, Feiticeiro, Mago)","top":497.9171,"prose":true,"stat":false,"head":false,"page":40,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":513.5831,"prose":false,"stat":false,"head":false,"page":40,"col":1}],"Alcance":[{"text":"18 metros","top":525.4830999999999,"prose":false,"stat":false,"head":false,"page":40,"col":1}],"Componentes":[{"text":"V, S, M (uma bola de cera)","top":537.3831,"prose":false,"stat":false,"head":false,"page":40,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":549.2831,"prose":false,"stat":false,"head":false,"page":40,"col":1}]},"desc":[{"text":"Você cria uma esfera de fogo de 1,5 metro de diâmetro","top":567.3384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"em um espaço desocupado no chão no alcance e pela","top":579.2384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"duração da magia. Qualquer criatura que termine o","top":591.1384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"turno a até 1,5 metro da esfera realiza uma salvaguarda","top":603.0383999999999,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"de Destreza, sofrendo 2d6 pontos de dano Ígneo se","top":614.9384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"falhar, ou metade desse dano em caso de sucesso.","top":626.8384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"Como uma Ação Bônus, você pode mover a esfera","top":638.7384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"até 9 metros, rolando-a pelo chão. Se você mover a","top":650.6384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"esfera para o espaço de uma criatura, essa criatura","top":662.5384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"realiza a salvaguarda contra a esfera, e a esfera para de","top":674.4384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"se mover durante o turno.","top":686.3384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"Ao mover a esfera, você pode direcioná-la sobre bar-","top":698.2384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"reiras de até 1,5 metro de altura e saltar sobre poços de","top":710.1384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"até 3 metros de largura. Objetos inflamáveis que não","top":722.0384,"prose":true,"stat":false,"head":false,"page":40,"col":1},{"text":"estão sendo usados ou carregados entram em combus-","top":402.4174,"prose":true,"stat":false,"head":false,"page":41,"col":0},{"text":"tão se tocados pela esfera, e ela emite Luz Plena em um","top":414.3173,"prose":true,"stat":false,"head":false,"page":41,"col":0},{"text":"raio de 6 metros e Meia-luz por mais 6 metros.","top":426.2173,"prose":true,"stat":false,"head":false,"page":41,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":438.1173,"prose":true,"stat":false,"head":false,"page":41,"col":0},{"text":"dano aumenta em 1d6 para cada círculo de espaço de","top":450.0174,"prose":true,"stat":false,"head":false,"page":41,"col":0},{"text":"magia acima de 2.","top":461.9174,"prose":true,"stat":false,"head":false,"page":41,"col":0}],"page":40}');
