INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(149,'Espinho Mental','espinho mental',2,8,1,'S','Ação','36 metros','Concentração, até 1 hora','Você crava um espinho de energia psíquica na mente
de uma criatura à sua vista e no alcance da magia. O
alvo realiza uma salvaguarda de Sabedoria, sofrendo
3d8 pontos de dano Psíquico se falhar ou metade desse
dano em caso de sucesso. Se falhar na salvaguarda,
você também sempre sabe a localização do alvo até que
a magia termine, mas apenas enquanto ambos esti-
verem no mesmo plano de existência. Enquanto você
tiver essa informação, o alvo não pode se esconder de
você, e se tem a condição Invisível, não obtém nenhum
benefício dela contra você.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 2.',42,'Adivinhação (Bruxo, Feiticeiro, Mago)','{"level":"2","name":"Espinho Mental","school":[{"text":"Adivinhação (Bruxo, Feiticeiro, Mago)","top":307.5171,"prose":true,"stat":false,"head":false,"page":42,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":323.18309999999997,"prose":false,"stat":false,"head":false,"page":42,"col":0}],"Alcance":[{"text":"36 metros","top":335.08309999999994,"prose":false,"stat":false,"head":false,"page":42,"col":0}],"Componentes":[{"text":"S","top":346.9831,"prose":false,"stat":false,"head":false,"page":42,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":358.88309999999996,"prose":false,"stat":false,"head":false,"page":42,"col":0}]},"desc":[{"text":"Você crava um espinho de energia psíquica na mente","top":376.9384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"de uma criatura à sua vista e no alcance da magia. O","top":388.8384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"alvo realiza uma salvaguarda de Sabedoria, sofrendo","top":400.7384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"3d8 pontos de dano Psíquico se falhar ou metade desse","top":412.6384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"dano em caso de sucesso. Se falhar na salvaguarda,","top":424.5384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"você também sempre sabe a localização do alvo até que","top":436.4384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"a magia termine, mas apenas enquanto ambos esti-","top":448.3384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"verem no mesmo plano de existência. Enquanto você","top":460.2384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"tiver essa informação, o alvo não pode se esconder de","top":472.1384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"você, e se tem a condição Invisível, não obtém nenhum","top":484.0384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"benefício dela contra você.","top":495.9384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":507.8384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"dano aumenta em 1d8 para cada círculo de espaço de","top":519.7384,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"magia acima de 2.","top":531.6384,"prose":true,"stat":false,"head":false,"page":42,"col":0}],"page":42}');
