INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(150,'Esquentar Metal','esquentar metal',2,5,1,'V, S, M (um pedaço de ferro e uma chama)','Ação','18 metros','Concentração, até 1 minuto','Escolha um objeto de metal fabricado, como uma arma
ou uma armadura de metal pesada ou média, à sua
vista e no alcance da magia. Você faz com que o objeto
brilhe em brasa. Qualquer criatura em contato físico
com o objeto sofre 2d8 pontos de dano ígneo quando
você conjura a magia. Enquanto a magia durar, você
pode executar uma ação Bônus em cada um dos seus
turnos subsequentes para causar esse dano novamente,
desde que o objeto esteja no alcance da magia.
Se uma criatura estiver segurando ou usando o
objeto e sofrer dano, ela deve ser bem-sucedida em
uma salvaguarda de Constituição ou soltar o objeto, se
puder. Se não soltar o objeto, ela tem Desvantagem em
jogadas de ataque e testes de atributo até o início do
seu próximo turno.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 2.',42,'Transmutação (Bardo, Druida)','{"level":"2","name":"Esquentar Metal","school":[{"text":"Transmutação (Bardo, Druida)","top":575.8423,"prose":true,"stat":false,"head":false,"page":42,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":591.5083,"prose":false,"stat":false,"head":false,"page":42,"col":0}],"Alcance":[{"text":"18 metros","top":603.4083,"prose":false,"stat":false,"head":false,"page":42,"col":0}],"Componentes":[{"text":"V, S, M (um pedaço de ferro e uma chama)","top":615.3082999999999,"prose":false,"stat":false,"head":false,"page":42,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":627.2083,"prose":false,"stat":false,"head":false,"page":42,"col":0}]},"desc":[{"text":"Escolha um objeto de metal fabricado, como uma arma","top":645.2636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"ou uma armadura de metal pesada ou média, à sua","top":657.1636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"vista e no alcance da magia. Você faz com que o objeto","top":669.0636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"brilhe em brasa. Qualquer criatura em contato físico","top":680.9636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"com o objeto sofre 2d8 pontos de dano ígneo quando","top":692.8636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"você conjura a magia. Enquanto a magia durar, você","top":704.7636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"pode executar uma ação Bônus em cada um dos seus","top":716.6636,"prose":true,"stat":false,"head":false,"page":42,"col":0},{"text":"turnos subsequentes para causar esse dano novamente,","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"desde que o objeto esteja no alcance da magia.","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"Se uma criatura estiver segurando ou usando o","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"objeto e sofrer dano, ela deve ser bem-sucedida em","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"uma salvaguarda de Constituição ou soltar o objeto, se","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"puder. Se não soltar o objeto, ela tem Desvantagem em","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"jogadas de ataque e testes de atributo até o início do","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"seu próximo turno.","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"dano aumenta em 1d8 para cada círculo de espaço de","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"magia acima de 2.","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":42,"col":1}],"page":42}');
