INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(151,'Estática Sináptica','estatica sinaptica',5,1,1,'V, S','Ação','36 metros','Instantânea','Você faz com que a energia psíquica entre em erupção
em um ponto no alcance da magia. Cada criatura em
uma Esfera de 6 metros de raio centrada nesse ponto
realiza uma salvaguarda de Inteligência, sofrendo 8d6
pontos de dano Psíquico se falhar, ou metade desse
dano em caso de sucesso.
Se falhar, um alvo também tem pensamentos confu-
sos por 1 minuto. Durante esse tempo, ele subtrai 1d6
de todas as suas jogadas de ataque e testes de atributo,
bem como quaisquer salvaguardas de Constituição para
manter a Concentração. A criatura realiza uma salva-
guarda de Inteligência no final de cada um dos turnos
dela, encerrando o efeito sobre si em caso de sucesso.',42,'Encantamento (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"5","name":"Estática Sináptica","school":[{"text":"Encantamento (Bardo, Bruxo, Feiticeiro, Mago)","top":199.56129999999996,"prose":true,"stat":false,"head":false,"page":42,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":215.2273,"prose":false,"stat":false,"head":false,"page":42,"col":1}],"Alcance":[{"text":"36 metros","top":227.1273,"prose":false,"stat":false,"head":false,"page":42,"col":1}],"Componentes":[{"text":"V, S","top":239.0272,"prose":false,"stat":false,"head":false,"page":42,"col":1}],"Duração":[{"text":"Instantânea","top":250.92729999999995,"prose":false,"stat":false,"head":false,"page":42,"col":1}]},"desc":[{"text":"Você faz com que a energia psíquica entre em erupção","top":268.98249999999996,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"em um ponto no alcance da magia. Cada criatura em","top":280.8826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"uma Esfera de 6 metros de raio centrada nesse ponto","top":292.7826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"realiza uma salvaguarda de Inteligência, sofrendo 8d6","top":304.6826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"pontos de dano Psíquico se falhar, ou metade desse","top":316.5825,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"dano em caso de sucesso.","top":328.4825,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"Se falhar, um alvo também tem pensamentos confu-","top":340.3826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"sos por 1 minuto. Durante esse tempo, ele subtrai 1d6","top":352.2826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"de todas as suas jogadas de ataque e testes de atributo,","top":364.1826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"bem como quaisquer salvaguardas de Constituição para","top":376.0825,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"manter a Concentração. A criatura realiza uma salva-","top":387.9825,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"guarda de Inteligência no final de cada um dos turnos","top":399.8826,"prose":true,"stat":false,"head":false,"page":42,"col":1},{"text":"dela, encerrando o efeito sobre si em caso de sucesso.","top":411.7826,"prose":true,"stat":false,"head":false,"page":42,"col":1}],"page":42}');
