INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(155,'Faca de Gelo','faca de gelo',1,4,1,'S, M (uma gota de água ou um pedaço de gelo)','Ação','18 metros','Instantânea','Você cria um fragmento de gelo e o arremessa em uma
criatura no alcance da magia. Realize um ataque má-
gico à distância contra o alvo. Se o ataque for bem-su-
cedido, o alvo sofre 1d10 pontos de dano Perfurante.
Independentemente de ter acertado ou não, o frag-
mento explode. O alvo e cada criatura a até 1,5 metro
dele devem ser bem-sucedidos em uma salvaguarda de
Destreza ou sofrem 2d6 pontos de dano Gélido.
Usando um Espaço de Magia de Círculo Superior.
O dano Gélido aumenta em 1d6 para cada círculo de
espaço de magia acima de 1.',43,'Invocação (Druida, Feiticeiro, Mago)','{"level":"1","name":"Faca de Gelo","school":[{"text":"Invocação (Druida, Feiticeiro, Mago)","top":659.1423,"prose":true,"stat":false,"head":false,"page":43,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":674.8083,"prose":false,"stat":false,"head":false,"page":43,"col":0}],"Alcance":[{"text":"18 metros","top":686.7083,"prose":false,"stat":false,"head":false,"page":43,"col":0}],"Componentes":[{"text":"S, M (uma gota de água ou um pedaço de gelo)","top":698.6083,"prose":false,"stat":false,"head":false,"page":43,"col":0}],"Duração":[{"text":"Instantânea","top":710.5083,"prose":false,"stat":false,"head":false,"page":43,"col":0}]},"desc":[{"text":"Você cria um fragmento de gelo e o arremessa em uma","top":178.0897,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"criatura no alcance da magia. Realize um ataque má-","top":189.98969999999997,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"gico à distância contra o alvo. Se o ataque for bem-su-","top":201.88959999999997,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"cedido, o alvo sofre 1d10 pontos de dano Perfurante.","top":213.78969999999993,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"Independentemente de ter acertado ou não, o frag-","top":225.68959999999993,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"mento explode. O alvo e cada criatura a até 1,5 metro","top":237.5897,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"dele devem ser bem-sucedidos em uma salvaguarda de","top":249.48969999999997,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"Destreza ou sofrem 2d6 pontos de dano Gélido.","top":261.3896,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":273.4697,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"O dano Gélido aumenta em 1d6 para cada círculo de","top":285.1897,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"espaço de magia acima de 1.","top":297.0897,"prose":true,"stat":false,"head":false,"page":43,"col":1}],"page":43}');
