INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(156,'Fagulha Estelar','fagulha estelar',0,6,1,'V, S','Ação','18 metros','Instantânea','Você lança uma faísca de luz em uma criatura ou
objeto no alcance da magia. Realize um ataque mágico
à distância contra o alvo. Em caso de acerto, o alvo
sofre 1d8 pontos de dano Radiante e, até o final do seu
próximo turno, emite Meia-luz em um raio de 3 metros
e não pode se beneficiar da condição Invisível.
Aprimoramento de Truque. O dano aumenta em 1d8
quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).',43,'Evocação (Bardo, Druida)','{"level":"0","name":"Fagulha Estelar","school":[{"text":"Evocação (Bardo, Druida)","top":341.2936,"prose":true,"stat":false,"head":false,"page":43,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":356.95959999999997,"prose":false,"stat":false,"head":false,"page":43,"col":1}],"Alcance":[{"text":"18 metros","top":368.85959999999994,"prose":false,"stat":false,"head":false,"page":43,"col":1}],"Componentes":[{"text":"V, S","top":380.75949999999995,"prose":false,"stat":false,"head":false,"page":43,"col":1}],"Duração":[{"text":"Instantânea","top":392.65959999999995,"prose":false,"stat":false,"head":false,"page":43,"col":1}]},"desc":[{"text":"Você lança uma faísca de luz em uma criatura ou","top":410.7148,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"objeto no alcance da magia. Realize um ataque mágico","top":422.61490000000003,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"à distância contra o alvo. Em caso de acerto, o alvo","top":434.5149,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"sofre 1d8 pontos de dano Radiante e, até o final do seu","top":446.4149,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"próximo turno, emite Meia-luz em um raio de 3 metros","top":458.3148,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"e não pode se beneficiar da condição Invisível.","top":470.2148,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"Aprimoramento de Truque. O dano aumenta em 1d8","top":482.11490000000003,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).","top":494.0149,"prose":true,"stat":false,"head":false,"page":43,"col":1}],"page":43}');
