INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(157,'Falar com Animais','falar com animais',1,8,1,'V, S','Ação ou Ritual','Pessoal','10 minutos','Pela duração da magia, você pode compreender e
se comunicar verbalmente com Feras, e pode usar
com elas qualquer uma das opções de perícia da ação
Influenciar.
A maioria das Feras oferece pouca informação sobre
assuntos que não estejam diretamente ligados à sobre-
vivência ou ao companheirismo mas, no mínimo, uma
Fera pode fornecer informações sobre áreas vizinhas e
monstros, incluindo o que percebeu no último dia.',43,'Adivinhação (Bardo, Bruxo, Druida, Guardião)','{"level":"1","name":"Falar com Animais","school":[{"text":"Adivinhação (Bardo, Bruxo, Druida, Guardião)","top":538.2188,"prose":true,"stat":false,"head":false,"page":43,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":553.8848,"prose":false,"stat":false,"head":false,"page":43,"col":1}],"Alcance":[{"text":"Pessoal","top":565.7846999999999,"prose":false,"stat":false,"head":false,"page":43,"col":1}],"Componentes":[{"text":"V, S","top":577.6848,"prose":false,"stat":false,"head":false,"page":43,"col":1}],"Duração":[{"text":"10 minutos","top":589.5848,"prose":false,"stat":false,"head":false,"page":43,"col":1}]},"desc":[{"text":"Pela duração da magia, você pode compreender e","top":607.64,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"se comunicar verbalmente com Feras, e pode usar","top":619.5400999999999,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"com elas qualquer uma das opções de perícia da ação","top":631.4401,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"Influenciar.","top":643.3401,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"A maioria das Feras oferece pouca informação sobre","top":655.24,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"assuntos que não estejam diretamente ligados à sobre-","top":667.14,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"vivência ou ao companheirismo mas, no mínimo, uma","top":679.0400999999999,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"Fera pode fornecer informações sobre áreas vizinhas e","top":690.9401,"prose":true,"stat":false,"head":false,"page":43,"col":1},{"text":"monstros, incluindo o que percebeu no último dia.","top":702.84,"prose":true,"stat":false,"head":false,"page":43,"col":1}],"page":43}');
