INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(158,'Falar com Mortos','falar com mortos',3,2,1,'V, S, M (um incenso aceso)','Ação','3 metros','10 minutos','Você confere uma aparência de vida a um cadáver à
sua escolha que esteja no alcance da magia, permitindo
que ele responda às perguntas que você fizer. O cadá-
ver precisa ter boca, e a magia falha se a criatura morta
era um Morto-Vivo quando pereceu ou se foi o alvo
desta magia nos últimos 10 dias.
Até que a magia termine, você pode fazer até cinco
perguntas ao cadáver. O cadáver sabe apenas o que
sabia em vida, incluindo os idiomas que conhecia. As
respostas geralmente são breves, enigmáticas ou repe-
titivas, e o cadáver não tem obrigação de oferecer uma
resposta verdadeira se você for hostil a ele ou se ele o
reconhecer como um inimigo. Esta magia não devolve
a alma da criatura ao corpo dela, apenas o espírito
animado. Assim, o cadáver não pode aprender novas
informações, não compreende nada do que aconteceu
desde que morreu e não pode discorrer sobre eventos
futuros.',44,'Necromancia (Bardo, Clérigo, Mago)','{"level":"3","name":"Falar com Mortos","school":[{"text":"Necromancia (Bardo, Clérigo, Mago)","top":337.9022,"prose":true,"stat":false,"head":false,"page":44,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":353.56819999999993,"prose":false,"stat":false,"head":false,"page":44,"col":0}],"Alcance":[{"text":"3 metros","top":365.46819999999997,"prose":false,"stat":false,"head":false,"page":44,"col":0}],"Componentes":[{"text":"V, S, M (um incenso aceso)","top":377.36819999999994,"prose":false,"stat":false,"head":false,"page":44,"col":0}],"Duração":[{"text":"10 minutos","top":389.2682,"prose":false,"stat":false,"head":false,"page":44,"col":0}]},"desc":[{"text":"Você confere uma aparência de vida a um cadáver à","top":407.3235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"sua escolha que esteja no alcance da magia, permitindo","top":419.2235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"que ele responda às perguntas que você fizer. O cadá-","top":431.1235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"ver precisa ter boca, e a magia falha se a criatura morta","top":443.0235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"era um Morto-Vivo quando pereceu ou se foi o alvo","top":454.9235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"desta magia nos últimos 10 dias.","top":466.8235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"Até que a magia termine, você pode fazer até cinco","top":478.7235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"perguntas ao cadáver. O cadáver sabe apenas o que","top":490.6235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"sabia em vida, incluindo os idiomas que conhecia. As","top":502.5235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"respostas geralmente são breves, enigmáticas ou repe-","top":514.4235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"titivas, e o cadáver não tem obrigação de oferecer uma","top":526.3235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"resposta verdadeira se você for hostil a ele ou se ele o","top":538.2235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"reconhecer como um inimigo. Esta magia não devolve","top":550.1234999999999,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"a alma da criatura ao corpo dela, apenas o espírito","top":562.0235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"animado. Assim, o cadáver não pode aprender novas","top":573.9235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"informações, não compreende nada do que aconteceu","top":585.8235,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"desde que morreu e não pode discorrer sobre eventos","top":597.7234,"prose":true,"stat":false,"head":false,"page":44,"col":0},{"text":"futuros.","top":609.6234999999999,"prose":true,"stat":false,"head":false,"page":44,"col":0}],"page":44}');
