INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(159,'Falar com Plantas','falar com plantas',3,5,1,'V, S','Ação','Pessoal','10 minutos','Você imbuí plantas em uma Emanação imóvel de 9
metros com razão e intelecto limitado, permitindo que
elas se comuniquem com você e sigam seus comandos
simples. Você pode questionar as plantas sobre eventos
na área da magia nas últimas 24 horas, obtendo infor-
mações sobre criaturas que passaram, clima e outras
circunstâncias.
Além disso, você pode transformar Terreno Difícil
causado pelo crescimento vegetal (como moitas e
vegetação densa) em terreno comum pela duração da
magia. Como alternativa, você pode transformar terre-
no comum onde há plantas em Terreno Difícil, também
pela duração da magia.
A magia não permite que as plantas se desloquem,
mas elas podem mover seus galhos, cipós e caules para
você.
Caso haja uma criatura do tipo Planta na área, você
pode se comunicar com ela como se compartilhassem
um idioma em comum.',44,'Transmutação (Bardo, Druida, Guardião)','{"level":"3","name":"Falar com Plantas","school":[{"text":"Transmutação (Bardo, Druida, Guardião)","top":653.8274,"prose":true,"stat":false,"head":false,"page":44,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":669.4934,"prose":false,"stat":false,"head":false,"page":44,"col":0}],"Alcance":[{"text":"Pessoal","top":681.3933999999999,"prose":false,"stat":false,"head":false,"page":44,"col":0}],"Componentes":[{"text":"V, S","top":693.2934,"prose":false,"stat":false,"head":false,"page":44,"col":0}],"Duração":[{"text":"10 minutos","top":705.1934,"prose":false,"stat":false,"head":false,"page":44,"col":0}]},"desc":[{"text":"Você imbuí plantas em uma Emanação imóvel de 9","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"metros com razão e intelecto limitado, permitindo que","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"elas se comuniquem com você e sigam seus comandos","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"simples. Você pode questionar as plantas sobre eventos","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"na área da magia nas últimas 24 horas, obtendo infor-","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"mações sobre criaturas que passaram, clima e outras","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"circunstâncias.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"Além disso, você pode transformar Terreno Difícil","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"causado pelo crescimento vegetal (como moitas e","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"vegetação densa) em terreno comum pela duração da","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"magia. Como alternativa, você pode transformar terre-","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"no comum onde há plantas em Terreno Difícil, também","top":167.2573,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"pela duração da magia.","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"A magia não permite que as plantas se desloquem,","top":191.05729999999994,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"mas elas podem mover seus galhos, cipós e caules para","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"você.","top":214.8572999999999,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"Caso haja uma criatura do tipo Planta na área, você","top":226.7573,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"pode se comunicar com ela como se compartilhassem","top":238.65729999999996,"prose":true,"stat":false,"head":false,"page":44,"col":1},{"text":"um idioma em comum.","top":250.55729999999994,"prose":true,"stat":false,"head":false,"page":44,"col":1}],"page":44}');
