INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(162,'Flecha Relâmpago','flecha relampago',3,5,1,'V, S','Ação Bônus, que você realiza
imediatamente após atingir ou errar um alvo com um
ataque à distância usando uma arma','Pessoal','Instantânea','Quando seu ataque atinge ou erra o alvo, a arma ou
munição que você está usando se transforma em um
relâmpago. Em vez de sofrer qualquer dano ou outros
efeitos do ataque, o alvo sofre 4d8 pontos de dano Elé-
trico em um acerto ou metade desse dano em um erro.
Cada criatura em um raio de 3 metros do alvo deve
então realizar uma salvaguarda de Destreza, sofrendo
2d8 pontos de dano Elétrico se falhar ou metade desse
dano em caso de sucesso.
A arma ou munição retorna então à sua forma normal.
Usando um Espaço de Magia de Círculo Superior. O
dano para ambos os efeitos da magia aumenta em 1d8
para cada círculo de espaço de magia acima de 3.',44,'Transmutação (Guardião)','{"level":"3","name":"Flecha Relâmpago","school":[{"text":"Transmutação (Guardião)","top":641.0117,"prose":true,"stat":false,"head":false,"page":44,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus, que você realiza","top":656.6776,"prose":false,"stat":false,"head":false,"page":44,"col":1},{"text":"imediatamente após atingir ou errar um alvo com um","top":668.5776,"prose":false,"stat":false,"head":false,"page":44,"col":1},{"text":"ataque à distância usando uma arma","top":680.4775999999999,"prose":false,"stat":false,"head":false,"page":44,"col":1}],"Alcance":[{"text":"Pessoal","top":692.3776,"prose":false,"stat":false,"head":false,"page":44,"col":1}],"Componentes":[{"text":"V, S","top":704.2776,"prose":false,"stat":false,"head":false,"page":44,"col":1}],"Duração":[{"text":"Instantânea","top":716.1776,"prose":false,"stat":false,"head":false,"page":44,"col":1}]},"desc":[{"text":"Quando seu ataque atinge ou erra o alvo, a arma ou","top":412.9611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"munição que você está usando se transforma em um","top":424.8611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"relâmpago. Em vez de sofrer qualquer dano ou outros","top":436.7611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"efeitos do ataque, o alvo sofre 4d8 pontos de dano Elé-","top":448.66110000000003,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"trico em um acerto ou metade desse dano em um erro.","top":460.5611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"Cada criatura em um raio de 3 metros do alvo deve","top":472.4611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"então realizar uma salvaguarda de Destreza, sofrendo","top":484.3611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"2d8 pontos de dano Elétrico se falhar ou metade desse","top":496.2611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"dano em caso de sucesso.","top":508.16110000000003,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"A arma ou munição retorna então à sua forma normal.","top":520.0611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":531.9611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"dano para ambos os efeitos da magia aumenta em 1d8","top":543.8611,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"para cada círculo de espaço de magia acima de 3.","top":555.761,"prose":true,"stat":false,"head":false,"page":45,"col":0}],"page":44}');
