INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(163,'Fogo das Fadas','fogo das fadas',1,6,1,'V','Ação','18 metros','Concentração, até 1 minuto','Objetos em um Cubo de 6 metros de lado no alcance
da magia são delineados por luz azul, verde ou violeta
(à sua escolha). Cada criatura no Cubo também é deli-
neada se falhar em uma salvaguarda de Destreza. Pela
duração da magia, objetos e criaturas afetadas emitem
Meia-Luz em um raio de 3 metros e não podem se
beneficiar da condição Invisível.
Jogadas de ataque contra uma criatura ou objeto
afetado têm Vantagem se o atacante puder vê-la.',45,'Evocação (Bardo, Druida)','{"level":"1","name":"Fogo das Fadas","school":[{"text":"Evocação (Bardo, Druida)","top":599.9649999999999,"prose":true,"stat":false,"head":false,"page":45,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":615.631,"prose":false,"stat":false,"head":false,"page":45,"col":0}],"Alcance":[{"text":"18 metros","top":627.531,"prose":false,"stat":false,"head":false,"page":45,"col":0}],"Componentes":[{"text":"V","top":639.431,"prose":false,"stat":false,"head":false,"page":45,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":651.3308999999999,"prose":false,"stat":false,"head":false,"page":45,"col":0}]},"desc":[{"text":"Objetos em um Cubo de 6 metros de lado no alcance","top":669.3863,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"da magia são delineados por luz azul, verde ou violeta","top":681.2862,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"(à sua escolha). Cada criatura no Cubo também é deli-","top":693.1863,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"neada se falhar em uma salvaguarda de Destreza. Pela","top":705.0862999999999,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"duração da magia, objetos e criaturas afetadas emitem","top":716.9863,"prose":true,"stat":false,"head":false,"page":45,"col":0},{"text":"Meia-Luz em um raio de 3 metros e não podem se","top":412.9611,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"beneficiar da condição Invisível.","top":424.8611,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"Jogadas de ataque contra uma criatura ou objeto","top":436.7611,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"afetado têm Vantagem se o atacante puder vê-la.","top":448.66110000000003,"prose":true,"stat":false,"head":false,"page":45,"col":1}],"page":45}');
