INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(164,'Fome de Hadar','fome de hadar',3,4,1,'V, S, M (um tentáculo em conserva)','Ação','45 metros','Concentração, até 1 minuto','Você abre uma porta de entrada para o Reino Distante,
uma região infestada de horrores indizíveis. Uma Esfe-
ra de Escuridão de 6 metros de raio aparece, centrada
em um ponto no alcance e pela duração da magia. A
Esfera é considerada Terreno Difícil, e está cheia de
sussurros estranhos e sons de sucção que podem ser
ouvidos a até 9 metros de distância. Nenhuma luz, seja
mágica ou não, pode iluminar a área, e criaturas total-
mente dentro da área têm a condição Cego.
Qualquer criatura que comece seu turno na área
sofre 2d6 pontos de dano Gélido. Qualquer criatura
que termine seu turno na área deve ser bem-sucedida
em uma salvaguarda de Destreza ou sofre 2d6 pontos
de dano Ácido enquanto tentáculos esbranquiçados de
outro mundo se esfregam nela.
Usando um Espaço de Magia de Círculo Superior. O
dano Ácido ou Gélido (à sua escolha) aumenta em 1d6
para cada círculo de espaço de magia acima de 3.',45,'Invocação (Bruxo)','{"level":"3","name":"Fome de Hadar","school":[{"text":"Invocação (Bruxo)","top":492.865,"prose":true,"stat":false,"head":false,"page":45,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":508.53099999999995,"prose":false,"stat":false,"head":false,"page":45,"col":1}],"Alcance":[{"text":"45 metros","top":520.431,"prose":false,"stat":false,"head":false,"page":45,"col":1}],"Componentes":[{"text":"V, S, M (um tentáculo em conserva)","top":532.3309999999999,"prose":false,"stat":false,"head":false,"page":45,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":544.231,"prose":false,"stat":false,"head":false,"page":45,"col":1}]},"desc":[{"text":"Você abre uma porta de entrada para o Reino Distante,","top":562.2862,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"uma região infestada de horrores indizíveis. Uma Esfe-","top":574.1863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"ra de Escuridão de 6 metros de raio aparece, centrada","top":586.0862999999999,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"em um ponto no alcance e pela duração da magia. A","top":597.9863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"Esfera é considerada Terreno Difícil, e está cheia de","top":609.8863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"sussurros estranhos e sons de sucção que podem ser","top":621.7862,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"ouvidos a até 9 metros de distância. Nenhuma luz, seja","top":633.6863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"mágica ou não, pode iluminar a área, e criaturas total-","top":645.5862999999999,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"mente dentro da área têm a condição Cego.","top":657.4863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"Qualquer criatura que comece seu turno na área","top":669.3863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"sofre 2d6 pontos de dano Gélido. Qualquer criatura","top":681.2862,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"que termine seu turno na área deve ser bem-sucedida","top":693.1863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"em uma salvaguarda de Destreza ou sofre 2d6 pontos","top":705.0862999999999,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"de dano Ácido enquanto tentáculos esbranquiçados de","top":716.9863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"outro mundo se esfregam nela.","top":728.8863,"prose":true,"stat":false,"head":false,"page":45,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":416.4988,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"dano Ácido ou Gélido (à sua escolha) aumenta em 1d6","top":428.3988,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"para cada círculo de espaço de magia acima de 3.","top":440.2989,"prose":true,"stat":false,"head":false,"page":46,"col":0}],"page":45}');
