INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(165,'Fonte do Luar','fonte do luar',4,6,1,'V, S','Ação','Pessoal','Concentração, até 10 minutos','Uma luz fria envolve seu corpo pela duração da magia,
emitindo Luz Plena em um raio de 6 metros e Meia-luz
por mais 6 metros.
Até que a magia termine, você tem Resistência a
dano Radiante e seus ataques corpo a corpo causam
2d6 pontos de dano Radiante adicionais em caso de
acerto.
Além disso, imediatamente após sofrer dano de uma
criatura à sua vista a até 18 metros de si, você pode
executar uma Reação para forçar a criatura a realizar
uma salvaguarda de Constituição. Se falhar, a criatura
tem a condição Cego até o final do seu próximo turno.',46,'Evocação (Bardo, Druida)','{"level":"4","name":"Fonte do Luar","school":[{"text":"Evocação (Bardo, Druida)","top":484.5028,"prose":true,"stat":false,"head":false,"page":46,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":500.16869999999994,"prose":false,"stat":false,"head":false,"page":46,"col":0}],"Alcance":[{"text":"Pessoal","top":512.0687,"prose":false,"stat":false,"head":false,"page":46,"col":0}],"Componentes":[{"text":"V, S","top":523.9686999999999,"prose":false,"stat":false,"head":false,"page":46,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":535.8688,"prose":false,"stat":false,"head":false,"page":46,"col":0}]},"desc":[{"text":"Uma luz fria envolve seu corpo pela duração da magia,","top":553.9241,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"emitindo Luz Plena em um raio de 6 metros e Meia-luz","top":565.824,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"por mais 6 metros.","top":577.7240999999999,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"Até que a magia termine, você tem Resistência a","top":589.624,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"dano Radiante e seus ataques corpo a corpo causam","top":601.524,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"2d6 pontos de dano Radiante adicionais em caso de","top":613.4241,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"acerto.","top":625.324,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"Além disso, imediatamente após sofrer dano de uma","top":637.2240999999999,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"criatura à sua vista a até 18 metros de si, você pode","top":649.124,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"executar uma Reação para forçar a criatura a realizar","top":661.024,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"uma salvaguarda de Constituição. Se falhar, a criatura","top":672.9241,"prose":true,"stat":false,"head":false,"page":46,"col":0},{"text":"tem a condição Cego até o final do seu próximo turno.","top":684.824,"prose":true,"stat":false,"head":false,"page":46,"col":0}],"page":46}');
