INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(166,'Força Espectral','forca espectral',2,7,1,'V, S, M (um pouco de lã)','Ação','18 metros','Concentração, até 1 minuto','Você tenta criar uma ilusão na mente de uma criatura
à sua vista e no alcance da magia. O alvo realiza uma
salvaguarda de Inteligência. Se falhar, você cria um ob-
jeto, criatura ou outro fenômeno espectral que não seja
maior do que um cubo de 3 metros de lado e que seja
perceptível apenas para o alvo pela duração da magia.
O espectro inclui som, temperatura e outros estímulos.
O alvo pode executar uma ação Analisar para exami-
nar o espectro com um teste de Inteligência (Investi-
gação) contra a CD para evitar sua magia. Em caso de
sucesso, o alvo percebe que o espectro é uma ilusão e a
magia se encerra.
Enquanto afetado pela magia, o alvo trata o espectro
como se fosse real e racionaliza quaisquer resultados
ilógicos da interação com ele. Por exemplo, um alvo
que esteja tentando atravessar uma ponte espectral
e sobreviva à queda acredita na existência da ponte e
tenta achar alguma explicação para a própria queda.
Um alvo afetado pode até sofrer dano da ilusão se o
espectro representar uma criatura ou risco. Em cada
um dos seus turnos, tal espectro pode causar 2d8
pontos de dano Psíquico ao alvo se estiver na área do
espectro ou a até 1,5 metro do espectro. O alvo percebe
o dano como um tipo apropriado para a ilusão.',46,'Ilusão (Bardo, Feiticeiro, Mago)','{"level":"2","name":"Força Espectral","school":[{"text":"Ilusão (Bardo, Feiticeiro, Mago)","top":443.1335,"prose":true,"stat":false,"head":false,"page":46,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":458.79949999999997,"prose":false,"stat":false,"head":false,"page":46,"col":1}],"Alcance":[{"text":"18 metros","top":470.69939999999997,"prose":false,"stat":false,"head":false,"page":46,"col":1}],"Componentes":[{"text":"V, S, M (um pouco de lã)","top":482.59939999999995,"prose":false,"stat":false,"head":false,"page":46,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":494.49949999999995,"prose":false,"stat":false,"head":false,"page":46,"col":1}]},"desc":[{"text":"Você tenta criar uma ilusão na mente de uma criatura","top":512.5547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"à sua vista e no alcance da magia. O alvo realiza uma","top":524.4547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"salvaguarda de Inteligência. Se falhar, você cria um ob-","top":536.3548,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"jeto, criatura ou outro fenômeno espectral que não seja","top":548.2547999999999,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"maior do que um cubo de 3 metros de lado e que seja","top":560.1547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"perceptível apenas para o alvo pela duração da magia.","top":572.0546999999999,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"O espectro inclui som, temperatura e outros estímulos.","top":583.9548,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"O alvo pode executar uma ação Analisar para exami-","top":595.8547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"nar o espectro com um teste de Inteligência (Investi-","top":607.7547999999999,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"gação) contra a CD para evitar sua magia. Em caso de","top":619.6547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"sucesso, o alvo percebe que o espectro é uma ilusão e a","top":631.5546999999999,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"magia se encerra.","top":643.4548,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"Enquanto afetado pela magia, o alvo trata o espectro","top":655.3547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"como se fosse real e racionaliza quaisquer resultados","top":667.2547999999999,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"ilógicos da interação com ele. Por exemplo, um alvo","top":679.1547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"que esteja tentando atravessar uma ponte espectral","top":691.0547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"e sobreviva à queda acredita na existência da ponte e","top":702.9548,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"tenta achar alguma explicação para a própria queda.","top":714.8547,"prose":true,"stat":false,"head":false,"page":46,"col":1},{"text":"Um alvo afetado pode até sofrer dano da ilusão se o","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"espectro representar uma criatura ou risco. Em cada","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"um dos seus turnos, tal espectro pode causar 2d8","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"pontos de dano Psíquico ao alvo se estiver na área do","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"espectro ou a até 1,5 metro do espectro. O alvo percebe","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"o dano como um tipo apropriado para a ilusão.","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":47,"col":0}],"page":46}');
