INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(168,'Forma Gasosa','forma gasosa',3,5,1,'V, S, M (um pouco de gaze)','Ação','Toque','Concentração, até 1 hora','Uma criatura voluntária que você toca multimorfa-se,
junto com tudo o que está vestindo e carregando, em
uma nuvem de neblina durante a duração da magia. A
magia se encerra no alvo se ele for reduzido a 0 Pontos
de Vida ou se executar uma ação Usar Magia para
encerrá-la.
Enquanto estiver nesta forma, o único método de
movimento do alvo é um Deslocamento de Voo de 3
metros, e ele pode pairar. O alvo pode entrar e ocupar
o espaço de outra criatura. O alvo tem Resistência a
dano Contundente, Cortante e Perfurante; tem Imu-
nidade à condição Caído; e tem Vantagem em salva-
guardas de Força, Destreza e Constituição. O alvo pode
passar por aberturas estreitas, mas considera líquidos
como se fossem superfícies sólidas.
O alvo não pode falar ou manipular objetos, e qual-
quer objeto que ele estava carregando ou segurando não
pode ser derrubado, usado ou interagido de outra forma.
Por fim, o alvo não pode atacar ou conjurar magias.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher uma criatura adicional para cada
círculo de espaço de magia acima de 3.',47,'Transmutação (Bruxo, Feiticeiro, Mago)','{"level":"3","name":"Forma Gasosa","school":[{"text":"Transmutação (Bruxo, Feiticeiro, Mago)","top":598.7864,"prose":true,"stat":false,"head":false,"page":47,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":614.4524,"prose":false,"stat":false,"head":false,"page":47,"col":0}],"Alcance":[{"text":"Toque","top":626.3524,"prose":false,"stat":false,"head":false,"page":47,"col":0}],"Componentes":[{"text":"V, S, M (um pouco de gaze)","top":638.2524,"prose":false,"stat":false,"head":false,"page":47,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":650.1524,"prose":false,"stat":false,"head":false,"page":47,"col":0}]},"desc":[{"text":"Uma criatura voluntária que você toca multimorfa-se,","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"junto com tudo o que está vestindo e carregando, em","top":680.1077,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"uma nuvem de neblina durante a duração da magia. A","top":692.0077,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"magia se encerra no alvo se ele for reduzido a 0 Pontos","top":703.9077,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"de Vida ou se executar uma ação Usar Magia para","top":715.8077,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"encerrá-la.","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":47,"col":0},{"text":"Enquanto estiver nesta forma, o único método de","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"movimento do alvo é um Deslocamento de Voo de 3","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"metros, e ele pode pairar. O alvo pode entrar e ocupar","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"o espaço de outra criatura. O alvo tem Resistência a","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"dano Contundente, Cortante e Perfurante; tem Imu-","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"nidade à condição Caído; e tem Vantagem em salva-","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"guardas de Força, Destreza e Constituição. O alvo pode","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"passar por aberturas estreitas, mas considera líquidos","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"como se fossem superfícies sólidas.","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"O alvo não pode falar ou manipular objetos, e qual-","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"quer objeto que ele estava carregando ou segurando não","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"pode ser derrubado, usado ou interagido de outra forma.","top":167.2573,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"Por fim, o alvo não pode atacar ou conjurar magias.","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":191.2373,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"Você pode escolher uma criatura adicional para cada","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"círculo de espaço de magia acima de 3.","top":214.8572999999999,"prose":true,"stat":false,"head":false,"page":47,"col":1}],"page":47}');
