INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(169,'Formas Animais','formas animais',8,5,1,'V, S','Ação','9 metros','24 horas','Escolha qualquer número de criaturas voluntárias à
vista e no alcance da magia. Cada alvo se multimorfa
em uma Fera Grande ou menor à sua escolha e que
tenha um Nível de Desafio igual ou inferior a 4. Você
pode escolher uma forma diferente para cada alvo. Em
turnos posteriores, você pode executar uma ação Usar
Magia para transformar os alvos novamente.
As estatísticas de jogo de um alvo são substituídas
pelas estatísticas da Fera escolhida, mas o alvo mantém
seu tipo de criatura, Pontos de Vida, Dados de Pontos
de Vida, alinhamento, capacidade de comunicação, e
valores de atributo de Inteligência, Sabedoria e Caris-
ma. As ações do alvo são limitadas pela anatomia da
forma da Fera, e ele não pode conjurar magias. O equi-
pamento do alvo se funde com a nova forma, e o alvo
não pode usar nenhum desses equipamentos enquanto
estiver nesta forma.
O alvo adquire um número de Pontos de Vida Tem-
porários igual aos Pontos de Vida da primeira forma
que assume. Esses Pontos de Vida Temporários desapa-
recem, caso ainda restem, quando a magia terminar. A
transformação permanece pela duração da magia, até
que o alvo encerre voluntariamente a transformação
com uma Ação Bônus.',47,'Transmutação (Druida)','{"level":"8","name":"Formas Animais","school":[{"text":"Transmutação (Druida)","top":259.0612,"prose":true,"stat":false,"head":false,"page":47,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":47,"col":1}],"Alcance":[{"text":"9 metros","top":286.62719999999996,"prose":false,"stat":false,"head":false,"page":47,"col":1}],"Componentes":[{"text":"V, S","top":298.52719999999994,"prose":false,"stat":false,"head":false,"page":47,"col":1}],"Duração":[{"text":"24 horas","top":310.42719999999997,"prose":false,"stat":false,"head":false,"page":47,"col":1}]},"desc":[{"text":"Escolha qualquer número de criaturas voluntárias à","top":328.4825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"vista e no alcance da magia. Cada alvo se multimorfa","top":340.3825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"em uma Fera Grande ou menor à sua escolha e que","top":352.2825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"tenha um Nível de Desafio igual ou inferior a 4. Você","top":364.1825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"pode escolher uma forma diferente para cada alvo. Em","top":376.0825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"turnos posteriores, você pode executar uma ação Usar","top":387.9825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"Magia para transformar os alvos novamente.","top":399.8825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"As estatísticas de jogo de um alvo são substituídas","top":411.7825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"pelas estatísticas da Fera escolhida, mas o alvo mantém","top":423.6825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"seu tipo de criatura, Pontos de Vida, Dados de Pontos","top":435.5825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"de Vida, alinhamento, capacidade de comunicação, e","top":447.4825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"valores de atributo de Inteligência, Sabedoria e Caris-","top":459.3825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"ma. As ações do alvo são limitadas pela anatomia da","top":471.2825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"forma da Fera, e ele não pode conjurar magias. O equi-","top":483.1825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"pamento do alvo se funde com a nova forma, e o alvo","top":495.0825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"não pode usar nenhum desses equipamentos enquanto","top":506.9825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"estiver nesta forma.","top":518.8824999999999,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"O alvo adquire um número de Pontos de Vida Tem-","top":530.7825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"porários igual aos Pontos de Vida da primeira forma","top":542.6825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"que assume. Esses Pontos de Vida Temporários desapa-","top":554.5825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"recem, caso ainda restem, quando a magia terminar. A","top":566.4825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"transformação permanece pela duração da magia, até","top":578.3824999999999,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"que o alvo encerre voluntariamente a transformação","top":590.2825,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"com uma Ação Bônus.","top":602.1825,"prose":true,"stat":false,"head":false,"page":47,"col":1}],"page":47}');
