INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(170,'Gargalhada Nefasta de Tasha','gargalhada nefasta de tasha',1,1,1,'V, S, M (uma torta e uma pena)','Ação','9 metros','Concentração, até 1 minuto','Uma criatura à sua escolha à sua vista e no alcance da
magia realiza uma salvaguarda de Sabedoria. Se falhar,
ela está com as condições Caído e Incapacitado pela
duração da magia. Durante esse tempo, ela ri incontro-
lavelmente se for capaz de rir, e não pode encerrar a
condição Caído por si só.
No final de cada um dos turnos dela e cada vez que
sofrer dano, a criatura realiza outra salvaguarda de
Sabedoria. O alvo tem Vantagem na salvaguarda se a
salvaguarda for acionada por dano. Em caso de suces-
so, a magia encerra.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher uma criatura adicional para cada
círculo de espaço de magia acima de 1.',47,'Encantamento (Bardo, Bruxo, Mago)','{"level":"1","name":"Gargalhada Nefasta de Tasha","school":[{"text":"Encantamento (Bardo, Bruxo, Mago)","top":646.3864,"prose":true,"stat":false,"head":false,"page":47,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":662.0524,"prose":false,"stat":false,"head":false,"page":47,"col":1}],"Alcance":[{"text":"9 metros","top":673.9524,"prose":false,"stat":false,"head":false,"page":47,"col":1}],"Componentes":[{"text":"V, S, M (uma torta e uma pena)","top":685.8524,"prose":false,"stat":false,"head":false,"page":47,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":697.7524,"prose":false,"stat":false,"head":false,"page":47,"col":1}]},"desc":[{"text":"Uma criatura à sua escolha à sua vista e no alcance da","top":715.8077,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"magia realiza uma salvaguarda de Sabedoria. Se falhar,","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":47,"col":1},{"text":"ela está com as condições Caído e Incapacitado pela","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"duração da magia. Durante esse tempo, ela ri incontro-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"lavelmente se for capaz de rir, e não pode encerrar a","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"condição Caído por si só.","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"No final de cada um dos turnos dela e cada vez que","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"sofrer dano, a criatura realiza outra salvaguarda de","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"Sabedoria. O alvo tem Vantagem na salvaguarda se a","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"salvaguarda for acionada por dano. Em caso de suces-","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"so, a magia encerra.","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":143.63729999999998,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"Você pode escolher uma criatura adicional para cada","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":48,"col":0},{"text":"círculo de espaço de magia acima de 1.","top":167.2573,"prose":true,"stat":false,"head":false,"page":48,"col":0}],"page":47}');
