INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(172,'Globo de Invulnerabilidade','globo de invulnerabilidade',6,3,1,'V, S, M (uma conta de vidro)','Ação','Pessoal','Concentração, até 1 minuto','Uma barreira imóvel e cintilante aparece em uma
Emanação de 3 metros ao seu redor e permanece pela
duração da magia.
Qualquer magia de 5º círculo ou inferior conjurada
de fora da barreira não pode afetar nada dentro dela.
Tal magia pode ter como alvo criaturas e objetos den-
tro da barreira, mas a magia não tem efeito sobre eles.
Da mesma forma, a área dentro da barreira é excluída
das áreas de efeito criadas por tais magias.
Usando um Espaço de Magia de Círculo Superior. A
barreira bloqueia magias de 1º círculo ou superior para
cada círculo de espaço de magia acima de 6.',48,'Abjuração (Feiticeiro, Mago)','{"level":"6","name":"Globo de Invulnerabilidade","school":[{"text":"Abjuração (Feiticeiro, Mago)","top":282.8612,"prose":true,"stat":false,"head":false,"page":48,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":298.52719999999994,"prose":false,"stat":false,"head":false,"page":48,"col":1}],"Alcance":[{"text":"Pessoal","top":310.42719999999997,"prose":false,"stat":false,"head":false,"page":48,"col":1}],"Componentes":[{"text":"V, S, M (uma conta de vidro)","top":322.32719999999995,"prose":false,"stat":false,"head":false,"page":48,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":334.2272,"prose":false,"stat":false,"head":false,"page":48,"col":1}]},"desc":[{"text":"Uma barreira imóvel e cintilante aparece em uma","top":352.2825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"Emanação de 3 metros ao seu redor e permanece pela","top":364.1825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"duração da magia.","top":376.0825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"Qualquer magia de 5º círculo ou inferior conjurada","top":387.9825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"de fora da barreira não pode afetar nada dentro dela.","top":399.8825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"Tal magia pode ter como alvo criaturas e objetos den-","top":411.7825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"tro da barreira, mas a magia não tem efeito sobre eles.","top":423.6825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"Da mesma forma, a área dentro da barreira é excluída","top":435.5825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"das áreas de efeito criadas por tais magias.","top":447.4825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. A","top":459.3825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"barreira bloqueia magias de 1º círculo ou superior para","top":471.2825,"prose":true,"stat":false,"head":false,"page":48,"col":1},{"text":"cada círculo de espaço de magia acima de 6.","top":483.1825,"prose":true,"stat":false,"head":false,"page":48,"col":1}],"page":48}');
