INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(174,'Golpe Constritor','golpe constritor',1,4,1,'V','Ação Bônus, que você realiza
imediatamente após atingir uma criatura com uma arma','Pessoal','Concentração, até 1 minuto','Ao acertar o alvo, vinhas agarradoras aparecem nele
e ele realiza uma salvaguarda de Força. Uma criatura
Grande ou maior tem Vantagem nesta salvaguarda. Se
falhar, o alvo está com a condição Contido até que a
magia termine. Em caso de sucesso, as videiras mur-
cham e a magia se encerra.
Enquanto Contido desse modo, o alvo sofre 1d6
pontos de dano Perfurante no início de cada um dos
turnos dele. O alvo ou uma criatura ao alcance dele
pode executar uma ação para realizar um teste de For-
ça (Atletismo) contra a CD para evitar sua magia. Em
caso de sucesso, as videiras desaparecem.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d6 pontos para cada círculo de
espaço de magia acima de 1.',49,'Invocação (Guardião)','{"level":"1","name":"Golpe Constritor","school":[{"text":"Invocação (Guardião)","top":62.591999999999985,"prose":true,"stat":false,"head":false,"page":49,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus, que você realiza","top":78.0578999999999,"prose":false,"stat":false,"head":false,"page":49,"col":0},{"text":"imediatamente após atingir uma criatura com uma arma","top":89.75789999999995,"prose":false,"stat":false,"head":false,"page":49,"col":0}],"Alcance":[{"text":"Pessoal","top":101.4579,"prose":false,"stat":false,"head":false,"page":49,"col":0}],"Componentes":[{"text":"V","top":113.15789999999993,"prose":false,"stat":false,"head":false,"page":49,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":124.85789999999997,"prose":false,"stat":false,"head":false,"page":49,"col":0}]},"desc":[{"text":"Ao acertar o alvo, vinhas agarradoras aparecem nele","top":142.71319999999992,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"e ele realiza uma salvaguarda de Força. Uma criatura","top":154.41319999999996,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"Grande ou maior tem Vantagem nesta salvaguarda. Se","top":166.1131999999999,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"falhar, o alvo está com a condição Contido até que a","top":177.81319999999994,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"magia termine. Em caso de sucesso, as videiras mur-","top":189.51319999999998,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"cham e a magia se encerra.","top":201.21319999999992,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"Enquanto Contido desse modo, o alvo sofre 1d6","top":212.91319999999996,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"pontos de dano Perfurante no início de cada um dos","top":224.6131999999999,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"turnos dele. O alvo ou uma criatura ao alcance dele","top":236.31319999999994,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"pode executar uma ação para realizar um teste de For-","top":248.01319999999998,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"ça (Atletismo) contra a CD para evitar sua magia. Em","top":259.7131999999999,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"caso de sucesso, as videiras desaparecem.","top":271.41319999999996,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":283.1132,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"dano aumenta em 1d6 pontos para cada círculo de","top":294.8132,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"espaço de magia acima de 1.","top":306.5132,"prose":true,"stat":false,"head":false,"page":49,"col":0}],"page":49}');
