INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(176,'Graxa','graxa',1,4,1,'V, S, M (um pouco de banha de porco ou
manteiga)','Ação','18 metros','1 minuto','Uma graxa não inflamável cobre o solo em um qua-
drado de 3 metros de lados centrado em um ponto no
alcance da magia e o transforma em Terreno Difícil
pela duração da magia.
Quando a graxa aparece, cada criatura em pé e na
área da magia deve ser bem-sucedida em uma salva-
guarda de Destreza ou tem a condição Caído. Uma
criatura que entra na área ou termina o turno nela
também deve ser bem-sucedida nessa salvaguarda ou
fica Caída.',49,'Invocação (Feiticeiro, Mago)','{"level":"1","name":"Graxa","school":[{"text":"Invocação (Feiticeiro, Mago)","top":544.0424,"prose":true,"stat":false,"head":false,"page":49,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":559.5083,"prose":false,"stat":false,"head":false,"page":49,"col":0}],"Alcance":[{"text":"18 metros","top":571.2083,"prose":false,"stat":false,"head":false,"page":49,"col":0}],"Componentes":[{"text":"V, S, M (um pouco de banha de porco ou","top":582.9083,"prose":false,"stat":false,"head":false,"page":49,"col":0},{"text":"manteiga)","top":594.6083,"prose":false,"stat":false,"head":false,"page":49,"col":0}],"Duração":[{"text":"1 minuto","top":606.3082999999999,"prose":false,"stat":false,"head":false,"page":49,"col":0}]},"desc":[{"text":"Uma graxa não inflamável cobre o solo em um qua-","top":624.1636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"drado de 3 metros de lados centrado em um ponto no","top":635.8636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"alcance da magia e o transforma em Terreno Difícil","top":647.5636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"pela duração da magia.","top":659.2636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"Quando a graxa aparece, cada criatura em pé e na","top":670.9636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"área da magia deve ser bem-sucedida em uma salva-","top":682.6636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"guarda de Destreza ou tem a condição Caído. Uma","top":694.3636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"criatura que entra na área ou termina o turno nela","top":706.0636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"também deve ser bem-sucedida nessa salvaguarda ou","top":717.7636,"prose":true,"stat":false,"head":false,"page":49,"col":0},{"text":"fica Caída.","top":729.4636,"prose":true,"stat":false,"head":false,"page":49,"col":0}],"page":49}');
