INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(177,'Guardiões Espirituais','guardioes espirituais',3,4,1,'V, S, M (um pergaminho de oração)','Ação','Pessoal','Concentração, até 10 minutos','Espíritos protetores voam ao seu redor em uma Ema-
nação de 4,5 metros pela duração da magia. Se você
for bom ou neutro, a forma espectral deles parece
angelical ou feérica (à sua escolha). Se você é mau, eles
parecem ínferos.
Ao conjurar esta magia, você pode escolher criaturas
que não serão afetadas. O Deslocamento de quaisquer
outras criaturas é reduzido pela metade na Emanação.
Sempre que a Emanação entrar no espaço de uma cria-
tura ou uma criatura entrar na Emanação, ou terminar
seu turno nela, ela deve realizar uma salvaguarda de
Sabedoria. Se falhar, a criatura sofre 3d8 pontos de
dano Radiante (se você for bom ou neutro) ou 3d8
pontos de dano Necrótico (se for mau). Em caso de su-
cesso, a criatura sofre metade do dano. Cada criatura
realiza essa salvaguarda apenas uma vez por turno.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 3.',49,'Invocação (Clérigo)','{"level":"3","name":"Guardiões Espirituais","school":[{"text":"Invocação (Clérigo)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":49,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Alcance":[{"text":"Pessoal","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Componentes":[{"text":"V, S, M (um pergaminho de oração)","top":102.4579,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":49,"col":1}]},"desc":[{"text":"Espíritos protetores voam ao seu redor em uma Ema-","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"nação de 4,5 metros pela duração da magia. Se você","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"for bom ou neutro, a forma espectral deles parece","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"angelical ou feérica (à sua escolha). Se você é mau, eles","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"parecem ínferos.","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Ao conjurar esta magia, você pode escolher criaturas","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"que não serão afetadas. O Deslocamento de quaisquer","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"outras criaturas é reduzido pela metade na Emanação.","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Sempre que a Emanação entrar no espaço de uma cria-","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"tura ou uma criatura entrar na Emanação, ou terminar","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"seu turno nela, ela deve realizar uma salvaguarda de","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Sabedoria. Se falhar, a criatura sofre 3d8 pontos de","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"dano Radiante (se você for bom ou neutro) ou 3d8","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"pontos de dano Necrótico (se for mau). Em caso de su-","top":287.1132,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"cesso, a criatura sofre metade do dano. Cada criatura","top":299.0132,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"realiza essa salvaguarda apenas uma vez por turno.","top":310.9132,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":322.8132,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"dano aumenta em 1d8 para cada círculo de espaço de","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"magia acima de 3.","top":346.6132,"prose":true,"stat":false,"head":false,"page":49,"col":1}],"page":49}');
