INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(178,'Heroísmo','heroismo',1,1,1,'V, S','Ação','Toque','Concentração, até 1 minuto','Você toca uma criatura voluntária que se torna imbu-
ída de bravura. Até que a magia termine, a criatura é
imune à condição Amedrontado e recebe Pontos de
Vida Temporários igual ao seu modificador de atributo
de conjuração no início de cada um dos turnos dela.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher uma criatura adicional para cada
círculo de espaço de magia acima de 1.',49,'Encantamento (Bardo, Paladino)','{"level":"1","name":"Heroísmo","school":[{"text":"Encantamento (Bardo, Paladino)","top":390.8171,"prose":true,"stat":false,"head":false,"page":49,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":406.4831,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Alcance":[{"text":"Toque","top":418.38309999999996,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Componentes":[{"text":"V, S","top":430.28309999999993,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":442.18309999999997,"prose":false,"stat":false,"head":false,"page":49,"col":1}]},"desc":[{"text":"Você toca uma criatura voluntária que se torna imbu-","top":460.2384,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"ída de bravura. Até que a magia termine, a criatura é","top":472.1384,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"imune à condição Amedrontado e recebe Pontos de","top":484.0384,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Vida Temporários igual ao seu modificador de atributo","top":495.9384,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"de conjuração no início de cada um dos turnos dela.","top":507.8384,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":519.9184,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Você pode escolher uma criatura adicional para cada","top":531.6384,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"círculo de espaço de magia acima de 1.","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":49,"col":1}],"page":49}');
