INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(179,'Identificar','identificar',1,8,1,'V, S, M (uma pérola no valor de 100 ou mais PO)','1 minuto ou Ritual','Toque','Instantânea','Você toca um objeto durante a conjuração da magia.
Se for um item mágico ou algum outro objeto mágico,
você descobre suas propriedades e como usá-las, se
ele requer Sintonização e quantas cargas possui, se
houver. Você também descobre se alguma magia está
afetando o item e quais são elas. Se o item foi criado
por uma magia, você identifica o nome dessa magia.
Se em vez disso você tocar uma criatura durante a
conjuração, você descobre quais magias a estão afetan-
do, caso estejam.',49,'Adivinhação (Bardo, Mago)','{"level":"1","name":"Identificar","school":[{"text":"Adivinhação (Bardo, Mago)","top":587.7423,"prose":true,"stat":false,"head":false,"page":49,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":603.4083,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Alcance":[{"text":"Toque","top":615.3082999999999,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Componentes":[{"text":"V, S, M (uma pérola no valor de 100 ou mais PO)","top":627.2083,"prose":false,"stat":false,"head":false,"page":49,"col":1}],"Duração":[{"text":"Instantânea","top":639.1083,"prose":false,"stat":false,"head":false,"page":49,"col":1}]},"desc":[{"text":"Você toca um objeto durante a conjuração da magia.","top":657.1636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Se for um item mágico ou algum outro objeto mágico,","top":669.0636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"você descobre suas propriedades e como usá-las, se","top":680.9636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"ele requer Sintonização e quantas cargas possui, se","top":692.8636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"houver. Você também descobre se alguma magia está","top":704.7636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"afetando o item e quais são elas. Se o item foi criado","top":716.6636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"por uma magia, você identifica o nome dessa magia.","top":728.5636,"prose":true,"stat":false,"head":false,"page":49,"col":1},{"text":"Se em vez disso você tocar uma criatura durante a","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"conjuração, você descobre quais magias a estão afetan-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"do, caso estejam.","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":50,"col":0}],"page":49}');
