INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(180,'Ilusão Menor','ilusao menor',0,7,1,'S, M (um pouco de lã)','Ação','9 metros','1 minuto','Você cria um som ou uma imagem de um objeto no al-
cance da magia que permanece pela duração da magia.
Veja as descrições abaixo para os efeitos de cada um. A
ilusão encerra se você conjurar essa magia novamente.
Se uma criatura executar uma ação Analisar para
examinar o som ou a imagem, ela pode determinar que
é uma ilusão com um teste bem-sucedido de Inteligên-
cia (Investigação) contra a CD para evitar sua magia.
Se a criatura perceber a ilusão pelo que ela realmente
é, a ilusão se torna tênue para essa criatura.
Som. Se você criar um som, o volume pode variar
de um sussurro a um grito. Pode ser sua voz, a voz de
outra pessoa, o rugido de um leão, o bater de tambores
ou qualquer outro som que você escolher. O som conti-
nua ininterrupto pela duração da magia, ou você pode
criar sons distintos em diferentes momentos antes que
a magia termine.
Imagem. Se você criar a imagem de um objeto —
como uma cadeira, pegadas enlameadas ou um peque-
no baú — ela não pode ter dimensões superiores a um
cubo de 1,5 metro de lados. A imagem não pode gerar
som, luz, cheiro ou qualquer outro efeito sensorial. A
interação física com a imagem demonstra que se trata
de uma ilusão, pois os objetos podem atravessá-la.',50,'Ilusão (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"0","name":"Ilusão Menor","school":[{"text":"Ilusão (Bardo, Bruxo, Feiticeiro, Mago)","top":104.36129999999991,"prose":true,"stat":false,"head":false,"page":50,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":120.02729999999997,"prose":false,"stat":false,"head":false,"page":50,"col":0}],"Alcance":[{"text":"9 metros","top":131.92729999999995,"prose":false,"stat":false,"head":false,"page":50,"col":0}],"Componentes":[{"text":"S, M (um pouco de lã)","top":143.82729999999992,"prose":false,"stat":false,"head":false,"page":50,"col":0}],"Duração":[{"text":"1 minuto","top":155.7273,"prose":false,"stat":false,"head":false,"page":50,"col":0}]},"desc":[{"text":"Você cria um som ou uma imagem de um objeto no al-","top":173.7826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"cance da magia que permanece pela duração da magia.","top":185.68259999999998,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Veja as descrições abaixo para os efeitos de cada um. A","top":197.58259999999996,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"ilusão encerra se você conjurar essa magia novamente.","top":209.48259999999993,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Se uma criatura executar uma ação Analisar para","top":221.3825999999999,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"examinar o som ou a imagem, ela pode determinar que","top":233.2826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"é uma ilusão com um teste bem-sucedido de Inteligên-","top":245.18259999999998,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"cia (Investigação) contra a CD para evitar sua magia.","top":257.08259999999996,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Se a criatura perceber a ilusão pelo que ela realmente","top":268.98259999999993,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"é, a ilusão se torna tênue para essa criatura.","top":280.8826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Som. Se você criar um som, o volume pode variar","top":292.7826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"de um sussurro a um grito. Pode ser sua voz, a voz de","top":304.6826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"outra pessoa, o rugido de um leão, o bater de tambores","top":316.5826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"ou qualquer outro som que você escolher. O som conti-","top":328.4826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"nua ininterrupto pela duração da magia, ou você pode","top":340.3826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"criar sons distintos em diferentes momentos antes que","top":352.2826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"a magia termine.","top":364.1826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Imagem. Se você criar a imagem de um objeto —","top":376.0826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"como uma cadeira, pegadas enlameadas ou um peque-","top":387.9826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"no baú — ela não pode ter dimensões superiores a um","top":399.8826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"cubo de 1,5 metro de lados. A imagem não pode gerar","top":411.7826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"som, luz, cheiro ou qualquer outro efeito sensorial. A","top":423.6826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"interação física com a imagem demonstra que se trata","top":435.5826,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"de uma ilusão, pois os objetos podem atravessá-la.","top":447.4826,"prose":true