INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(181,'Ilusão Programada','ilusao programada',6,7,1,'V, S, M (pó de jade no valor de 25 ou mais PO)','Ação','36 metros','Até ser dissipada','Você cria a ilusão de um objeto, criatura ou outro
fenômeno visível no alcance da magia, ativada por um
gatilho específico. A ilusão permanece imperceptível
até o gatilho ocorrer. Ela não pode ser maior que um
Cubo de 9 metros de lado. Ao conjurar a magia, você
define o comportamento da ilusão e os sons que ela
emite, com duração máxima de 5 minutos.
Quando o gatilho especificado ocorre, a ilusão apare-
ce e age conforme você a descreveu. Após a conclusão,
ela desaparece e permanece inativa por 10 minutos,
podendo ser ativada novamente depois desse período.
O gatilho pode ser tão geral ou detalhado quanto
você desejar, mas deve se basear em fenômenos visuais
ou audíveis que ocorram a até 9 metros da área. Por
exemplo, você pode criar uma ilusão de si mesmo que
aparece para alertar aqueles que tentarem abrir uma
porta com armadilha.
Interação física com a imagem revela sua natureza
ilusória, já que objetos podem atravessá-la. Uma criatu-
ra que executa a ação Analisar para examinar a imagem
pode determinar que se trata de uma ilusão com um
teste bem-sucedido de Inteligência (Investigação) con-
tra a CD para evitar sua magia. Se uma criatura perce-
ber a ilusão, ela pode ver através da imagem, e qualquer
som que a ilusão emita parece vago para essa criatura.',50,'Ilusão (Bardo, Mago)','{"level":"6","name":"Ilusão Programada","school":[{"text":"Ilusão (Bardo, Mago)","top":491.6865,"prose":true,"stat":false,"head":false,"page":50,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":507.35249999999996,"prose":false,"stat":false,"head":false,"page":50,"col":0}],"Alcance":[{"text":"36 metros","top":519.2524999999999,"prose":false,"stat":false,"head":false,"page":50,"col":0}],"Componentes":[{"text":"V, S, M (pó de jade no valor de 25 ou mais PO)","top":531.1524999999999,"prose":false,"stat":false,"head":false,"page":50,"col":0}],"Duração":[{"text":"Até ser dissipada","top":543.0525,"prose":false,"stat":false,"head":false,"page":50,"col":0}]},"desc":[{"text":"Você cria a ilusão de um objeto, criatura ou outro","top":561.1078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"fenômeno visível no alcance da magia, ativada por um","top":573.0078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"gatilho específico. A ilusão permanece imperceptível","top":584.9078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"até o gatilho ocorrer. Ela não pode ser maior que um","top":596.8078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Cubo de 9 metros de lado. Ao conjurar a magia, você","top":608.7077999999999,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"define o comportamento da ilusão e os sons que ela","top":620.6078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"emite, com duração máxima de 5 minutos.","top":632.5078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"Quando o gatilho especificado ocorre, a ilusão apare-","top":644.4078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"ce e age conforme você a descreveu. Após a conclusão,","top":656.3078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"ela desaparece e permanece inativa por 10 minutos,","top":668.2078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"podendo ser ativada novamente depois desse período.","top":680.1078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"O gatilho pode ser tão geral ou detalhado quanto","top":692.0078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"você desejar, mas deve se basear em fenômenos visuais","top":703.9078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"ou audíveis que ocorram a até 9 metros da área. Por","top":715.8078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"exemplo, você pode criar uma ilusão de si mesmo que","top":727.7078,"prose":true,"stat":false,"head":false,"page":50,"col":0},{"text":"aparece para alertar aqueles que tentarem abrir uma","top":300.3559,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"porta com armadilha.","top":312.2559,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"Interação física com a imagem revela sua natureza","top":324.1558,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"ilusória, já que objetos podem atravessá-la. Uma criatu-","top":336.05580000000003,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"ra que executa a ação Analisar para examinar a imagem","top":347.9558,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"pode determinar que se trata de uma ilusão com um","top":359.8559,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"teste bem-sucedido de Inteligência (Investigação) con-","top":371.7559,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"tra a CD para evitar sua magia. Se uma criatura perce-","top":383.6558,"prose":true,"stat":false,"head":false,"page":50,"col":1},{"text":"ber a ilusão, ela pode ver através da imagem, e qualquer","top":395.55580000000003,"prose":true,"stat":false,"head":false,"page":50,"co