INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(185,'Infligir Ferimentos','infligir ferimentos',1,2,1,'V, S','Ação','Toque','Instantânea','Uma criatura que você tocar realiza uma salvaguarda
de Constituição, sofrendo 2d10 pontos de dano Necró-
tico se falhar ou metade desse dano em caso de sucesso.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d10 para cada círculo de espaço de
magia acima de 1.',51,'Necromancia (Clérigo)','{"level":"1","name":"Infligir Ferimentos","school":[{"text":"Necromancia (Clérigo)","top":306.5339,"prose":true,"stat":false,"head":false,"page":51,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":322.19989999999996,"prose":false,"stat":false,"head":false,"page":51,"col":1}],"Alcance":[{"text":"Toque","top":334.09989999999993,"prose":false,"stat":false,"head":false,"page":51,"col":1}],"Componentes":[{"text":"V, S","top":345.99989999999997,"prose":false,"stat":false,"head":false,"page":51,"col":1}],"Duração":[{"text":"Instantânea","top":357.89989999999995,"prose":false,"stat":false,"head":false,"page":51,"col":1}]},"desc":[{"text":"Uma criatura que você tocar realiza uma salvaguarda","top":375.9552,"prose":true,"stat":false,"head":false,"page":51,"col":1},{"text":"de Constituição, sofrendo 2d10 pontos de dano Necró-","top":387.8552,"prose":true,"stat":false,"head":false,"page":51,"col":1},{"text":"tico se falhar ou metade desse dano em caso de sucesso.","top":399.7552,"prose":true,"stat":false,"head":false,"page":51,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":411.6552,"prose":true,"stat":false,"head":false,"page":51,"col":1},{"text":"dano aumenta em 1d10 para cada círculo de espaço de","top":423.5552,"prose":true,"stat":false,"head":false,"page":51,"col":1},{"text":"magia acima de 1.","top":435.4552,"prose":true,"stat":false,"head":false,"page":51,"col":1}],"page":51}');
