INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(187,'Inverter a Gravidade','inverter a gravidade',7,5,1,'V, S, M (uma pedra-ímã e raspas de ferro)','Ação','30 metros','Concentração, até 1 minuto','Esta magia inverte a gravidade em um Cilindro de 15 me-
tros de raio e 30 metros de altura, centrado em um pon-
to ao alcance da magia. Todas as criaturas e objetos na
área que não estão fixos ao chão são levados para cima
até o topo do Cilindro. Uma criatura pode realizar uma
salvaguarda de Destreza para agarrar um objeto fixo que
possa alcançar, evitando assim a queda ascendente.
Se um teto ou objeto ancorado for encontrado nessa
subida, criaturas e objetos colidem com ele como em uma
queda normal. Se chegarem ao topo do Cilindro sem coli-
dir com nada, pairam lá pela duração da magia. Quando a
magia termina, criaturas e objetos afetados caem.',52,'Transmutação (Druida, Feiticeiro, Mago)','{"level":"7","name":"Inverter a Gravidade","school":[{"text":"Transmutação (Druida, Feiticeiro, Mago)","top":515.1179,"prose":true,"stat":false,"head":false,"page":52,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":530.7838999999999,"prose":false,"stat":false,"head":false,"page":52,"col":0}],"Alcance":[{"text":"30 metros","top":542.6839,"prose":false,"stat":false,"head":false,"page":52,"col":0}],"Componentes":[{"text":"V, S, M (uma pedra-ímã e raspas de ferro)","top":554.5839,"prose":false,"stat":false,"head":false,"page":52,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":566.4839,"prose":false,"stat":false,"head":false,"page":52,"col":0}]},"desc":[{"text":"Esta magia inverte a gravidade em um Cilindro de 15 me-","top":584.5391999999999,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"tros de raio e 30 metros de altura, centrado em um pon-","top":596.4392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"to ao alcance da magia. Todas as criaturas e objetos na","top":608.3392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"área que não estão fixos ao chão são levados para cima","top":620.2392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"até o topo do Cilindro. Uma criatura pode realizar uma","top":632.1392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"salvaguarda de Destreza para agarrar um objeto fixo que","top":644.0391999999999,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"possa alcançar, evitando assim a queda ascendente.","top":655.9392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"Se um teto ou objeto ancorado for encontrado nessa","top":667.8392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"subida, criaturas e objetos colidem com ele como em uma","top":679.7392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"queda normal. Se chegarem ao topo do Cilindro sem coli-","top":691.6392,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"dir com nada, pairam lá pela duração da magia. Quando a","top":703.5391999999999,"prose":true,"stat":false,"head":false,"page":52,"col":0},{"text":"magia termina, criaturas e objetos afetados caem.","top":715.4392,"prose":true,"stat":false,"head":false,"page":52,"col":0}],"page":52}');
