INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(190,'Invocação Instantânea de Drawmij','invocacao instantanea de drawmij',6,4,1,'V, S, M (uma safira no valor de 1.000 ou mais PO)','1 minuto ou Ritual','Toque','Até ser dissipada','Você toca a safira usada na conjuração e um objeto
pesando 3 quilos ou menos, cuja dimensão mais longa
é de 2 metros ou menos. A magia deixa uma marca
invisível nesse objeto e inscreve invisivelmente o nome
do objeto na safira. Cada vez que você conjura essa
magia, deve usar uma safira diferente.
Depois disso, você pode executar uma ação Usar
Magia para proferir o nome do objeto e esmagar a
safira. O objeto aparece instantaneamente em sua mão,
independentemente das distâncias físicas ou planares, e
a magia termina.
Se outra criatura estiver segurando ou carregando o
objeto, esmagar a safira não a transporta, mas, em vez
disso, você descobre quem é essa criatura e onde ela
está localizada no momento.',52,'Invocação (Mago)','{"level":"6","name":"Invocação Instantânea de Drawmij","school":[{"text":"Invocação (Mago)","top":373.5423,"prose":true,"stat":false,"head":false,"page":52,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":389.20829999999995,"prose":false,"stat":false,"head":false,"page":52,"col":1}],"Alcance":[{"text":"Toque","top":401.1083,"prose":false,"stat":false,"head":false,"page":52,"col":1}],"Componentes":[{"text":"V, S, M (uma safira no valor de 1.000 ou mais PO)","top":413.00829999999996,"prose":false,"stat":false,"head":false,"page":52,"col":1}],"Duração":[{"text":"Até ser dissipada","top":424.90829999999994,"prose":false,"stat":false,"head":false,"page":52,"col":1}]},"desc":[{"text":"Você toca a safira usada na conjuração e um objeto","top":442.9636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"pesando 3 quilos ou menos, cuja dimensão mais longa","top":454.8636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"é de 2 metros ou menos. A magia deixa uma marca","top":466.7636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"invisível nesse objeto e inscreve invisivelmente o nome","top":478.66360000000003,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"do objeto na safira. Cada vez que você conjura essa","top":490.5636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"magia, deve usar uma safira diferente.","top":502.4636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"Depois disso, você pode executar uma ação Usar","top":514.3636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"Magia para proferir o nome do objeto e esmagar a","top":526.2636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"safira. O objeto aparece instantaneamente em sua mão,","top":538.1636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"independentemente das distâncias físicas ou planares, e","top":550.0636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"a magia termina.","top":561.9636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"Se outra criatura estiver segurando ou carregando o","top":573.8636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"objeto, esmagar a safira não a transporta, mas, em vez","top":585.7636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"disso, você descobre quem é essa criatura e onde ela","top":597.6636,"prose":true,"stat":false,"head":false,"page":52,"col":1},{"text":"está localizada no momento.","top":609.5636,"prose":true,"stat":false,"head":false,"page":52,"col":1}],"page":52}');
