INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(192,'Invocar Animais','invocar animais',3,4,1,'V, S','Ação','18 metros','Concentração, até 10 minutos','Você conjura espíritos da natureza que aparecem como
um grande bando de animais espectrais e intangíveis
em um espaço desocupado à sua vista e no alcance da
magia. O bando permanece pela duração da magia e
você escolhe a forma animal dos espíritos, como lobos,
serpentes ou pássaros.
Você tem Vantagem em salvaguardas de Força
enquanto estiver a até 1,5 metro do bando e, quando se
mover no seu turno, também pode mover o bando até
9 metros para um espaço desocupado à sua vista.
Sempre que o bando se mover até 3 metros de uma
criatura à sua vista ou quando uma criatura à sua vista
entrar ou terminar seu turno a até 3 metros do bando,
você pode forçá-la a realizar uma salvaguarda de Des-
treza. Se falhar, a criatura sofre 3d10 pontos de dano
Cortante. Cada criatura só realiza essa salvaguarda
uma vez por turno.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d10 para cada círculo de espaço de
magia acima de 3.',53,'Invocação (Druida, Guardião)','{"level":"3","name":"Invocar Animais","school":[{"text":"Invocação (Druida, Guardião)","top":313.44280000000003,"prose":true,"stat":false,"head":false,"page":53,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":329.1088,"prose":false,"stat":false,"head":false,"page":53,"col":1}],"Alcance":[{"text":"18 metros","top":341.00879999999995,"prose":false,"stat":false,"head":false,"page":53,"col":1}],"Componentes":[{"text":"V, S","top":352.9088,"prose":false,"stat":false,"head":false,"page":53,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":364.80879999999996,"prose":false,"stat":false,"head":false,"page":53,"col":1}]},"desc":[{"text":"Você conjura espíritos da natureza que aparecem como","top":382.8641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"um grande bando de animais espectrais e intangíveis","top":394.7641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"em um espaço desocupado à sua vista e no alcance da","top":406.6641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"magia. O bando permanece pela duração da magia e","top":418.5641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"você escolhe a forma animal dos espíritos, como lobos,","top":430.46410000000003,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"serpentes ou pássaros.","top":442.3641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"Você tem Vantagem em salvaguardas de Força","top":454.2641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"enquanto estiver a até 1,5 metro do bando e, quando se","top":466.1641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"mover no seu turno, também pode mover o bando até","top":478.0641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"9 metros para um espaço desocupado à sua vista.","top":489.96410000000003,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"Sempre que o bando se mover até 3 metros de uma","top":501.8641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"criatura à sua vista ou quando uma criatura à sua vista","top":513.7641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"entrar ou terminar seu turno a até 3 metros do bando,","top":525.6641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"você pode forçá-la a realizar uma salvaguarda de Des-","top":537.5640999999999,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"treza. Se falhar, a criatura sofre 3d10 pontos de dano","top":549.4640999999999,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"Cortante. Cada criatura só realiza essa salvaguarda","top":561.3641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"uma vez por turno.","top":573.2641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":585.1641,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"dano aumenta em 1d10 para cada círculo de espaço de","top":597.0640999999999,"prose":true,"stat":false,"head":false,"page":53,"col":1},{"text":"magia acima de 3.","top":608.9640999999999,"prose":true,"stat":false,"head":false,"page":53,"col":1}],"page":53}');
