INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(193,'Invocar Barragem','invocar barragem',3,4,1,'V, S, M (uma arma Corpo a Corpo ou à
Distância que vale pelo menos 1 PP)','Ação','Pessoal','Instantânea','Você brande a arma usada para conjurar a magia e in-
voca armas espectrais semelhantes (ou munição apro-
priada para a arma) que são lançadas adiante e depois
desaparecem. Cada criatura à sua escolha à sua vista
em um Cone de 18 metros realiza uma salvaguarda de
Destreza, sofrendo 5d8 pontos de dano Energético se
falhar, ou metade desse dano em caso de sucesso.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 3.',53,'Invocação (Guardião)','{"level":"3","name":"Invocar Barragem","school":[{"text":"Invocação (Guardião)","top":653.168,"prose":true,"stat":false,"head":false,"page":53,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":668.834,"prose":false,"stat":false,"head":false,"page":53,"col":1}],"Alcance":[{"text":"Pessoal","top":680.7339999999999,"prose":false,"stat":false,"head":false,"page":53,"col":1}],"Componentes":[{"text":"V, S, M (uma arma Corpo a Corpo ou à","top":692.634,"prose":false,"stat":false,"head":false,"page":53,"col":1},{"text":"Distância que vale pelo menos 1 PP)","top":704.534,"prose":false,"stat":false,"head":false,"page":53,"col":1}],"Duração":[{"text":"Instantânea","top":716.434,"prose":false,"stat":false,"head":false,"page":53,"col":1}]},"desc":[{"text":"Você brande a arma usada para conjurar a magia e in-","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"voca armas espectrais semelhantes (ou munição apro-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"priada para a arma) que são lançadas adiante e depois","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"desaparecem. Cada criatura à sua escolha à sua vista","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"em um Cone de 18 metros realiza uma salvaguarda de","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Destreza, sofrendo 5d8 pontos de dano Energético se","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"falhar, ou metade desse dano em caso de sucesso.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"dano aumenta em 1d8 para cada círculo de espaço de","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"magia acima de 3.","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":54,"col":0}],"page":53}');
