INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(194,'Invocar Celestial','invocar celestial',7,4,1,'V, S','Ação','27 metros','Concentração, até 10 minutos','Você conjura um espírito dos Planos Superiores, que
se manifesta como um pilar de luz em um Cilindro de
3 metros de raio e 12 metros de altura centrado em um
ponto no alcance da magia. Para cada criatura à sua vis-
ta no Cilindro, escolha qual dessas luzes brilha sobre ela:
Luz Curativa. O alvo recupera Pontos de Vida
iguais a 4d12 mais seu modificador de atributo de
conjuração.
Luz Ardente. O alvo realiza uma salvaguarda de
Destreza, sofrendo 6d12 pontos de dano Radiante se
falhar, ou metade desse dano em caso de sucesso.
Até que a magia termine, Luz Plena preenche o Ci-
lindro e, quando você se mover no seu turno, também
pode mover o Cilindro até 9 metros.
Sempre que o Cilindro se mover para o espaço de
uma criatura à sua vista e sempre que uma criatura à
sua vista entrar no Cilindro ou terminar seu turno lá,
você pode envolvê-lo com uma das luzes. Uma criatura
pode ser afetada por esta magia apenas uma vez por
turno.
Usando um Espaço de Magia de Círculo Superior. A
cura e o dano aumentam em 1d12 para cada círculo de
espaço de magia acima de 7.',54,'Invocação (Clérigo)','{"level":"7","name":"Invocar Celestial","school":[{"text":"Invocação (Clérigo)","top":187.66129999999998,"prose":true,"stat":false,"head":false,"page":54,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":203.32719999999995,"prose":false,"stat":false,"head":false,"page":54,"col":0}],"Alcance":[{"text":"27 metros","top":215.22719999999993,"prose":false,"stat":false,"head":false,"page":54,"col":0}],"Componentes":[{"text":"V, S","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":54,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":239.0272,"prose":false,"stat":false,"head":false,"page":54,"col":0}]},"desc":[{"text":"Você conjura um espírito dos Planos Superiores, que","top":257.0825,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"se manifesta como um pilar de luz em um Cilindro de","top":268.98249999999996,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"3 metros de raio e 12 metros de altura centrado em um","top":280.8825,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"ponto no alcance da magia. Para cada criatura à sua vis-","top":292.7825,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"ta no Cilindro, escolha qual dessas luzes brilha sobre ela:","top":304.6825,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Luz Curativa. O alvo recupera Pontos de Vida","top":322.2518,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"iguais a 4d12 mais seu modificador de atributo de","top":334.1518,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"conjuração.","top":346.0518,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Luz Ardente. O alvo realiza uma salvaguarda de","top":357.9518,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Destreza, sofrendo 6d12 pontos de dano Radiante se","top":369.8518,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"falhar, ou metade desse dano em caso de sucesso.","top":381.7518,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Até que a magia termine, Luz Plena preenche o Ci-","top":399.3211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"lindro e, quando você se mover no seu turno, também","top":411.2211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"pode mover o Cilindro até 9 metros.","top":423.1211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Sempre que o Cilindro se mover para o espaço de","top":435.0211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"uma criatura à sua vista e sempre que uma criatura à","top":446.9211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"sua vista entrar no Cilindro ou terminar seu turno lá,","top":458.8211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"você pode envolvê-lo com uma das luzes. Uma criatura","top":470.7211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"pode ser afetada por esta magia apenas uma vez por","top":482.6211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"turno.","top":494.5211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. A","top":506.4211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"cura e o dano aumentam em 1d12 para cada círculo de","top":518.3211,"prose":true,"stat":false,"head":false,"page":54,"col":0},{"text":"espaço de magia acima de 7.","top":530.2211,"prose":true,"stat":false,"head":false,"page":54,"col":0}],"page":54}');
