INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(198,'Invocar Elemental','invocar elemental',5,4,1,'V, S','Ação','18 metros','Concentração, até 10 minutos','Você conjura um espírito Grande e intangível dos Pla-
nos Elementais que aparece em um espaço desocupado
no alcance da magia. Escolha o elemento do espírito,
que determina o tipo de dano que ele causa: água (Géli-
do), ar (Elétrico), fogo (Ígneo) ou terra (Trovejante). O
espírito permanece pela duração da magia.
Sempre que uma criatura à sua vista entrar no
espaço do espírito ou iniciar o turno a até 1,5 metro do
espírito, você pode forçá-la a realizar uma salvaguarda
de Destreza se o espírito não tiver nenhuma criatura
Contida. Se falhar, o alvo sofre 8d8 pontos de dano
do tipo do espírito, e tem a condição Contido até que
a magia termine. No início de cada um dos turnos do
alvo Contido, ele repete a salvaguarda. Se falhar, o alvo
sofre 4d8 pontos de dano do tipo do espírito. Em caso
de sucesso, o alvo não é Contido pelo espírito.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 5.',56,'Invocação (Druida, Mago)','{"level":"5","name":"Invocar Elemental","school":[{"text":"Invocação (Druida, Mago)","top":211.46119999999996,"prose":true,"stat":false,"head":false,"page":56,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":56,"col":0}],"Alcance":[{"text":"18 metros","top":239.0272,"prose":false,"stat":false,"head":false,"page":56,"col":0}],"Componentes":[{"text":"V, S","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":56,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":56,"col":0}]},"desc":[{"text":"Você conjura um espírito Grande e intangível dos Pla-","top":280.8825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"nos Elementais que aparece em um espaço desocupado","top":292.7825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"no alcance da magia. Escolha o elemento do espírito,","top":304.6825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"que determina o tipo de dano que ele causa: água (Géli-","top":316.5825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"do), ar (Elétrico), fogo (Ígneo) ou terra (Trovejante). O","top":328.4825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"espírito permanece pela duração da magia.","top":340.3825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"Sempre que uma criatura à sua vista entrar no","top":352.2825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"espaço do espírito ou iniciar o turno a até 1,5 metro do","top":364.1825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"espírito, você pode forçá-la a realizar uma salvaguarda","top":376.0825,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"de Destreza se o espírito não tiver nenhuma criatura","to