INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(199,'Invocar Feérico','invocar feerico',6,4,1,'V, S','Ação','18 metros','Concentração, até 10 minutos','Você conjura um espírito Médio de Faéria em um
espaço desocupado à sua vista e no alcance da magia.
O espírito permanece pela duração da magia e se asse-
melha a uma criatura Feérica à sua escolha. Quando o
espírito aparece, você pode realizar um ataque mágico
corpo a corpo contra uma criatura a até 1,5 metro dele.
Em caso de acerto, o alvo sofre dano Psíquico igual a
3d12 mais o seu modificador de atributo de conjuração,
e o alvo tem a condição Amedrontado até o início do
seu próximo turno, com você e o espírito como a fonte
do medo.
Como uma Ação Bônus em seus turnos posteriores,
você pode teleportar o espírito para um espaço desocu-
pado à sua vista a até 9 metros do espaço restante e rea-
lizar o ataque contra uma criatura a até 1,5 metro dele.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d12 para cada círculo de espaço de
magia acima de 6.',56,'Invocação (Druida)','{"level":"6","name":"Invocar Feérico","school":[{"text":"Invocação (Druida)","top":539.2864,"prose":true,"stat":false,"head":false,"page":56,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":554.9524,"prose":false,"stat":false,"head":false,"page":56,"col":0}],"Alcance":[{"text":"18 metros","top":566.8524,"prose":false,"stat":false,"head":false,"page":56,"col":0}],"Componentes":[{"text":"V, S","top":578.7524,"prose":false,"stat":false,"head":false,"page":56,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":590.6524,"prose":false,"stat":false,"head":false,"page":56,"col":0}]},"desc":[{"text":"Você conjura um espírito Médio de Faéria em um","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"espaço desocupado à sua vista e no alcance da magia.","top":620.6077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"O espírito permanece pela duração da magia e se asse-","top":632.5077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"melha a uma criatura Feérica à sua escolha. Quando o","top":644.4077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"espírito aparece, você pode realizar um ataque mágico","top":656.3077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"corpo a corpo contra uma criatura a até 1,5 metro dele.","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"Em caso de acerto, o alvo sofre dano Psíquico igual a","top":680.1077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"3d12 mais o seu modificador de atributo de conjuração,","top":692.0077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"e o alvo tem a condição Amedrontado até o início do","top":703.9077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"seu próximo turno, com você e o espírito como a fonte","top":715.8077,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"do medo.","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":56,"col":0},{"text":"Como uma Ação Bônus em seus turnos posteriores,","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":56,"col":1},{"text":"você pode teleportar o espírito para um espaço desocu-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":56,"col":1},{"text":"pado à sua vista a até 9 metros do espaço restante e rea-","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":56,"col":1},{"text":"lizar o ataque contra uma criatura a até 1,5 metro dele.","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":56,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":56,"col":1},{"text":"dano aumenta em 1d12 para cada círculo de espaço de","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":56,"col":1},{"text":"magia acima de 6.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":56,"col":1}],"page":56}');
