INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(204,'Invocar Seres da Floresta','invocar seres da floresta',4,4,1,'V, S','Ação','Pessoal','Concentração, até 10 minutos','Você conjura espíritos da natureza que voam ao seu
redor em uma Emanação de 3 metros pela duração da
magia. Quando a Emanação invade o espaço de uma
criatura à sua vista, ou quando uma criatura à sua vista
entra ou termina o turno na Emanação, você pode
forçá-la a realizar uma salvaguarda de Sabedoria. Se
falhar, a criatura sofre 5d8 pontos de dano Energético
ou metade desse dano se tiver sucesso. A criatura reali-
za essa salvaguarda apenas uma vez por turno.
Além disso, você pode executar a ação Desengajar
como uma Ação Bônus pela duração da magia.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 4.',59,'Invocação (Druida, Guardião)','{"level":"4","name":"Invocar Seres da Floresta","school":[{"text":"Invocação (Druida, Guardião)","top":283.7172,"prose":true,"stat":false,"head":false,"page":59,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":299.38309999999996,"prose":false,"stat":false,"head":false,"page":59,"col":0}],"Alcance":[{"text":"Pessoal","top":311.28309999999993,"prose":false,"stat":false,"head":false,"page":59,"col":0}],"Componentes":[{"text":"V, S","top":323.18309999999997,"prose":false,"stat":false,"head":false,"page":59,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":335.08309999999994,"prose":false,"stat":false,"head":false,"page":59,"col":0}]},"desc":[{"text":"Você conjura espíritos da natureza que voam ao seu","top":353.1384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"redor em uma Emanação de 3 metros pela duração da","top":365.0384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"magia. Quando a Emanação invade o espaço de uma","top":376.9384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"criatura à sua vista, ou quando uma criatura à sua vista","top":388.8384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"entra ou termina o turno na Emanação, você pode","top":400.7384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"forçá-la a realizar uma salvaguarda de Sabedoria. Se","top":412.6384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"falhar, a criatura sofre 5d8 pontos de dano Energético","top":424.5384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"ou metade desse dano se tiver sucesso. A criatura reali-","top":436.4384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"za essa salvaguarda apenas uma vez por turno.","top":448.3384,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"Além disso, você pode executar a ação Desengajar",