INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(205,'Labirinto','labirinto',8,4,1,'V, S','Ação','18 metros','Concentração, até 10 minutos','Você bane uma criatura à sua vista e no alcance da ma-
gia para um semiplano labiríntico. O alvo permanece lá
pela duração ou até escapar do labirinto.
O alvo pode executar uma ação Analisar para tentar
escapar. Quando isso acontece, ele realiza um teste de
Inteligência (Investigação) CD 20. Em caso de sucesso,
ele escapa e a magia se encerra.
Quando a magia termina, o alvo reaparece no espaço
que deixou ou, se esse espaço estiver ocupado, no espa-
ço desocupado mais próximo.',59,'Invocação (Mago)','{"level":"8","name":"Labirinto","school":[{"text":"Invocação (Mago)","top":552.0424,"prose":true,"stat":false,"head":false,"page":59,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":567.7083,"prose":false,"stat":false,"head":false,"page":59,"col":0}],"Alcance":[{"text":"18 metros","top":579.6083,"prose":false,"stat":false,"head":false,"page":59,"col":0}],"Componentes":[{"text":"V, S","top":591.5083,"prose":false,"stat":false,"head":false,"page":59,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":603.4083,"prose":false,"stat":false,"head":false,"page":59,"col":0}]},"desc":[{"text":"Você bane uma criatura à sua vista e no alcance da ma-","top":621.4636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"gia para um semiplano labiríntico. O alvo permanece lá","top":633.3636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"pela duração ou até escapar do labirinto.","top":645.2636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"O alvo pode executar uma ação Analisar para tentar","top":657.1636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"escapar. Quando isso acontece, ele realiza um teste de","top":669.0636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"Inteligência (Investigação) CD 20. Em caso de sucesso,","top":680.9636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"ele escapa e a magia se encerra.","top":692.8636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"Quando a magia termina, o alvo reaparece no espaço","top":704.7636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"que deixou ou, se esse espaço estiver ocupado, no espa-","top":716.6636,"prose":true,"stat":false,"head":false,"page":59,"col":0},{"text":"ço desocupado mais próximo.","top":728.5636,"prose":true,"stat":false,"head":false,"page":59,"col":0}],"page":59}');
