INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(206,'Lâmina Flamejante','lamina flamejante',2,6,1,'V, S, M (uma folha de sumagre)','Ação Bônus','Pessoal','Concentração, até 10 minutos','Você evoca uma lâmina flamejante em sua mão livre.
A lâmina é semelhante em tamanho e forma a uma
cimitarra e permanece pela duração da magia. Se você
soltar a lâmina, ela desaparece, mas você pode evocá-la
novamente como uma Ação Bônus.
Como uma ação Usar Magia, você pode realizar um
ataque mágico corpo a corpo com a lâmina flamejante.
Em caso de acerto, o alvo sofre 3d6 pontos de dano Íg-
neo mais o seu modificador de atributo de conjuração.
A lâmina flamejante emite Luz Plena em um raio de
3 metros e Meia-luz por mais 3 metros.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d6 para cada círculo de espaço de
magia acima de 2.',59,'Evocação (Druida, Feiticeiro)','{"level":"2","name":"Lâmina Flamejante","school":[{"text":"Evocação (Druida, Feiticeiro)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":59,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":59,"col":1}],"Alcance":[{"text":"Pessoal","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":59,"col":1}],"Componentes":[{"text":"V, S, M (uma folha de sumagre)","top":102.4579,"prose":false,"stat":false,"head":false,"page":59,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":59,"col":1}]},"desc":[{"text":"Você evoca uma lâmina flamejante em sua mão livre.","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"A lâmina é semelhante em tamanho e forma a uma","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"cimitarra e permanece pela duração da magia. Se você","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"soltar a lâmina, ela desaparece, mas você pode evocá-la","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"novamente como uma Ação Bônus.","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"Como uma ação Usar Magia, você pode realizar um","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"ataque mágico corpo a corpo com a lâmina flamejante.","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"Em caso de acerto, o alvo sofre 3d6 pontos de dano Íg-","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"neo mais o seu modificador de atributo de conjuração.","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"A lâmina flamejante emite Luz Plena em um raio de","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"3 metros e Meia-luz por mais 3 metros.","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"dano aumenta em 1d6 para cada círculo de espaço de","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"magia acima de 2.","top":287.1132,"prose":true,"stat":false,"head":false,"page":59,"col":1}],"page":59}');
