INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(207,'Lendas e Histórias','lendas e historias',5,8,1,'V, S, M (incenso no valor de 250 ou mais PO,
que a magia consome, e quatro tiras de marfim no valor de
50 ou mais PO cada)','10 minutos','Pessoal','Instantânea','Nomeie ou descreva uma pessoa, lugar ou objeto
famoso. A magia traz à sua mente um breve resumo
do conhecimento significativo sobre essa coisa famosa,
conforme descrito pelo Mestre.
O conhecimento pode incluir detalhes significativos,
revelações intrigantes ou até mesmo informações se-
cretas que nunca foram amplamente divulgadas. Quan-
to mais você já sabe sobre o assunto, mais precisas e
detalhadas se tornam as informações que recebe. Essas
informações são exatas, mas podem ser expressas em
linguagem figurada ou poesia, conforme determinado
pelo Mestre. Se a coisa famosa que você escolheu não
for realmente famosa, você ouve notas musicais tristes
tocadas em um trombone, e a magia falha.',59,'Adivinhação (Bardo, Clérigo, Mago)','{"level":"5","name":"Lendas e Histórias","school":[{"text":"Adivinhação (Bardo, Clérigo, Mago)","top":331.3171,"prose":true,"stat":false,"head":false,"page":59,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos","top":346.9831,"prose":false,"stat":false,"head":false,"page":59,"col":1}],"Alcance":[{"text":"Pessoal","top":358.88309999999996,"prose":false,"stat":false,"head":false,"page":59,"col":1}],"Componentes":[{"text":"V, S, M (incenso no valor de 250 ou mais PO,","top":370.78309999999993,"prose":false,"stat":false,"head":false,"page":59,"col":1},{"text":"que a magia consome, e quatro tiras de marfim no valor de","top":382.68309999999997,"prose":false,"stat":false,"head":false,"page":59,"col":1},{"text":"50 ou mais PO cada)","top":394.58309999999994,"prose":false,"stat":false,"head":false,"page":59,"col":1}],"Duração":[{"text":"Instantânea","top":406.4831,"prose":false,"stat":false,"head":false,"page":59,"col":1}]},"desc":[{"text":"Nomeie ou descreva uma pessoa, lugar ou objeto","top":424.5384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"famoso. A magia traz à sua mente um breve resumo","top":436.4384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"do conhecimento significativo sobre essa coisa famosa,","top":448.3384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"conforme descrito pelo Mestre.","top":460.2384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"O conhecimento pode incluir detalhes significativos,","top":472.1384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"revelações intrigantes ou até mesmo informações se-","top":484.0384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"cretas que nunca foram amplamente divulgadas. Quan-","top":495.9384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"to mais você já sabe sobre o assunto, mais precisas e","top":507.8384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"detalhadas se tornam as informações que recebe. Essas","top":519.7384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"informações são exatas, mas podem ser expressas em","top":531.6384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"linguagem figurada ou poesia, conforme determinado","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"pelo Mestre. Se a coisa famosa que você escolheu não","top":555.4384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"for realmente famosa, você ouve notas musicais tristes","top":567.3384,"prose":true,"stat":false,"head":false,"page":59,"col":1},{"text":"tocadas em um trombone, e a magia falha.","top":579.2384,"prose":true,"stat":false,"head":false,"page":59,"col":1}],"page":59}');
