INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(210,'Levitação','levitacao',2,5,1,'V, S, M (uma mola de metal)','Ação','18 metros','Concentração, até 10 minutos','Uma criatura ou objeto solto à sua escolha, à sua vista
e no alcance da magia sobe verticalmente até 6 metros
e permanece suspenso pela duração. A magia pode levi-
tar um objeto que pesa até 200 quilos. Uma criatura
involuntária que seja bem-sucedida em uma salvaguar-
da de Constituição não é afetada.
O alvo pode se mover apenas empurrando ou
puxando um objeto ou superfície fixa ao alcance dele
(como uma parede ou um teto), o que permite que ele
se mova como se estivesse escalando. No seu turno,
você pode mudar a altitude do alvo em até 6 metros
em qualquer direção. Se você for o alvo, pode se mover
para cima ou para baixo como parte de seu movimen-
to. Caso contrário, você pode executar uma ação Usar
Magia para mover o alvo, que deve permanecer no
alcance da magia.
Quando a magia termina, o alvo flutua suavemente
até o chão se ainda estiver no alto.',60,'Transmutação (Feiticeiro, Mago)','{"level":"2","name":"Levitação","school":[{"text":"Transmutação (Feiticeiro, Mago)","top":396.4864,"prose":true,"stat":false,"head":false,"page":60,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":412.15239999999994,"prose":false,"stat":false,"head":false,"page":60,"col":0}],"Alcance":[{"text":"18 metros","top":424.0524,"prose":false,"stat":false,"head":false,"page":60,"col":0}],"Componentes":[{"text":"V, S, M (uma mola de metal)","top":435.95239999999995,"prose":false,"stat":false,"head":false,"page":60,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":447.85239999999993,"prose":false,"stat":false,"head":false,"page":60,"col":0}]},"desc":[{"text":"Uma criatura ou objeto solto à sua escolha, à sua vista","top":465.90770000000003,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"e no alcance da magia sobe verticalmente até 6 metros","top":477.8077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"e permanece suspenso pela duração. A magia pode levi-","top":489.7077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"tar um objeto que pesa até 200 quilos. Uma criatura","top":501.6077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"involuntária que seja bem-sucedida em uma salvaguar-","top":513.5077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"da de Constituição não é afetada.","top":525.4077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"O alvo pode se mover apenas empurrando ou","top":537.3077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"puxando um objeto ou superfície fixa ao alcance dele","top":549.2076999999999,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"(como uma parede ou um teto), o que permite que ele","top":561.1077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"se mova como se estivesse escalando. No seu turno,","top":573.0077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"você pode mudar a altitude do alvo em até 6 metros","top":584.9077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"em qualquer direção. Se você for o alvo, pode se mover","top":596.8077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"para cima ou para baixo como parte de seu movimen-","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"to. Caso contrário, você pode executar uma ação Usar","top":620.6077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"Magia para mover o alvo, que deve permanecer no","top":632.5077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"alcance da magia.","top":644.4077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"Quando a magia termina, o alvo flutua suavemente","top":656.3077,"prose":true,"stat":false,"head":false,"page":60,"col":0},{"text":"até o chão se ainda estiver no alto.","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":60,"col":0}],"page":60}');
