INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(212,'Limpar a Mente','limpar a mente',8,3,1,'V, S','Ação','Toque','24 horas','Até que a magia termine, uma criatura voluntária
que você toca adquire Imunidade a dano Psíquico e
à condição Enfeitiçado. O alvo também fica imune a
qualquer coisa que possa detectar suas emoções ou
alinhamento, ler seus pensamentos, detectar magi-
camente sua localização, e nenhuma magia — nem
mesmo Desejo — pode obter informações sobre o alvo,
