INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(219,'Luz','luz',0,6,1,'V, M (um vaga-lume ou musgo fosforescente)','Ação','Toque','1 hora','Você toca em um objeto Grande ou menor que não
está sendo usado ou carregado por outra pessoa. Até
que a magia termine, o objeto emite Luz Plena em um
raio de 6 metros e Meia-luz por mais 6 metros. A luz
pode ter a cor que você desejar.
Cobrir o objeto com algo opaco bloqueia a luz. A
magia se encerra se você a conjurar novamente.',61,'Evocação (Bardo, Clérigo, Feiticeiro, Mago)','{"level":"0","name":"Luz","school":[{"text":"Evocação (Bardo, Clérigo, Feiticeiro, Mago)","top":540.1423,"prose":true,"stat":false,"head":false,"page":61,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":555.8082999999999,"prose":false,"stat":false,"head":false,"page":61,"col":1}],"Alcance":[{"text":"Toque","top":567.7083,"prose":false,"stat":false,"head":false,"page":61,"col":1}],"Componentes":[{"text":"V, M (um vaga-lume ou musgo fosforescente)","top":579.6083,"prose":false,"stat":false,"head":false,"page":61,"col":1}],"Duração":[{"text":"1 hora","top":591.5083,"prose":false,"stat":false,"head":false,"page":61,"col":1}]},"desc":[{"text":"Você toca em um objeto Grande ou menor que não","top":609.5636,"prose":true,"stat":false,"head":false,"page":61,"col":1},{"text":"está sendo usado ou carregado por outra pessoa. Até","top":621.4636,"prose":true,"stat":false,"head":false,"page":61,"col":1},{"text":"que a magia termine, o objeto emite Luz Plena em um","top":633.3636,"prose":true,"stat":false,"head":false,"page":61,"col":1},{"text":"raio de 6 metros e Meia-luz por mais 6 metros. A luz","top":645.2636,"prose":true,"stat":false,"head":false,"page":61,"col":1},{"text":"pode ter a cor que você desejar.","top":657.1636,"prose":true,"stat":false,"head":false,"page":61,"col":1},{"text":"Cobrir o objeto com algo opaco bloqueia a luz. A","top":669.0636,"prose":true,"stat":false,"head":false,"page":61,"col":1},{"text":"magia se encerra se você a conjurar novamente.","top":680.9636,"prose":true,"stat":false,"head":false,"page":61,"col":1}],"page":61}');
