INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(220,'Luz do Dia','luz do dia',3,6,1,'V, S','Ação','18 metros','1 hora','Pela duração da magia, a luz do sol se espalha de um
ponto no alcance da magia e preenche uma Esfera de
18 metros de raio. A área da luz do sol é Luz Plena e
emite Meia-luz por mais 18 metros.
Como alternativa, você conjura a magia em um objeto
que não esteja sendo usado ou carregado, fazendo com
que a luz do sol preencha uma Emanação de 18 metros
originada desse objeto. Cobrir esse objeto com algo
opaco, como uma tigela ou elmo, bloqueia a luz do sol.
Se qualquer área desta magia se sobrepuser a uma
área de Escuridão criada por uma magia de 3º círculo
ou inferior, essa outra magia é dissipada.',62,'Evocação (Clérigo, Druida, Feiticeiro, Guardião,
Paladino)','{"level":"3","name":"Luz do Dia","school":[{"text":"Evocação (Clérigo, Druida, Feiticeiro, Guardião,","top":428.9603,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"Paladino)","top":440.8603,"prose":true,"stat":false,"head":false,"page":62,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":456.52619999999996,"prose":false,"stat":false,"head":false,"page":62,"col":0}],"Alcance":[{"text":"18 metros","top":468.42619999999994,"prose":false,"stat":false,"head":false,"page":62,"col":0}],"Componentes":[{"text":"V, S","top":480.3262,"prose":false,"stat":false,"head":false,"page":62,"col":0}],"Duração":[{"text":"1 hora","top":492.22619999999995,"prose":false,"stat":false,"head":false,"page":62,"col":0}]},"desc":[{"text":"Pela duração da magia, a luz do sol se espalha de um","top":510.2815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"ponto no alcance da magia e preenche uma Esfera de","top":522.1815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"18 metros de raio. A área da luz do sol é Luz Plena e","top":534.0815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"emite Meia-luz por mais 18 metros.","top":545.9815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"Como alternativa, você conjura a magia em um objeto","top":557.8815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"que não esteja sendo usado ou carregado, fazendo com","top":569.7814999999999,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"que a luz do sol preencha uma Emanação de 18 metros","top":581.6814999999999,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"originada desse objeto. Cobrir esse objeto com algo","top":593.5815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"opaco, como uma tigela ou elmo, bloqueia a luz do sol.","top":605.4815,"prose":true,"stat":false,"head":false,"page":62,"col":0},{"text":"Se qualquer ár