INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(222,'Malogro','malogro',4,2,1,'V, S','Ação','9 metros','Instantânea','Uma criatura à sua vista e no alcance da magia realiza
uma salvaguarda de Constituição, sofrendo 8d8 pontos
de dano Necrótico se falhar ou metade desse dano em
caso de sucesso. Uma criatura do tipo Planta falha
automaticamente na salvaguarda.
Como alternativa, escolha como alvo uma planta não
mágica que não seja uma criatura, como uma árvore
ou um arbusto. Ela não realiza uma salvaguarda; ela
simplesmente murcha e morre.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d8 para cada círculo de espaço de
magia acima de 4.',62,'Necromancia (Bruxo, Druida, Feiticeiro, Mago)','{"level":"4","name":"Malogro","school":[{"text":"Necromancia (Bruxo, Druida, Feiticeiro, Mago)","top":673.4855,"prose":true,"stat":false,"head":false,"page":62,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":689.1514,"prose":false,"stat":false,"head":false,"page":62,"col":1}],"Alcance":[{"text":"9 metros","top":701.0514,"prose":false,"stat":false,"head":false,"page":62,"col":1}],"Componentes":[{"text":"V, S","top":712.9514,"prose":false,"stat":false,"head":false,"page":62,"col":1}],"Duração":[{"text":"Instantânea","top":724.8514,"prose":false,"stat":false,"head":false,"page":62,"col":1}]},"desc":[{"text":"Uma criatura à sua vista e no alcance da magia realiza","top":393.8217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"uma salvaguarda de Constituição, sofrendo 8d8 pontos","top":405.7217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"de dano Necrótico se falhar ou metade desse dano em","top":417.62170000000003,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"caso de sucesso. Uma criatura do tipo Planta falha","top":429.5217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"automaticamente na salvaguarda.","top":441.4217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"Como alternativa, escolha como alvo uma planta não","top":453.3217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"mágica que não seja uma criatura, como uma árvore","top":465.2217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"ou um arbusto. Ela não realiza uma salvaguarda; ela","top":477.12170000000003,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"simplesmente murcha e morre.","top":489.0217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":500.9217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"dano aumenta em 1d8 para cada círculo de espaço de","top":512.8217,"prose":true,"stat":false,"head":false,"page":63,"col":0},{"text":"magia acima de 4.","top":524.7217,"prose":true,"stat":false,"head":false,"page":63,"col":0}],"page":62}');
