atingir com uma arma ou um Ataque Desarmado.',64,'Evocação (Paladino)','{"level":"3","name":"Manto do Cruzado","school":[{"text":"Evocação (Paladino)","top":432.23720000000003,"prose":true,"stat":false,"head":false,"page":64,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":447.90319999999997,"prose":false,"stat":false,"head":false,"page":64,"col":0}],"Alcance":[{"text":"Pessoal","top":459.80319999999995,"prose":false,"stat":false,"head":false,"page":64,"col":0}],"Componentes":[{"text":"V","top":471.7032,"prose":false,"stat":false,"head":false,"page":64,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":483.60319999999996,"prose":false,"stat":false,"head":false,"page":64,"col":0}]},"desc":[{"text":"Você irradia uma aura mágica em uma Emanação de 9","top":501.6585,"prose":true,"stat":false,"head":false,"page":64,"col":0},{"text":"metros. Enquanto estiver na aura, você e seus aliados","top":513.5585,"prose":true,"stat":false,"head":false,"page":64,"col":0},{"text":"causam 1d4 pontos de dano Radiante adicionais ao","top":525.4585,"prose":true,"stat":false,"head":false,"page":64,"col":0},{"text":"atingir com uma arma ou um Ataque Desarmado.","top":537.3584999999999,"prose":true,"stat":false,"head":false,"page":64,"col":0}],"page":64}');
