INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(227,'Mãos Mágicas','maos magicas',0,4,1,'V, S','Ação','9 metros','1 minuto','Uma mão espectral flutuante aparece em um ponto
que você escolher no alcance da magia. A mão perma-
nece pela duração. A mão desaparece se estiver a mais
de 9 metros de você ou se você conjurar esta magia
novamente.
Ao conjurar a magia, você pode usar a mão para ma-
nipular um objeto, abrir uma porta ou um recipiente
destrancado, guardar ou recolher itens de recipientes
abertos, ou despejar o conteúdo de um frasco.
Como uma ação Usar Magia em seus próximos
turnos, você pode controlar a mão novamente. Como
parte dessa ação, você pode mover a mão até 9 metros.
A mão não pode atacar, ativar itens mágicos ou car-
regar mais de 5 quilos.',65,'Invocação (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"0","name":"Mãos Mágicas","school":[{"text":"Invocação (Bardo, Bruxo, Feiticeiro, Mago)","top":348.8866,"prose":true,"stat":false,"head":false,"page":65,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":364.55249999999995,"prose":false,"stat":false,"head":false,"page":65,"col":0}],"Alcance":[{"text":"9 metros","top":376.4525,"prose":false,"stat":false,"head":false,"page":65,"col":0}],"Componentes":[{"text":"V, S","top":388.35249999999996,"prose":false,"stat":false,"head":false,"page":65,"col":0}],"Duração":[{"text":"1 minuto","top":400.25249999999994,"prose":false,"stat":false,"head":false,"page":65,"col":0}]},"desc":[{"text":"Uma mão espectral flutuante aparece em um ponto","top":418.3078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"que você escolher no alcance da magia. A mão perma-","top":430.2078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"nece pela duração. A mão desaparece se estiver a mais","top":442.1078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"de 9 metros de você ou se você conjurar esta magia","top":454.00780000000003,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"novamente.","top":465.9078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"Ao conjurar a magia, você pode usar a mão para ma-","top":477.8078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"nipular um objeto, abrir uma porta ou um recipiente","top":489.7078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"destrancado, guardar ou recolher itens de recipientes","top":501.6078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"abertos, ou despejar o conteúdo de um frasco.","top":513.5078000000001,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"Como uma ação Usar Magia em seus próximos","top":525.4078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"turnos, você pode controlar a mão novamente. Como","top":537.3078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"parte dessa ação, você pode mover a mão até 9 metros.","top":549.2077999999999,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"A mão não pode atacar, ativar itens mágicos ou car-","top":561.1078,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"regar mais de 5 quilos.","top":573.0078,"prose":true,"stat":false,"head":false,"page":65,"col":0}],"page":65}');
