INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(228,'Marca do Predador','marca do predador',1,8,1,'V','Ação Bônus','27 metros','Concentração, até 1 hora','Você marca magicamente como sua presa uma criatura
à sua vista e no alcance da magia. Até que a magia ter-
mine, você causa 1d6 pontos de dano Energético adi-
cionais ao alvo sempre que o acertar com uma jogada
de ataque. Você também tem Vantagem em qualquer
teste de Sabedoria (Percepção ou Sobrevivência) que
realizar para encontrá-lo.
Se o alvo é reduzido a 0 Pontos de Vida antes que
esta magia termine, você pode executar uma ação
Bônus para mover a marca para uma nova criatura à
sua vista e no alcance da magia.
Usando um Espaço de Magia de Círculo Superior.
Sua Concentração pode durar mais com um espaço de
magia de 3º–4º círculo (em até 8 horas) ou 5º círculo
ou superior (em até 24 horas).',65,'Adivinhação (Guardião)','{"level":"1","name":"Marca do Predador","school":[{"text":"Adivinhação (Guardião)","top":617.2117,"prose":true,"stat":false,"head":false,"page":65,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":632.8777,"prose":false,"stat":false,"head":false,"page":65,"col":0}],"Alcance":[{"text":"27 metros","top":644.7777,"prose":false,"stat":false,"head":false,"page":65,"col":0}],"Componentes":[{"text":"V","top":656.6777,"prose":false,"stat":false,"head":false,"page":65,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":668.5777,"prose":false,"stat":false,"head":false,"page":65,"col":0}]},"desc":[{"text":"Você marca magicamente como sua presa uma criatura","top":686.633,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"à sua vista e no alcance da magia. Até que a magia ter-","top":698.533,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"mine, você causa 1d6 pontos de dano Energético adi-","top":710.433,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"cionais ao alvo sempre que o acertar com uma jogada","top":722.333,"prose":true,"stat":false,"head":false,"page":65,"col":0},{"text":"de ataque. Você também tem Vantagem em qualquer","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"teste de Sabedoria (Percepção ou Sobrevivência) que","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"realizar para encontrá-lo.","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Se o alvo é reduzido a 0 Pontos de Vida antes que","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"esta magia termine, você pode executar uma ação","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Bônus para mover a marca para uma nova criatura à","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"sua vista e no alcance da magia.","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":119.83730000000003,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Sua Concentração pode durar mais com um espaço de","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"magia de 3º–4º círculo (em até 8 horas) ou 5º círculo","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"ou superior (em até 24 horas).","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":65,"col":1}],"page":65}');
