INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(229,'Mau Olhado','mau olhado',6,2,1,'V, S','Ação','Pessoal','Concentração, até 1 minuto','Pela duração da magia, seus olhos se tornam um vazio
escuro. Uma criatura à sua escolha à sua vista e a até
18 metros de você deve ser bem-sucedida em uma
salvaguarda de Sabedoria ou é afetada por um dos
seguintes efeitos à sua escolha pela duração da magia.
Em cada um dos seus turnos até que a magia ter-
mine, você pode executar uma ação Usar Magia para
atingir outra criatura, mas não pode atingir uma cria-
tura novamente se ela tiver sido bem-sucedida em uma
salvaguarda contra a conjuração desta magia.
Adoecer. O alvo tem a condição Envenenado.
Adormecer. O alvo tem a condição Inconsciente. Ele
acorda se sofrer algum dano ou se outra criatura exe-
cutar uma ação para sacudi-la.
Apavorar. O alvo tem a condição Amedrontado. Em
cada um dos turnos dele, o alvo Amedrontado deve
executar a ação Correr e se afastar de você pela rota
mais segura e curta disponível. Se o alvo se mover para
um espaço a pelo menos 18 metros de distância de você
onde não possa vê-lo, esse efeito encerra.',65,'Necromancia (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"6","name":"Mau Olhado","school":[{"text":"Necromancia (Bardo, Bruxo, Feiticeiro, Mago)","top":199.56129999999996,"prose":true,"stat":false,"head":false,"page":65,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":215.2273,"prose":false,"stat":false,"head":false,"page":65,"col":1}],"Alcance":[{"text":"Pessoal","top":227.1273,"prose":false,"stat":false,"head":false,"page":65,"col":1}],"Componentes":[{"text":"V, S","top":239.0272,"prose":false,"stat":false,"head":false,"page":65,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":250.92729999999995,"prose":false,"stat":false,"head":false,"page":65,"col":1}]},"desc":[{"text":"Pela duração da magia, seus olhos se tornam um vazio","top":268.98249999999996,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"escuro. Uma criatura à sua escolha à sua vista e a até","top":280.8826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"18 metros de você deve ser bem-sucedida em uma","top":292.7826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"salvaguarda de Sabedoria ou é afetada por um dos","top":304.6826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"seguintes efeitos à sua escolha pela duração da magia.","top":316.5825,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Em cada um dos seus turnos até que a magia ter-","top":328.4825,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"mine, você pode executar uma ação Usar Magia para","top":340.3826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"atingir outra criatura, mas não pode atingir uma cria-","top":352.2826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"tura novamente se ela tiver sido bem-sucedida em uma","top":364.1826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"salvaguarda contra a conjuração desta magia.","top":376.0825,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Adoecer. O alvo tem a condição Envenenado.","top":387.9825,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Adormecer. O alvo tem a condição Inconsciente. Ele","top":399.8826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"acorda se sofrer algum dano ou se outra criatura exe-","top":411.7826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"cutar uma ação para sacudi-la.","top":423.6826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Apavorar. O alvo tem a condição Amedrontado. Em","top":435.5825,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"cada um dos turnos dele, o alvo Amedrontado deve","top":447.4825,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"executar a ação Correr e se afastar de você pela rota","top":459.3826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"mais segura e curta disponível. Se o alvo se mover para","top":471.2826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"um espaço a pelo menos 18 metros de distância de você","top":483.1826,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"onde não possa vê-lo, esse efeito encerra.","top":495.0825,"prose":true,"stat":false,"head":false,"page":65,"col":1}],"page":65}');
