INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(230,'Medo','medo',3,7,1,'V, S, M (uma pena branca)','Ação','Pessoal','Concentração, até 1 minuto','Cada criatura em um Cone de 9 metros deve ser bem-
-sucedida em uma salvaguarda de Sabedoria ou larga o
que estiver segurando e tem a condição Amedrontado
pela duração da magia.
Uma criatura Amedrontada executa a ação Correr e
se afasta de você pela rota mais segura em cada um dos
turnos dela, a menos que não haja para onde se mover.
Se a criatura encerrar o turno dela em um espaço onde
não tenha linha de visão para você, a criatura realiza
uma salvaguarda de Sabedoria. Em caso de sucesso, a
magia encerra naquela criatura.',65,'Ilusão (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"3","name":"Medo","school":[{"text":"Ilusão (Bardo, Bruxo, Feiticeiro, Mago)","top":539.2864999999999,"prose":true,"stat":false,"head":false,"page":65,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":554.9525,"prose":false,"stat":false,"head":false,"page":65,"col":1}],"Alcance":[{"text":"Pessoal","top":566.8524,"prose":false,"stat":false,"head":false,"page":65,"col":1}],"Componentes":[{"text":"V, S, M (uma pena branca)","top":578.7525,"prose":false,"stat":false,"head":false,"page":65,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":590.6524999999999,"prose":false,"stat":false,"head":false,"page":65,"col":1}]},"desc":[{"text":"Cada criatura em um Cone de 9 metros deve ser bem-","top":608.7077999999999,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"-sucedida em uma salvaguarda de Sabedoria ou larga o","top":620.6077,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"que estiver segurando e tem a condição Amedrontado","top":632.5077,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"pela duração da magia.","top":644.4078,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Uma criatura Amedrontada executa a ação Correr e","top":656.3077,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"se afasta de você pela rota mais segura em cada um dos","top":668.2078,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"turnos dela, a menos que não haja para onde se mover.","top":680.1077,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"Se a criatura encerrar o turno dela em um espaço onde","top":692.0077,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"não tenha linha de visão para você, a criatura realiza","top":703.9078,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"uma salvaguarda de Sabedoria. Em caso de sucesso, a","top":715.8077,"prose":true,"stat":false,"head":false,"page":65,"col":1},{"text":"magia encerra naquela criatura.","top":727.7078,"prose":true,"stat":false,"head":false,"page":65,"col":1}],"page":65}');
