INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(231,'Mensageiro Animal','mensageiro animal',2,1,1,'V, S, M (um bocado de comida)','Ação ou Ritual','9 metros','24 horas','Uma Besta Minúscula à sua escolha à sua vista e no
alcance da magia deve ser bem-sucedida em uma
salvaguarda de Carisma, ou ela tenta entregar uma
mensagem por você (se o Nível de Desafio do alvo não
for 0, ele é automaticamente bem-sucedido). Você
especifica um local que visitou e um destinatário que
corresponda a uma descrição geral, como “uma pessoa
vestida com o uniforme da guarda da cidade” ou “um
anão ruivo usando um chapéu pontudo”. Você também
comunica uma mensagem de até vinte e cinco palavras.
A Fera viaja pela duração da magia em direção ao local
especificado, cobrindo cerca de 40 quilômetros a cada
24 horas ou 80 quilômetros se a Fera puder voar.
Quando a Fera chega, ela entrega sua mensagem à
criatura que você descreveu, imitando sua comunica-
ção. Se a Fera não chegar ao seu destino antes que a
magia termine, a mensagem é perdida e a Besta retorna
para onde você conjurou a magia.
Usando um Espaço de Magia de Círculo Superior. A
duração da magia aumenta em 48 horas para cada
círculo de espaço de magia acima de 2.',66,'Encantamento (Bardo, Druida, Guardião)','{"level":"2","name":"Mensageiro Animal","school":[{"text":"Encantamento (Bardo, Druida, Guardião)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":66,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":66,"col":0}],"Alcance":[{"text":"9 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":66,"col":0}],"Componentes":[{"text":"V, S, M (um bocado de comida)","top":102.4579,"prose":false,"stat":false,"head":false,"page":66,"col":0}],"Duração":[{"text":"24 horas","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":66,"col":0}]},"desc":[{"text":"Uma Besta Minúscula à sua escolha à sua vista e no","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"alcance da magia deve ser bem-sucedida em uma","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"salvaguarda de Carisma, ou ela tenta entregar uma","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"mensagem por você (se o Nível de Desafio do alvo não","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"for 0, ele é automaticamente bem-sucedido). Você","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"especifica um local que visitou e um destinatário que","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"corresponda a uma descrição geral, como “uma pessoa","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"vestida com o uniforme da guarda da cidade” ou “um","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"anão ruivo usando um chapéu pontudo”. Você também","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"comunica uma mensagem de até vinte e cinco palavras.","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"A Fera viaja pela duração da magia em direção ao local","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"especificado, cobrindo cerca de 40 quilômetros a cada","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"24 horas ou 80 quilômetros se a Fera puder voar.","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"Quando a Fera chega, ela entrega sua mensagem à","top":287.1132,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"criatura que você descreveu, imitando sua comunica-","top":299.0132,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"ção. Se a Fera não chegar ao seu destino antes que a","top":310.9132,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"magia termine, a mensagem é perdida e a Besta retorna","top":322.8132,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"para onde você conjurou a magia.","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. A","top":346.6132,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"duração da magia aumenta em 48 horas para cada","top":358.5132,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"círculo de espaço de magia acima de 2.","top":370.4132,"prose":true,"stat":false,"head":false,"page":66,"col":0}],"page":66}');
