INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(233,'Mesclar-se às Rochas','mesclar-se as rochas',3,5,1,'V, S','Ação ou Ritual','Toque','8 horas','Você adentra em um objeto ou superfície rochosa
grande o suficiente para caber completamente seu
corpo, fundindo a si e seu equipamento com a pedra
pela duração. Você deve tocar a pedra para fazer isso.
Nada da sua presença permanece visível ou detectável
por sentidos não mágicos.
Enquanto estiver fundido com a rocha, você não
pode ver o que ocorre fora dela, e quaisquer testes
de Sabedoria (Percepção) que você realize para ouvir
sons fora dela são realizados com Desvantagem. Você
permanece ciente da passagem do tempo e pode
conjurar magias em si mesmo enquanto está fundido
à pedra. Você pode usar 1,5 metro de movimento para
sair da rocha onde entrou, o que encerra a magia. Caso
contrário, você não pode se mover.
Danos físicos menores à rocha não o afetam, mas
a destruição parcial ou mudança na forma dela (a
ponto de você não caber mais nela) o expulsa e causa
6d6 pontos de dano Energético a você. A destruição
completa da rocha (ou a transmutação dela em outra
substância) o expulsa e causa 50 pontos de dano
Energético.
Se expulso, você é movido para o espaço desocupado
mais próximo de onde entrou e tem a condição Caído.',66,'Transmutação (Clérigo, Druida, Guardião)','{"level":"3","name":"Mesclar-se às Rochas","school":[{"text":"Transmutação (Clérigo, Druida, Guardião)","top":623.4422999999999,"prose":true,"stat":false,"head":false,"page":66,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":639.1083,"prose":false,"stat":false,"head":false,"page":66,"col":0}],"Alcance":[{"text":"Toque","top":651.0083,"prose":false,"stat":false,"head":false,"page":66,"col":0}],"Componentes":[{"text":"V, S","top":662.9082999999999,"prose":false,"stat":false,"head":false,"page":66,"col":0}],"Duração":[{"text":"8 horas","top":674.8083,"prose":false,"stat":false,"head":false,"page":66,"col":0}]},"desc":[{"text":"Você adentra em um objeto ou superfície rochosa","top":692.8636,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"grande o suficiente para caber completamente seu","top":704.7636,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"corpo, fundindo a si e seu equipamento com a pedra","top":716.6636,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"pela duração. Você deve tocar a pedra para fazer isso.","top":728.5636,"prose":true,"stat":false,"head":false,"page":66,"col":0},{"text":"Nada da sua presença permanece visível ou detectável","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"por sentidos não mágicos.","top":48.157299999999964,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Enquanto estiver fundido com a rocha, você não","top":59.95729999999992,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"pode ver o que ocorre fora dela, e quaisquer testes","top":71.75739999999996,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"de Sabedoria (Percepção) que você realize para ouvir","top":83.55739999999992,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"sons fora dela são realizados com Desvantagem. Você","top":95.35739999999998,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"permanece ciente da passagem do tempo e pode","top":107.15729999999996,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"conjurar magias em si mesmo enquanto está fundido","top":118.95729999999992,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"à pedra. Você pode usar 1,5 metro de movimento para","top":130.75739999999996,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"sair da rocha onde entrou, o que encerra a magia. Caso","top":142.55739999999992,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"contrário, você não pode se mover.","top":154.35739999999998,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Danos físicos menores à rocha não o afetam, mas","top":166.15729999999996,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"a destruição parcial ou mudança na forma dela (a","top":177.9573999999999,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"ponto de você não caber mais nela) o expulsa e causa","top":189.75739999999996,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"6d6 pontos de dano Energético a você. A destruição","top":201.55739999999992,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"completa da rocha (ou a transmutação dela em outra","top":213.35739999999998,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"substância) o expulsa e causa 50 pontos de dano","top":225.15739999999994,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Energético.","top":236.9573999999999,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Se expulso, você é movido para o espaço desocupado","top":248.75739999999996,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"mais próximo de onde entrou e tem a condição Caído.","top":260.65