INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(234,'Metamorfose','metamorfose',9,5,1,'V, S, M (uma argola de jade no valor de 1.500
ou mais PO)','Ação','Pessoal','Concentração, até 1 hora','Você se multimorfa em outra criatura pela duração da
magia ou até executar uma ação Usar Magia para se
multimorfa em uma criatura diferente. A nova forma
deve ser de uma criatura com um Nível de Desafio
igual ou inferior ao seu nível ou ao seu Nível de Desa-
fio. Você deve ter visto esse tipo de criatura antes, e ela
não pode ser um Constructo ou um Morto-vivo.
Ao conjurar esta magia, você recebe um número de
Pontos de Vida Temporários igual aos Pontos de Vida
da primeira forma na qual você se transforma. Esses
Pontos de Vida Temporários desaparecem, caso ainda
restem, quando a magia terminar.
As suas estatísticas de jogo são substituídas pelo blo-
co de estatísticas da nova forma, mas você mantém seu
tipo de criatura, alinhamento, personalidade, valores
de Inteligência, Sabedoria e Carisma, Pontos de Vida,
Dados de Vida, proficiências e capacidade de comu-
nicação. Se você possuir a característica Conjuração,
também a mantém.
Ao se multimorfar, você decide se seu equipamento
cai no chão ou se altera em tamanho e forma para se
ajustar à nova forma enquanto você a mantém.',66,'Transmutação (Druida, Mago)','{"level":"9","name":"Metamorfose","school":[{"text":"Transmutação (Druida, Mago)","top":304.8614,"prose":true,"stat":false,"head":false,"page":66,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":320.52729999999997,"prose":false,"stat":false,"head":false,"page":66,"col":1}],"Alcance":[{"text":"Pessoal","top":332.42729999999995,"prose":false,"stat":false,"head":false,"page":66,"col":1}],"Componentes":[{"text":"V, S, M (uma argola de jade no valor de 1.500","top":344.3273,"prose":false,"stat":false,"head":false,"page":66,"col":1},{"text":"ou mais PO)","top":356.22729999999996,"prose":false,"stat":false,"head":false,"page":66,"col":1}],"Duração":[{"text":"Concentração, até 1 hora","top":368.12729999999993,"prose":false,"stat":false,"head":false,"page":66,"col":1}]},"desc":[{"text":"Você se multimorfa em outra criatura pela duração da","top":386.1826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"magia ou até executar uma ação Usar Magia para se","top":398.0826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"multimorfa em uma criatura diferente. A nova forma","top":409.9826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"deve ser de uma criatura com um Nível de Desafio","top":421.8826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"igual ou inferior ao seu nível ou ao seu Nível de Desa-","top":433.7826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"fio. Você deve ter visto esse tipo de criatura antes, e ela","top":445.6826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"não pode ser um Constructo ou um Morto-vivo.","top":457.5826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Ao conjurar esta magia, você recebe um número de","top":469.4826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Pontos de Vida Temporários igual aos Pontos de Vida","top":481.3826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"da primeira forma na qual você se transforma. Esses","top":493.2826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Pontos de Vida Temporários desaparecem, caso ainda","top":505.1826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"restem, quando a magia terminar.","top":517.0826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"As suas estatísticas de jogo são substituídas pelo blo-","top":528.9826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"co de estatísticas da nova forma, mas você mantém seu","top":540.8825999999999,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"tipo de criatura, alinhamento, personalidade, valores","top":552.7826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"de Inteligência, Sabedoria e Carisma, Pontos de Vida,","top":564.6826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Dados de Vida, proficiências e capacidade de comu-","top":576.5826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"nicação. Se você possuir a característica Conjuração,","top":588.4826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"também a mantém.","top":600.3825999999999,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"Ao se multimorfar, você decide se seu equipamento","top":612.2826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"cai no chão ou se altera em tamanho e forma para se","top":624.1826,"prose":true,"stat":false,"head":false,"page":66,"col":1},{"text":"ajustar à nova forma enquanto você a mantém.","top":636.0826,"prose":true,"stat":false,"head":false,"page":66,"col":1}],"page":66}');
