INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(235,'Miragem Arcana','miragem arcana',7,7,1,'V, S','10 minutos','À sua vista','10 dias','Você faz com que o terreno em uma área de até 2,5
quilômetros quadrados pareça, soe, cheire e até mesmo
seja sentido como algum outro tipo de terreno. Cam-
pos abertos ou uma estrada podem ser transformados
em um pântano, colina, fenda ou qualquer outro tipo
de terreno irregular ou intransitável. Um lago pode ser
formado para parecer um prado gramado, um precipí-
cio como uma suave encosta ou uma ravina cheia de
pedras como uma estrada larga e lisa.
Da mesma forma, você pode alterar a aparência
de estruturas ou adicioná-las onde não há nenhuma
presente. A magia não disfarça, oculta ou adiciona
criaturas.
A ilusão inclui elementos audíveis, visuais, táteis e ol-
fativos, podendo transformar terreno desimpedido em
Terreno Difícil (ou vice-versa) ou, de outra forma, di-
ficultar o movimento pela área. Qualquer parte do ter-
reno ilusório (como uma pedra ou um galho) que for
removida da área da magia desaparece imediatamente.
Criaturas com Visão Verdadeira podem ver através
da ilusão e discernir a verdadeira forma do terreno; no
entanto, todos os outros elementos da ilusão permane-
cem, de modo que, embora a criatura esteja ciente da
ilusão, ainda pode interagir fisicamente com ela.',66,'Ilusão (Bardo, Druida, Mago)','{"level":"7","name":"Miragem Arcana","school":[{"text":"Ilusão (Bardo, Druida, Mago)","top":680.2866,"prose":true,"stat":false,"head":false,"page":66,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos","top":695.9525,"prose":false,"stat":false,"head":false,"page":66,"col":1}],"Alcance":[{"text":"À sua vista","top":707.8525,"prose":false,"stat":false,"head":false,"page":66,"col":1}],"Componentes":[{"text":"V, S","top":719.7524999999999,"prose":false,"stat":false,"head":false,"page":66,"col":1}],"Duração":[{"text":"10 dias","top":731.6525,"prose":false,"stat":false,"head":false,"page":66,"col":1}]},"desc":[{"text":"Você faz com que o terreno em uma área de até 2,5","top":385.03950000000003,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"quilômetros quadrados pareça, soe, cheire e até mesmo","top":396.9396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"seja sentido como algum outro tipo de terreno. Cam-","top":408.8396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"pos abertos ou uma estrada podem ser transformados","top":420.7396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"em um pântano, colina, fenda ou qualquer outro tipo","top":432.63960000000003,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"de terreno irregular ou intransitável. Um lago pode ser","top":444.53950000000003,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"formado para parecer um prado gramado, um precipí-","top":456.4396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"cio como uma suave encosta ou uma ravina cheia de","top":468.3396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"pedras como uma estrada larga e lisa.","top":480.2396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"Da mesma forma, você pode alterar a aparência","top":492.13960000000003,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"de estruturas ou adicioná-las onde não há nenhuma","top":504.03950000000003,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"presente. A magia não disfarça, oculta ou adiciona","top":515.9395999999999,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"criaturas.","top":527.8396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"A ilusão inclui elementos audíveis, visuais, táteis e ol-","top":539.7396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"fativos, podendo transformar terreno desimpedido em","top":551.6396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"Terreno Difícil (ou vice-versa) ou, de outra forma, di-","top":563.5395,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"ficultar o movimento pela área. Qualquer parte do ter-","top":575.4395999999999,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"reno ilusório (como uma pedra ou um galho) que for","top":587.3395,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"removida da área da magia desaparece imediatamente.","top":599.2396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"Criaturas com Visão Verdadeira podem ver através","top":611.1396,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"da ilusão e discernir a verdadeira forma do terreno; no","top":623.0395,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"entanto, todos os outros elementos da ilusão permane-","top":634.9395999999999,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"cem, de modo que, embora a criatura esteja ciente da","top":646.8395,"prose":true,"stat":false,"head":false,"page":67,"col":0},{"text":"ilusão, ainda pode interagir fisicamente com ela.","top":658.7396,"prose":true,"stat":false,"head":false,"page":67,"col":0}],"page":66}');
