INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(236,'Missão','missao',5,1,1,'V','1 minuto','18 metros','30 dias','Você dá um comando verbal a uma criatura à sua
vista no alcance da magia, ordenando que ela realize
algum serviço ou não realize uma ação ou um curso de
atividade conforme você decidir. O alvo deve ser bem-
-sucedido em uma salvaguarda de Sabedoria ou tem
a condição Enfeitiçado pela duração da magia. O alvo
é bem-sucedido automaticamente se não conseguir
entender seu comando.
Enquanto Enfeitiçada, a criatura sofre 5d10 pontos
de dano Psíquico se agir de maneira diretamente con-
trária ao seu comando. Ela não sofre esse dano mais do
que uma vez por dia.
Você pode dar qualquer comando à sua escolha,
exceto uma atividade que resultaria em morte certa. Se
você der um comando suicida, a magia se encerra.
Uma magia Desejo, Remover Maldição ou Restauração
Maior encerra esta magia.
Usando um Espaço de Magia de Círculo Superior. Se
você usar um espaço de magia de 7º ou 8º círculo, a
duração é de 365 dias. Se você usar um espaço de ma-
gia de 9º círculo, a magia dura até que seja encerrada
por uma das magias mencionadas acima.',67,'Encantamento (Bardo, Clérigo, Druida, Mago,
Paladino)','{"level":"5","name":"Missão","school":[{"text":"Encantamento (Bardo, Clérigo, Druida, Mago,","top":410.87420000000003,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"Paladino)","top":422.37420000000003,"prose":true,"stat":false,"head":false,"page":67,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":437.64019999999994,"prose":false,"stat":false,"head":false,"page":67,"col":1}],"Alcance":[{"text":"18 metros","top":449.14019999999994,"prose":false,"stat":false,"head":false,"page":67,"col":1}],"Componentes":[{"text":"V","top":460.64019999999994,"prose":false,"stat":false,"head":false,"page":67,"col":1}],"Duração":[{"text":"30 dias","top":472.14019999999994,"prose":false,"stat":false,"head":false,"page":67,"col":1}]},"desc":[{"text":"Você dá um comando verbal a uma criatura à sua","top":489.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"vista no alcance da magia, ordenando que ela realize","top":501.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"algum serviço ou não realize uma ação ou um curso de","top":512.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"atividade conforme você decidir. O alvo deve ser bem-","top":524.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"-sucedido em uma salvaguarda de Sabedoria ou tem","top":535.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"a condição Enfeitiçado pela duração da magia. O alvo","top":547.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"é bem-sucedido automaticamente se não conseguir","top":558.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"entender seu comando.","top":570.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"Enquanto Enfeitiçada, a criatura sofre 5d10 pontos","top":581.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"de dano Psíquico se agir de maneira diretamente con-","top":593.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"trária ao seu comando. Ela não sofre esse dano mais do","top":604.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"que uma vez por dia.","top":616.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"Você pode dar qualquer comando à sua escolha,","top":627.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"exceto uma atividade que resultaria em morte certa. Se","top":639.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"você der um comando suicida, a magia se encerra.","top":650.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"Uma magia Desejo, Remover Maldição ou Restauração","top":662.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"Maior encerra esta magia.","top":673.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. Se","top":685.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"você usar um espaço de magia de 7º ou 8º círculo, a","top":696.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"duração é de 365 dias. Se você usar um espaço de ma-","top":708.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"gia de 9º círculo, a magia dura até que seja encerrada","top":719.7955,"prose":true,"stat":false,"head":false,"page":67,"col":1},{"text":"por uma das magias mencionadas acima.","top":731.2955,"prose":true,"stat":false,"head":false,"page":67,"col":1}],"page":67}');
