INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(237,'Mísseis Mágicos','misseis magicos',1,6,1,'V, S','Ação','36 metros','Instantânea','Você cria três dardos brilhantes feitos de pura energia
mágica. Cada dardo acerta uma criatura à sua escolha,
à sua vista e no alcance da magia. Um dardo causa 1d4
+ 1 pontos de dano Energético ao alvo. Os dardos acer-
tam ao mesmo tempo, e você pode direcioná-los para
uma mesma criatura ou várias.
Usando um Espaço de Magia de Círculo Superior. A
magia cria um dardo adicional para cada círculo de
espaço de magia acima de 1.',68,'Evocação (Feiticeiro, Mago)','{"level":"1","name":"Mísseis Mágicos","school":[{"text":"Evocação (Feiticeiro, Mago)","top":447.6042,"prose":true,"stat":false,"head":false,"page":68,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":463.27019999999993,"prose":false,"stat":false,"head":false,"page":68,"col":0}],"Alcance":[{"text":"36 metros","top":475.17019999999997,"prose":false,"stat":false,"head":false,"page":68,"col":0}],"Componentes":[{"text":"V, S","top":487.07019999999994,"prose":false,"stat":false,"head":false,"page":68,"col":0}],"Duração":[{"text":"Instantânea","top":498.9702,"prose":false,"stat":false,"head":false,"page":68,"col":0}]},"desc":[{"text":"Você cria três dardos brilhantes feitos de pura energia","top":517.0255,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"mágica. Cada dardo acerta uma criatura à sua escolha,","top":528.9255,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"à sua vista e no alcance da magia. Um dardo causa 1d4","top":540.8254999999999,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"+ 1 pontos de dano Energético ao alvo. Os dardos acer-","top":552.7255,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"tam ao mesmo tempo, e você pode direcioná-los para","top":564.6255,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"uma mesma criatura ou várias.","top":576.5255,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. A","top":588.4254999999999,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"magia cria um dardo adicional para cada círculo de","top":600.3254999999999,"prose":true,"stat":false,"head":false,"page":68,"col":0},{"text":"espaço de magia acima de 1.","top":612.2255,"prose":true,"stat":false,"head":false,"page":68,"col":0}],"page":68}');
