INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(239,'Moldar Rochas','moldar rochas',4,5,1,'V, S, M (argila mole)','Ação','Toque','Instantânea','Você toca um objeto de pedra de tamanho Médio ou
menor, ou uma seção de pedra com no máximo 1,5
metro em qualquer dimensão e o molda na forma que
desejar. Por exemplo, você pode moldar uma rocha
grande em uma arma, estátua ou baú, ou criar uma
pequena passagem por uma parede com até 1,5 metro
de espessura. Também é possível moldar uma porta de
pedra ou seu batente para selar a porta. O objeto cria-
do pode ter até duas dobradiças e uma fechadura, mas
detalhes mecânicos mais finos não são possíveis.',69,'Transmutação (Clérigo, Druida, Mago)','{"level":"4","name":"Moldar Rochas","school":[{"text":"Transmutação (Clérigo, Druida, Mago)","top":282.8612,"prose":true,"stat":false,"head":false,"page":69,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":298.52719999999994,"prose":false,"stat":false,"head":false,"page":69,"col":0}],"Alcance":[{"text":"Toque","top":310.42719999999997,"prose":false,"stat":false,"head":false,"page":69,"col":0}],"Componentes":[{"text":"V, S, M (argila mole)","top":322.32719999999995,"prose":false,"stat":false,"head":false,"page":69,"col":0}],"Duração":[{"text":"Instantânea","top":334.2272,"prose":false,"stat":false,"head":false,"page":69,"col":0}]},"desc":[{"text":"Você toca um objeto de pedra de tamanho Médio ou","top":352.2825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"menor, ou uma seção de pedra com no máximo 1,5","top":364.1825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"metro em qualquer dimensão e o molda na forma que","top":376.0825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"desejar. Por exemplo, você pode moldar uma rocha","top":387.9825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"grande em uma arma, estátua ou baú, ou criar uma","top":399.8825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"pequena passagem por uma parede com até 1,5 metro","top":411.7825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"de espessura. Também é possível moldar uma porta de","top":423.6825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"pedra ou seu batente para selar a porta. O objeto cria-","top":435.5825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"do pode ter até duas dobradiças e uma fechadura, mas","top":447.4825,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"detalhes mecânicos mais finos não são possíveis.","top":459.3825,"prose":true,"stat":false,"head":false,"page":69,"col":0}],"page":69}');
