INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(240,'Moléstia','molestia',6,2,1,'V, S','Ação','18 metros','Instantânea','Você libera magia virulenta em uma criatura à sua
vista e no alcance da magia. O alvo deve realizar uma
salvaguarda de Constituição. Se falhar, sofre 14d6 de
dano Necrótico e seus Pontos de Vida máximos são
reduzidos em um valor igual ao dano sofrido. Em caso
de sucesso, sofre apenas metade do dano. Esta magia
não pode reduzir os Pontos de Vida máximos de um
alvo abaixo de 1.',69,'Necromancia (Clérigo)','{"level":"6","name":"Moléstia","school":[{"text":"Necromancia (Clérigo)","top":503.5864,"prose":true,"stat":false,"head":false,"page":69,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":519.2524,"prose":false,"stat":false,"head":false,"page":69,"col":0}],"Alcance":[{"text":"18 metros","top":531.1524,"prose":false,"stat":false,"head":false,"page":69,"col":0}],"Componentes":[{"text":"V, S","top":543.0524,"prose":false,"stat":false,"head":false,"page":69,"col":0}],"Duração":[{"text":"Instantânea","top":554.9524,"prose":false,"stat":false,"head":false,"page":69,"col":0}]},"desc":[{"text":"Você libera magia virulenta em uma criatura à sua","top":573.0077,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"vista e no alcance da magia. O alvo deve realizar uma","top":584.9077,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"salvaguarda de Constituição. Se falhar, sofre 14d6 de","top":596.8077,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"dano Necrótico e seus Pontos de Vida máximos são","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"reduzidos em um valor igual ao dano sofrido. Em caso","top":620.6077,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"de sucesso, sofre apenas metade do dano. Esta magia","top":632.5077,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"não pode reduzir os Pontos de Vida máximos de um","top":644.4077,"prose":true,"stat":false,"head":false,"page":69,"col":0},{"text":"alvo abaixo de 1.","top":656.3077,"prose":true,"stat":false,"head":false,"page":69,"col":0}],"page":69}');
