INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(241,'Montaria Fantasmagórica','montaria fantasmagorica',3,7,1,'V, S','1 minuto ou Ritual','9 metros','1 hora','Uma criatura Grande, quase real e semelhante a um
cavalo aparece no chão em um espaço desocupado
à sua escolha no alcance da magia. Você decide a
aparência da criatura e ela é equipada com uma sela,
rédea e freio. Qualquer equipamento criado pela magia
desaparece em uma nuvem de fumaça se for carregado
a mais de 3 metros de distância da montaria.
Pela duração da magia, você ou uma criatura à sua
escolha pode usar a montaria. A montaria usa o bloco
de estatísticas do Cavalo de Montaria (veja também
o apêndice B), exceto que ele tem um Deslocamento
de 30 metros e pode viajar 20 quilômetros em uma
hora. Quando a magia termina, a montaria desaparece
gradualmente, dando ao cavaleiro 1 minuto para des-
montar. A magia se encerra se a montaria sofrer algum
dano.',69,'Ilusão (Mago)','{"level":"3","name":"Montaria Fantasmagórica","school":[{"text":"Ilusão (Mago)","top":397.5532,"prose":true,"stat":false,"head":false,"page":69,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":413.21919999999994,"prose":false,"stat":false,"head":false,"page":69,"col":1}],"Alcance":[{"text":"9 metros","top":425.1192,"prose":false,"stat":false,"head":false,"page":69,"col":1}],"Componentes":[{"text":"V, S","top":437.01919999999996,"prose":false,"stat":false,"head":false,"page":69,"col":1}],"Duração":[{"text":"1 hora","top":448.91919999999993,"prose":false,"stat":false,"head":false,"page":69,"col":1}]},"desc":[{"text":"Uma criatura Grande, quase real e semelhante a um","top":466.9745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"cavalo aparece no chão em um espaço desocupado","top":478.8745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"à sua escolha no alcance da magia. Você decide a","top":490.7745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"aparência da criatura e ela é equipada com uma sela,","top":502.6745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"rédea e freio. Qualquer equipamento criado pela magia","top":514.5745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"desaparece em uma nuvem de fumaça se for carregado","top":526.4745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"a mais de 3 metros de distância da montaria.","top":538.3745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"Pela duração da magia, você ou uma criatura à sua","top":550.2745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"escolha pode usar a montaria. A montaria usa o bloco","top":562.1745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"de estatísticas do Cavalo de Montaria (veja também","top":574.0745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"o apêndice B), exceto que ele tem um Deslocamento","top":585.9745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"de 30 metros e pode viajar 20 quilômetros em uma","top":597.8745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"hora. Quando a magia termina, a montaria desaparece","top":609.7745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"gradualmente, dando ao cavaleiro 1 minuto para des-","top":621.6745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"montar. A magia se encerra se a montaria sofrer algum","top":633.5745,"prose":true,"stat":false,"head":false,"page":69,"col":1},{"text":"dano.","top":645.4745,"prose":true,"stat":false,"head":false,"page":69,"col":1}],"page":69}');
