INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(242,'Mover Terra','mover terra',6,5,1,'V, S, M (uma pá em miniatura)','Ação','36 metros','Concentração, até 2 horas','Escolha uma área de terreno no alcance da magia, com
até 12 metros de lados. Você pode remodelar terra,
areia ou argila na área da maneira que desejar pela
duração. Você pode aumentar ou diminuir a elevação
da área, criar ou preencher uma trincheira, erguer ou
aplanar uma parede, ou formar um pilar. A extensão
dessas mudanças não pode exceder metade da maior
dimensão da área. Por exemplo, se você afetar um
quadrado de 12 metros, pode criar um pilar de até 6
metros de altura, aumentar ou diminuir a elevação do
quadrado em até 6 metros, cavar uma trincheira de até
6 metros de profundidade, e assim por diante. Essas
mudanças demoram 10 minutos para serem concluídas.
Como a transformação do terreno ocorre lentamente,
criaturas na área geralmente não ficam presas ou feri-
das pelo movimento do solo.
Ao final de cada 10 minutos que gastar se concen-
trando na magia, você pode escolher uma nova área de
terreno para afetar.
Essa magia não pode manipular pedra natural ou
construção de pedra. Rochas e estruturas se ajustam
para acomodar o novo terreno. Se a forma que você
moldar o terreno tornar uma estrutura instável, ela
pode desmoronar.
Da mesma forma, essa magia não afeta diretamente
o crescimento de plantas. A terra movida carrega qual-
quer planta junto com ela.',70,'Transmutação (Druida, Feiticeiro, Mago)','{"level":"6","name":"Mover Terra","school":[{"text":"Transmutação (Druida, Feiticeiro, Mago)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":70,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":70,"col":0}],"Alcance":[{"text":"36 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":70,"col":0}],"Componentes":[{"text":"V, S, M (uma pá em miniatura)","top":102.4579,"prose":false,"stat":false,"head":false,"page":70,"col":0}],"Duração":[{"text":"Concentração, até 2 horas","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":70,"col":0}]},"desc":[{"text":"Escolha uma área de terreno no alcance da magia, com","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"até 12 metros de lados. Você pode remodelar terra,","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"areia ou argila na área da maneira que desejar pela","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"duração. Você pode aumentar ou diminuir a elevação","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"da área, criar ou preencher uma trincheira, erguer ou","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"aplanar uma parede, ou formar um pilar. A extensão","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"dessas mudanças não pode exceder metade da maior","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"dimensão da área. Por exemplo, se você afetar um","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"quadrado de 12 metros, pode criar um pilar de até 6","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"metros de altura, aumentar ou diminuir a elevação do","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"quadrado em até 6 metros, cavar uma trincheira de até","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"6 metros de profundidade, e assim por diante. Essas","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"mudanças demoram 10 minutos para serem concluídas.","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Como a transformação do terreno ocorre lentamente,","top":287.1132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"criaturas na área geralmente não ficam presas ou feri-","top":299.0132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"das pelo movimento do solo.","top":310.9132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Ao final de cada 10 minutos que gastar se concen-","top":322.8132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"trando na magia, você pode escolher uma nova área de","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"terreno para afetar.","top":346.6132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Essa magia não pode manipular pedra natural ou","top":358.5132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"construção de pedra. Rochas e estruturas se ajustam","top":370.4132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"para acomodar o novo terreno. Se a forma que você","top":382.3132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"moldar o terreno tornar uma estrutura instável, ela","top":394.21320000000003,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"pode desmoronar.","top":406.1132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Da mesma forma, essa magia não afeta diretamente","top":418.0132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"o crescimento de plantas. A terra movida carrega qual-","top":429.9132,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"quer planta junto com ela.","top":441.8132,"prose":true,"stat":false,"head":false,"page":70,"col":0}],"page":70}');
