INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(243,'Movimentação Livre','movimentacao livre',4,3,1,'V, S, M (uma alça de couro)','Ação','Toque','1 hora','Você toca uma criatura voluntária. Pela duração da
magia, o movimento do alvo não é afetado por Terreno
Difícil, e magias e outros efeitos mágicos não podem
reduzir o Deslocamento do alvo nem fazer com que
ele tenha as condições Contido ou Paralisado. O alvo
também tem um Deslocamento de Natação igual ao
Deslocamento de caminhada.
Além disso, o alvo pode gastar 1,5 metro de movi-
mento para escapar automaticamente de restrições não
mágicas, como grilhões ou uma criatura impondo a
condição Imobilizado.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher uma criatura adicional para cada
círculo de espaço de magia acima de 4.',70,'Abjuração (Bardo, Clérigo, Druida, Guardião)','{"level":"4","name":"Movimentação Livre","school":[{"text":"Abjuração (Bardo, Clérigo, Druida, Guardião)","top":486.0171,"prose":true,"stat":false,"head":false,"page":70,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":501.68309999999997,"prose":false,"stat":false,"head":false,"page":70,"col":0}],"Alcance":[{"text":"Toque","top":513.5831,"prose":false,"stat":false,"head":false,"page":70,"col":0}],"Componentes":[{"text":"V, S, M (uma alça de couro)","top":525.4830999999999,"prose":false,"stat":false,"head":false,"page":70,"col":0}],"Duração":[{"text":"1 hora","top":537.3831,"prose":false,"stat":false,"head":false,"page":70,"col":0}]},"desc":[{"text":"Você toca uma criatura voluntária. Pela duração da","top":555.4384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"magia, o movimento do alvo não é afetado por Terreno","top":567.3384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Difícil, e magias e outros efeitos mágicos não podem","top":579.2384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"reduzir o Deslocamento do alvo nem fazer com que","top":591.1384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"ele tenha as condições Contido ou Paralisado. O alvo","top":603.0383999999999,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"também tem um Deslocamento de Natação igual ao","top":614.9384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Deslocamento de caminhada.","top":626.8384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Além disso, o alvo pode gastar 1,5 metro de movi-","top":638.7384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"mento para escapar automaticamente de restrições não","top":650.6384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"mágicas, como grilhões ou uma criatura impondo a","top":662.5384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"condição Imobilizado.","top":674.4384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":686.5183999999999,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"Você pode escolher uma criatura adicional para cada","top":698.2384,"prose":true,"stat":false,"head":false,"page":70,"col":0},{"text":"círculo de espaço de magia acima de 4.","top":710.1384,"prose":true,"stat":false,"head":false,"page":70,"col":0}],"page":70}');
