INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(244,'Muralha de Energia','muralha de energia',5,6,1,'V, S, M (um caco de vidro)','Ação','36 metros','Concentração, até 10 minutos','Uma muralha de energia invisível surge em um ponto
à sua escolha no alcance da magia. A muralha aparece
em qualquer direção que você escolher, como uma
barreira horizontal, vertical ou inclinação. Pode flutuar
livremente ou repousar sobre uma superfície sólida.
Você pode moldá-la em um domo hemisférico ou em
um globo com um raio de até 3 metros, ou em uma
superfície plana composta por dez painéis de 3 metros
de lados. Cada painel deve ser contíguo a outro painel.
De qualquer forma, a parede tem 6 milímetros de es-
pessura e permanece pela duração da magia. Ao surgir,
se a muralha passar por um espaço ocupado por uma
criatura, a criatura é empurrada para um dos lados da
muralha (à sua escolha).
Nada pode passar fisicamente pela muralha. Ela é
imune a todo tipo de dano e não pode ser anulada por
Dissipar Magia. Entretanto, a magia Desintegrar a destrói
instantaneamente. A muralha também se estende para
o Plano Etéreo, e bloqueia viagens etéreas através dela.',70,'Evocação (Mago)','{"level":"5","name":"Muralha de Energia","school":[{"text":"Evocação (Mago)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":70,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":70,"col":1}],"Alcance":[{"text":"36 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":70,"col":1}],"Componentes":[{"text":"V, S, M (um caco de vidro)","top":102.4579,"prose":false,"stat":false,"head":false,"page":70,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":70,"col":1}]},"desc":[{"text":"Uma muralha de energia invisível surge em um ponto","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"à sua escolha no alcance da magia. A muralha aparece","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"em qualquer direção que você escolher, como uma","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"barreira horizontal, vertical ou inclinação. Pode flutuar","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"livremente ou repousar sobre uma superfície sólida.","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Você pode moldá-la em um domo hemisférico ou em","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"um globo com um raio de até 3 metros, ou em uma","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"superfície plana composta por dez painéis de 3 metros","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"de lados. Cada painel deve ser contíguo a outro painel.","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"De qualquer forma, a parede tem 6 milímetros de es-","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"pessura e permanece pela duração da magia. Ao surgir,","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"se a muralha passar por um espaço ocupado por uma","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"criatura, a criatura é empurrada para um dos lados da","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"muralha (à sua escolha).","top":287.1132,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Nada pode passar fisicamente pela muralha. Ela é","top":299.0132,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"imune a todo tipo de dano e não pode ser anulada por","top":310.9132,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Dissipar Magia. Entretanto, a magia Desintegrar a destrói","top":322.8132,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"instantaneamente. A muralha também se estende para","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"o Plano Etéreo, e bloqueia viagens etéreas através dela.","top":346.6132,"prose":true,"stat":false,"head":false,"page":70,"col":1}],"page":70}');
