INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(245,'Muralha de Espinhos','muralha de espinhos',6,4,1,'V, S, M (um punhado de espinhos)','Uma ação','36 metros','Concentração, até 10 minutos','Você cria uma muralha com um emaranhado de espi-
nhos que parecem agulhas. A muralha aparece em uma
superfície sólida, à sua vista e no alcance da magia e
permanece pela duração. É possível escolher entre uma
muralha de até 18 metros de comprimento, 3 metros
de altura e 1,5 metro de espessura ou um círculo que
tenha até 6 metros de diâmetro, 6 metros de altura e
1,5 metro de espessura. A muralha bloqueia a linha de
visão.
Quando a muralha aparece, cada criatura na área
dela realiza uma salvaguarda de Destreza, sofrendo
7d8 pontos de dano Perfurante se falhar, ou metade
desse dano em caso de sucesso.
Uma criatura pode se mover através da parede,
embora lenta e dolorosamente. Para cada 1,5 metro
que uma criatura atravessa a parede, ela deve gastar 6
metros de movimento. Além disso, a primeira vez que
uma criatura entra em um espaço na muralha ou ter-
mina o turno dela lá, a criatura realiza uma salvaguar-
da de Destreza, sofrendo 7d8 pontos de dano Cortante
se falhar ou metade desse dano em caso de sucesso.
Uma criatura realiza essa salvaguarda apenas uma vez
por turno.
Usando um Espaço de Magia de Círculo Superior.
Ambos os tipos de dano aumentam em 1d8 para cada
círculo de espaço de magia acima de 6.',70,'Invocação (Druida)','{"level":"6","name":"Muralha de Espinhos","school":[{"text":"Invocação (Druida)","top":390.8171,"prose":true,"stat":false,"head":false,"page":70,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Uma ação","top":406.4831,"prose":false,"stat":false,"head":false,"page":70,"col":1}],"Alcance":[{"text":"36 metros","top":418.38309999999996,"prose":false,"stat":false,"head":false,"page":70,"col":1}],"Componentes":[{"text":"V, S, M (um punhado de espinhos)","top":430.28309999999993,"prose":false,"stat":false,"head":false,"page":70,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":442.18309999999997,"prose":false,"stat":false,"head":false,"page":70,"col":1}]},"desc":[{"text":"Você cria uma muralha com um emaranhado de espi-","top":460.2384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"nhos que parecem agulhas. A muralha aparece em uma","top":472.1384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"superfície sólida, à sua vista e no alcance da magia e","top":484.0384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"permanece pela duração. É possível escolher entre uma","top":495.9384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"muralha de até 18 metros de comprimento, 3 metros","top":507.8384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"de altura e 1,5 metro de espessura ou um círculo que","top":519.7384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"tenha até 6 metros de diâmetro, 6 metros de altura e","top":531.6384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"1,5 metro de espessura. A muralha bloqueia a linha de","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"visão.","top":555.4384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Quando a muralha aparece, cada criatura na área","top":567.3384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"dela realiza uma salvaguarda de Destreza, sofrendo","top":579.2384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"7d8 pontos de dano Perfurante se falhar, ou metade","top":591.1384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"desse dano em caso de sucesso.","top":603.0383999999999,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Uma criatura pode se mover através da parede,","top":614.9384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"embora lenta e dolorosamente. Para cada 1,5 metro","top":626.8384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"que uma criatura atravessa a parede, ela deve gastar 6","top":638.7384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"metros de movimento. Além disso, a primeira vez que","top":650.6384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"uma criatura entra em um espaço na muralha ou ter-","top":662.5384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"mina o turno dela lá, a criatura realiza uma salvaguar-","top":674.4384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"da de Destreza, sofrendo 7d8 pontos de dano Cortante","top":686.3384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"se falhar ou metade desse dano em caso de sucesso.","top":698.2384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Uma criatura realiza essa salvaguarda apenas uma vez","top":710.1384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"por turno.","top":722.0384,"prose":true,"stat":false,"head":false,"page":70,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":36.53740000000005,"prose":true,"stat":false,"head":false,"page":71,"col":0},{"text":"Ambos os tipos de dano aumentam em 1d8 para cada","top":48.25739999999996,"prose":true,"stat