INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(249,'Muralha de Vento','muralha de vento',3,6,1,'V, S, M (um leque e uma pena)','Ação','36 metros','Concentração, até 1 minuto','Uma muralha de vento forte sobe do chão em um
ponto à sua escolha no alcance da magia. Você pode
realizar uma parede de até 15 metros de comprimento,
4,5 metros de altura e 30 centímetros de espessura.
Você pode moldar a parede da maneira que quiser,
desde que ela faça um caminho contínuo ao longo do
chão. A muralha permanece pela duração da magia.
Quando a muralha surge, cada criatura na área dela
realiza uma salvaguarda de Força, sofrendo 4d8 pontos
de dano Contundente se falhar, ou metade desse dano
em caso de sucesso.
O vento forte mantém névoa, fumaça e outros gases
afastados. Criaturas ou objetos Pequenos ou menores
não podem atravessar a muralha. Materiais soltos e
leves que entrem na muralha são lançados para cima.
Flechas, virotes e outros projéteis comuns disparados
contra alvos atrás da muralha são desviados para cima
e erram automaticamente. Pedras arremessadas por
Gigantes ou máquinas de cerco, assim como projéteis
semelhantes, não são afetados. Criaturas em forma
gasosa não conseguem atravessar a muralha.',72,'Evocação (Druida, Guardião)','{"level":"3","name":"Muralha de Vento","school":[{"text":"Evocação (Druida, Guardião)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":72,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":72,"col":0}],"Alcance":[{"text":"36 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":72,"col":0}],"Componentes":[{"text":"V, S, M (um leque e uma pena)","top":102.4579,"prose":false,"stat":false,"head":false,"page":72,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":72,"col":0}]},"desc":[{"text":"Uma muralha de vento forte sobe do chão em um","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"ponto à sua escolha no alcance da magia. Você pode","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"realizar uma parede de até 15 metros de comprimento,","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"4,5 metros de altura e 30 centímetros de espessura.","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"Você pode moldar a parede da maneira que quiser,","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"desde que ela faça um caminho contínuo ao longo do","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"chão. A muralha permanece pela duração da magia.","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"Quando a muralha surge, cada criatura na área dela","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"realiza uma salvaguarda de Força, sofrendo 4d8 pontos","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"de dano Contundente se falhar, ou metade desse dano","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"em caso de sucesso.","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"O vento forte mantém névoa, fumaça e outros gases","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"afastados. Criaturas ou objetos Pequenos ou menores","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"não podem atravessar a muralha. Materiais soltos e","top":287.1132,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"leves que entrem na muralha são lançados para cima.","top":299.0132,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"Flechas, virotes e outros projéteis comuns disparados","top":310.9132,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"contra alvos atrás da muralha são desviados para cima","top":322.8132,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"e erram automaticamente. Pedras arremessadas por","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"Gigantes ou máquinas de cerco, assim como projéteis","top":346.6132,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"semelhantes, não são afetados. Criaturas em forma","top":358.5132,"prose":true,"stat":false,"head":false,"page":72,"col":0},{"text":"gasosa não conseguem atravessar a muralha.","top":370.4132,"prose":true,"stat":false,"head":false,"page":72,"col":0}],"page":72}');
