INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(251,'Nevasca','nevasca',3,4,1,'V, S, M (um guarda-chuva em miniatura)','Ação','45 metros','Concentração, até 1 minuto','Até que a magia termine, granizo cai em um Cilindro
de 12 metros de altura e 6 metros de raio centrado em
um ponto à sua escolha no alcance da magia. A área
está Totalmente Obscurecida e as chamas expostas na
área são apagadas.
O Solo no Cilindro é Terreno Difícil. Quando uma
criatura entra no Cilindro pela primeira vez em um
turno ou começa o turno dela nele, deve ser bem-suce-
dida em uma salvaguarda de Destreza ou está Caída e
perde a Concentração.',73,'Invocação (Druida, Feiticeiro, Mago)','{"level":"3","name":"Nevasca","school":[{"text":"Invocação (Druida, Feiticeiro, Mago)","top":197.29539999999997,"prose":true,"stat":false,"head":false,"page":73,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":212.9613999999999,"prose":false,"stat":false,"head":false,"page":73,"col":0}],"Alcance":[{"text":"45 metros","top":224.8614,"prose":false,"stat":false,"head":false,"page":73,"col":0}],"Componentes":[{"text":"V, S, M (um guarda-chuva em miniatura)","top":236.76139999999998,"prose":false,"stat":false,"head":false,"page":73,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":248.66139999999996,"prose":false,"stat":false,"head":false,"page":73,"col":0}]},"desc":[{"text":"Até que a magia termine, granizo cai em um Cilindro","top":266.71669999999995,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"de 12 metros de altura e 6 metros de raio centrado em","top":278.6166999999999,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"um ponto à sua escolha no alcance da magia. A área","top":290.5167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"está Totalmente Obscurecida e as chamas expostas na","top":302.4167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"área são apagadas.","top":314.3167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"O Solo no Cilindro é Terreno Difícil. Quando uma","top":326.2167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"criatura entra no Cilindro pela primeira vez em um","top":338.1167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"turno ou começa o turno dela nele, deve ser bem-suce-","top":350.0167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"dida em uma salvaguarda de Destreza ou está Caída e","top":361.9167,"prose":true,"stat":false,"head":false,"page":73,"col":0},{"text":"perde a Concentração.","top