INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(261,'Orbe Cromático','orbe cromatico',1,6,1,'V, S, M (um diamante no valor de 50 ou mais PO)','Ação','27 metros','Instantânea','Você arremessa um orbe de energia em um alvo no
alcance da magia. Escolha Ácido, Elétrico, Gélido,
Ígneo, Trovejante ou Venenoso para o tipo de orbe que
você criar e, em seguida, realize um ataque mágico à
distância contra o alvo. Em caso de acerto, o alvo sofre
3d8 pontos de dano do tipo escolhido.
Se você jogar o mesmo número em dois ou mais dos
dados d8, o orbe salta para outro alvo à sua escolha
dentro de 9 metros do alvo. Realize uma jogada de
ataque contra o novo alvo e realize uma nova jogada
de dano. A esfera não pode saltar novamente, a menos
que você conjure a magia usando um espaço de magia
de 2º círculo ou superior.
Usando um Espaço de Magia de Círculo Superior.
O dano aumenta em 1d8 para cada círculo de espaço
de magia acima de 1. O orbe pode saltar um número
máximo de vezes igual ao círculo do espaço de magia
utilizado, e uma criatura pode ser atingida apenas uma
vez por cada conjuração desta magia.',74,'Evocação (Feiticeiro, Mago)','{"level":"1","name":"Orbe Cromático","school":[{"text":"Evocação (Feiticeiro, Mago)","top":504.4423,"prose":true,"stat":false,"head":false,"page":74,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":520.1083,"prose":false,"stat":false,"head":false,"page":74,"col":1}],"Alcance":[{"text":"27 metros","top":532.0083,"prose":false,"stat":false,"head":false,"page":74,"col":1}],"Componentes":[{"text":"V, S, M (um diamante no valor de 50 ou mais PO)","top":543.9083,"prose":false,"stat":false,"head":false,"page":74,"col":1}],"Duração":[{"text":"Instantânea","top":555.8082999999999,"prose":false,"stat":false,"head":false,"page":74,"col":1}]},"desc":[{"text":"Você arremessa um orbe de energia em um alvo no","top":573.8636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"alcance da magia. Escolha Ácido, Elétrico, Gélido,","top":585.7636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"Ígneo, Trovejante ou Venenoso para o tipo de orbe que","top":597.6636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"você criar e, em seguida, realize um ataque mágico à","top":609.5636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"distância contra o alvo. Em caso de acerto, o alvo sofre","top":621.4636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"3d8 pontos de dano do tipo escolhido.","top":633.3636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"Se você jogar o mesmo número em dois ou mais dos","top":645.2636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"dados d8, o orbe salta para outro alvo à sua escolha","top":657.1636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"dentro de 9 metros do alvo. Realize uma jogada de","top":669.0636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"ataque contra o novo alvo e realize uma nova jogada","top":680.9636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"de dano. A esfera não pode saltar novamente, a menos","top":692.8636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"que você conjure a magia usando um espaço de magia","top":704.7636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"de 2º círculo ou superior.","top":716.6636,"prose":true,"stat":false,"head":false,"page":74,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":416.8718,"prose":true,"stat":false,"head":false,"page":75,"col":0},{"text":"O dano aumenta em 1d8 para cada círculo de espaço","top":428.5918,"prose":true,"stat":false,"head":false,"page":75,"col":0},{"text":"de magia acima de 1. O orbe pode saltar um número","top":440.4918,"prose":true,"stat":false,"head":false,"page":75,"col":0},{"text":"máximo de vezes igual ao círculo do espaço de magia","top":452.3918,"prose":true,"stat":false,"head":false,"page":75,"col":0},{"text":"utilizado, e uma criatura pode ser atingida apenas uma","top":464.2918,"prose":true,"stat":false,"head":false,"page":75,"col":0},{"text":"vez por cada conjuração desta magia.","top":476.1918,"prose":true,"stat":false,"head":false,"page":75,"col":0}],"page":74}');
