do a condição em caso de sucesso.',76,'Encantamento (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"8","name":"Palavra de Poder: Atordoar","school":[{"text":"Encantamento (Bardo, Bruxo, Feiticeiro, Mago)","top":236.11709999999994,"prose":true,"stat":false,"head":false,"page":76,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":251.7831,"prose":false,"stat":false,"head":false,"page":76,"col":0}],"Alcance":[{"text":"18 metros","top":263.68309999999997,"prose":false,"stat":false,"head":false,"page":76,"col":0}],"Componentes":[{"text":"V","top":275.58309999999994,"prose":false,"stat":false,"head":false,"page":76,"col":0}],"Duração":[{"text":"Instantânea","top":287.4831,"prose":false,"stat":false,"head":false,"page":76,"col":0}]},"desc":[{"text":"Você domina a mente de uma criatura à sua vista e no","top":305.5384,"prose":true,"stat":false,"head":false,"page":76,"col":0},{"text":"alcance da magia. Se o alvo tiver 150 Pontos de Vida ou","top":317.4384,"prose":true,"stat":false,"head":false,"page":76,"col":0},{"text":"menos, ele tem a condição Atordoado. Caso contrário, o","top":329.3384,"prose":true,"stat":false,"head":false,"page":76,"col":0},{"text":"Deslocamento dele é 0 até o início do seu próximo turno.","top":341.2384,"prose":true,"stat":false,"head":false,"page":76,"col":0},{"text":"O alvo Atordoado realiza uma salvaguarda de Cons-","top":353.1384,"prose":true,"stat":false,"head":false,"page":76,"col":0},{"text":"tituição no final de cada um dos turnos dele, encerran-","top":365.0384,"prose":true,"stat":false,"head":false,"page":76,"col":0},{"text":"do a condição em caso de sucesso.","top":376.9384,"prose":true,"stat":false,"head":false,"page":76,"col":0}],"page":76}');
