INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(272,'Palavra Sagrada','palavra sagrada',7,6,1,'V','Ação Bônus','9 metros','Instantânea','Você pronuncia uma palavra imbuída de poder dos
Planos Superiores. Cada criatura à sua escolha no
alcance da magia realiza uma salvaguarda de Carisma.
Se falhar, um alvo com 50 Pontos de Vida ou menos
sofre um efeito com base nos Pontos de Vida atuais
dele, conforme mostrado na tabela Efeitos de Palavra
Sagrada. Independentemente dos Pontos de Vida, um
alvo Celestial, Elemental, Feérico ou Ínfero que falhar
na salvaguarda é forçado a voltar ao seu plano de
origem (se ainda não estiver lá) e não pode retornar ao
plano atual por 24 horas por qualquer meio que não
seja uma magia Desejo.
Efeitos de Palavra Sagrada
Pontos de Vida Efeito
0–20 O alvo morre.
21–30 O alvo está com as condições Atordoado,
Cego e Surdo por 1 hora.
31–40 O alvo está com as condições Cego e Surdo
por 10 minutos.
41–50 O alvo tem a condição Surdo por 1 minuto.',76,'Evocação (Clérigo)','{"level":"7","name":"Palavra Sagrada","school":[{"text":"Evocação (Clérigo)","top":629.9675,"prose":true,"stat":false,"head":false,"page":76,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":645.6335,"prose":false,"stat":false,"head":false,"page":76,"col":1}],"Alcance":[{"text":"9 metros","top":657.5335,"prose":false,"stat":false,"head":false,"page":76,"col":1}],"Componentes":[{"text":"V","top":669.4335,"prose":false,"stat":false,"head":false,"page":76,"col":1}],"Duração":[{"text":"Instantânea","top":681.3335,"prose":false,"stat":false,"head":false,"page":76,"col":1}]},"desc":[{"text":"Você pronuncia uma palavra imbuída de poder dos","top":699.3888,"prose":true,"stat":false,"head":false,"page":76,"col":1},{"text":"Planos Superiores. Cada criatura à sua escolha no","top":711.2888,"prose":true,"stat":false,"head":false,"page":76,"col":1},{"text":"alcance da magia realiza uma salvaguarda de Carisma.","top":723.1888,"prose":true,"stat":false,"head":false,"page":76,"col":1},{"text":"Se falhar, um alvo com 50 Pontos de Vida ou menos","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"sofre um efeito com base nos Pontos de Vida atuais","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"dele, conforme mostrado na tabela Efeitos de Palavra","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"Sagrada. Independentemente dos Pontos de Vida, um","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"alvo Celestial, Elemental, Feérico ou Ínfero que falhar","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"na salvaguarda é forçado a voltar ao seu plano de","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"origem (se ainda não estiver lá) e não pode retornar ao","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"plano atual por 24 horas por qualquer meio que não","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"seja uma magia Desejo.","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"Efeitos de Palavra Sagrada","top":151.30630000000008,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"Pontos de Vida Efeito","top":167.48059999999998,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"0–20 O alvo morre.","top":181.56380000000001,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"21–30 O alvo está com as condições Atordoado,","top":195.73699999999997,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"Cego e Surdo por 1 hora.","top":210.23699999999997,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"31–40 O alvo está com as condições Cego e Surdo","top":224.08349999999996,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"por 10 minutos.","top":238.58349999999996,"prose":false,"stat":false,"head":false,"page":77,"col":0},{"text":"41–50 O alvo tem a condição Surdo por 1 minuto.","top":252.42989999999998,"prose":false,"stat":false,"head":false,"page":77,"col":0}],"page":76}');
