INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(274,'Paralisar Pessoa','paralisar pessoa',2,1,1,'V, S, M (um pedaço reto de ferro)','Ação','18 metros','Concentração, até 1 minuto','Escolha um Humanoide à sua vista e no alcance da
magia. O alvo deve ser bem-sucedido em uma salva-
guarda de Sabedoria ou tem a condição Paralisado pela
duração da magia. No final de cada um dos turnos dele,
o alvo realiza uma nova salvaguarda, encerrando a
magia em caso de sucesso.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher um Humanoide adicional para cada
círculo de espaço de magia acima de 2.',77,'Encantamento (Bardo, Bruxo, Clérigo, Druida,
Feiticeiro, Mago)','{"level":"2","name":"Paralisar Pessoa","school":[{"text":"Encantamento (Bardo, Bruxo, Clérigo, Druida,","top":509.8724,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"Feiticeiro, Mago)","top":521.7724000000001,"prose":true,"stat":false,"head":false,"page":77,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":537.4383,"prose":false,"stat":false,"head":false,"page":77,"col":0}],"Alcance":[{"text":"18 metros","top":549.3383,"prose":false,"stat":false,"head":false,"page":77,"col":0}],"Componentes":[{"text":"V, S, M (um pedaço reto de ferro)","top":561.2384,"prose":false,"stat":false,"head":false,"page":77,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":573.1383,"prose":false,"stat":false,"head":false,"page":77,"col":0}]},"desc":[{"text":"Escolha um Humanoide à sua vista e no alcance da","top":591.1937,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"magia. O alvo deve ser bem-sucedido em uma salva-","top":603.0935999999999,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"guarda de Sabedoria ou tem a condição Paralisado pela","top":614.9936,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"duração da magia. No final de cada um dos turnos dele,","top":626.8936,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"o alvo realiza uma nova salvaguarda, encerrando a","top":638.7936,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"magia em caso de sucesso.","top":650.6937,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":662.7736,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"Você pode escolher um Humanoide adicional para cada","top":674.4936,"prose":true,"stat":false,"head":false,"page":77,"col":0},{"text":"círculo de espaço de magia acima de 2.","top":686.3936,"prose":true,"stat":false,"head":false,"page":77,"col":0}],"page":77}');
