INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(282,'Pequeno Refúgio de Leomund','pequeno refugio de leomund',3,6,1,'V, S, M (uma conta de cristal)','1 minuto ou Ritual','Pessoal','8 horas','Uma Emanação de 3 metros surge ao seu redor e
permanece estacionária pela duração. A magia falha
quando você a conjura se a Emanação não for grande o
suficiente para envolver totalmente todas as criaturas
em sua área.
Criaturas e objetos dentro da Emanação quando
você conjura a magia podem se mover livremente atra-
vés dela. Todas as outras criaturas e objetos são impe-
didos de atravessá-la. Magias de 3º círculo ou inferior
não podem ser conjuradas através dela, e os efeitos
dessas magias não podem se estender para dentro dela.
A atmosfera no interior da Emanação é confortável
e seca, independentemente do clima externo. Até que a
magia termine, você pode determinar se no interior há
Meia-luz ou Escuridão (nenhuma ação é necessária). A
Emanação é opaca por fora e de qualquer cor que você
escolher, mas é transparente por dentro.
A magia encerra se você sair da Emanação ou se a
conjurar novamente.',78,'Evocação (Bardo, Mago)','{"level":"3","name":"Pequeno Refúgio de Leomund","school":[{"text":"Evocação (Bardo, Mago)","top":681.2927,"prose":true,"stat":false,"head":false,"page":78,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto ou Ritual","top":696.6587,"prose":false,"stat":false,"head":false,"page":78,"col":0}],"Alcance":[{"text":"Pessoal","top":708.2587,"prose":false,"stat":false,"head":false,"page":78,"col":0}],"Componentes":[{"text":"V, S, M (uma conta de cristal)","top":719.8587,"prose":false,"stat":false,"head":false,"page":78,"col":0}],"Duração":[{"text":"8 horas","top":731.7587,"prose":false,"stat":false,"head":false,"page":78,"col":0}]},"desc":[{"text":"Uma Emanação de 3 metros surge ao seu redor e","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"permanece estacionária pela duração. A magia falha","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"quando você a conjura se a Emanação não for grande o","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"suficiente para envolver totalmente todas as criaturas","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"em sua área.","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Criaturas e objetos dentro da Emanação quando","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"você conjura a magia podem se mover livremente atra-","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"vés dela. Todas as outras criaturas e objetos são impe-","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"didos de atravessá-la. Magias de 3º círculo ou inferior","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"não podem ser conjuradas através dela, e os efeitos","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"dessas magias não podem se estender para dentro dela.","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"A atmosfera no interior da Emanação é confortável","top":167.2573,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"e seca, independentemente do clima externo. Até que a","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"magia termine, você pode determinar se no interior há","top":191.05729999999994,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Meia-luz ou Escuridão (nenhuma ação é necessária). A","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Emanação é opaca por fora e de qualquer cor que você","top":214.8572999999999,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"escolher, mas é transparente por dentro.","top":226.7573,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"A magia encerra se você sair da Emanação ou se a","top":238.65729999999996,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"conjurar novamente.","top":250.55729999999994,"prose":true,"stat":false,"head":false,"page":78,"col":1}],"page":78}');
