INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(283,'Perdição','perdicao',1,1,1,'V, S, M (uma gota de sangue)','Ação','9 metros','Concentração, até 1 minuto','Até três criaturas à sua escolha à sua vista e no alcance
da magia devem realizar uma salvaguarda de Carisma.
Sempre que um alvo que falhar nesta salvaguarda reali-
zar uma jogada de ataque ou uma salvaguarda antes da
magia terminar, o alvo deve subtrair 1d4 da jogada de
ataque ou salvaguarda.
Usando um Espaço de Magia de Círculo Superior.
Você pode escolher uma criatura adicional para cada
círculo de espaço de magia acima de 1.',78,'Encantamento (Bardo, Bruxo, Clérigo)','{"level":"1","name":"Perdição","school":[{"text":"Encantamento (Bardo, Bruxo, Clérigo)","top":294.76120000000003,"prose":true,"stat":false,"head":false,"page":78,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":310.42719999999997,"prose":false,"stat":false,"head":false,"page":78,"col":1}],"Alcance":[{"text":"9 metros","top":322.32719999999995,"prose":false,"stat":false,"head":false,"page":78,"col":1}],"Componentes":[{"text":"V, S, M (uma gota de sangue)","top":334.2272,"prose":false,"stat":false,"head":false,"page":78,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":346.12719999999996,"prose":false,"stat":false,"head":false,"page":78,"col":1}]},"desc":[{"text":"Até três criaturas à sua escolha à sua vista e no alcance","top":364.1825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"da magia devem realizar uma salvaguarda de Carisma.","top":376.0825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Sempre que um alvo que falhar nesta salvaguarda reali-","top":387.9825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"zar uma jogada de ataque ou uma salvaguarda antes da","top":399.8825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"magia terminar, o alvo deve subtrair 1d4 da jogada de","top":411.7825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"ataque ou salvaguarda.","top":423.6825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":435.7625,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Você pode escolher uma criatura adicional para cada","top":447.4825,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"círculo de espaço de magia acima de 1.","top":459.3825,"prose":true,"stat":false,"head":false,"page":78,"col":1}],"page":78}');
