INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(284,'Piscar','piscar',3,5,1,'V, S','Ação','Pessoal','1 minuto','Jogue 1d6 no final de cada um dos seus turnos pela
duração da magia. Em um resultado de 4−6, você
desaparece do seu plano de existência atual e aparece
no Plano Etéreo (a magia termina instantaneamente se
você já estiver nesse plano). Enquanto estiver no Plano
Etéreo, você pode ver o plano que você deixou, que
aparece em tons de cinza, mas você não pode ver nada
nele a mais de 18 metros de distância. Você só pode
afetar e ser afetado por criaturas que estejam no Plano
Etéreo, e criaturas no outro plano não podem percebê-
-lo, a menos que tenham uma habilidade específica que
lhes permita perceber coisas no Plano Etéreo.
Você retorna ao outro plano no início do seu próxi-
mo turno e quando a magia termina se você estiver no
Plano Etéreo. Você retorna a um espaço desocupado à
sua escolha à sua vista e a até 3 metros do espaço que
deixou. Se nenhum espaço desocupado estiver dispo-
nível dentro desse intervalo, você aparece no espaço
desocupado mais próximo.',78,'Transmutação (Feiticeiro, Mago)','{"level":"3","name":"Piscar","school":[{"text":"Transmutação (Feiticeiro, Mago)","top":503.5864,"prose":true,"stat":false,"head":false,"page":78,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":519.2524,"prose":false,"stat":false,"head":false,"page":78,"col":1}],"Alcance":[{"text":"Pessoal","top":531.1524,"prose":false,"stat":false,"head":false,"page":78,"col":1}],"Componentes":[{"text":"V, S","top":543.0524,"prose":false,"stat":false,"head":false,"page":78,"col":1}],"Duração":[{"text":"1 minuto","top":554.9524,"prose":false,"stat":false,"head":false,"page":78,"col":1}]},"desc":[{"text":"Jogue 1d6 no final de cada um dos seus turnos pela","top":573.0077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"duração da magia. Em um resultado de 4−6, você","top":584.9077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"desaparece do seu plano de existência atual e aparece","top":596.8077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"no Plano Etéreo (a magia termina instantaneamente se","top":608.7076999999999,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"você já estiver nesse plano). Enquanto estiver no Plano","top":620.6077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Etéreo, você pode ver o plano que você deixou, que","top":632.5077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"aparece em tons de cinza, mas você não pode ver nada","top":644.4077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"nele a mais de 18 metros de distância. Você só pode","top":656.3077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"afetar e ser afetado por criaturas que estejam no Plano","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Etéreo, e criaturas no outro plano não podem percebê-","top":680.1077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"-lo, a menos que tenham uma habilidade específica que","top":692.0077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"lhes permita perceber coisas no Plano Etéreo.","top":703.9077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Você retorna ao outro plano no início do seu próxi-","top":715.8077,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"mo turno e quando a magia termina se você estiver no","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":78,"col":1},{"text":"Plano Etéreo. Você retorna a um espaço desocupado à","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"sua escolha à sua vista e a até 3 metros do espaço que","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"deixou. Se nenhum espaço desocupado estiver dispo-","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"nível dentro desse intervalo, você aparece no espaço","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"desocupado mais próximo.","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":79,"col":0}],"page":78}');
