INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(285,'Polimorfia','polimorfia',4,5,1,'V, S, M (um casulo de lagarta)','Ação','18 metros','Concentração, até 1 hora','Você tenta transformar uma criatura à sua vista e no
alcance da magia em uma Fera. O alvo deve ser bem-
-sucedido em uma salvaguarda de Sabedoria ou se
multimorfa em uma Fera pela duração da magia. Essa
forma pode ser qualquer Fera com Nível de Desafio
igual ou menor que o do alvo (ou igual ao seu nível
se não tiver Nível de Desafio). As estatísticas do alvo
são substituídas pelas da Fera escolhida, mas o alvo
mantém seu alinhamento, personalidade, tipo de
criatura, Pontos de Vida e Dados de Pontos de Vida.
Veja também o apêndice B para amostras dos blocos de
estatísticas das Feras.
O alvo recebe um número de Pontos de Vida Tem-
porários igual aos Pontos de Vida da forma de Fera.
A magia se encerra no alvo se ele não tiver Pontos
de Vida Temporários restantes. Esses Pontos de Vida
Temporários desaparecem, caso ainda restem, quando
a magia terminar.
O alvo é limitado às ações que pode realizar pela ana-
tomia de sua nova forma, e não pode falar ou conjurar
magias.
O equipamento do alvo se funde com a nova forma.
A criatura não pode usar ou se beneficiar de nenhum
desses equipamentos.',79,'Transmutação (Bardo, Druida, Feiticeiro, Mago)','{"level":"4","name":"Polimorfia","school":[{"text":"Transmutação (Bardo, Druida, Feiticeiro, Mago)","top":128.16129999999998,"prose":true,"stat":false,"head":false,"page":79,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":143.82719999999995,"prose":false,"stat":false,"head":false,"page":79,"col":0}],"Alcance":[{"text":"18 metros","top":155.72719999999993,"prose":false,"stat":false,"head":false,"page":79,"col":0}],"Componentes":[{"text":"V, S, M (um casulo de lagarta)","top":167.6271999999999,"prose":false,"stat":false,"head":false,"page":79,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":179.5272,"prose":false,"stat":false,"head":false,"page":79,"col":0}]},"desc":[{"text":"Você tenta transformar uma criatura à sua vista e no","top":197.58249999999998,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"alcance da magia em uma Fera. O alvo deve ser bem-","top":209.48249999999996,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"-sucedido em uma salvaguarda de Sabedoria ou se","top":221.38249999999994,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"multimorfa em uma Fera pela duração da magia. Essa","top":233.2824999999999,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"forma pode ser qualquer Fera com Nível de Desafio","top":245.1825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"igual ou menor que o do alvo (ou igual ao seu nível","top":257.0825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"se não tiver Nível de Desafio). As estatísticas do alvo","top":268.98249999999996,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"são substituídas pelas da Fera escolhida, mas o alvo","top":280.8825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"mantém seu alinhamento, personalidade, tipo de","top":292.7825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"criatura, Pontos de Vida e Dados de Pontos de Vida.","top":304.6825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"Veja também o apêndice B para amostras dos blocos de","top":316.5825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"estatísticas das Feras.","top":328.4825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"O alvo recebe um número de Pontos de Vida Tem-","top":340.3825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"porários igual aos Pontos de Vida da forma de Fera.","top":352.2825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"A magia se encerra no alvo se ele não tiver Pontos","top":364.1825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"de Vida Temporários restantes. Esses Pontos de Vida","top":376.0825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"Temporários desaparecem, caso ainda restem, quando","top":387.9825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"a magia terminar.","top":399.8825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"O alvo é limitado às ações que pode realizar pela ana-","top":411.7825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"tomia de sua nova forma, e não pode falar ou conjurar","top":423.6825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"magias.","top":435.5825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"O equipamento do alvo se funde com a nova forma.","top":447.4825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"A criatura não pode usar ou se beneficiar de nenhum","top":459.3825,"prose":true,"stat":false,"head":false,"page":79,"col":0},{"text":"desses equipamentos.","top":471.2825,"prose":true,"stat":false,"head":false,"page":79,"col":0}],"page":79}');
