INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(287,'Porta Dimensional','porta dimensional',4,4,1,'V','Ação','150 metros','Instantânea','Você se teleporta para um local no alcance da magia.
Você chega exatamente ao local desejado. Pode ser um
lugar que você pode ver, um que você pode visualizar ou
um que você pode descrever indicando distância e dire-
ção, como “60 metros para baixo” ou “90 metros para
cima em direção ao noroeste em um ângulo de 45 graus”.
Você também pode teleportar uma criatura voluntá-
ria. A criatura deve estar a até 1,5 metro de você quan-
do você se teleporta, e ela se teleporta para um espaço
a até 1,5 metro do seu espaço de destino.
Se você, a outra criatura ou ambas chegarem a um
espaço ocupado por uma criatura, ou completamente
preenchido por um ou mais objetos, você e qualquer
criatura viajando com você sofre 4d6 pontos de dano
Energético, e o teleporte falha.',79,'Invocação (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"4","name":"Porta Dimensional","school":[{"text":"Invocação (Bardo, Bruxo, Feiticeiro, Mago)","top":497.0612,"prose":true,"stat":false,"head":false,"page":79,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":512.7272,"prose":false,"stat":false,"head":false,"page":79,"col":1}],"Alcance":[{"text":"150 metros","top":524.6271999999999,"prose":false,"stat":false,"head":false,"page":79,"col":1}],"Componentes":[{"text":"V","top":536.5272,"prose":false,"stat":false,"head":false,"page":79,"col":1}],"Duração":[{"text":"Instantânea","top":548.4272,"prose":false,"stat":false,"head":false,"page":79,"col":1}]},"desc":[{"text":"Você se teleporta para um local no alcance da magia.","top":566.4825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"Você chega exatamente ao local desejado. Pode ser um","top":578.3824999999999,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"lugar que você pode ver, um que você pode visualizar ou","top":590.2825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"um que você pode descrever indicando distância e dire-","top":602.1825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"ção, como “60 metros para baixo” ou “90 metros para","top":614.0825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"cima em direção ao noroeste em um ângulo de 45 graus”.","top":625.9825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"Você também pode teleportar uma criatura voluntá-","top":637.8824999999999,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"ria. A criatura deve estar a até 1,5 metro de você quan-","top":649.7825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"do você se teleporta, e ela se teleporta para um espaço","top":661.6825,"prose":true,"stat":false,"head":false,"page":79,"col":1},{"text":"a até 1,5 metro do seu 