INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(288,'Portais Arcanos','portais arcanos',6,4,1,'V, S','Ação','150 metros','Concentração, até 10 minutos','Você cria portais de teleporte vinculados. Escolha dois
espaços grandes e desocupados no chão à sua vista, um
espaço no alcance da magia e o outro a até 3 metros
de você. Um portal circular se abre em cada um desses
espaços e permanece pela duração da magia.
Os portais são anéis brilhantes bidimensionais cheios
de névoa que bloqueiam a visão. Eles pairam a centí-
metros do chão e são perpendiculares a ele.
Um portal fica aberto apenas de um lado (à sua es-
colha). Qualquer coisa que entre no lado aberto de um
portal sai do lado aberto do outro portal como se os
dois fossem adjacentes um ao outro. Como uma Ação
Bônus, você pode alterar a face dos lados abertos.',80,'Invocação (Bruxo, Feiticeiro, Mago)','{"level":"6","name":"Portais Arcanos","school":[{"text":"Invocação (Bruxo, Feiticeiro, Mago)","top":429.2731,"prose":true,"stat":false,"head":false,"page":80,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":444.93899999999996,"prose":false,"stat":false,"head":false,"page":80,"col":0}],"Alcance":[{"text":"150 metros","top":456.83899999999994,"prose":false,"stat":false,"head":false,"page":80,"col":0}],"Componentes":[{"text":"V, S","top":468.739,"prose":false,"stat":false,"head":false,"page":80,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":480.63899999999995,"prose":false,"stat":false,"head":false,"page":80,"col":0}]},"desc":[{"text":"Você cria portais de teleporte vinculados. Escolha dois","top":498.6943,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"espaços grandes e desocupados no chão à sua vista, um","top":510.59430000000003,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"espaço no alcance da magia e o outro a até 3 metros","top":522.4943000000001,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"de você. Um portal circular se abre em cada um desses","top":534.3942999999999,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"espaços e permanece pela duração da magia.","top":546.2943,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"Os portais são anéis brilhantes bidimensionais cheios","top":558.1943,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"de névoa que bloqueiam a visão. Eles pairam a centí-","top":570.0944,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"metros do chão e são perpendiculares a ele.","top":581.9943,"prose":true,"stat":false,"head":false,"page":80,"col":0},{"text":"Um portal fica aberto apenas de um lado (à sua es-","top":593.8942999999999,"prose":true,"stat":false,"head":false,"page":80,"col":