INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(289,'Portal','portal',9,4,1,'V, S, M (um diamante no valor de 5.000 ou
mais PO)','Ação','18 metros','Concentração, até 1 minuto','Você conjura um portal que liga um espaço deso-
cupado à sua vista e no alcance da magia a um local
preciso em um plano de existência diferente. O portal
é uma abertura circular, que você pode criar com 1,5
a 6 metros de diâmetro. Você pode orientar o portal
em qualquer direção que escolher. O portal permanece
pela duração da magia e o destino para o qual ele leva é
visível através dele.
O portal tem uma frente e um verso em cada plano
onde aparece. Se deslocar pelo portal só é possível
movendo-se pela frente. Qualquer coisa que o faça é
instantaneamente transportada para o outro plano, apa-
recendo no espaço desocupado mais próximo do portal.
Divindades e outros governantes dos planos podem im-
pedir que portais criados por esta magia se abram em sua
presença ou em qualquer lugar dentro de seus domínios.
Ao conjurar esta magia, você pode proferir o nome
de uma criatura específica (não funciona com um
pseudônimo, título ou apelido). Se essa criatura estiver
em um plano diferente daquele em que você está, o
portal se abre ao lado da criatura nomeada e a trans-
porta para o espaço desocupado mais próximo do seu
lado do portal. Você não recebe nenhum poder espe-
cial sobre a criatura, e ela é livre para agir conforme o
Mestre julgar apropriado. Ela pode ir embora, atacar
você ou ajudá-lo.',80,'Invocação (Bruxo, Clérigo, Feiticeiro, Mago)','{"level":"9","name":"Portal","school":[{"text":"Invocação (Bruxo, Clérigo, Feiticeiro, Mago)","top":429.2731,"prose":true,"stat":false,"head":false,"page":80,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":444.93899999999996,"prose":false,"stat":false,"head":false,"page":80,"col":1}],"Alcance":[{"text":"18 metros","top":456.83899999999994,"prose":false,"stat":false,"head":false,"page":80,"col":1}],"Componentes":[{"text":"V, S, M (um diamante no valor de 5.000 ou","top":468.739,"prose":false,"stat":false,"head":false,"page":80,"col":1},{"text":"mais PO)","top":480.63899999999995,"prose":false,"stat":false,"head":false,"page":80,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":492.539,"prose":false,"stat":false,"head":false,"page":80,"col":1}]},"desc":[{"text":"Você conjura um portal que liga um espaço deso-","top":510.59430000000003,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"cupado à sua vista e no alcance da magia a um local","top":522.4943000000001,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"preciso em um plano de existência diferente. O portal","top":534.3942999999999,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"é uma abertura circular, que você pode criar com 1,5","top":546.2943,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"a 6 metros de diâmetro. Você pode orientar o portal","top":558.1943,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"em qualquer direção que escolher. O portal permanece","top":570.0944,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"pela duração da magia e o destino para o qual ele leva é","top":581.9943,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"visível através dele.","top":593.8942999999999,"prose":true,"stat":false,"head":false,"page":80,"col":1},{"text":"O portal tem uma frente e um verso em c