INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(290,'Praga de Insetos','praga de insetos',5,4,1,'V, S, M (um gafanhoto)','Ação','90 metros','Concentração, até 10 minutos','Um enxame de gafanhotos preenche uma Esfera de 6
metros de raio centrada em um ponto à sua escolha no
alcance da magia. A Esfera permanece pela duração, e
sua área é Parcialmente Obscurecida e Terreno Difícil.
Quando o enxame aparece, cada criatura dentro dele
realiza uma salvaguarda de Constituição, sofrendo
4d10 pontos de dano Perfurante se falhar, ou metade
desse dano em caso de sucesso. Uma criatura também
realiza essa salvaguarda quando entra na área da magia
pela primeira vez em um turno ou encerra o turno
nela. Uma criatura realiza essa salvaguarda apenas
uma vez por turno.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d10 para cada círculo de espaço de
magia acima de 5.',81,'Invocação (Clérigo, Druida, Feiticeiro)','{"level":"5","name":"Praga de Insetos","school":[{"text":"Invocação (Clérigo, Druida, Feiticeiro)","top":151.9613999999999,"prose":true,"stat":false,"head":false,"page":81,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":167.6273,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Alcance":[{"text":"90 metros","top":179.52729999999997,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Componentes":[{"text":"V, S, M (um gafanhoto)","top":191.42729999999995,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":203.32729999999992,"prose":false,"stat":false,"head":false,"page":81,"col":0}]},"desc":[{"text":"Um enxame de gafanhotos preenche uma Esfera de 6","top":221.3825999999999,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"metros de raio centrada em um ponto à sua escolha no","top":233.2826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"alcance da magia. A Esfera permanece pela duração, e","top":245.18259999999998,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"sua área é Parcialmente Obscurecida e Terreno Difícil.","top":257.08259999999996,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"Quando o enxame aparece, cada criatura dentro dele","top":268.98259999999993,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"realiza uma salvaguarda de Constituição, sofrendo","top":280.8826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"4d10 pontos de dano Perfurante se falhar, ou metade","top":292.7826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"desse dano em caso de sucesso. Uma criatura também","top":304.6826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"realiza essa salvaguarda quando entra na área da magia","top":316.5826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"pela primeira vez em um turno ou encerra o turno","top":328.4826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"nela. Uma criatura realiza essa salvaguarda apenas","top":340.3826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"uma vez por turno.","top":352.2826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":364.1826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"dano aumenta em 1d10 para cada círculo de espaço de","top":376.0826,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"magia acima de 5.","top":387.9826,"prose":true,"stat":false,"head":false,"page":81,"col":0}],"page":81}');
