INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(291,'Presença Régia de Yolande','presenca regia de yolande',5,1,1,'V, S, M (uma tiara em miniatura)','Ação','Pessoal','Concentração, até 1 minuto','Você se envolve com uma majestade sobrenatural em
uma Emanação de 3 metros. Sempre que a Emana-
ção entra no espaço de uma criatura à sua vista, ou
quando uma criatura à sua vista entra na Emanação ou
termina seu turno nela, você pode forçar essa criatura
a realizar uma salvaguarda de Sabedoria. Se falhar, o
alvo sofre 4d6 pontos de dano Psíquico e tem a condi-
ção Caído, e você pode empurrá-lo até 3 metros para
longe de você. Em caso de sucesso, o alvo sofre apenas
metade do dano. Uma criatura realiza essa salvaguarda
apenas uma vez por turno.',81,'Encantamento (Bardo, Mago)','{"level":"5","name":"Presença Régia de Yolande","school":[{"text":"Encantamento (Bardo, Mago)","top":432.1865,"prose":true,"stat":false,"head":false,"page":81,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":447.85249999999996,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Alcance":[{"text":"Pessoal","top":459.75249999999994,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Componentes":[{"text":"V, S, M (uma tiara em miniatura)","top":471.6525,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":483.55249999999995,"prose":false,"stat":false,"head":false,"page":81,"col":0}]},"desc":[{"text":"Você se envolve com uma majestade sobrenatural em","top":501.6078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"uma Emanação de 3 metros. Sempre que a Emana-","top":513.5078000000001,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"ção entra no espaço de uma criatura à sua vista, ou","top":525.4078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"quando uma criatura à sua vista entra na Emanação ou","top":537.3078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"termina seu turno nela, você pode forçar essa criatura","top":549.2077999999999,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"a realizar uma salvaguarda de Sabedoria. Se falhar, o","top":561.1078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"alvo sofre 4d6 pontos de dano Psíquico e tem a condi-","top":573.0078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"ção Caído, e você pode empurrá-lo até 3 metros para","top":584.9078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"longe de você. Em caso de sucesso, o alvo sofre apenas","top":596.8078,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"metade do dano. Uma criatura realiza essa salvaguarda","top":608.7077999999999,"prose":true,"stat":false,"head":false,"page":81,"col":0},{"text":"apenas uma vez por turno.","top":620.6078,"prose":true,"stat":false,"head":false,"page":81,"col":0}],"page":81}');
