INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(292,'Presságio','pressagio',4,8,1,'V, S, M (incenso no valor de 25 ou mais PO,
que a magia consome)','Ação ou Ritual','Pessoal','Instantânea','Esta magia coloca você em contato com um deus ou
com os servos de um deus. Você faz uma pergunta
sobre um objetivo, evento ou atividade específica que
ocorrerá em até 7 dias. O Mestre oferece uma resposta
verdadeira, que pode ser uma frase curta ou uma rima
enigmática. A magia não leva em conta circunstâncias
que podem alterar a resposta, como a conjuração de
outras magias.
Se você conjurar a magia mais de uma vez antes de
completar um Descanso Longo, há uma chance cumu-
lativa de 25% para cada conjuração após a primeira de
que você não receba resposta.',81,'Adivinhação (Clérigo, Druida, Mago)','{"level":"4","name":"Presságio","school":[{"text":"Adivinhação (Clérigo, Druida, Mago)","top":664.8118,"prose":true,"stat":false,"head":false,"page":81,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":680.4777,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Alcance":[{"text":"Pessoal","top":692.3777,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Componentes":[{"text":"V, S, M (incenso no valor de 25 ou mais PO,","top":704.2777,"prose":false,"stat":false,"head":false,"page":81,"col":0},{"text":"que a magia consome)","top":716.1777,"prose":false,"stat":false,"head":false,"page":81,"col":0}],"Duração":[{"text":"Instantânea","top":728.0776999999999,"prose":false,"stat":false,"head":false,"page":81,"col":0}]},"desc":[{"text":"Esta magia coloca você em contato com um deus ou","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"com os servos de um deus. Você faz uma pergunta","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"sobre um objetivo, evento ou atividade específica que","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"ocorrerá em até 7 dias. O Mestre oferece uma resposta","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"verdadeira, que pode ser uma frase curta ou uma rima","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"enigmática. A magia não leva em conta circunstâncias","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"que podem alterar a resposta, como a conjuração de","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"outras magias.","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Se você conjurar a magia mais de uma vez antes de","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"completar um Descanso Longo, há uma chance cumu-","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"lativa de 25% para cada conjuração após a primeira de","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"que você não receba resposta.","top":167.2573,"prose":true,"stat":false,"head":false,"page":81,"col":1}],"page":81}');
