INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(293,'Prestidigitação Arcana','prestidigitacao arcana',0,5,1,'V, S','Ação','3 metros','Até 1 hora','Você cria um efeito mágico no alcance da magia.
Escolha o efeito entre as opções abaixo. Se conjurar
esta magia várias vezes, você pode ter até três de seus
efeitos não instantâneos ativos ao mesmo tempo.
Brincar com Fogo. Você instantaneamente acende ou
apaga uma vela, uma tocha ou uma pequena fogueira.
Criação Menor. Você cria uma bugiganga não mágica,
sem valor monetário e incapaz de causar dano, ou uma
imagem ilusória, sendo que ambas devem caber na sua
mão. Ela dura até o final do seu próximo turno.
Efeito Sensorial. Você cria um efeito sensorial instantâ-
neo e inofensivo, como uma chuva de faíscas, um sopro
de vento, notas musicais suaves ou um odor estranho.
Limpar ou Sujar. Você limpa ou suja instantaneamen-
te um objeto com menos de 30 centímetros cúbicos.
Marca Mágica. Você faz aparecer uma cor, uma pe-
quena marca ou um símbolo em um objeto ou superfí-
cie por 1 hora.
Sensação Ideal. Você esfria, aquece ou dá sabor a
um material não vivo com menos de 30 centímetros
cúbicos por 1 hora.',81,'Transmutação (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"0","name":"Prestidigitação Arcana","school":[{"text":"Transmutação (Bardo, Bruxo, Feiticeiro, Mago)","top":211.46119999999996,"prose":true,"stat":false,"head":false,"page":81,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":81,"col":1}],"Alcance":[{"text":"3 metros","top":239.0272,"prose":false,"stat":false,"head":false,"page":81,"col":1}],"Componentes":[{"text":"V, S","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":81,"col":1}],"Duração":[{"text":"Até 1 hora","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":81,"col":1}]},"desc":[{"text":"Você cria um efeito mágico no alcance da magia.","top":280.8825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Escolha o efeito entre as opções abaixo. Se conjurar","top":292.7825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"esta magia várias vezes, você pode ter até três de seus","top":304.6825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"efeitos não instantâneos ativos ao mesmo tempo.","top":316.5825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Brincar com Fogo. Você instantaneamente acende ou","top":328.4825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"apaga uma vela, uma tocha ou uma pequena fogueira.","top":340.3825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Criação Menor. Você cria uma bugiganga não mágica,","top":352.2825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"sem valor monetário e incapaz de causar dano, ou uma","top":364.1825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"imagem ilusória, sendo que ambas devem caber na sua","top":376.0825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"mão. Ela dura até o final do seu próximo turno.","top":387.9825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Efeito Sensorial. Você cria um efeito sensorial instantâ-","top":399.8825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"neo e inofensivo, como uma chuva de faíscas, um sopro","top":411.7825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"de vento, notas musicais suaves ou um odor estranho.","top":423.6825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Limpar ou Sujar. Você limpa ou suja instantaneamen-","top":435.5825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"te um objeto com menos de 30 centímetros cúbicos.","top":447.4825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Marca Mágica. Você faz aparecer uma cor, uma pe-","top":459.3825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"quena marca ou um símbolo em um objeto ou superfí-","top":471.2825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"cie por 1 hora.","top":483.1825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Sensação Ideal. Você esfria, aquece ou dá sabor a","top":495.0825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"um material não vivo com menos de 30 centímetros","top":506.9825,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"cúbicos por 1 hora.","top":518.8824999999999,"prose":true,"stat":false,"head":false,"page":81,"col":1}],"page":81}');
