INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(294,'Proibição','proibicao',6,3,1,'V, S, M (rubi em pó no valor de 1.000 ou mais PO)','10 minutos ou Ritual','Toque','1 dia','Você cria uma proteção contra viagens mágicas que
protege até 3.700 metros quadrados de espaço a uma
altura de 9 metros acima do chão. Pela duração da ma-
gia, as criaturas não podem se teleportar para a área ou
usar portais, como aqueles criados pela magia Portal,
para entrar na área. A magia bloqueia a área contra
viagens planares e, portanto, impede que criaturas
acessem a área pelo Plano Astral, Plano Etéreo, Faéria,
Sombral ou pela magia Transição Planar.
Além disso, a magia causa dano aos tipos de criaturas,
entre um ou mais, que você escolhe ao conjurá-la: Aber-
rações, Celestiais, Elementais, Feéricos, Ínferos e Mortos-
-Vivos. Quando uma criatura de um dos tipos escolhidos
entra pela primeira vez na área da magia ou termina
seu turno nela, sofre 5d10 pontos de dano Necrótico ou
Radiante (à sua escolha ao conjurar esta magia).
Você pode definir uma senha ao conjurar a magia.
Uma criatura que profere a senha ao entrar na área
não sofre dano da magia.
A área da magia não pode se sobrepor à área de
outra magia Proibição. Se você conjurar Proibição todos
os dias por 30 dias no mesmo local, a magia permane-
ce até ser dissipada e os componentes Materiais são
consumidos na última conjuração.',81,'Abjuração (Clérigo)','{"level":"6","name":"Proibição","school":[{"text":"Abjuração (Clérigo)","top":563.0863999999999,"prose":true,"stat":false,"head":false,"page":81,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos ou Ritual","top":578.7524,"prose":false,"stat":false,"head":false,"page":81,"col":1}],"Alcance":[{"text":"Toque","top":590.6524,"prose":false,"stat":false,"head":false,"page":81,"col":1}],"Componentes":[{"text":"V, S, M (rubi em pó no valor de 1.000 ou mais PO)","top":602.5524,"prose":false,"stat":false,"head":false,"page":81,"col":1}],"Duração":[{"text":"1 dia","top":614.4524,"prose":false,"stat":false,"head":false,"page":81,"col":1}]},"desc":[{"text":"Você cria uma proteção contra viagens mágicas que","top":632.5077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"protege até 3.700 metros quadrados de espaço a uma","top":644.4077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"altura de 9 metros acima do chão. Pela duração da ma-","top":656.3077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"gia, as criaturas não podem se teleportar para a área ou","top":668.2076999999999,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"usar portais, como aqueles criados pela magia Portal,","top":680.1077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"para entrar na área. A magia bloqueia a área contra","top":692.0077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"viagens planares e, portanto, impede que criaturas","top":703.9077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"acessem a área pelo Plano Astral, Plano Etéreo, Faéria,","top":715.8077,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Sombral ou pela magia Transição Planar.","top":727.7076999999999,"prose":true,"stat":false,"head":false,"page":81,"col":1},{"text":"Além disso, a magia causa dano aos tipos de criaturas,","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"entre um ou mais, que você escolhe ao conjurá-la: Aber-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"rações, Celestiais, Elementais, Feéricos, Ínferos e Mortos-","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"-Vivos. Quando uma criatura de um dos tipos escolhidos","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"entra pela primeira vez na área da magia ou termina","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"seu turno nela, sofre 5d10 pontos de dano Necrótico ou","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Radiante (à sua escolha ao conjurar esta magia).","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Você pode definir uma senha ao conjurar a magia.","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Uma criatura que profere a senha ao entrar na área","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"não sofre dano da magia.","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"A área da magia não pode se sobrepor à área de","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"outra magia Proibição. Se você conjurar Proibição todos","top":167.2573,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"os dias por 30 dias no mesmo local, a magia permane-","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"ce até ser dissipada e os componentes Materiais são","top":191.05729999999994,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"consumidos na última conjuração.","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":82,"col":0}],"page":81}');
