INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(295,'Projeção Astral','projecao astral',9,2,1,'V, S, M (para cada um dos alvos da magia, um
zircão no valor de 1.000 ou mais PO e uma barra de prata
no valor de 100 ou mais PO, que a magia consome)','1 hora','3 metros','Até ser dissipada','Você e até oito criaturas voluntárias no alcance da magia
projetam seus corpos astrais no Plano Astral (a magia se
encerra instantaneamente se você já estiver nesse plano).
O corpo de cada alvo é deixado para trás em um estado
de animação suspensa; ele tem a condição Inconsciente,
não precisa comer ou respirar e não envelhece.
A forma astral de um alvo se assemelha ao seu corpo
em quase todos os aspectos, replicando suas estatís-
ticas de jogo e pertences. A principal diferença é a
adição de um cordão prateado que se arrasta entre as
omoplatas da forma astral. O cordão desaparece de
vista após 30 centímetros. Se o cordão for cortado —
algo que só pode acontecer quando um efeito especifi-
camente declarar isto — tanto o corpo quanto a forma
astral do alvo morrem.
A forma astral de um alvo pode viajar pelo Plano
Astral. No momento em que uma forma astral deixa
aquele plano, o corpo e os pertences do alvo viajam
ao longo do cordão prateado, fazendo com que o alvo
reentre em seu corpo no novo plano.
Qualquer dano ou efeito aplicável a uma forma astral
não afeta o corpo do alvo e vice-versa. Se o corpo ou
a forma astral de um alvo for reduzido a 0 Pontos de
Vida, a magia se encerra para esse alvo. A magia se
encerra para todos os alvos se você executar uma ação
Usar Magia para descartá-la.
Quando a magia termina para um alvo que não está
morto, o alvo reaparece em seu corpo e sai do estado
de animação suspensa.',82,'Necromancia (Bruxo, Clérigo, Mago)','{"level":"9","name":"Projeção Astral","school":[{"text":"Necromancia (Bruxo, Clérigo, Mago)","top":247.1611999999999,"prose":true,"stat":false,"head":false,"page":82,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 hora","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":82,"col":0}],"Alcance":[{"text":"3 metros","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":82,"col":0}],"Componentes":[{"text":"V, S, M (para cada um dos alvos da magia, um","top":286.62719999999996,"prose":false,"stat":false,"head":false,"page":82,"col":0},{"text":"zircão no valor de 1.000 ou mais PO e uma barra de prata","top":298.52719999999994,"prose":false,"stat":false,"head":false,"page":82,"col":0},{"text":"no valor de 100 ou mais PO, que a magia consome)","top":310.42719999999997,"prose":false,"stat":false,"head":false,"page":82,"col":0}],"Duração":[{"text":"Até ser dissipada","top":322.32719999999995,"prose":false,"stat":false,"head":false,"page":82,"col":0}]},"desc":[{"text":"Você e até oito criaturas voluntárias no alcance da magia","top":340.3825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"projetam seus corpos astrais no Plano Astral (a magia se","top":352.2825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"encerra instantaneamente se você já estiver nesse plano).","top":364.1825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"O corpo de cada alvo é deixado para trás em um estado","top":376.0825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"de animação suspensa; ele tem a condição Inconsciente,","top":387.9825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"não precisa comer ou respirar e não envelhece.","top":399.8825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"A forma astral de um alvo se assemelha ao seu corpo","top":411.7825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"em quase todos os aspectos, replicando suas estatís-","top":423.6825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"ticas de jogo e pertences. A principal diferença é a","top":435.5825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"adição de um cordão prateado que se arrasta entre as","top":447.4825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"omoplatas da forma astral. O cordão desaparece de","top":459.3825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"vista após 30 centímetros. Se o cordão for cortado —","top":471.2825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"algo que só pode acontecer quando um efeito especifi-","top":483.1825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"camente declarar isto — tanto o corpo quanto a forma","top":495.0825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"astral do alvo morrem.","top":506.9825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"A forma astral de um alvo pode viajar pelo Plano","top":518.8824999999999,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Astral. No momento em que uma forma astral deixa","top":530.7825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"aquele plano, o corpo e os pertences do alvo viajam","top":542.6825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"ao longo do cordão prateado, fazendo com que o alvo","top":554.5825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"reentre em seu corpo no novo plano.","top":566.4825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Qualquer dano ou efeito aplicável a uma forma astral","top":578.3824999999999,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"não afeta o corpo do alvo e vice-versa. Se o corpo ou","top":590.2825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"a forma astral de um alvo for reduzido a 0 Pontos de","top":602.1825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Vida, a magia se encerra para esse alvo. A magia se","top":614.0825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"encerra para todos os alvos se você executar uma ação","top":625.9825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Usar Magia para descartá-la.","top":637.8824999999999,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"Quando a magia termina para um alvo que não está","top":649.7825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"morto, o alvo reaparece em seu corpo e sai do estado","top":661.6825,"prose":true,"stat":false,"head":false,"page":82,"col":0},{"text":"de animação suspensa.","top":673.5825,"prose":true,"stat":false,"head":false,"page":82,"col":0}],"page":82}');
