INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(296,'Projetar Imagem','projetar imagem',7,7,1,'V, S, M (uma estatueta de si mesmo no valor de
5 ou mais PO)','Ação','800 quilômetros','Concentração, até 1 dia','Você cria uma cópia ilusória de si mesmo que dura
enquanto a magia estiver ativa. A cópia pode surgir em
qualquer lugar que você já tenha visto e que esteja no
alcance da magia, ignorando obstáculos. A ilusão se pa-
rece e soa como você, mas é intangível. Se a ilusão sofrer
qualquer dano, ela desaparece e a magia se encerra.
Você pode ver através dos olhos da ilusão e ouvir
através dos ouvidos dela, como se você estivesse no
espaço dela. Com uma ação Usar Magia, você pode mo-
vê-la até 18 metros e fazer com que ela gesticule, fale
e se comporte da maneira que desejar. Ela imita seus
maneirismos perfeitamente.
Interação física com a imagem revela sua natureza
ilusória, já que objetos podem atravessá-la. Uma criatu-
ra que executa a ação Analisar para examinar a imagem
pode determinar que se trata de uma ilusão com um
teste bem-sucedido de Inteligência (Investigação) con-
tra a CD para evitar sua magia. Se uma criatura perce-
ber a ilusão, ela pode ver através da imagem, e qualquer
som que a ilusão emita parece vago para essa criatura.',82,'Ilusão (Bardo, Mago)','{"level":"7","name":"Projetar Imagem","school":[{"text":"Ilusão (Bardo, Mago)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":82,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":82,"col":1}],"Alcance":[{"text":"800 quilômetros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":82,"col":1}],"Componentes":[{"text":"V, S, M (uma estatueta de si mesmo no valor de","top":102.4579,"prose":false,"stat":false,"head":false,"page":82,"col":1},{"text":"5 ou mais PO)","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":82,"col":1}],"Duração":[{"text":"Concentração, até 1 dia","top":126.25789999999995,"prose":false,"stat":false,"head":false,"page":82,"col":1}]},"desc":[{"text":"Você cria uma cópia ilusória de si mesmo que dura","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"enquanto a magia estiver ativa. A cópia pode surgir em","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"qualquer lugar que você já tenha visto e que esteja no","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"alcance da magia, ignorando obstáculos. A ilusão se pa-","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"rece e soa como você, mas é intangível. Se a ilusão sofrer","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"qualquer dano, ela desaparece e a magia se encerra.","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"Você pode ver através dos olhos da ilusão e ouvir","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"através dos ouvidos dela, como se você estivesse no","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"espaço dela. Com uma ação Usar Magia, você pode mo-","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"vê-la até 18 metros e fazer com que ela gesticule, fale","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"e se comporte da maneira que desejar. Ela imita seus","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"maneirismos perfeitamente.","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"Interação física com a imagem revela sua natureza","top":287.1132,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"ilusória, já que objetos podem atravessá-la. Uma criatu-","top":299.0132,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"ra que executa a ação Analisar para examinar a imagem","top":310.9132,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"pode determinar que se trata de uma ilusão com um","top":322.8132,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"teste bem-sucedido de Inteligência (Investigação) con-","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"tra a CD para evitar sua magia. Se uma criatura perce-","top":346.6132,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"ber a ilusão, ela pode ver através da imagem, e qualquer","top":358.5132,"prose":true,"stat":false,"head":false,"page":82,"col":1},{"text":"som que a ilusão emita parece vago para essa criatura.","top":370.4132,"prose":true,"stat":false,"head":false,"page":82,"col":1}],"page":82}');
