da queda e a magia se encerra para ela.',84,'Transmutação (Bardo, Feiticeiro, Mago)','{"level":"1","name":"Queda Suave","school":[{"text":"Transmutação (Bardo, Feiticeiro, Mago)","top":429.3651,"prose":true,"stat":false,"head":false,"page":84,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Reação, que você executa quando você","top":445.0311,"prose":false,"stat":false,"head":false,"page":84,"col":0},{"text":"ou uma criatura à sua vista a até 18 metros de você entra","top":456.93109999999996,"prose":false,"stat":false,"head":false,"page":84,"col":0},{"text":"em queda","top":468.83109999999994,"prose":false,"stat":false,"head":false,"page":84,"col":0}],"Alcance":[{"text":"18 metros","top":480.73109999999997,"prose":false,"stat":false,"head":false,"page":84,"col":0}],"Componentes":[{"text":"V, M (uma pequena pena ou pedaço de","top":492.63109999999995,"prose":false,"stat":false,"head":false,"page":84,"col":0},{"text":"penugem)","top":504.5311,"prose":false,"stat":false,"head":false,"page":84,"col":0}],"Duração":[{"text":"1 minuto","top":516.4311,"prose":false,"stat":false,"head":false,"page":84,"col":0}]},"desc":[{"text":"Escolha até cinco criaturas em queda no alcance da","top":534.4864,"prose":true,"stat":false,"head":false,"page":84,"col":0},{"text":"magia. A taxa de queda de cada uma diminui para 18","top":546.3863,"prose":true,"stat":false,"head":false,"page":84,"col":0},{"text":"metros por rodada até que a magia termine. Se uma","top":558.2864,"prose":true,"stat":false,"head":false,"page":84,"col":0},{"text":"criatura pousar antes do fim da magia, não sofre dano","top":570.1863,"prose":true,"stat":false,"head":false,"page":84,"col":0},{"text":"da queda e a magia se encerra para ela.","top":582.0863999999999,"prose":true,"stat":false,"head":false,"page":84,"col":0}],"page":84}');
