espaço de magia acima de 1.',84,'Evocação (Bruxo, Feiticeiro, Mago)','{"level":"1","name":"Raio de Bruxa","school":[{"text":"Evocação (Bruxo, Feiticeiro, Mago)","top":470.7344,"prose":true,"stat":false,"head":false,"page":84,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":486.40039999999993,"prose":false,"stat":false,"head":false,"page":84,"col":1}],"Alcance":[{"text":"18 metros","top":498.30039999999997,"prose":false,"stat":false,"head":false,"page":84,"col":1}],"Componentes":[{"text":"V, S, M (um galho atingido por um raio)","top":510.20039999999995,"prose":false,"stat":false,"head":false,"page":84,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":522.1004,"prose":false,"stat":false,"head":false,"page":84,"col":1}]},"desc":[{"text":"Um feixe de energia crepitante é lançado em direção a","top":540.1555999999999,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"uma criatura no alcance da magia, formando um arco","top":552.0557,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"sustentado de relâmpago entre você e o alvo. Realize","top":563.9557,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"um ataque mágico à distância contra ele. Em caso de","top":575.8556,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"acerto, o alvo sofre 2d12 pontos de dano Elétrico.","top":587.7556999999999,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"Em cada um dos seus turnos posteriores, você pode","top":599.6555999999999,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"executar uma ação Bônus para causar 1d12 pontos de","top":611.5557,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"dano Elétrico automaticamente ao alvo, mesmo que o","top":623.4557,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"primeiro ataque tenha falhado.","top":635.3556,"prose":true,"stat":false,"head":false,"page":84,"col":1},{"text":"A magia e