INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(311,'Raio Lunar','raio lunar',2,6,1,'V, S, M (uma folha de dama-da-noite)','Ação','36 metros','Concentração, até 1 minuto','Um feixe prateado de luz pálida brilha em um Cilindro
com 1,5 metro de raio e 12 metros de altura, centrado
em um ponto no alcance da magia. Até que a magia
termine, Meia-luz preenche o Cilindro, e você pode
executar uma ação Usar Magia nos turnos subsequen-
tes para mover o Cilindro até 18 metros.
Quando o Cilindro surge, cada criatura em seu
interior deve realizar uma salvaguarda de Constituição.
Em caso de falha, a criatura sofre 2d10 pontos de dano
Radiante e, se estiver multimorfada (como resultado da
magia Polimorfia, por exemplo), reverte-se à sua forma
verdadeira e não pode se multimorfar novamente até
sair do Cilindro. Em caso de sucesso, a criatura recebe
apenas metade do dano. Uma criatura também realiza
essa salvaguarda quando a área da magia se move para
o espaço dela, quando ela entra na área da magia ou
quando encerra o próprio turno nela. A criatura realiza
essa salvaguarda apenas uma vez por turno.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d10 para cada círculo de espaço de
magia acima de 2.',85,'Evocação (Druida)','{"level":"2","name":"Raio Lunar","school":[{"text":"Evocação (Druida)","top":271.8171,"prose":true,"stat":false,"head":false,"page":85,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":287.4831,"prose":false,"stat":false,"head":false,"page":85,"col":1}],"Alcance":[{"text":"36 metros","top":299.38309999999996,"prose":false,"stat":false,"head":false,"page":85,"col":1}],"Componentes":[{"text":"V, S, M (uma folha de dama-da-noite)","top":311.28309999999993,"prose":false,"stat":false,"head":false,"page":85,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":323.18309999999997,"prose":false,"stat":false,"head":false,"page":85,"col":1}]},"desc":[{"text":"Um feixe prateado de luz pálida brilha em um Cilindro","top":341.2384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"com 1,5 metro de raio e 12 metros de altura, centrado","top":353.1384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"em um ponto no alcance da magia. Até que a magia","top":365.0384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"termine, Meia-luz preenche o Cilindro, e você pode","top":376.9384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"executar uma ação Usar Magia nos turnos subsequen-","top":388.8384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"tes para mover o Cilindro até 18 metros.","top":400.7384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"Quando o Cilindro surge, cada criatura em seu","top":412.6384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"interior deve realizar uma salvaguarda de Constituição.","top":424.5384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"Em caso de falha, a criatura sofre 2d10 pontos de dano","top":436.4384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"Radiante e, se estiver multimorfada (como resultado da","top":448.3384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"magia Polimorfia, por exemplo), reverte-se à sua forma","top":460.2384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"verdadeira e não pode se multimorfar novamente até","top":472.1384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"sair do Cilindro. Em caso de sucesso, a criatura recebe","top":484.0384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"apenas metade do dano. Uma criatura também realiza","top":495.9384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"essa salvaguarda quando a área da magia se move para","top":507.8384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"o espaço dela, quando ela entra na área da magia ou","top":519.7384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"quando encerra o próprio turno nela. A criatura realiza","top":531.6384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"essa salvaguarda apenas uma vez por turno.","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":555.4384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"dano aumenta em 1d10 para cada círculo de espaço de","top":567.3384,"prose":true,"stat":false,"head":false,"page":85,"col":1},{"text":"magia acima de 2.","top":579.2384,"prose":true,"stat":false,"head":false,"page":85,"col":1}],"page":85}');
