INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(318,'Reencarnar','reencarnar',5,2,1,'V, S, M (óleos raros no valor de 1.000 ou mais
PO, que a magia consome)','1 hora','Toque','Instantânea','Você toca um Humanoide morto ou parte dele. Se a
criatura estiver morta há, no máximo, 10 dias, a magia
cria um novo corpo para ela e chama a alma para ha-
bitar esse corpo. Jogue 1d10 e consulte a tabela abaixo
para determinar a espécie do novo corpo ou o Mestre
escolhe outra espécie jogável.
1d10 Espécies 1d10 Espécies
1 Aasimar 6 Golias
2 Draconato 7 Pequenino
3 Anão 8 Humano
4 Elfo 9 Orc
5 Gnomo 10 Tiferino
A criatura reencarnada faz quaisquer escolhas que a
descrição de sua nova espécie oferece e mantém as me-
mórias de sua vida anterior. Ela conserva as capacidades
que possuía em sua forma original, mas perde os traços
da espécie anterior e adquire os traços da nova espécie.',87,'Necromancia (Druida)','{"level":"5","name":"Reencarnar","school":[{"text":"Necromancia (Druida)","top":328.0614,"prose":true,"stat":false,"head":false,"page":87,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 hora","top":343.62729999999993,"prose":false,"stat":false,"head":false,"page":87,"col":1}],"Alcance":[{"text":"Toque","top":355.42729999999995,"prose":false,"stat":false,"head":false,"page":87,"col":1}],"Componentes":[{"text":"V, S, M (óleos raros no valor de 1.000 ou mais","top":367.22729999999996,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"PO, que a magia consome)","top":379.02729999999997,"prose":false,"stat":false,"head":false,"page":87,"col":1}],"Duração":[{"text":"Instantânea","top":390.8273,"prose":false,"stat":false,"head":false,"page":87,"col":1}]},"desc":[{"text":"Você toca um Humanoide morto ou parte dele. Se a","top":408.7826,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"criatura estiver morta há, no máximo, 10 dias, a magia","top":420.5826,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"cria um novo corpo para ela e chama a alma para ha-","top":432.3826,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"bitar esse corpo. Jogue 1d10 e consulte a tabela abaixo","top":444.1826,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"para determinar a espécie do novo corpo ou o Mestre","top":455.9826,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"escolhe outra espécie jogável.","top":467.7826,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"1d10 Espécies 1d10 Espécies","top":489.4325,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"1 Aasimar 6 Golias","top":503.51579999999996,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"2 Draconato 7 Pequenino","top":517.689,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"3 Anão 8 Humano","top":531.8622,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"4 Elfo 9 Orc","top":546.0354,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"5 Gnomo 10 Tiferino","top":560.2087,"prose":false,"stat":false,"head":false,"page":87,"col":1},{"text":"A criatura reencarnada faz quaisquer escolhas que a","top":588.222,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"descrição de sua nova espécie oferece e mantém as me-","top":600.0219999999999,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"mórias de sua vida anterior. Ela conserva as capacidades","top":611.822,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"que possuía em sua forma original, mas perde os traços","top":623.622,"prose":true,"stat":false,"head":false,"page":87,"col":1},{"text":"da espécie anterior e adquire os traços da nova espécie.","top":635.422,"prose":true,"stat":false,"head":false,"page":87,"col":1}],"page":87}');
