INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(319,'Reflexos','reflexos',2,7,1,'V, S','Ação','Pessoal','1 minuto','Três cópias ilusórias suas aparecem em seu espaço. Até
que a magia termine, as cópias se movem com você e
imitam suas ações, mudando de posição de forma que
seja impossível rastrear qual imagem é a verdadeira.
Cada vez que uma criatura atinge você com uma
jogada de ataque pela duração da magia, jogue um d6
para cada uma das cópias restantes. Se qualquer um
dos d6s resultar em 3 ou mais, uma das cópias é atingi-
da em seu lugar e é destruída. As cópias ignoram todos
os outros danos e efeitos. A magia se encerra quando
as três cópias são destruídas.
Uma criatura não é afetada por esta magia se tem a
condição Cego, ou se possuir Visão às Cegas ou Visão
Verdadeira.',87,'Ilusão (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"2","name":"Reflexos","school":[{"text":"Ilusão (Bardo, Bruxo, Feiticeiro, Mago)","top":679.3259,"prose":true,"stat":false,"head":false,"page":87,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":694.8919,"prose":false,"stat":false,"head":false,"page":87,"col":1}],"Alcance":[{"text":"Pessoal","top":706.6919,"prose":false,"stat":false,"head":false,"page":87,"col":1}],"Componentes":[{"text":"V, S","top":718.4919,"prose":false,"stat":false,"head":false,"page":87,"col":1}],"Duração":[{"text":"1 minuto","top":730.2918999999999,"prose":false,"stat":false,"head":false,"page":87,"col":1}]},"desc":[{"text":"Três cópias ilusórias suas aparecem em seu espaço. Até","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"que a magia termine, as cópias se movem com você e","top":48.057399999999916,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"imitam suas ações, mudando de posição de forma que","top":59.75739999999996,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"seja impossível rastrear qual imagem é a verdadeira.","top":71.45729999999992,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"Cada vez que uma criatura atinge você com uma","top":83.15729999999996,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"jogada de ataque pela duração da magia, jogue um d6","top":94.85739999999998,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"para cada uma das cópias restantes. Se qualquer um","top":106.55739999999992,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"dos d6s resultar em 3 ou mais, uma das cópias é atingi-","top":118.25739999999996,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"da em seu lugar e é destruída. As cópias ignoram todos","top":129.95729999999992,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"os outros danos e efeitos. A magia se encerra quando","top":141.65729999999996,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"as três cópias são destruídas.","top":153.35739999999998,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"Uma criatura não é afetada por esta magia se tem a","top":165.05739999999992,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"condição Cego, ou se possuir Visão às Cegas ou Visão","top":176.7573,"prose":true,"stat":false,"head":false,"page":88,"col":0},{"text":"Verdadeira.","top":188.45729999999992,"prose":true,"stat":false,"head":false,"page":88,"col":0}],"page":87}');
