INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(323,'Remeter','remeter',3,8,1,'V, S, M (um fio de cobre)','Ação','Ilimitado','Instantânea','Você envia uma mensagem curta de 25 palavras ou
menos para uma criatura que você já encontrou ou que
foi descrita a você por alguém que a tenha conhecido.
O alvo ouve a mensagem na mente, reconhece você
como remetente se o conhecer e pode responder da
mesma forma imediatamente. A magia permite que o
alvo compreenda o significado da sua mensagem.
Você pode enviar a mensagem através de qualquer
distância e até para outros planos de existência, mas
se o alvo estiver em um plano diferente do seu, há uma
chance de 5% de que a mensagem não chegue. Você
sabe se a entrega falha.
Ao receber sua mensagem, a criatura pode bloquear
sua capacidade de contactá-la novamente com essa
magia por 8 horas. Se você tentar enviar outra mensa-
gem durante esse período, descobre que está bloquea-
do e a magia falha.',88,'Adivinhação (Bardo, Clérigo, Mago)','{"level":"3","name":"Remeter","school":[{"text":"Adivinhação (Bardo, Clérigo, Mago)","top":175.7613,"prose":true,"stat":false,"head":false,"page":88,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":191.42729999999995,"prose":false,"stat":false,"head":false,"page":88,"col":1}],"Alcance":[{"text":"Ilimitado","top":203.32729999999992,"prose":false,"stat":false,"head":false,"page":88,"col":1}],"Componentes":[{"text":"V, S, M (um fio de cobre)","top":215.2273,"prose":false,"stat":false,"head":false,"page":88,"col":1}],"Duração":[{"text":"Instantânea","top":227.1273,"prose":false,"stat":false,"head":false,"page":88,"col":1}]},"desc":[{"text":"Você envia uma mensagem curta de 25 palavras ou","top":245.18259999999998,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"menos para uma criatura que você já encontrou ou que","top":257.08259999999996,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"foi descrita a você por alguém que a tenha conhecido.","top":268.98259999999993,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"O alvo ouve a mensagem na mente, reconhece você","top":280.8826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"como remetente se o conhecer e pode responder da","top":292.7826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"mesma forma imediatamente. A magia permite que o","top":304.6826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"alvo compreenda o significado da sua mensagem.","top":316.5826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"Você pode enviar a mensagem através de qualquer","top":328.4826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"distância e até para outros planos de existência, mas","top":340.3826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"se o alvo estiver em um plano diferente do seu, há uma","top":352.2826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"chance de 5% de que a mensagem não chegue. Você","top":364.1826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"sabe se a entrega falha.","top":376.0826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"Ao receber sua mensagem, a criatura pode bloquear","top":387.9826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"sua capacidade de contactá-la novamente com essa","top":399.8826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"magia por 8 horas. Se você tentar enviar outra mensa-","top":411.7826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"gem durante esse período, descobre que está bloquea-","top":423.6826,"prose":true,"stat":false,"head":false,"page":88,"col":1},{"text":"do e a magia falha.","top":435.5826,"prose":true,"stat":false,"head":false,"page":88,"col":1}],"page":88}');
