INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(337,'Rogar Maldição','rogar maldicao',3,2,1,'V, S','Ação','Toque','Concentração, até 1 minuto','Você toca uma criatura, que deve ser bem-sucedida
em uma salvaguarda de Sabedoria ou fica amaldiçoada
pela duração da magia. Até que a maldição termine, o
alvo sofre um dos seguintes efeitos à sua escolha:
• Escolha um atributo. O alvo tem Desvantagem em
testes de atributo e salvaguardas realizadas com esse
atributo.
• O alvo tem Desvantagem em jogadas de ataque con-
tra você.
• Em combate, o alvo deve ser bem-sucedido em uma
salvaguarda de Sabedoria no início de cada um dos
turnos dele ou ele é forçado a executar a ação Esqui-
var neste turno.
• Se você causar dano ao alvo com uma jogada de ata-
que ou uma magia, o alvo sofre 1d8 pontos de dano
Necrótico adicionais.
Usando um Espaço de Magia de Círculo Superior. Se
você conjurar esta magia usando um espaço de magia
de 4º círculo, você pode manter a Concentração nela
por até 10 minutos. Se você usar um espaço de magia
de 5º círculo ou superior, a magia não requer Concen-
tração, e a duração se torna 8 horas (espaço de 5º e 6º
círculo) ou 24 horas (espaço de 7º ou 8º círculo). Se
você usar um espaço de magia de 9º círculo, a magia
permanece até ser dissipada.',92,'Necromancia (Bardo, Clérigo, Mago)','{"level":"3","name":"Rogar Maldição","school":[{"text":"Necromancia (Bardo, Clérigo, Mago)","top":236.11709999999994,"prose":true,"stat":false,"head":false,"page":92,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":251.7831,"prose":false,"stat":false,"head":false,"page":92,"col":0}],"Alcance":[{"text":"Toque","top":263.68309999999997,"prose":false,"stat":false,"head":false,"page":92,"col":0}],"Componentes":[{"text":"V, S","top":275.58309999999994,"prose":false,"stat":false,"head":false,"page":92,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":287.4831,"prose":false,"stat":false,"head":false,"page":92,"col":0}]},"desc":[{"text":"Você toca uma criatura, que deve ser bem-sucedida","top":305.5384,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"em uma salvaguarda de Sabedoria ou fica amaldiçoada","top":317.4384,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"pela duração da magia. Até que a maldição termine, o","top":329.3384,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"alvo sofre um dos seguintes efeitos à sua escolha:","top":341.2384,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"• Escolha um atributo. O alvo tem Desvantagem em","top":358.8077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"testes de atributo e salvaguardas realizadas com esse","top":370.7077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"atributo.","top":382.6077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"• O alvo tem Desvantagem em jogadas de ataque con-","top":394.5077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"tra você.","top":406.40770000000003,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"• Em combate, o alvo deve ser bem-sucedido em uma","top":418.3077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"salvaguarda de Sabedoria no início de cada um dos","top":430.2077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"turnos dele ou ele é forçado a executar a ação Esqui-","top":442.1077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"var neste turno.","top":454.0077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"• Se você causar dano ao alvo com uma jogada de ata-","top":465.90770000000003,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"que ou uma magia, o alvo sofre 1d8 pontos de dano","top":477.8077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"Necrótico adicionais.","top":489.7077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. Se","top":507.277,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"você conjurar esta magia usando um espaço de magia","top":519.177,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"de 4º círculo, você pode manter a Concentração nela","top":531.077,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"por até 10 minutos. Se você usar um espaço de magia","top":542.977,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"de 5º círculo ou superior, a magia não requer Concen-","top":554.877,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"tração, e a duração se torna 8 horas (espaço de 5º e 6º","top":566.777,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"círculo) ou 24 horas (espaço de 7º ou 8º círculo). Se","top":578.6769999999999,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"você usar um espaço de magia de 9º círculo, a magia","top":590.577,"prose":true,"stat":false,"head":false,"page":92,"col":0},{"text":"permanece até ser dissipada.","top":602.477,"prose":true,"stat":false,"head":false,"page":92,"col":0}],"page":92}');
