magia acima de 1.',93,'Invocação (Guardião)','{"level":"1","name":"Saraivada de Espinhos","school":[{"text":"Invocação (Guardião)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":93,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus, que você realiza","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":93,"col":0},{"text":"imediatamente após atingir uma criatura com um ataque","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":93,"col":0},{"text":"com arma à Distância","top":102.4579,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Alcance":[{"text":"Pessoal","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Componentes":[{"text":"V","top":126.25789999999995,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Duração":[{"text":"Instantânea","top":138.15789999999993,"prose":false,"stat":false,"head":false,"page":93,"col":0}]},"desc":[{"text":"Ao atingir uma criatura, essa magia faz surgir uma","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"chuva de espinhos a partir da sua arma à distância","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"ou munição. O alvo e cada criatura em um raio de 1,5","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"metro devem realizar uma salvaguarda de Destreza,","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"sofrendo 1d10 pontos de dano perfurante se falharem","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"ou metade desse dano em caso de sucesso.","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"dano aumenta em 1d10 para cada círculo de espaço de","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"magia acima de 1.","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":93,"col":0}],"page":93}');
