INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(342,'Semiplano','semiplano',8,4,1,'S','Ação','18 metros','1 hora','Você cria uma porta Média de sombras em uma
superfície sólida e plana à sua vista e no alcance da
magia. Essa porta pode ser aberta e fechada, levando a
uma sala vazia de 9 metros em cada dimensão, feita de
madeira ou pedra à sua escolha, em semiplano.
Quando a magia termina, a porta desaparece e os ob-
jetos dentro do semiplano permanecem nele. Qualquer
criatura dentro dele também permanece nele, a menos
que escolha passar pela porta enquanto ela desaparece,
saindo com a condição Caído e nos espaços desocu-
pados mais próximos do espaço que a porta ocupava
anteriormente.
Ao conjurar esta magia, você pode criar um novo se-
miplano ou conectar a porta de sombras a um semiplano
que você criou em uma conjuração anterior desta magia.
Além disso, se souber a natureza e o conteúdo de um se-
miplano criado por outra criatura com esta magia, você
pode conectar a porta de sombras a esse semiplano.',93,'Invocação (Bruxo, Feiticeiro, Mago)','{"level":"8","name":"Semiplano","school":[{"text":"Invocação (Bruxo, Feiticeiro, Mago)","top":295.6172,"prose":true,"stat":false,"head":false,"page":93,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":311.28309999999993,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Alcance":[{"text":"18 metros","top":323.18309999999997,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Componentes":[{"text":"S","top":335.08309999999994,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Duração":[{"text":"1 hora","top":346.9831,"prose":false,"stat":false,"head":false,"page":93,"col":0}]},"desc":[{"text":"Você cria uma porta Média de sombras em uma","top":365.0384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"superfície sólida e plana à sua vista e no alcance da","top":376.9384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"magia. Essa porta pode ser aberta e fechada, levando a","top":388.8384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"uma sala vazia de 9 metros em cada dimensão, feita de","top":400.7384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"madeira ou pedra à sua escolha, em semiplano.","top":412.6384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"Quando a magia termina, a porta desaparece e os ob-","top":424.5384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"jetos dentro do semiplano permanecem nele. Qualquer","top":436.4384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"criatura dentro dele também permanece nele, a menos","top":448.3384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"que escolha passar pela porta enquanto ela desaparece,","top":460.2384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"saindo com a condição Caído e nos espaços desocu-","top":472.1384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"pados mais próximos do espaço que a porta ocupava","top":484.0384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"anteriormente.","top":495.9384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"Ao conjurar esta magia, você pode criar um novo se-","top":507.8384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"miplano ou conectar a porta de sombras a um semiplano","top":519.7384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"que você criou em uma conjuração anterior desta magia.","top":531.6384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"Além disso, se souber a natureza e o conteúdo de um se-","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"miplano criado por outra criatura com esta magia, você","top":555.4384,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"pode conectar a porta de sombras a esse semiplano.","top":567.3384,"prose":true,"stat":false,"head":false,"page":93,"col":0}],"page":93}');
