INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(343,'Sentido Feral','sentido feral',2,8,1,'S','Ação ou Ritual','Toque','Concentração, até 1 hora','Você toca uma Fera voluntária. Pela duração da magia,
você pode perceber através dos sentidos da Fera, bem
como dos seus próprios. Ao perceber através dos sen-
tidos da Fera, você se beneficia de quaisquer sentidos
especiais que ela tenha.',93,'Adivinhação (Druida, Guardião)','{"level":"2","name":"Sentido Feral","school":[{"text":"Adivinhação (Druida, Guardião)","top":611.5424,"prose":true,"stat":false,"head":false,"page":93,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":627.2083,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Alcance":[{"text":"Toque","top":639.1083,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Componentes":[{"text":"S","top":651.0083,"prose":false,"stat":false,"head":false,"page":93,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":662.9082999999999,"prose":false,"stat":false,"head":false,"page":93,"col":0}]},"desc":[{"text":"Você toca uma Fera voluntária. Pela duração da magia,","top":680.9636,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"você pode perceber através dos sentidos da Fera, bem","top":692.8636,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"como dos seus próprios. Ao perceber através dos sen-","top":704.7636,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"tidos da Fera, você se beneficia de quaisquer sentidos","top":716.6636,"prose":true,"stat":false,"head":false,"page":93,"col":0},{"text":"especiais que ela tenha.","top":728.5636,"prose":true,"stat":false,"head":false,"page":93,"col":0}],"page":93}');
