INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(344,'Servo Invisível','servo invisivel',1,4,1,'V, S, M (um pedaço de barbante e de madeira)','Ação ou Ritual','18 metros','1 hora','Esta magia cria uma força Invisível, sem mente, disfor-
me e Média que executa tarefas simples ao seu coman-
do até que a magia termine. O servo nasce em um es-
paço desocupado no chão no alcance da magia. Ele tem
CA 10, 1 Ponto de Vida e Força 2, e não pode atacar. Se
ele é reduzido a 0 Pontos de Vida, a magia encerra.
Uma vez em cada um de seus turnos como uma Ação
Bônus, você pode comandar mentalmente o servo a
se mover até 4,5 metros e interagir com um objeto. O
servo pode realizar tarefas simples que um humano
poderia fazer, como buscar coisas, limpar, consertar,
dobrar roupas, acender fogueiras, servir comida e bebi-
das. Depois de dar o comando, o servo executa a tarefa
da melhor forma possível até que conclua a tarefa e,
em seguida, aguarda seu próximo comando.
Ao ordenar ao servo que realize uma tarefa que o
mova a mais de 18 metros de distância de você, a magia
se encerra.',93,'Invocação (Bardo, Bruxo, Mago)','{"level":"1","name":"Servo Invisível","school":[{"text":"Invocação (Bardo, Bruxo, Mago)","top":62.99209999999994,"prose":true,"stat":false,"head":false,"page":93,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":93,"col":1}],"Alcance":[{"text":"18 metros","top":90.55809999999997,"prose":false,"stat":false,"head":false,"page":93,"col":1}],"Componentes":[{"text":"V, S, M (um pedaço de barbante e de madeira)","top":102.45799999999997,"prose":false,"stat":false,"head":false,"page":93,"col":1}],"Duração":[{"text":"1 hora","top":114.35799999999995,"prose":false,"stat":false,"head":false,"page":93,"col":1}]},"desc":[{"text":"Esta magia cria uma força Invisível, sem mente, disfor-","top":132.41329999999994,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"me e Média que executa tarefas simples ao seu coman-","top":144.3132999999999,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"do até que a magia termine. O servo nasce em um es-","top":156.2133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"paço desocupado no chão no alcance da magia. Ele tem","top":168.11329999999998,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"CA 10, 1 Ponto de Vida e Força 2, e não pode atacar. Se","top":180.01329999999996,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"ele é reduzido a 0 Pontos de Vida, a magia encerra.","top":191.91329999999994,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"Uma vez em cada um de seus turnos como uma Ação","top":203.8132999999999,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"Bônus, você pode comandar mentalmente o servo a","top":215.7133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"se mover até 4,5 metros e interagir com um objeto. O","top":227.61329999999998,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"servo pode realizar tarefas simples que um humano","top":239.51329999999996,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"poderia fazer, como buscar coisas, limpar, consertar,","top":251.41329999999994,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"dobrar roupas, acender fogueiras, servir comida e bebi-","top":263.3132999999999,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"das. Depois de dar o comando, o servo executa a tarefa","top":275.2133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"da melhor forma possível até que conclua a tarefa e,","top":287.1133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"em seguida, aguarda seu próximo comando.","top":299.0133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"Ao ordenar ao servo que realize uma tarefa que o","top":310.9133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"mova a mais de 18 metros de distância de você, a magia","top":322.8133,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"se encerra.","top":334.7133,"prose":true,"stat":false,"head":false,"page":93,"col":1}],"page":93}');
