INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(346,'Silêncio','silencio',2,7,1,'V, S','Ação ou Ritual','36 metros','Concentração, até 10 minutos','Pela duração da magia, nenhum som pode ser criado
dentro ou passar através de uma esfera com raio de 6
metros centrada em um ponto à sua escolha no alcance
da magia. Qualquer criatura ou objeto totalmente den-
tro da esfera é imune a dano Trovejante, e as criaturas
têm a condição Surdo enquanto estiverem totalmente
dentro dela. É impossível conjurar uma magia que
incluia um componente Verbal neste local.',93,'Ilusão (Bardo, Clérigo, Guardião)','{"level":"2","name":"Silêncio","school":[{"text":"Ilusão (Bardo, Clérigo, Guardião)","top":552.0425,"prose":true,"stat":false,"head":false,"page":93,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":567.7085,"prose":false,"stat":false,"head":false,"page":93,"col":1}],"Alcance":[{"text":"36 metros","top":579.6084,"prose":false,"stat":false,"head":false,"page":93,"col":1}],"Componentes":[{"text":"V, S","top":591.5083999999999,"prose":false,"stat":false,"head":false,"page":93,"col":1}],"Duração":[{"text":"Concentração, até 10 minutos","top":603.4084,"prose":false,"stat":false,"head":false,"page":93,"col":1}]},"desc":[{"text":"Pela duração da magia, nenhum som pode ser criado","top":621.4637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"dentro ou passar através de uma esfera com raio de 6","top":633.3637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"metros centrada em um ponto à sua escolha no alcance","top":645.2637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"da magia. Qualquer criatura ou objeto totalmente den-","top":657.1637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"tro da esfera é imune a dano Trovejante, e as criaturas","top":669.0637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"têm a condição Surdo enquanto estiverem totalmente","top":680.9637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"dentro dela. É impossível conjurar uma magia que","top":692.8637,"prose":true,"stat":false,"head":false,"page":93,"col":1},{"text":"incluia um componente Verbal neste local.","top":704.7637,"prose":true,"stat":false,"head":false,"page":93,"col":1}],"page":93}');
