INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(348,'Similaridade','similaridade',5,7,1,'V, S','Ação','9 metros','8 horas','Você dá uma aparência ilusória a cada criatura à sua
escolha à sua vista e no alcance da magia. Um alvo
involuntário pode realizar uma salvaguarda de Carisma
e, se for bem-sucedido, não é afetado por esta magia.
Você pode dar a mesma aparência ou aparências
diferentes aos alvos. A magia pode alterar a aparência
dos corpos e equipamentos dos alvos, fazendo com que
cada criatura pareça até 30 centímetros mais alta ou
mais baixa e mais pesada ou mais leve. A nova apa-
rência deve manter os aspectos básicos de membros
do corpo do alvo, mas o restante da ilusão fica a seu
critério. Os efeitos permanecem pela duração da magia.
As mudanças causadas por esta magia falham me-
diante uma inspeção física. Por exemplo, se você usar
a magia para adicionar um chapéu ao traje de uma
criatura, objetos passam através do chapéu.
Uma criatura que executa a ação Analisar para exami-
nar um alvo pode realizar um teste de Inteligência (In-
vestigação) contra a CD para evitar sua magia. Em caso
de sucesso, a criatura percebe que o alvo está disfarçado.',94,'Ilusão (Bardo, Feiticeiro, Mago)','{"level":"5","name":"Similaridade","school":[{"text":"Ilusão (Bardo, Feiticeiro, Mago)","top":175.76119999999992,"prose":true,"stat":false,"head":false,"page":94,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":191.42719999999997,"prose":false,"stat":false,"head":false,"page":94,"col":1}],"Alcance":[{"text":"9 metros","top":203.32719999999995,"prose":false,"stat":false,"head":false,"page":94,"col":1}],"Componentes":[{"text":"V, S","top":215.22719999999993,"prose":false,"stat":false,"head":false,"page":94,"col":1}],"Duração":[{"text":"8 horas","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":94,"col":1}]},"desc":[{"text":"Você dá uma aparência ilusória a cada criatura à sua","top":245.1825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"escolha à sua vista e no alcance da magia. Um alvo","top":257.0825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"involuntário pode realizar uma salvaguarda de Carisma","top":268.98249999999996,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"e, se for bem-sucedido, não é afetado por esta magia.","top":280.8825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"Você pode dar a mesma aparência ou aparências","top":292.7825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"diferentes aos alvos. A magia pode alterar a aparência","top":304.6825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"dos corpos e equipamentos dos alvos, fazendo com que","top":316.5825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"cada criatura pareça até 30 centímetros mais alta ou","top":328.4825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"mais baixa e mais pesada ou mais leve. A nova apa-","top":340.3825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"rência deve manter os aspectos básicos de membros","top":352.2825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"do corpo do alvo, mas o restante da ilusão fica a seu","top":364.1825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"critério. Os efeitos permanecem pela duração da magia.","top":376.0825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"As mudanças causadas por esta magia falham me-","top":387.9825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"diante uma inspeção física. Por exemplo, se você usar","top":399.8825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"a magia para adicionar um chapéu ao traje de uma","top":411.7825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"criatura, objetos passam através do chapéu.","top":423.6825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"Uma criatura que executa a ação Analisar para exami-","top":435.5825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"nar um alvo pode realizar um teste de Inteligência (In-","top":447.4825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"vestigação) contra a CD para evitar sua magia. Em caso","top":459.3825,"prose":true,"stat":false,"head":false,"page":94,"col":1},{"text":"de sucesso, a criatura percebe que o alvo está disfarçado.","top":471.2825,"prose":true,"stat":false,"head":false,"page":94,"col":1}],"page":94}');
