INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(350,'Simular Morte','simular morte',3,2,1,'V, S, M (uma pitada de terra de cemitério)','Ação ou Ritual','Toque','1 hora','Você toca uma criatura voluntária e a coloca em um
estado cataléptico que é indistinguível da morte.
Pela duração da magia, o alvo parece morto em uma
inspeção externa e para magias usadas para determinar
a situação do alvo. O alvo está com as condições Cego
e Incapacitado, e o Deslocamento dele é 0.
O alvo também tem Resistência a todos os tipos de
dano, exceto dano Psíquico, e tem Imunidade à condi-
ção Envenenado.',95,'Necromancia (Bardo, Clérigo, Druida, Mago)','{"level":"3","name":"Simular Morte","school":[{"text":"Necromancia (Bardo, Clérigo, Druida, Mago)","top":211.46119999999996,"prose":true,"stat":false,"head":false,"page":95,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação ou Ritual","top":227.1271999999999,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Alcance":[{"text":"Toque","top":239.0272,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Componentes":[{"text":"V, S, M (uma pitada de terra de cemitério)","top":250.92719999999997,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Duração":[{"text":"1 hora","top":262.82719999999995,"prose":false,"stat":false,"head":false,"page":95,"col":0}]},"desc":[{"text":"Você toca uma criatura voluntária e a coloca em um","top":280.8825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"estado cataléptico que é indistinguível da morte.","top":292.7825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"Pela duração da magia, o alvo parece morto em uma","top":304.6825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"inspeção externa e para magias usadas para determinar","top":316.5825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"a situação do alvo. O alvo está com as condições Cego","top":328.4825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"e Incapacitado, e o Deslocamento dele é 0.","top":340.3825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"O alvo também tem Resistência a todos os tipos de","top":352.2825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"dano, exceto dano Psíquico, e tem Imunidade à condi-","top":364.1825,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"ção Envenenado.","top":376.0825,"prose":true,"stat":false,"head":false,"page":95,"col":0}],"page":95}');
