INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(351,'Sinal de Esperança','sinal de esperanca',3,3,1,'V, S','Ação','9 metros','Concentração, até 1 minuto','Escolha qualquer número de criaturas no alcance da
magia. Pela duração da magia, cada alvo tem Vantagem
em salvaguardas de Sabedoria e Salvaguarda contra
Morte e recupera o número de Pontos de Vida máxi-
mos possíveis de qualquer cura.',95,'Abjuração (Clérigo)','{"level":"3","name":"Sinal de Esperança","school":[{"text":"Abjuração (Clérigo)","top":420.2864,"prose":true,"stat":false,"head":false,"page":95,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":435.95239999999995,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Alcance":[{"text":"9 metros","top":447.85239999999993,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Componentes":[{"text":"V, S","top":459.75239999999997,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":471.65239999999994,"prose":false,"stat":false,"head":false,"page":95,"col":0}]},"desc":[{"text":"Escolha qualquer número de criaturas no alcance da","top":489.7077,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"magia. Pela duração da magia, cada alvo tem Vantagem","top":501.6077,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"em salvaguardas de Sabedoria e Salvaguarda contra","top":513.5077,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"Morte e recupera o número de Pontos de Vida máxi-","top":525.4077,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"mos possíveis de qualquer cura.","top":537.3077,"prose":true,"stat":false,"head":false,"page":95,"col":0}],"page":95}');
