INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(352,'Sonho','sonho',5,7,1,'V, S, M (um punhado de areia)','1 minuto','Especial','8 horas','Você tem como alvo uma criatura que você conhece
no mesmo plano de existência. Você ou uma criatura
voluntária que você toca entra em um estado de transe
para agir como um mensageiro dos sonhos. Enquanto
estiver em transe, o mensageiro está Incapacitado e
tem Deslocamento 0.
Se o alvo estiver dormindo, o mensageiro aparece
nos sonhos do alvo e pode conversar com ele enquan-
to ele permanecer dormindo, pela duração da magia.
O mensageiro também pode moldar o ambiente do
sonho, criando paisagens, objetos e outras imagens. O
mensageiro pode emergir do transe a qualquer mo-
mento, encerrando a magia. O alvo se lembra do sonho
perfeitamente ao acordar.
Se o alvo estiver acordado quando você conjurar a
magia, o mensageiro sabe disso e pode encerrar o tran-
se (e a magia) ou esperar que o alvo durma, momento
em que o mensageiro entra nos sonhos do alvo.
Você pode tornar o mensageiro aterrorizante para
o alvo. Se você fizer isso, o mensageiro pode entre-
gar uma mensagem de no máximo dez palavras e, em
seguida, o alvo realiza uma salvaguarda de Sabedoria.
Se falhar, o alvo não recebe nenhum benefício do
descanso e sofre 3d6 pontos de dano Psíquico quando
acordar.',95,'Ilusão (Bardo, Bruxo, Mago)','{"level":"5","name":"Sonho","school":[{"text":"Ilusão (Bardo, Bruxo, Mago)","top":581.5117,"prose":true,"stat":false,"head":false,"page":95,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":597.1776,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Alcance":[{"text":"Especial","top":609.0776,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Componentes":[{"text":"V, S, M (um punhado de areia)","top":620.9775999999999,"prose":false,"stat":false,"head":false,"page":95,"col":0}],"Duração":[{"text":"8 horas","top":632.8776,"prose":false,"stat":false,"head":false,"page":95,"col":0}]},"desc":[{"text":"Você tem como alvo uma criatura que você conhece","top":650.9329,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"no mesmo plano de existência. Você ou uma criatura","top":662.8329,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"voluntária que você toca entra em um estado de transe","top":674.7329,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"para agir como um mensageiro dos sonhos. Enquanto","top":686.6329,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"estiver em transe, o mensageiro está Incapacitado e","top":698.5329,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"tem Deslocamento 0.","top":710.4329,"prose":true,"stat":false,"head":false,"page":95,"col":0},{"text":"Se o alvo estiver dormindo, o mensageiro aparece","top":36.357399999999984,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"nos sonhos do alvo e pode conversar com ele enquan-","top":48.25739999999996,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"to ele permanecer dormindo, pela duração da magia.","top":60.15739999999994,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"O mensageiro também pode moldar o ambiente do","top":72.05739999999992,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"sonho, criando paisagens, objetos e outras imagens. O","top":83.9573999999999,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"mensageiro pode emergir do transe a qualquer mo-","top":95.85739999999998,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"mento, encerrando a magia. O alvo se lembra do sonho","top":107.75739999999996,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"perfeitamente ao acordar.","top":119.65739999999994,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"Se o alvo estiver acordado quando você conjurar a","top":131.55739999999992,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"magia, o mensageiro sabe disso e pode encerrar o tran-","top":143.4573999999999,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"se (e a magia) ou esperar que o alvo durma, momento","top":155.35739999999998,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"em que o mensageiro entra nos sonhos do alvo.","top":167.25739999999996,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"Você pode tornar o mensageiro aterrorizante para","top":179.15739999999994,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"o alvo. Se você fizer isso, o mensageiro pode entre-","top":191.05739999999992,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"gar uma mensagem de no máximo dez palavras e, em","top":202.9573999999999,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"seguida, o alvo realiza uma salvaguarda de Sabedoria.","top":214.85739999999998,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"Se falhar, o alvo não recebe nenhum benefício do","top":226.75739999999996,"prose":true,"stat":false,"head":false,"page":95,"col":1},{"text":"descanso e sofre 3d6 pontos de dano Psíquico quando","top":238.65739999999994,"prose":true,"stat":false,"head":false,"page":95,"col