INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(355,'Sugestão','sugestao',2,1,1,'V, M (uma gota de mel)','Ação','9 metros','Concentração, até 8 horas','Você sugere um curso de ação — descrito em no
máximo 25 palavras — para uma criatura à sua vista e
no alcance da magia e que possa ouvi-lo e entendê-lo.
A sugestão deve parecer razoável e não envolver nada
que obviamente cause dano ao alvo ou aos aliados dele.
Por exemplo, você poderia dizer: “Pegue a chave do
cofre do tesouro do culto e a traga para mim” ou “Pare
de lutar, saia desta biblioteca em paz e não volte”.
O alvo deve ser bem-sucedido em uma salvaguarda de
Sabedoria ou tem a condição Enfeitiçado pela duração
da magia ou até que você ou seus aliados causem dano
a ele. O alvo Enfeitiçado executa a sugestão da melhor
forma possível. A atividade sugerida pode durar en-
quanto a magia estiver ativa, mas se puder ser concluída
mais rapidamente, a magia se encerra ao finalizá-la.',96,'Encantamento (Bardo, Bruxo, Feiticeiro, Mago)','{"level":"2","name":"Sugestão","school":[{"text":"Encantamento (Bardo, Bruxo, Feiticeiro, Mago)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":96,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":96,"col":0}],"Alcance":[{"text":"9 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":96,"col":0}],"Componentes":[{"text":"V, M (uma gota de mel)","top":102.4579,"prose":false,"stat":false,"head":false,"page":96,"col":0}],"Duração":[{"text":"Concentração, até 8 horas","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":96,"col":0}]},"desc":[{"text":"Você sugere um curso de ação — descrito em no","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"máximo 25 palavras — para uma criatura à sua vista e","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"no alcance da magia e que possa ouvi-lo e entendê-lo.","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"A sugestão deve parecer razoável e não envolver nada","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"que obviamente cause dano ao alvo ou aos aliados dele.","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"Por exemplo, você poderia dizer: “Pegue a chave do","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"cofre do tesouro do culto e a traga para mim” ou “Pare","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"de lutar, saia desta biblioteca em paz e não volte”.","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"O alvo deve ser bem-sucedido em uma salvaguarda de","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"Sabedoria ou tem a condição Enfeitiçado pela duração","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"da magia ou até que você ou seus aliados causem dano","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"a ele. O alvo Enfeitiçado executa a sugestão da melhor","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"forma possível. A atividade sugerida pode durar en-","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"quanto a magia estiver ativa, mas se puder ser concluída","top":287.1132,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"mais rapidamente, a magia se encerra ao finalizá-la.","top":299.0132,"prose":true,"stat":false,"head":false,"page":96,"col":0}],"page":96}');
