INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(356,'Sugestão em Massa','sugestao em massa',6,1,1,'V, M (a língua de uma cobra)','Ação','18 metros','24 horas','Você sugere um curso de ação — descrito em não mais
de 25 palavras — para até doze criaturas à sua vista e
no alcance da magia que possam ouvi-lo e entendê-lo.
A sugestão deve parecer acessível e não envolver nada
que obviamente cause dano a qualquer um dos alvos
ou seus aliados. Por exemplo, você poderia dizer: “Ca-
minhe até a aldeia por essa estrada e auxilie os aldeões
a realizar a colheita até o pôr do sol” ou dizer: “Agora
não é hora para violência. Larguem as armas e dan-
cem! Parem em uma hora”.
Cada alvo deve ser bem-sucedido em uma salva-
guarda de Sabedoria ou tem a condição Enfeitiçado
pela duração da magia ou até que você ou seus aliados
causem dano ao alvo. Cada alvo Enfeitiçado cumpre a
sugestão com o melhor de sua capacidade. A atividade
sugerida pode continuar por toda a duração da magia,
mas se a atividade sugerida puder ser concluída em um
tempo mais curto, a magia encerra para um alvo que a
complete.
Usando um Espaço de Magia de Círculo Superior. A
duração é maior com um espaço de magia 7º círculo
(10 dias), 8º círculo (30 dias) ou 9º círculo (366 dias).',96,'Encantamento (Bardo, Feiticeiro, Mago)','{"level":"6","name":"Sugestão em Massa","school":[{"text":"Encantamento (Bardo, Feiticeiro, Mago)","top":343.2171,"prose":true,"stat":false,"head":false,"page":96,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":358.88309999999996,"prose":false,"stat":false,"head":false,"page":96,"col":0}],"Alcance":[{"text":"18 metros","top":370.78309999999993,"prose":false,"stat":false,"head":false,"page":96,"col":0}],"Componentes":[{"text":"V, M (a língua de uma cobra)","top":382.68309999999997,"prose":false,"stat":false,"head":false,"page":96,"col":0}],"Duração":[{"text":"24 horas","top":394.58309999999994,"prose":false,"stat":false,"head":false,"page":96,"col":0}]},"desc":[{"text":"Você sugere um curso de ação — descrito em não mais","top":412.6384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"de 25 palavras — para até doze criaturas à sua vista e","top":424.5384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"no alcance da magia que possam ouvi-lo e entendê-lo.","top":436.4384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"A sugestão deve parecer acessível e não envolver nada","top":448.3384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"que obviamente cause dano a qualquer um dos alvos","top":460.2384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"ou seus aliados. Por exemplo, você poderia dizer: “Ca-","top":472.1384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"minhe até a aldeia por essa estrada e auxilie os aldeões","top":484.0384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"a realizar a colheita até o pôr do sol” ou dizer: “Agora","top":495.9384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"não é hora para violência. Larguem as armas e dan-","top":507.8384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"cem! Parem em uma hora”.","top":519.7384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"Cada alvo deve ser bem-sucedido em uma salva-","top":531.6384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"guarda de Sabedoria ou tem a condição Enfeitiçado","top":543.5383999999999,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"pela duração da magia ou até que você ou seus aliados","top":555.4384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"causem dano ao alvo. Cada alvo Enfeitiçado cumpre a","top":567.3384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"sugestão com o melhor de sua capacidade. A atividade","top":579.2384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"sugerida pode continuar por toda a duração da magia,","top":591.1384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"mas se a atividade sugerida puder ser concluída em um","top":603.0383999999999,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"tempo mais curto, a magia encerra para um alvo que a","top":614.9384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"complete.","top":626.8384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. A","top":638.7384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"duração é maior com um espaço de magia 7º círculo","top":650.6384,"prose":true,"stat":false,"head":false,"page":96,"col":0},{"text":"(10 dias), 8º círculo (30 dias) ou 9º círculo (366 dias).","top":662.5384,"prose":true,"stat":false,"head":false,"page":96,"col":0}],"page":96}');
