INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(357,'Suplício','suplicio',8,1,1,'V, S, M (um chaveiro sem chaves)','Ação','45 metros','Instantânea','Você sobrecarrega a mente de uma criatura à sua vista
e no alcance da magia. O alvo realiza uma salvaguarda
de Inteligência.
Se falhar, o alvo sofre 10d12 pontos de dano Psí-
quico e não pode conjurar magias ou executar a ação
Usar Magia. Ao final de cada 30 dias, o alvo repete a
salvaguarda, encerrando o efeito em caso de sucesso.
O efeito também pode ser encerrado pela magia Cura
Completa, Desejo ou Restauração Maior.
Em uma salvaguarda bem-sucedida, o alvo recebe
apenas metade do dano.',96,'Encantamento (Bardo, Bruxo, Druida, Mago)','{"level":"8","name":"Suplício","school":[{"text":"Encantamento (Bardo, Bruxo, Druida, Mago)","top":62.99189999999999,"prose":true,"stat":false,"head":false,"page":96,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65789999999993,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Alcance":[{"text":"45 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Componentes":[{"text":"V, S, M (um chaveiro sem chaves)","top":102.4579,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Duração":[{"text":"Instantânea","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":96,"col":1}]},"desc":[{"text":"Você sobrecarrega a mente de uma criatura à sua vista","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"e no alcance da magia. O alvo realiza uma salvaguarda","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"de Inteligência.","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"Se falhar, o alvo sofre 10d12 pontos de dano Psí-","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"quico e não pode conjurar magias ou executar a ação","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"Usar Magia. Ao final de cada 30 dias, o alvo repete a","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"salvaguarda, encerrando o efeito em caso de sucesso.","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"O efeito também pode ser encerrado pela magia Cura","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"Completa, Desejo ou Restauração Maior.","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"Em uma salvaguarda bem-sucedida, o alvo recebe","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"apenas metade do dano.","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":96,"col":1}],"page":96}');
