INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(358,'Sussurros Dissonantes','sussurros dissonantes',1,1,1,'V','Ação','18 metros','Instantânea','Uma criatura à sua escolha à sua vista no alcance da
magia escuta uma melodia dissonante na mente. O alvo
deve realizar uma salvaguarda de Sabedoria. Se falhar,
sofre 3d6 pontos de dano Psíquico e deve usar imedia-
tamente a Reação, se disponível, para se mover o mais
longe possível de você, usando a rota mais segura. Em
caso de sucesso, o alvo sofre apenas metade do dano.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d6 pontos para cada círculo de
espaço de magia acima de 1.',96,'Encantamento (Bardo)','{"level":"1","name":"Sussurros Dissonantes","school":[{"text":"Encantamento (Bardo)","top":295.6172,"prose":true,"stat":false,"head":false,"page":96,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":311.28309999999993,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Alcance":[{"text":"18 metros","top":323.18309999999997,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Componentes":[{"text":"V","top":335.08309999999994,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Duração":[{"text":"Instantânea","top":346.9831,"prose":false,"stat":false,"head":false,"page":96,"col":1}]},"desc":[{"text":"Uma criatura à sua escolha à sua vista no alcance da","top":365.0384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"magia escuta uma melodia dissonante na mente. O alvo","top":376.9384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"deve realizar uma salvaguarda de Sabedoria. Se falhar,","top":388.8384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"sofre 3d6 pontos de dano Psíquico e deve usar imedia-","top":400.7384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"tamente a Reação, se disponível, para se mover o mais","top":412.6384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"longe possível de você, usando a rota mais segura. Em","top":424.5384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"caso de sucesso, o alvo sofre apenas metade do dano.","top":436.4384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":448.3384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"dano aumenta em 1d6 pontos para cada círculo de","top":460.2384,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"espaço de magia acima de 1.","top":472.1384,"prose":true,"stat":false,"head":false,"page":96,"col":1}],"page":96}');
