INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(359,'Talho Mental','talho mental',0,1,1,'V','Ação','18 metros','1 rodada','Você tenta fragmentar temporariamente a mente de
uma criatura à sua vista e no alcance da magia. O alvo
deve ser bem-sucedido em uma salvaguarda de Inteli-
gência ou sofre 1d6 pontos de dano Psíquico e subtrai
1d4 da próxima salvaguarda que realizar antes do final
do seu próximo turno.
Aprimoramento de Truque. O dano aumenta em 1d6
quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).',96,'Encantamento (Bruxo, Feiticeiro, Mago)','{"level":"0","name":"Talho Mental","school":[{"text":"Encantamento (Bruxo, Feiticeiro, Mago)","top":516.3423,"prose":true,"stat":false,"head":false,"page":96,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":532.0083,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Alcance":[{"text":"18 metros","top":543.9083,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Componentes":[{"text":"V","top":555.8082999999999,"prose":false,"stat":false,"head":false,"page":96,"col":1}],"Duração":[{"text":"1 rodada","top":567.7083,"prose":false,"stat":false,"head":false,"page":96,"col":1}]},"desc":[{"text":"Você tenta fragmentar temporariamente a mente de","top":585.7636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"uma criatura à sua vista e no alcance da magia. O alvo","top":597.6636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"deve ser bem-sucedido em uma salvaguarda de Inteli-","top":609.5636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"gência ou sofre 1d6 pontos de dano Psíquico e subtrai","top":621.4636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"1d4 da próxima salvaguarda que realizar antes do final","top":633.3636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"do seu próximo turno.","top":645.2636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"Aprimoramento de Truque. O dano aumenta em 1d6","top":657.1636,"prose":true,"stat":false,"head":false,"page":96,"col":1},{"text":"quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).","top":669.0636,"prose":true,"stat":false,"head":false,"page":96,"col":1}],"page":96}');
