INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(360,'Taumaturgia','taumaturgia',0,5,1,'V','Ação','9 metros','Até 1 minuto','Você conjura uma pequena maravilha mágica no al-
cance da magia, criando um dos efeitos abaixo. Se usar
esta magia várias vezes, pode ter até três efeitos de 1
minuto ativos simultaneamente.
Manipular Fogo. Você faz com que as chamas pisquem,
iluminem, escureçam ou mudem de cor por 1 minuto.
Mão Invisível. Você faz instantaneamente com que
uma porta ou janela destrancada se abra ou se feche.
Olhos Alterados. Você altera a aparência dos seus
olhos por 1 minuto.
Som Fantasmagórico. Você cria um som instantâneo
que se origina em um ponto à sua escolha no alcance
da magia, como um estrondo de trovão, o grito de um
corvo ou sussurros sinistros.
Voz Retumbante. Sua voz aumenta até três vezes
mais do que o normal por 1 minuto. Pela duração
da magia, você tem Vantagem em testes de Carisma
(Intimidação).
Tremores. Você causa tremores inofensivos no chão
por 1 minuto.',97,'Transmutação (Clérigo)','{"level":"0","name":"Taumaturgia","school":[{"text":"Transmutação (Clérigo)","top":62.791999999999916,"prose":true,"stat":false,"head":false,"page":97,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.35799999999995,"prose":false,"stat":false,"head":false,"page":97,"col":0}],"Alcance":[{"text":"9 metros","top":90.15800000000002,"prose":false,"stat":false,"head":false,"page":97,"col":0}],"Componentes":[{"text":"V","top":101.95799999999997,"prose":false,"stat":false,"head":false,"page":97,"col":0}],"Duração":[{"text":"Até 1 minuto","top":113.75799999999992,"prose":false,"stat":false,"head":false,"page":97,"col":0}]},"desc":[{"text":"Você conjura uma pequena maravilha mágica no al-","top":131.7133,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"cance da magia, criando um dos efeitos abaixo. Se usar","top":143.51319999999998,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"esta magia várias vezes, pode ter até três efeitos de 1","top":155.31319999999994,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"minuto ativos simultaneamente.","top":167.1131999999999,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Manipular Fogo. Você faz com que as chamas pisquem,","top":178.91319999999996,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"iluminem, escureçam ou mudem de cor por 1 minuto.","top":190.71319999999992,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Mão Invisível. Você faz instantaneamente com que","top":202.51319999999998,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"uma porta ou janela destrancada se abra ou se feche.","top":214.31319999999994,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Olhos Alterados. Você altera a aparência dos seus","top":226.1131999999999,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"olhos por 1 minuto.","top":237.91319999999996,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Som Fantasmagórico. Você cria um som instantâneo","top":249.71319999999992,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"que se origina em um ponto à sua escolha no alcance","top":261.5132,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"da magia, como um estrondo de trovão, o grito de um","top":273.31319999999994,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"corvo ou sussurros sinistros.","top":285.1132,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Voz Retumbante. Sua voz aumenta até três vezes","top":296.9132,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"mais do que o normal por 1 minuto. Pela duração","top":308.71320000000003,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"da magia, você tem Vantagem em testes de Carisma","top":320.5132,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"(Intimidação).","top":332.3132,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Tremores. Você causa tremores inofensivos no chão","top":344.1132,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"por 1 minuto.","top":355.9132,"prose":true,"stat":false,"head":false,"page":97,"col":0}],"page":97}');
