INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(361,'Teia','teia',2,4,1,'V, S, M (um pouco de teia de aranha)','Ação','18 metros','Concentração, até 1 hora','Você conjura uma massa de teias pegajosas em um
ponto no alcance da magia. As teias enchem um
Cubo de 6 metros de lado pela duração da magia, são
Terreno Difícil e a área dentro delas é Parcialmente
Obscurecida.
Se as teias não estiverem sustentadas entre duas
massas sólidas (como paredes ou árvores) ou em ca-
madas no chão, parede ou teto, a teia colapsa sobre si
mesma e a magia se encerra no início do seu próximo
turno. As teias em camadas sobre uma superfície plana
têm uma profundidade de 1,5 metro.
A primeira vez que uma criatura entra nas teias em
um turno ou começa o turno nelas, deve ser bem-suce-
dida em uma salvaguarda de Destreza ou tem a condi-
ção Contido enquanto está nas teias ou até se libertar.
Uma criatura Contida pelas teias pode executar uma
ação para realizar um teste de Força (Atletismo) contra
a CD para evitar sua magia. Em caso de sucesso, a cria-
tura não está mais Contida.
As teias são inflamáveis. Qualquer Cubo de 1,5
metro de lado com teias expostas ao fogo queima em 1
rodada, causando 2d4 pontos de dano Ígneo a qualquer
criatura que inicie seu turno no fogo.',97,'Invocação (Feiticeiro, Mago)','{"level":"2","name":"Teia","school":[{"text":"Invocação (Feiticeiro, Mago)","top":399.8171,"prose":true,"stat":false,"head":false,"page":97,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":415.38309999999996,"prose":false,"stat":false,"head":false,"page":97,"col":0}],"Alcance":[{"text":"18 metros","top":427.18309999999997,"prose":false,"stat":false,"head":false,"page":97,"col":0}],"Componentes":[{"text":"V, S, M (um pouco de teia de aranha)","top":438.9831,"prose":false,"stat":false,"head":false,"page":97,"col":0}],"Duração":[{"text":"Concentração, até 1 hora","top":450.78309999999993,"prose":false,"stat":false,"head":false,"page":97,"col":0}]},"desc":[{"text":"Você conjura uma massa de teias pegajosas em um","top":468.7384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"ponto no alcance da magia. As teias enchem um","top":480.5384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Cubo de 6 metros de lado pela duração da magia, são","top":492.3384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Terreno Difícil e a área dentro delas é Parcialmente","top":504.1384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Obscurecida.","top":515.9384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Se as teias não estiverem sustentadas entre duas","top":527.7384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"massas sólidas (como paredes ou árvores) ou em ca-","top":539.5383999999999,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"madas no chão, parede ou teto, a teia colapsa sobre si","top":551.3384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"mesma e a magia se encerra no início do seu próximo","top":563.1384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"turno. As teias em camadas sobre uma superfície plana","top":574.9384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"têm uma profundidade de 1,5 metro.","top":586.7384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"A primeira vez que uma criatura entra nas teias em","top":598.5383999999999,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"um turno ou começa o turno nelas, deve ser bem-suce-","top":610.3384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"dida em uma salvaguarda de Destreza ou tem a condi-","top":622.1384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"ção Contido enquanto está nas teias ou até se libertar.","top":633.9384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"Uma criatura Contida pelas teias pode executar uma","top":645.7384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"ação para realizar um teste de Força (Atletismo) contra","top":657.5384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"a CD para evitar sua magia. Em caso de sucesso, a cria-","top":669.3384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"tura não está mais Contida.","top":681.1384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"As teias são inflamáveis. Qualquer Cubo de 1,5","top":692.9384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"metro de lado com teias expostas ao fogo queima em 1","top":704.7384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"rodada, causando 2d4 pontos de dano Ígneo a qualquer","top":716.5384,"prose":true,"stat":false,"head":false,"page":97,"col":0},{"text":"criatura que inicie seu turno no fogo.","top":728.3384,"prose":true,"stat":false,"head":false,"page":97,"col":0}],"page":97}');
