INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(363,'Telepatia','telepatia',8,8,1,'V, S, M (um par de anéis de prata interligados)','Ação','Ilimitado','24 horas','Você cria um elo telepático entre você e uma criatura
voluntária com a qual está familiarizado. A criatura
pode estar em qualquer lugar no mesmo plano de exis-
tência que você. A magia encerra se você ou o alvo não
estiverem mais no mesmo plano.
Até que a magia termine, você e o alvo podem com-
partilhar instantaneamente palavras, imagens, sons e
outras mensagens sensoriais entre si através do elo,
e o alvo o reconhece como a criatura com a qual está
se comunicando. A magia permite que uma criatura
compreenda o significado de suas palavras e quaisquer
mensagens sensoriais que você enviar a ela.',97,'Adivinhação (Mago)','{"level":"8","name":"Telepatia","school":[{"text":"Adivinhação (Mago)","top":533.2172,"prose":true,"stat":false,"head":false,"page":97,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":548.5832,"prose":false,"stat":false,"head":false,"page":97,"col":1}],"Alcance":[{"text":"Ilimitado","top":560.1831999999999,"prose":false,"stat":false,"head":false,"page":97,"col":1}],"Componentes":[{"text":"V, S, M (um par de anéis de prata interligados)","top":571.7832,"prose":false,"stat":false,"head":false,"page":97,"col":1}],"Duração":[{"text":"24 horas","top":583.3833,"prose":false,"stat":false,"head":false,"page":97,"col":1}]},"desc":[{"text":"Você cria um elo telepático entre você e uma criatura","top":601.1385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"voluntária com a qual está familiarizado. A criatura","top":612.7384999999999,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"pode estar em qualquer lugar no mesmo plano de exis-","top":624.3385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"tência que você. A magia encerra se você ou o alvo não","top":635.9385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"estiverem mais no mesmo plano.","top":647.5385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"Até que a magia termine, você e o alvo podem com-","top":659.1385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"partilhar instantaneamente palavras, imagens, sons e","top":670.7384999999999,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"outras mensagens sensoriais entre si através do elo,","top":682.3385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"e o alvo o reconhece como a criatura com a qual está","top":693.9385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"se comunicando. A magia permite que uma criatura","top":705.5385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"compreenda o significado de suas palavras e quaisquer","top":717.1385,"prose":true,"stat":false,"head":false,"page":97,"col":1},{"text":"mensagens sensoriais que você enviar a ela.","top":729.0385,"prose":true,"stat":false,"head":false,"page":97,"col":1}],"page":97}');
