INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(365,'Tempestade da Vingança','tempestade da vinganca',9,4,1,'V, S','Ação','1,5 km','Concentração, até 1 minuto','Uma nuvem de tempestade agitada se forma, centrada
pela duração em um ponto no alcance da magia, se
espalhando para um raio de 90 metros. Cada criatura
sob a nuvem quando ela aparecer deve ser bem-sucedi-
da em uma salvaguarda de Constituição ou sofre 2d6
pontos de dano Trovejante e tem a condição Surdo
pela duração da magia.
No início de cada um dos seus turnos posteriores, a
tempestade produz efeitos diferentes, conforme deta-
lhado abaixo:
Turno 2: Chuva ácida cai. Cada criatura e objeto sob
a nuvem sofre 4d6 pontos de dano Ácido.
Turno 3: Você convoca seis relâmpagos da nuvem
para atingir seis criaturas ou objetos diferentes abaixo
dela. Cada alvo realiza uma salvaguarda de Destreza,
sofrendo 10d6 pontos de dano Elétrico se falhar ou
metade desse dano em caso de sucesso.
Turno 4: Chuva de pedras de granizo. Cada criatura
sob a nuvem sofre 2d6 pontos de dano Contundente.
Turnos 5-10: Rajadas de vento e chuva gelada surgem
sob a nuvem. Cada criatura na área sofre 1d6 pontos de
dano Gélido. Até que a magia termine, a área é Terreno
Difícil e está Totalmente Obscurecida, ataques à dis-
tância com armas são impossíveis nela e ventos fortes
sopram por toda a área.',98,'Invocação (Druida)','{"level":"9","name":"Tempestade da Vingança","school":[{"text":"Invocação (Druida)","top":259.0612,"prose":true,"stat":false,"head":false,"page":98,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":274.72720000000004,"prose":false,"stat":false,"head":false,"page":98,"col":1}],"Alcance":[{"text":"1,5 km","top":286.62719999999996,"prose":false,"stat":false,"head":false,"page":98,"col":1}],"Componentes":[{"text":"V, S","top":298.52719999999994,"prose":false,"stat":false,"head":false,"page":98,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":310.42719999999997,"prose":false,"stat":false,"head":false,"page":98,"col":1}]},"desc":[{"text":"Uma nuvem de tempestade agitada se forma, centrada","top":328.4825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"pela duração em um ponto no alcance da magia, se","top":340.3825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"espalhando para um raio de 90 metros. Cada criatura","top":352.2825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"sob a nuvem quando ela aparecer deve ser bem-sucedi-","top":364.1825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"da em uma salvaguarda de Constituição ou sofre 2d6","top":376.0825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"pontos de dano Trovejante e tem a condição Surdo","top":387.9825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"pela duração da magia.","top":399.8825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"No início de cada um dos seus turnos posteriores, a","top":411.7825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"tempestade produz efeitos diferentes, conforme deta-","top":423.6825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"lhado abaixo:","top":435.5825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"Turno 2: Chuva ácida cai. Cada criatura e objeto sob","top":447.4825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"a nuvem sofre 4d6 pontos de dano Ácido.","top":459.3825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"Turno 3: Você convoca seis relâmpagos da nuvem","top":471.2825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"para atingir seis criaturas ou objetos diferentes abaixo","top":483.1825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"dela. Cada alvo realiza uma salvaguarda de Destreza,","top":495.0825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"sofrendo 10d6 pontos de dano Elétrico se falhar ou","top":506.9825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"metade desse dano em caso de sucesso.","top":518.8824999999999,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"Turno 4: Chuva de pedras de granizo. Cada criatura","top":530.7825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"sob a nuvem sofre 2d6 pontos de dano Contundente.","top":542.6825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"Turnos 5-10: Rajadas de vento e chuva gelada surgem","top":554.5825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"sob a nuvem. Cada criatura na área sofre 1d6 pontos de","top":566.4825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"dano Gélido. Até que a magia termine, a área é Terreno","top":578.3824999999999,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"Difícil e está Totalmente Obscurecida, ataques à dis-","top":590.2825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"tância com armas são impossíveis nela e ventos fortes","top":602.1825,"prose":true,"stat":false,"head":false,"page":98,"col":1},{"text":"sopram por toda a área.","top":614.0825,"prose":true,"stat":false,"head":false,"page":98,"col":1}],"page":98}');
