INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(366,'Tempestade de Fogo','tempestade de fogo',7,6,1,'V, S','Ação','45 metros','Instantânea','Uma tempestade de fogo aparece no alcance da magia.
A área da tempestade consiste em até dez cubos de 3
metros, que você organiza como preferir. Cada Cubo
deve ser contíguo a pelo menos um outro Cubo. Cada
criatura na área realiza uma salvaguarda de Destreza,
sofrendo 7d10 pontos de dano Ígneo se falhar, ou me-
tade desse dano em caso de sucesso.
Objetos inflamáveis na área que não estão sendo
usados ou carregados entram em combustão.',98,'Evocação (Clérigo, Druida, Feiticeiro)','{"level":"7","name":"Tempestade de Fogo","school":[{"text":"Evocação (Clérigo, Druida, Feiticeiro)","top":658.2864,"prose":true,"stat":false,"head":false,"page":98,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":673.9524,"prose":false,"stat":false,"head":false,"page":98,"col":1}],"Alcance":[{"text":"45 metros","top":685.8524,"prose":false,"stat":false,"head":false,"page":98,"col":1}],"Componentes":[{"text":"V, S","top":697.7524,"prose":false,"stat":false,"head":false,"page":98,"col":1}],"Duração":[{"text":"Instantânea","top":709.6524,"prose":false,"stat":false,"head":false,"page":98,"col":1}]},"desc":[{"text":"Uma tempestade de fogo aparece no alcance da magia.","top":405.1603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"A área da tempestade consiste em até dez cubos de 3","top":417.0603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"metros, que você organiza como preferir. Cada Cubo","top":428.9603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"deve ser contíguo a pelo menos um outro Cubo. Cada","top":440.8603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"criatura na área realiza uma salvaguarda de Destreza,","top":452.7602,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"sofrendo 7d10 pontos de dano Ígneo se falhar, ou me-","top":464.6603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"tade desse dano em caso de sucesso.","top":476.5603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"Objetos inflamáveis na área que não estão sendo","top":488.4603,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"usados ou carregados entram em combustão.","top":500.3603,"prose":true,"stat":false,"head":false,"page":99,"col":0}],"page":98}');
