INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(367,'Tempestade Glacial','tempestade glacial',4,6,1,'V, S, M (uma luva)','Ação','90 metros','Instantânea','Granizo cai em um Cilindro de 6 metros de raio e 12
metros de altura, centrado em um ponto no alcance da
magia. Cada criatura no Cilindro realiza uma salva-
guarda de Destreza. Se falhar, uma criatura sofre 2d10
pontos de dano Contundente e 4d6 pontos de dano
Gélido, ou metade desse dano em caso de sucesso.
Pedras de granizo transformam o solo no Cilindro
em Terreno Difícil até o final do seu próximo turno.
Usando um Espaço de Magia de Círculo Superior. O
dano Contundente aumenta em 1d10 para cada círculo
de espaço de magia acima de 4.',99,'Evocação (Druida, Feiticeiro, Mago)','{"level":"4","name":"Tempestade Glacial","school":[{"text":"Evocação (Druida, Feiticeiro, Mago)","top":544.5642,"prose":true,"stat":false,"head":false,"page":99,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":560.2302,"prose":false,"stat":false,"head":false,"page":99,"col":0}],"Alcance":[{"text":"90 metros","top":572.1301,"prose":false,"stat":false,"head":false,"page":99,"col":0}],"Componentes":[{"text":"V, S, M (uma luva)","top":584.0301999999999,"prose":false,"stat":false,"head":false,"page":99,"col":0}],"Duração":[{"text":"Instantânea","top":595.9302,"prose":false,"stat":false,"head":false,"page":99,"col":0}]},"desc":[{"text":"Granizo cai em um Cilindro de 6 metros de raio e 12","top":613.9855,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"metros de altura, centrado em um ponto no alcance da","top":625.8854,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"magia. Cada criatura no Cilindro realiza uma salva-","top":637.7855,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"guarda de Destreza. Se falhar, uma criatura sofre 2d10","top":649.6855,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"pontos de dano Contundente e 4d6 pontos de dano","top":661.5853999999999,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"Gélido, ou metade desse dano em caso de sucesso.","top":673.4855,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"Pedras de granizo transformam o solo no Cilindro","top":685.3854,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"em Terreno Difícil até o final do seu próximo turno.","top":697.2855,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":709.1855,"prose":true,"stat":false,"head":false,"page":99,"col":0},{"text":"dano Contundente aumenta em 1d10 para cada círculo","top":