INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(368,'Tempestade Radiante de Jallarzi','tempestade radiante de jallarzi',5,6,1,'V, S, M (uma pitada de fósforo)','Ação','36 metros','Concentração, até 1 minuto','Você desencadeia uma tempestade de luz intermitente
e trovões furiosos em um Cilindro de 3 metros de raio
e 12 metros de altura centrado em um ponto à sua vista
e no alcance da magia. Enquanto estiverem nesta área,
criaturas têm as condições Cego e Surdo, e não podem
conjurar magias com um componente Verbal.
Quando a tempestade aparece, cada criatura dentro
dela realiza uma salvaguarda de Constituição, sofrendo
2d10 pontos de dano Radiante e 2d10 pontos de dano
Trovejante se falhar, ou metade desse dano em caso de
sucesso. Uma criatura também realiza essa salvaguarda
quando entra na área da magia pela primeira vez em
um turno ou termina o turno dela nela. Uma criatura
realiza essa salvaguarda apenas uma vez por turno.
Usando um Espaço de Magia de Círculo Superior. O
dano Radiante e Trovejante aumentam em 1d10 para
cada círculo de espaço de magia acima de 5.',99,'Evocação (Bruxo, Mago)','{"level":"5","name":"Tempestade Radiante de Jallarzi","school":[{"text":"Evocação (Bruxo, Mago)","top":431.795,"prose":true,"stat":false,"head":false,"page":99,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":447.4609,"prose":false,"stat":false,"head":false,"page":99,"col":1}],"Alcance":[{"text":"36 metros","top":459.36089999999996,"prose":false,"stat":false,"head":false,"page":99,"col":1}],"Componentes":[{"text":"V, S, M (uma pitada de fósforo)","top":471.26089999999994,"prose":false,"stat":false,"head":false,"page":99,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":483.16089999999997,"prose":false,"stat":false,"head":false,"page":99,"col":1}]},"desc":[{"text":"Você desencadeia uma tempestade de luz intermitente","top":501.2162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"e trovões furiosos em um Cilindro de 3 metros de raio","top":513.1161999999999,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"e 12 metros de altura centrado em um ponto à sua vista","top":525.0162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"e no alcance da magia. Enquanto estiverem nesta área,","top":536.9162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"criaturas têm as condições Cego e Surdo, e não podem","top":548.8162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"conjurar magias com um componente Verbal.","top":560.7162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"Quando a tempestade aparece, cada criatura dentro","top":572.6161999999999,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"dela realiza uma salvaguarda de Constituição, sofrendo","top":584.5162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"2d10 pontos de dano Radiante e 2d10 pontos de dano","top":596.4163,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"Trovejante se falhar, ou metade desse dano em caso de","top":608.3162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"sucesso. Uma criatura também realiza essa salvaguarda","top":620.2162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"quando entra na área da magia pela primeira vez em","top":632.1161999999999,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"um turno ou termina o turno dela nela. Uma criatura","top":644.0162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"realiza essa salvaguarda apenas uma vez por turno.","top":655.9163,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":667.8162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"dano Radiante e Trovejante aumentam em 1d10 para","top":679.7162,"prose":true,"stat":false,"head":false,"page":99,"col":1},{"text":"cada círculo de espaço de magia acima de 5.","top":691.6161999999999,"prose":true,"stat":false,"head":false,"page":99,"col":1}],"page":99}');
