INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(369,'Tentáculos Negros de Evard','tentaculos negros de evard',4,4,1,'V, S, M (um tentáculo)','Ação','27 metros','Concentração, até 1 minuto','Tentáculos pretos contorcendo-se enchem um quadra-
do de 6 metros de lados no chão à sua vista e no alcan-
ce da magia. Pela duração da magia, esses tentáculos
transformam o terreno nessa área em Terreno Difícil.
Cada criatura nessa área realiza uma salvaguarda de
Força. Se falhar, ela sofre 3d6 pontos de dano Contun-
dente e tem a condição Contido até que a magia termi-
ne. Uma criatura também realiza essa salvaguarda se
entrar na área ou terminar o turno nela. Uma criatura
realiza essa salvaguarda apenas uma vez por turno.
Uma criatura Contida pode executar uma ação para
realizar um teste de Força (Atletismo) contra a CD
para evitar sua magia, encerrando a condição em si
mesma em caso de sucesso.',100,'Invocação (Mago)','{"level":"4","name":"Tentáculos Negros de Evard","school":[{"text":"Invocação (Mago)","top":385.68580000000003,"prose":true,"stat":false,"head":false,"page":100,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":401.35179999999997,"prose":false,"stat":false,"head":false,"page":100,"col":0}],"Alcance":[{"text":"27 metros","top":413.25179999999995,"prose":false,"stat":false,"head":false,"page":100,"col":0}],"Componentes":[{"text":"V, S, M (um tentáculo)","top":425.1518,"prose":false,"stat":false,"head":false,"page":100,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":437.05179999999996,"prose":false,"stat":false,"head":false,"page":100,"col":0}]},"desc":[{"text":"Tentáculos pretos contorcendo-se enchem um quadra-","top":455.107,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"do de 6 metros de lados no chão à sua vista e no alcan-","top":467.007,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"ce da magia. Pela duração da magia, esses tentáculos","top":478.907,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"transformam o terreno nessa área em Terreno Difícil.","top":490.8071,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"Cada criatura nessa área realiza uma salvaguarda de","top":502.7071,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"Força. Se falhar, ela sofre 3d6 pontos de dano Contun-","top":514.607,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"dente e tem a condição Contido até que a magia termi-","top":526.5070000000001,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"ne. Uma criatura também realiza essa salvaguarda se","top":538.4069999999999,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"entrar na área ou terminar o turno nela. Uma criatura","top":550.3071,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"realiza essa salvaguarda apenas uma vez por turno.","top":562.207,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"Uma criatura Contida pode executar uma ação para","top":574.107,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"realizar um teste de Força (Atletismo) contra a CD","top":586.0071,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"para evitar sua magia, encerrando a condição em si","top":597.9069999999999,"prose":true,"stat":false,"head":false,"page":100,"col":0},{"text":"mesma em caso de sucesso.","top":609.8071,"prose":true,"stat":false,"head":false,"page":100,"col":0}],"page":100}');
