INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(371,'Terreno Alucinatório','terreno alucinatorio',4,7,1,'V, S, M (um cogumelo)','10 minutos','90 metros','24 horas','Você cria um terreno natural em um cubo de 45 metros
de comprimento que possui a aparência, o som e o chei-
ro de outro tipo de terreno natural. Assim, campos aber-
tos ou uma estrada podem ser moldados para se asseme-
lhar a um pântano, colina, fenda ou algum outro terreno
difícil ou intransitável. Uma lagoa pode ser formada para
parecer um prado verdejante, um precipício como uma
encosta suave ou um barranco pedregoso como uma es-
trada larga e plana. Criaturas, estruturas e equipamentos
manufaturados dentro da área não são alterados.
As características táteis do terreno permanecem
inalteradas, portanto, é provável que as criaturas que
entram na área percebam a ilusão. Se a diferença não
for evidente ao toque, uma criatura que examina a
ilusão pode executar a ação Analisar para realizar um
teste de Inteligência (Investigação) contra a CD para
evitar sua magia, a fim de não acreditar nela. Se uma
criatura perceber que o terreno é ilusório, ela vê uma
imagem vaga sobreposta ao terreno real.',101,'Ilusão (Bardo, Bruxo, Druida, Mago)','{"level":"4","name":"Terreno Alucinatório","school":[{"text":"Ilusão (Bardo, Bruxo, Druida, Mago)","top":62.99199999999996,"prose":true,"stat":false,"head":false,"page":101,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"10 minutos","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":101,"col":0}],"Alcance":[{"text":"90 metros","top":90.5578999999999,"prose":false,"stat":false,"head":false,"page":101,"col":0}],"Componentes":[{"text":"V, S, M (um cogumelo)","top":102.4579,"prose":false,"stat":false,"head":false,"page":101,"col":0}],"Duração":[{"text":"24 horas","top":114.35789999999997,"prose":false,"stat":false,"head":false,"page":101,"col":0}]},"desc":[{"text":"Você cria um terreno natural em um cubo de 45 metros","top":132.41319999999996,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"de comprimento que possui a aparência, o som e o chei-","top":144.31319999999994,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"ro de outro tipo de terreno natural. Assim, campos aber-","top":156.21319999999992,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"tos ou uma estrada podem ser moldados para se asseme-","top":168.1131999999999,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"lhar a um pântano, colina, fenda ou algum outro terreno","top":180.01319999999998,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"difícil ou intransitável. Uma lagoa pode ser formada para","top":191.91319999999996,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"parecer um prado verdejante, um precipício como uma","top":203.81319999999994,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"encosta suave ou um barranco pedregoso como uma es-","top":215.71319999999992,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"trada larga e plana. Criaturas, estruturas e equipamentos","top":227.6131999999999,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"manufaturados dentro da área não são alterados.","top":239.51319999999998,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"As características táteis do terreno permanecem","top":251.41319999999996,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"inalteradas, portanto, é provável que as criaturas que","top":263.31319999999994,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"entram na área percebam a ilusão. Se a diferença não","top":275.21320000000003,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"for evidente ao toque, uma criatura que examina a","top":287.1132,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"ilusão pode executar a ação Analisar para realizar um","top":299.0132,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"teste de Inteligência (Investigação) contra a CD para","top":310.9132,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"evitar sua magia, a fim de não acreditar nela. Se uma","top":322.8132,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"criatura perceber que o terreno é ilusório, ela vê uma","top":334.71320000000003,"prose":true,"stat":false,"head":false,"page":101,"col":0},{"text":"imagem vaga sobreposta ao terreno real.","top":346.6132,"prose":true,"stat":false,"head":false,"page":101,"col":0}],"page":101}');
