INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(373,'Toque Necrótico','toque necrotico',0,2,1,'V, S','Ação','Toque','Instantânea','Canalizando o frio da sepultura, realize um ataque
