INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(374,'Toque Vampírico','toque vampirico',3,2,1,'V, S','Ação','Pessoal','Concentração, até 1 minuto','O toque da sua mão envolta em sombras pode sugar a
força vital dos outros para curar suas feridas. Realize
um ataque mágico corpo a corpo contra uma criatura
no alcance da magia. Em caso de acerto, o alvo sofre
3d6 pontos de dano Necrótico e você recupera Pontos
de Vida iguais à metade da quantidade do dano Necró-
tico causado.
Até que a magia termine, você pode realizar o ataque
novamente em cada um dos seus turnos como uma
ação Usar Magia, atingindo a mesma criatura ou uma
diferente.
Usando um Espaço de Magia de Círculo Superior. O
dano aumenta em 1d6 para cada círculo de espaço de
magia acima de 3.',101,'Necromancia (Bruxo, Feiticeiro, Mago)','{"level":"3","name":"Toque Vampírico","school":[{"text":"Necromancia (Bruxo, Feiticeiro, Mago)","top":62.99209999999994,"prose":true,"stat":false,"head":false,"page":101,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":78.65800000000002,"prose":false,"stat":false,"head":false,"page":101,"col":1}],"Alcance":[{"text":"Pessoal","top":90.55809999999997,"prose":false,"stat":false,"head":false,"page":101,"col":1}],"Componentes":[{"text":"V, S","top":102.45799999999997,"prose":false,"stat":false,"head":false,"page":101,"col":1}],"Duração":[{"text":"Concentração, até 1 minuto","top":114.35799999999995,"prose":false,"stat":false,"head":false,"page":101,"col":1}]},"desc":[{"text":"O toque da sua mão envolta em sombras pode sugar a","top":132.41329999999994,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"força vital dos outros para curar suas feridas. Realize","top":144.3132999999999,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"um ataque mágico corpo a corpo contra uma criatura","top":156.2133,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"no alcance da magia. Em caso de acerto, o alvo sofre","top":168.11329999999998,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"3d6 pontos de dano Necrótico e você recupera Pontos","top":180.01329999999996,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"de Vida iguais à metade da quantidade do dano Necró-","top":191.91329999999994,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"tico causado.","top":203.8132999999999,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"Até que a magia termine, você pode realizar o ataque","top":215.7133,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"novamente em cada um dos seus turnos como uma","top":227.61329999999998,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"ação Usar Magia, atingindo a mesma criatura ou uma","top":239.51329999999996,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"diferente.","top":251.41329999999994,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior. O","top":263.3132999999999,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"dano aumenta em 1d6 para cada círculo de espaço de","top":275.2133,"prose":true,"stat":false,"head":false,"page":101,"col":1},{"text":"magia acima de 3.","top":287.1133,"prose":true,"stat":false,"head":false,"page":101,"col":1}],"page":101}');
