INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(379,'Tsunami','tsunami',8,4,1,'V, S','1 minuto','1,5 km','Concentração, até 6 rodadas','Uma muralha de água surge em um ponto à sua esco-
lha no alcance da magia. Você pode fazer a muralha
com até 90 metros de comprimento, 90 metros de
altura e 15 metros de espessura. A muralha permanece
pela duração da magia.
Quando a muralha aparece, cada criatura na área re-
aliza uma salvaguarda de Força, sofrendo 6d10 pontos
de dano Contundente se falhar, ou metade desse dano
em caso de sucesso.
No início de cada um dos seus turnos após o apareci-
mento da muralha, ela se move 15 metros para longe de
você, juntamente com quaisquer criaturas que estejam
dentro dela. Qualquer criatura de tamanho Enorme ou
menor dentro da muralha, ou cujo espaço a muralha
adentre ao se mover, deve ser bem-sucedida em uma
salvaguarda de Força ou sofre 5d10 pontos de dano
Contundente. Uma criatura pode sofrer esse dano
apenas uma vez por rodada. No final de cada turno, a
altura da muralha é reduzida em 15 metros, e o dano
que a muralha causa nas rodadas subsequentes é redu-
zido em 1d10. Quando a muralha atinge 0 metros de
altura, a magia termina.
Uma criatura apanhada pela muralha pode se mo-
ver nadando. No entanto, devido à força da onda, a
criatura deve ser bem-sucedida em um teste de Força
(Atletismo) contra a CD para evitar sua magia para se
mover. Se falhar no teste, ela não pode se mover. Uma
criatura que sair da muralha cai no chão.',102,'Invocação (Druida)','{"level":"8","name":"Tsunami","school":[{"text":"Invocação (Druida)","top":318.636,"prose":true,"stat":false,"head":false,"page":102,"col":1}],"meta":{"Tempo de Conjuração":[{"text":"1 minuto","top":334.30199999999996,"prose":false,"stat":false,"head":false,"page":102,"col":1}],"Alcance":[{"text":"1,5 km","top":346.20199999999994,"prose":false,"stat":false,"head":false,"page":102,"col":1}],"Componentes":[{"text":"V, S","top":358.102,"prose":false,"stat":false,"head":false,"page":102,"col":1}],"Duração":[{"text":"Concentração, até 6 rodadas","top":370.00199999999995,"prose":false,"stat":false,"head":false,"page":102,"col":1}]},"desc":[{"text":"Uma muralha de água surge em um ponto à sua esco-","top":388.0573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"lha no alcance da magia. Você pode fazer a muralha","top":399.95730000000003,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"com até 90 metros de comprimento, 90 metros de","top":411.8573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"altura e 15 metros de espessura. A muralha permanece","top":423.7573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"pela duração da magia.","top":435.6573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"Quando a muralha aparece, cada criatura na área re-","top":447.5573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"aliza uma salvaguarda de Força, sofrendo 6d10 pontos","top":459.45730000000003,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"de dano Contundente se falhar, ou metade desse dano","top":471.3573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"em caso de sucesso.","top":483.2573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"No início de cada um dos seus turnos após o apareci-","top":495.1573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"mento da muralha, ela se move 15 metros para longe de","top":507.0573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"você, juntamente com quaisquer criaturas que estejam","top":518.9573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"dentro dela. Qualquer criatura de tamanho Enorme ou","top":530.8573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"menor dentro da muralha, ou cujo espaço a muralha","top":542.7573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"adentre ao se mover, deve ser bem-sucedida em uma","top":554.6573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"salvaguarda de Força ou sofre 5d10 pontos de dano","top":566.5572,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"Contundente. Uma criatura pode sofrer esse dano","top":578.4573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"apenas uma vez por rodada. No final de cada turno, a","top":590.3573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"altura da muralha é reduzida em 15 metros, e o dano","top":602.2573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"que a muralha causa nas rodadas subsequentes é redu-","top":614.1573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"zido em 1d10. Quando a muralha atinge 0 metros de","top":626.0572,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"altura, a magia termina.","top":637.9573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"Uma criatura apanhada pela muralha pode se mo-","top":649.8573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"ver nadando. No entanto, devido à força da onda, a","top":661.7573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"criatura deve ser bem-sucedida em um teste de Força","top":673.6573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"(Atletismo) contra a CD para evitar sua magia para se","top":685.5572,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"mover. Se falhar no teste, ela não pode se mover. Uma","top":697.4573,"prose":true,"stat":false,"head":false,"page":102,"col":1},{"text":"criatura que sair da muralha cai no chão.","top":709.3573,"prose":true,"stat":false,"head":false,"page":102,"col":1}],"page":102}');
