INSERT INTO spells(id,name,search_name,level,school_id,source_id,components_text,casting_time_text,range_text,duration_text,description_text,source_page,source_school_text,original_entry_json) VALUES(385,'Vinha Agarradora','vinha agarradora',4,4,1,'V, S','Ação Bônus','18 metros','Concentração, até 1 minuto','Você conjura uma vinha que brota de uma superfície
em um espaço desocupado à sua vista e no alcance da
magia. A vinha permanece pela duração da magia.
Realize um ataque mágico corpo a corpo contra uma
criatura a até 9 metros da vinha. Em caso de acerto,
o alvo sofre 4d8 pontos de dano Contundente e é
puxado até 9 metros em direção à vinha; se o alvo for
Enorme ou menor, ele tem a condição Imobilizado (CD
para escapar é igual à sua CD para evitar sua magia). A
vinha pode imobilizar apenas uma criatura de cada vez,
e você pode fazer com que a vinha libere uma criatura
Imobilizada (nenhuma ação é necessária).
Como uma Ação Bônus em seus turnos posteriores,
você pode repetir o ataque contra uma criatura a até 9
metros da vinha.
Usando um Espaço de Magia de Círculo Superior.
O número de criaturas que a vinha pode imobilizar
aumenta em um para cada círculo de espaço de magia
acima de 4.',104,'Invocação (Druida, Guardião)','{"level":"4","name":"Vinha Agarradora","school":[{"text":"Invocação (Druida, Guardião)","top":676.7116,"prose":true,"stat":false,"head":false,"page":104,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação Bônus","top":692.3776,"prose":false,"stat":false,"head":false,"page":104,"col":0}],"Alcance":[{"text":"18 metros","top":704.2776,"prose":false,"stat":false,"head":false,"page":104,"col":0}],"Componentes":[{"text":"V, S","top":716.1776,"prose":false,"stat":false,"head":false,"page":104,"col":0}],"Duração":[{"text":"Concentração, até 1 minuto","top":728.0776,"prose":false,"stat":false,"head":false,"page":104,"col":0}]},"desc":[{"text":"Você conjura uma vinha que brota de uma superfície","top":36.357299999999896,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"em um espaço desocupado à sua vista e no alcance da","top":48.25729999999999,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"magia. A vinha permanece pela duração da magia.","top":60.157299999999964,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"Realize um ataque mágico corpo a corpo contra uma","top":72.05729999999994,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"criatura a até 9 metros da vinha. Em caso de acerto,","top":83.95729999999992,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"o alvo sofre 4d8 pontos de dano Contundente e é","top":95.8572999999999,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"puxado até 9 metros em direção à vinha; se o alvo for","top":107.75729999999999,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"Enorme ou menor, ele tem a condição Imobilizado (CD","top":119.65729999999996,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"para escapar é igual à sua CD para evitar sua magia). A","top":131.55729999999994,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"vinha pode imobilizar apenas uma criatura de cada vez,","top":143.45729999999992,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"e você pode fazer com que a vinha libere uma criatura","top":155.3572999999999,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"Imobilizada (nenhuma ação é necessária).","top":167.2573,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"Como uma Ação Bônus em seus turnos posteriores,","top":179.15729999999996,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"você pode repetir o ataque contra uma criatura a até 9","top":191.05729999999994,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"metros da vinha.","top":202.95729999999992,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":215.03729999999996,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"O número de criaturas que a vinha pode imobilizar","top":226.7573,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"aumenta em um para cada círculo de espaço de magia","top":238.65729999999996,"prose":true,"stat":false,"head":false,"page":104,"col":1},{"text":"acima de 4.","top":250.55729999999994,"prose":true,"stat":false,"head":false,"page":104,"col":1}],"page":104}');
