círculo de espaço de magia acima de 3.',105,'Transmutação (Bruxo, Feiticeiro, Mago)','{"level":"3","name":"Voo","school":[{"text":"Transmutação (Bruxo, Feiticeiro, Mago)","top":424.92,"prose":true,"stat":false,"head":false,"page":105,"col":0}],"meta":{"Tempo de Conjuração":[{"text":"Ação","top":440.5859,"prose":false,"stat":false,"head":false,"page":105,"col":0}],"Alcance":[{"text":"Toque","top":452.48589999999996,"prose":false,"stat":false,"head":false,"page":105,"col":0}],"Componentes":[{"text":"V, S, M (uma pena)","top":464.38589999999994,"prose":false,"stat":false,"head":false,"page":105,"col":0}],"Duração":[{"text":"Concentração, até 10 minutos","top":476.28589999999997,"prose":false,"stat":false,"head":false,"page":105,"col":0}]},"desc":[{"text":"Você toca uma criatura voluntária. Pela duração da","top":494.3412,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"magia, o alvo ganha um Deslocamento de Voo de 18","top":506.2412,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"metros e pode pairar. Quando a magia termina, o alvo","top":518.1412,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"entra em queda se ainda estiver no alto, a menos que","top":530.0412,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"possa impedir a queda.","top":541.9412,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"Usando um Espaço de Magia de Círculo Superior.","top":554.0212,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"Você pode escolher uma criatura adicional para cada","top":565.7411999999999,"prose":true,"stat":false,"head":false,"page":105,"col":0},{"text":"círculo de espaço de magia acima de 3.","top":577.6412,"prose":true,"stat":false,"head":false,"page":105,"col":0}],"page":105}');
